def _is_non_business_personal_event(ev: dict) -> bool:
    """True if a calendar event is personal-calendar leisure/logistics, not
    a business meeting that deserves prep treatment.

    RB-2026-09-06: the existing exclusion (a keyword blocklist for medical/
    dental appointments, duplicated in both _meeting_prep_items and
    _compute_day_ahead) never anticipated sports games or other personal
    entertainment -- confirmed live: "Badgers Football vs Notre Dame" got
    full meeting-prep treatment (prep questions, network-connections gaps,
    a dedicated meeting_briefs artifact target) and was pushed as the
    day's headline signal in CoS Opening/Decision Queue/Bottom Line. Its
    real event data already carries a reliable, general signal instead of
    another keyword to maintain forever: account_id == "personal" with
    zero matched/unknown attendees and no thread/company/deliverable tie.
    A real meeting on the personal calendar (a school event with another
    parent invited, a call with a named attendee) still has at least one
    of those signals and is unaffected."""
    if (ev.get("account_id") or "").lower() != "personal":
        return False
    attendees = ev.get("attendees_matched") or []
    if attendees:
        return False
    if ev.get("matched_threads") or ev.get("active_thread_company_hits"):
        return False
    title_low = (ev.get("title") or "").lower()
    if any(k in title_low for k in MEETING_DELIVERABLE_KEYWORDS):
        return False
    return True


def _load_source_health() -> dict | None:
    """Load the persisted source-health report when refresh_sources wrote one."""
    path = core.SYSTEM_DIR / ".cache" / "source_health.json"
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return None


def _load_active_knowledge_assets() -> list[dict]:
    """Load active knowledge assets from the graph registry for session-start context seeding.

    These are surfaced in every canonical brief to 'mount' specialized graphs at
    session start.  When the GPT calls getDailyBrief and sees active_knowledge_assets,
    it treats those graphs as MOUNTED for the entire session — all queries matching
    activation_terms route to getMicroGraphSummary before any other source or base model
    knowledge.  This is the primary defense against micro-graph routing failures
    (DEFECT-017, DEFECT-019).

    Returns a list of asset dicts, one per active/partial micro-graph in the registry.
    """
    registry_path = core.SYSTEM_DIR / "graphs" / "index.json"
    if not registry_path.exists():
        return []
    try:
        registry = json.loads(registry_path.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return []

    assets: list[dict] = []
    for graph in registry.get("graphs") or []:
        status = (graph.get("status") or "unknown").lower()
        if status not in ("active", "partial"):
            continue
        counts = graph.get("counts") or {}
        graph_slug = graph.get("graph_slug") or ""
        entity_name = graph.get("name") or graph_slug
        activation_terms = graph.get("activation_terms") or []

        # Option C: precomputed_answers live in index.json (written at graph build time).
        # Brief build is now a pure read — no computation here.
        # Fallback: if the index hasn't been rebuilt since Option C was deployed,
        # precomputed_answers will be empty and the GPT falls back to getMicroGraphSummary.
        precomputed_answers: dict = {}
        index_rel = graph.get("index_path")
        if index_rel:
            index_path = core.PROJECT_DIR / index_rel
            try:
                index = json.loads(index_path.read_text(encoding="utf-8"))
                precomputed_answers = index.get("precomputed_answers") or {}
            except Exception:  # noqa: BLE001
                pass

        assets.append({
            "asset_id": graph.get("graph_id"),
            "asset_type": graph.get("graph_type") or "micro_graph",
            "entity": entity_name,
            "graph_slug": graph_slug,
            "activation_terms": activation_terms,
            "retrieval_action": "getMicroGraphSummary",
            "retrieval_params": {"query": entity_name},
            "status": status,
            "freshness_date": (graph.get("updated_at") or "")[:7] or None,
            "node_count": counts.get("nodes", 0),
            "edge_count": counts.get("edges", 0),
            "source_workbook": graph.get("source_workbook"),
            "routing_rule": (
                f"MOUNTED FOR SESSION: All queries containing any activation_term route to "
                f"getMicroGraphSummary(query=\"{entity_name}\") BEFORE any other source or "
                f"base model knowledge. Context boost window: session-scoped — this mount "
                f"persists from the first brief load until the session ends. "
                f"Bypassing this graph to answer from base model knowledge is a retrieval defect."
            ),
            "context_boost_window": "session_scoped",
            "graceful_failure_mode": (
                f"If getMicroGraphSummary is unavailable or returns an error, respond: "
                f"\"Expected source: {entity_name} Micro Graph — Source status: unavailable "
                f"— Confidence: unable to answer from verified data.\" "
                f"Do not fill the answer from base model knowledge."
            ),
            **({"precomputed_answers": precomputed_answers} if precomputed_answers else {}),
        })
    return assets


def _load_artifact_freshness_items(today: date) -> list[dict]:
    """DEFECT-014: Scan the artifact registry for stale or stub artifacts.

    Returns canonical-item-compatible dicts for the information_debt_queue and
    resource_verification_and_freshness_status sections.

    Thresholds:
      active artifact freshness_date > 30 days ago → stale, surface as DEGRADED
      stub artifact → surface as opportunity to build (disposition=monitor)
    """
    ARTIFACT_STALE_DAYS = 30
    try:
        registry_path = core.SYSTEM_DIR / "artifacts" / "registry.json"
        if not registry_path.exists():
            return []
        registry = json.loads(registry_path.read_text(encoding="utf-8"))
        artifacts = registry.get("artifacts") or []
    except Exception:  # noqa: BLE001
        return []

    items: list[dict] = []
    for art in artifacts:
        art_id = art.get("artifact_id") or ""
        name = art.get("name") or art_id
        status = art.get("status") or "unknown"
        freshness_raw = art.get("freshness_date") or ""
        art_type = art.get("artifact_type") or "artifact"

        if status == "active" and freshness_raw:
            try:
                fresh_date = date.fromisoformat(str(freshness_raw)[:10])
                age_days = (today - fresh_date).days
                if age_days > ARTIFACT_STALE_DAYS:
                    items.append(_canonical_item(
                        title=f"[ARTIFACT STALE] {name} — {age_days}d since last enrichment",
                        summary=(
                            f"{name} ({art_id}) last enriched {freshness_raw}. "
                            f"Artifacts older than {ARTIFACT_STALE_DAYS} days may not reflect current state."
                        ),
                        why_it_matters=(
                            f"Stale {art_type} reduces confidence in {name} queries. "
                            "New source data may be available for enrichment."
                        ),
                        recommended_action=(
                            f"POST /artifacts/{art_id}/enrich to add new source data, "
                            "or drop a new export into the pipeline."
                        ),
                        disposition="monitor",
                        grounding="system_detected",
                        freshness="stale_source_limited",
                        source_refs=["system/artifacts/registry.json"],
                        confidence="high",
                        extras={
                            "artifact_id": art_id,
                            "artifact_type": art_type,
                            "artifact_status": status,
                            "freshness_date": freshness_raw,
                            "age_days": age_days,
                            "debt_type": "artifact_stale",
                        },
                    ))
            except (ValueError, TypeError):
                pass

        elif status == "building":
            # building status: dossier seeded but not yet fully queryable
            # Surface as a monitor item with enrich recommendation
            freshness_d = freshness_raw[:10] if freshness_raw else "unknown"
            items.append(_canonical_item(
                title=f"[ARTIFACT BUILDING] {name} — dossier seeded, enrichment available",
                summary=(
                    f"{name} ({art_id}) has initial context seeded (freshness: {freshness_d}). "
                    "Enrich with additional source data to promote to active."
                ),
                why_it_matters=(
                    f"Building artifact for {name}. Structured queries are available via getArtifact "
                    "but the dossier is not yet complete."
                ),
                recommended_action=(
                    f"POST /artifacts/{art_id}/enrich with additional source data "
                    "(emails, org chart, competitive analysis) to enrich this dossier."
                ),
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["system/artifacts/registry.json"],
                confidence="medium",
                extras={
                    "artifact_id": art_id,
                    "artifact_type": art_type,
                    "artifact_status": "building",
                    "freshness_date": freshness_d,
                    "debt_type": "artifact_building",
                },
            ))

        elif status == "stub":
            # Active opportunity threads get elevated disposition
            active_threads = ["global payments", "foods connected", "par technology", "toast"]
            name_lower = name.lower()
            is_active = any(kw in name_lower for kw in active_threads)
            items.append(_canonical_item(
                title=f"[ARTIFACT STUB] {name} — no source data ingested yet",
                summary=(
                    f"{name} ({art_id}) is registered but has no source data. "
                    "Building this artifact would enable structured queries without re-uploading data each session."
                ),
                why_it_matters=(
                    f"Stub artifacts block structured intelligence for {name}. "
                    "Every question about this entity currently falls back to model knowledge."
                ),
                recommended_action=(
                    f"POST /artifacts/{art_id}/enrich with source data to begin building. "
                    "Once ingested, queries about this entity will use the artifact instead of base model."
                ),
                disposition="act_today" if is_active else "monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["system/artifacts/registry.json"],
                confidence="high",
                extras={
                    "artifact_id": art_id,
                    "artifact_type": art_type,
                    "artifact_status": "stub",
                    "freshness_date": None,
                    "is_active_thread": is_active,
                    "debt_type": "artifact_stub",
                },
            ))

    return items


def _load_recent_ri_events(today: date) -> dict:
    """Load RI events captured in the last 24h, bucketed for the brief.

    Returns:
        {
            "newly_captured": [...],            # persistence_status='persisted'
            "proposed_unconfirmed": [...],      # 'proposed_write_pending_confirmation'
            "historical_uploaded": [...],       # event_at >14 days before captured_at
            "rejected_today": [...],            # 'rejected_by_operator'
            "by_persistence_status": {...},     # counts
        }

    Import is local so the daily brief doesn't fail when ri_events isn't
    yet present in older RB installations.
    """
    try:
        import ri_events as _ri  # local import — same package directory
    except ImportError:
        return {"newly_captured": [], "proposed_unconfirmed": [],
                "historical_uploaded": [], "rejected_today": [],
                "by_persistence_status": {}, "available": False}

    from datetime import datetime, timedelta
    since_dt = datetime.combine(today, datetime.min.time()) - timedelta(hours=24)
    events = _ri.load_events(since=since_dt.isoformat(timespec="seconds"), limit=200)

    excluded_contact_ids, excluded_contact_names = _nontracked_personal_contact_keys()

    buckets = {
        "newly_captured": [],
        "proposed_unconfirmed": [],
        "historical_uploaded": [],
        "rejected_today": [],
    }
    counts: dict[str, int] = {}

    def _to_date(s: str | None) -> date | None:
        if not s:
            return None
        try:
            return date.fromisoformat(s[:10])
        except ValueError:
            return None

    for ev in events:
        if _ri_event_is_nontracked_personal(ev, excluded_contact_ids, excluded_contact_names):
            continue
        status = (ev.get("persistence") or {}).get("status")
        counts[status or "unknown"] = counts.get(status or "unknown", 0) + 1

        # Bucket
        if status == "persisted":
            buckets["newly_captured"].append(ev)
        elif status == "proposed_write_pending_confirmation":
            buckets["proposed_unconfirmed"].append(ev)
        elif status == "rejected_by_operator":
            buckets["rejected_today"].append(ev)

        # Historical-uploaded: event happened > 14 days before capture.
        # This carries low-confidence dates separately so the operator
        # doesn't read upload as fresh momentum (per P-020 §"Date-of-
        # intelligence rule" and the daily-brief integration UX rule).
        ev_at = _to_date(ev.get("event_at"))
        cap_at = _to_date(ev.get("captured_at"))
        if ev_at and cap_at and (cap_at - ev_at).days > 14:
            buckets["historical_uploaded"].append(ev)

    return {
        **buckets,
        "by_persistence_status": counts,
        "available": True,
    }


def _nontracked_personal_contact_keys() -> tuple[set[str], set[str]]:
    """Return baseline contact ids/names excluded from professional RI surfaces.

    These contacts can remain in baseline for identity resolution, but the daily
    brief should not turn personal relationships into action debt.
    """
    try:
        baseline = core.load_baseline()
    except Exception:  # noqa: BLE001
        return set(), set()

    ids: set[str] = set()
    names: set[str] = set()
    for entry in baseline:
        domain = str(entry.get("relationship_domain") or "").strip().lower()
        tags = {str(t).strip().lower() for t in (entry.get("tags") or [])}
        notes = str(entry.get("notes") or "").lower()
        excluded = (
            domain in {"personal", "family"}
            or "do_not_track" in tags
            or "personal_friend" in tags
            or "best friend" in notes
        )
        if not excluded:
            continue
        if entry.get("id"):
            ids.add(str(entry["id"]).strip().lower())
        if entry.get("name"):
            names.add(str(entry["name"]).strip().lower())
    return ids, names


def _ri_event_is_nontracked_personal(
    ev: dict,
    excluded_contact_ids: set[str],
    excluded_contact_names: set[str],
) -> bool:
    people = (ev.get("entities") or {}).get("people") or []
    for person in people:
        matched_id = str(person.get("matched_id") or "").strip().lower()
        raw = str(person.get("raw") or "").strip().lower()
        if matched_id and matched_id in excluded_contact_ids:
            return True
        if raw and raw in excluded_contact_names:
            return True
    src_id = str((ev.get("source") or {}).get("id") or "").strip().lower()
    if src_id:
        for contact_id in excluded_contact_ids:
            if contact_id and contact_id in src_id:
                return True
    return False


def _filter_nontracked_personal_interaction_overlay(interaction: dict) -> dict:
    excluded_contact_ids, excluded_contact_names = _nontracked_personal_contact_keys()
    if not excluded_contact_ids and not excluded_contact_names:
        return interaction

    def _contact_excluded(row: dict) -> bool:
        contact_id = str(row.get("id") or row.get("contact_id") or "").strip().lower()
        name = str(row.get("name") or "").strip().lower()
        return (
            bool(contact_id and contact_id in excluded_contact_ids)
            or bool(name and name in excluded_contact_names)
        )

    filtered = dict(interaction or {})
    if isinstance(filtered.get("matched_contacts"), list):
        filtered["matched_contacts"] = [
            row for row in filtered["matched_contacts"]
            if not _contact_excluded(row)
        ]
    if isinstance(filtered.get("proposed_last_touch_updates"), list):
        filtered["proposed_last_touch_updates"] = [
            row for row in filtered["proposed_last_touch_updates"]
            if not _contact_excluded(row)
        ]
    totals = dict(filtered.get("totals") or {})
    if "matched_contacts" in filtered:
        totals["matched_count"] = len(filtered.get("matched_contacts") or [])
    filtered["totals"] = totals
    return filtered


