def _load_competitor_battle_card_review() -> dict:
    """Load competitor_intelligence_review.py's pending review queue
    (RB-2026-09-01), split into new-today (full detail) vs. persisting
    (already pending from a prior day -- compacted so a stale battle card
    doesn't nag every single day, same discipline as
    entity_convergence_scan.py's persisting-vs-new dedup). Always returns a
    dict -- empty when the module isn't available or nothing is pending."""
    if not _HAS_COMPETITOR_INTELLIGENCE:
        return {"new_today": [], "persisting": []}
    try:
        queue = _cic.load_review_queue()
    except Exception:  # noqa: BLE001
        return {"new_today": [], "persisting": []}
    today_str = date.today().isoformat()
    new_today, persisting = [], []
    for item in queue.get("pending_reviews", []):
        if item.get("status") != "pending":
            continue
        queued_date = (item.get("queued_at") or "")[:10]
        (new_today if queued_date == today_str else persisting).append(item)
    return {"new_today": new_today, "persisting": persisting}


def _load_intelligence_action_queue() -> dict:
    """Load the unified review-first intelligence decision queue."""
    path = core.CACHE_DIR / "intelligence_action_queue.json"
    if not path.exists():
        return {"items": [], "total_pending": 0, "action_class_counts": {}}
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return value if isinstance(value, dict) else {"items": []}
    except Exception:  # noqa: BLE001
        return {"items": [], "total_pending": 0, "action_class_counts": {}}


