def _load_job_intelligence() -> dict:
    """Load job intelligence cache, or run the scanner if cache is missing/stale.

    Always returns a dict — gate_status='inactive' when job_search_active is false.
    This loader is safe to call unconditionally; the module gates itself.
    """
    if not _HAS_JOB_INTELLIGENCE:
        return {"gate_status": "module_unavailable", "signals": [], "signal_count": 0}
    cache_path = core.SYSTEM_DIR / ".cache" / "job_intelligence.json"
    if cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            # Use cache if it was generated today
            gen_at = str(cached.get("generated_at") or "")
            if gen_at[:10] == str(date.today()):
                return cached
        except Exception:  # noqa: BLE001
            pass
    try:
        report = _ji.build_report()
        _ji.write_cache(report)
        return report
    except Exception as exc:  # noqa: BLE001
        return {"gate_status": "error", "error": str(exc), "signals": [], "signal_count": 0}


def _load_opportunity_signals() -> dict:
    """Load cross-channel opportunity stakeholder signal correlation.

    Always returns a dict with at least "opportunities": [] — safe to call
    unconditionally even if the module is unavailable or scanning fails.
    """
    if not _HAS_OPPORTUNITY_SIGNAL_CORRELATION:
        return {"gate_status": "module_unavailable", "opportunities": [], "opportunity_count": 0}
    cache_path = _osc.CACHE_PATH
    if cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            gen_at = str(cached.get("generated_at") or "")
            if gen_at[:10] == str(date.today()):
                return cached
        except Exception:  # noqa: BLE001
            pass
    try:
        report = _osc.build_report()
        _osc.write_cache(report)
        return report
    except Exception as exc:  # noqa: BLE001
        return {"gate_status": "error", "error": str(exc), "opportunities": [], "opportunity_count": 0}


