def _load_intelligence_assessment() -> dict | None:
    """Sprint F: Load today's pre-brief intelligence assessment if fresh.

    Written by intelligence_assessment.py (which runs in refresh_all.py
    before daily_brief.py is invoked).  Returns None when the cache is
    absent, stale, or unreadable — daily_brief falls back to inline behavior.
    """
    path = core.SYSTEM_DIR / ".cache" / "intelligence_assessment.json"
    if not path.exists():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if data.get("assessment_date") != date.today().isoformat():
            return None  # stale — built for a different day
        return data
    except Exception:  # noqa: BLE001
        return None


def _run_web_scan(assessment: dict | None = None) -> dict:
    """
    Sprint E-2 / Sprint F: Run the external web scanner and return a serialisable dict.

    Sprint F: If today's intelligence_assessment cache is available, use its
    web intelligence data (Phase 1 result) instead of re-running the scanner.
    This ensures the web fetch happens before brief generation (in the assess
    phase) rather than during it, and that convergence analysis has already
    seen today's web items.

    Falls back to inline scanner call when assessment is absent or stale.
    Returns {world_national, restaurant_industry, restaurant_technology,
             source_health, stats} — shape mirrors ScanResult fields.
    On any failure: returns the empty structure so the brief never blocks.
    """
    # Sprint F: prefer pre-built assessment data when fresh
    if assessment and isinstance(assessment, dict):
        p1 = assessment.get("phase_1_web") or {}
        # RB-DEFECT: a technically "ok" assessment can still be a partial scan —
        # e.g. 2 of 4 world/national feeds failed or timed out but the other 2
        # still returned items, so status=ok and items_fetched>0 both pass while
        # the world_national pool is a fraction of what a full scan yields. This
        # silently starved the World/National headline sections (e.g. only
        # BBC+NPR made it in while Yahoo Finance and Axios contributed zero).
        # A full scan across the configured sources reliably yields 60-75 items;
        # treat anything well below that as partial and re-scan live instead.
        _wn_count = len(p1.get("world_national") or [])
        if p1.get("status") == "ok" and p1.get("items_fetched", 0) > 0 and _wn_count >= 20:
            return {
                "world_national": p1.get("world_national") or [],
                "restaurant_industry": p1.get("industry_primary") or [],
                "restaurant_technology": p1.get("industry_technology") or [],
                "source_health": p1.get("source_health") or [],
                "stats": {
                    "items_fetched": p1.get("items_fetched", 0),
                    "items_from_cache": p1.get("items_from_cache", 0),
                    "errors": p1.get("errors") or [],
                },
                "metadata": p1.get("metadata") or {},
                "_source": "intelligence_assessment_cache",
            }

    if not _HAS_WEB_SCANNER:
        return {
            "world_national": [],
            "restaurant_industry": [],
            "restaurant_technology": [],
            "source_health": [],
            "stats": {"items_fetched": 0, "items_from_cache": 0, "errors": []},
        }
    try:
        result = _ws.scan_all_sources()
        return {
            "world_national": result.world_national,
            "restaurant_industry": result.restaurant_industry,
            "restaurant_technology": result.restaurant_technology,
            "source_health": result.source_health,
            "stats": {
                "items_fetched": result.items_fetched,
                "items_from_cache": result.items_from_cache,
                "errors": result.errors,
            },
        }
    except Exception:  # noqa: BLE001
        return {
            "world_national": [],
            "restaurant_industry": [],
            "restaurant_technology": [],
            "source_health": [],
            "stats": {"items_fetched": 0, "items_from_cache": 0, "errors": []},
        }


def build_report(today: date) -> dict:
    baseline = core.load_baseline()
    settings = core.load_settings()
    summary = core.baseline_summary(baseline)
    crossings, gap_no_lt = core.compute_crossings(baseline, today)
    loops = core.parse_loop_ledger()
    loop_buckets = core.loops_by_status(loops, today)
    quiet = core.compute_quiet_zones(baseline, today)
    missing_cards = core.rcs_without_cards(baseline)
    contact_gaps = core.contact_field_gaps(baseline)
    circles = core.circle_summary()
    brief_count = core.count_briefs()
    all_threads = core.load_active_threads()
    open_threads = [t for t in all_threads if t.get("status") == "open"]

    # Top-N DRR with thread boost applied
    drr_rows = [core.drr_score(e, today, open_threads) for e in baseline]
    drr_rows.sort(key=lambda r: r["score"], reverse=True)
    drr_top = drr_rows[:15]

    # Inbox overlays (calendar + email + social inbound + social outbound + interactions)
    cal = core.calendar_overlay(today, baseline=baseline, threads=open_threads)
    em = core.email_overlay(baseline=baseline, threads=open_threads)
    social = core.social_overlay(baseline=baseline, threads=open_threads)
    social_out = core.social_outbound_overlay(baseline=baseline, threads=open_threads, today=today)
    post_recs = core.post_recommendations(baseline=baseline, threads=open_threads, today=today)
    interaction = _filter_nontracked_personal_interaction_overlay(
        core.interaction_overlay(baseline=baseline, today=today)
    )

    # Phase 9 — relationship signals from the last 48 hours (RB-9.66-D widened
    # from 24h: a strict same-day window misses Friday-evening activity on
    # Monday briefs and routinely yields 0-1 signals/day even when contacts
    # are active). previously_surfaced (via .cache/relationship_signals_seen.json)
    # prevents the same signal repeating across consecutive briefs.
    # This is the CoS section: industry intelligence is subordinate to
    # relationship/action intelligence (see test trace 2026-05-18-rb9-daily-brief-cos-vs-news).
    relationship_signals_report = rs.build_report(today=today, hours=48)
    relationship_signals_report.pop("_seen_fingerprints", None)

    # Phase 9D (sprint step 6) — market / operator signals. Source-backed
    # only; the canonical brief reports stale/missing state explicitly
    # rather than synthesizing market commentary when the inbox file is
    # empty.
    market_signals_report = ms.build_report(top_n=7)
    # RB-DEFECT-031 — morning-newspaper headlines + overnight change digest.
    # Pure assembly-stage reframes over data already loaded (computed here,
    # merged into `report` below once it exists) so they read as the brief's
    # lead-in ("what happened" / "what changed") rather than buried CoS-recap.
    try:
        _morning_headlines = _build_morning_headlines(market_signals_report)
        _overnight_change_digest = _build_overnight_change_digest(today)
        _morning_headlines_error = None
    except Exception as _exc:  # noqa: BLE001
        _morning_headlines, _overnight_change_digest = [], {}
        _morning_headlines_error = str(_exc)
    strategic_memory_report = sm.build_report(limit=7)
    strategic_events_report = se.build_report(market_report=market_signals_report, persist=True)
    strategic_operator_report = {}
    db_settings = settings.get("daily_briefing") or {}
    soi_settings = db_settings.get("strategic_operators") or {}
    if soi_settings.get("enabled", True):
        try:
            strategic_operator_report = so.build_overlay(
                today=today,
                recent_days=int(soi_settings.get("recent_days") or 90),
                baseline=baseline,
                threads=open_threads,
            )
        except Exception as exc:  # noqa: BLE001
            strategic_operator_report = {
                "error": str(exc),
                "operator_count": 0,
                "top": [],
                "reconciliation_prompts": [],
            }

    # LinkedIn messaging overlay — best-effort. When the inbox file is
    # missing the module returns a zero-totals dict, never raises.
    try:
        import linkedin_messaging as _lim  # type: ignore
        linkedin_messaging_overlay = _lim.linkedin_message_overlay()
    except Exception:  # noqa: BLE001
        linkedin_messaging_overlay = {}

    # RB 9.12 — opportunity sensing. Profile-driven; always best-effort.
    # Loads the selected user profile, scores market and job signals against it,
    # and surfaces actionable opportunities for the daily brief.
    opportunity_sensing_report: dict = {}
    if _HAS_OPPORTUNITY_SENSING:
        try:
            _profile = _up.load()
            opportunity_sensing_report = _ops.build_section(
                profile=_profile,
                market_signals_report=market_signals_report,
                max_surface=5,
            )
        except Exception as _exc:  # noqa: BLE001
            opportunity_sensing_report = {
                "error": str(_exc),
                "surface": [],
                "ignored_count": 0,
                "proof_stats": {"sources_reviewed": 0},
            }

    # RB 9.16 — Ecosystem intelligence section. Always best-effort;
    # returns empty section structure when graph is unavailable.
    ecosystem_intelligence_report: dict = {}
    if _HAS_ECOSYSTEM_BRIEF:
        try:
            ecosystem_intelligence_report = _eb.build_section(today=today)
        except Exception as _exc:  # noqa: BLE001
            ecosystem_intelligence_report = {"error": str(_exc)}

    # RB-2026-08-27/28 — downstream artifact cascade. Reads the signals/
    # relationships _eb.build_section() just wrote above; idempotent per
    # calendar day (this function runs twice per pipeline cycle).
    intelligence_cascade_report: dict = {}
    if _HAS_INTELLIGENCE_CASCADE:
        try:
            intelligence_cascade_report = _ic.build_section(today=today)
        except Exception as _exc:  # noqa: BLE001
            intelligence_cascade_report = {"error": str(_exc)}

    intelligence_ramifications_report: dict = {}
    if _HAS_INTELLIGENCE_RAMIFICATIONS:
        try:
            intelligence_ramifications_report = _iram.build_section(today=today)
        except Exception as _exc:  # noqa: BLE001
            intelligence_ramifications_report = {"error": str(_exc), "ramifications": []}

    # RB-DEFECT (2026-09-15): intelligence_action_queue.py runs as its own
    # morning_pipeline.py scan step, BEFORE competitor_intelligence_review_scan
    # (a later scan step) and before intelligence_ramifications is computed at
    # all (only ever computed here, inside brief construction, never persisted
    # by a dedicated pipeline step). The on-disk queue the brief renders below
    # (_load_intelligence_action_queue) could therefore miss this exact cycle's
    # competitor-review items and downstream ramifications. intelligence_
    # ramifications.build_section() just above already persisted a fresh
    # system/.cache/intelligence_ramifications.json (its own CACHE_PATH write),
    # and competitor_intelligence_review_scan already completed earlier in this
    # same pipeline run (scan phase always finishes before render_daily_brief
    # in the build phase) -- so review_queue.json is already current too.
    # Rebuild the queue now, with both same-cycle inputs current, before it is
    # read back in below. Best-effort: never fail brief construction over this.
    if _HAS_INTELLIGENCE_ACTION_QUEUE:
        try:
            _iaq.build(today=today)
        except Exception:  # noqa: BLE001
            pass

    downstream_impact_report: dict = {}
    if _HAS_DOWNSTREAM_IMPACT_QUEUE:
        try:
            downstream_impact_report = _diq.run(intelligence_ramifications_report, today=today)
        except Exception as _exc:  # noqa: BLE001
            downstream_impact_report = {"error": str(_exc), "status_counts": {}}

    intelligence_cycle_audit_report: dict = {}
    if _HAS_INTELLIGENCE_CYCLE_AUDIT:
        try:
            intelligence_cycle_audit_report = _ica.build(
                ramifications=intelligence_ramifications_report,
                downstream=downstream_impact_report,
                today=today,
            )
        except Exception as _exc:  # noqa: BLE001
            intelligence_cycle_audit_report = {"status": "failed", "error": str(_exc)}

    # Competitive Vulnerability & RFP Early Warning — account vulnerability
    # scoring across exec change, tech hiring, vendor relationship,
    # operational friction, strategic change, and vendor financial distress.
    # Always best-effort; returns empty brands list when sources unavailable.
    competitive_vulnerability_report: dict = {}
    if _HAS_COMPETITIVE_VULNERABILITY:
        try:
            competitive_vulnerability_report = _cv.build_report(today=today)
        except Exception as _exc:  # noqa: BLE001
            competitive_vulnerability_report = {"error": str(_exc), "brands": []}

    # RB-DEFECT-004 — Direct comms health (Apple Messages + Calls).
    # Always best-effort; returns empty list when module is unavailable.
    # baseline is loaded above; pass it through to avoid double-loading.
    direct_comms_items: list[dict] = []
    if _HAS_DIRECT_COMMS_HEALTH:
        try:
            direct_comms_items = _dch.build_direct_comms_brief_items(baseline)
        except Exception as _exc:  # noqa: BLE001
            direct_comms_items = [{"error": str(_exc)}]

    report = {
        "today": today.isoformat(),
        "weekday": today.strftime("%A"),
        "baseline": summary,
        "crossings": [c.__dict__ for c in crossings],
        "no_last_touch_rcs": [c.__dict__ for c in gap_no_lt],
        "loops": {k: [L.__dict__ for L in v] for k, v in loop_buckets.items()},
        "quiet_zones": [c.__dict__ for c in quiet],
        "missing_cards": missing_cards,
        "contact_gaps": contact_gaps,
        "circles": circles,
        "brief_count": brief_count,
        "active_threads": open_threads,
        "drr_top": drr_top,
        "calendar": cal,
        "email": em,
        "social": social,
        "social_outbound": social_out,
        "post_recommendations": post_recs,
        "interaction": interaction,
        "relationship_signals": relationship_signals_report,
        "market_signals": market_signals_report,
        "strategic_memory": strategic_memory_report,
        "strategic_events": strategic_events_report,
        "strategic_operators": strategic_operator_report,
        "linkedin_messaging": linkedin_messaging_overlay,
        "opportunity_sensing": opportunity_sensing_report,
        "passive_email_intelligence": _load_passive_email_intelligence(),
        # Job intelligence — gated by opportunity_context.yaml → job_search_active.
        # Returns gate_status='inactive' dict when not job searching; section
        # builder checks this and emits nothing when inactive.
        "job_intelligence": _load_job_intelligence(),
        # Cross-channel (email + SMS) milestone correlation against active
        # opportunity dossiers — independent of job_search_active gating,
        # since this covers opportunities already in motion.
        "opportunity_signals": _load_opportunity_signals(),
        "source_health": _load_source_health(),
        "delivery_check": _load_delivery_check(),
        "morning_pipeline_state": _load_morning_pipeline_state(),
        "ri_events_recent": _load_recent_ri_events(today),
        "passive_ri_ingest": _load_passive_ri_ingest(),
        "watch_scan_result": _load_watch_scan_result(),  # RB 9.29 — earnings watch-list auto-scan
        "ecosystem_intelligence": ecosystem_intelligence_report,
        "intelligence_cascade": intelligence_cascade_report,
        "intelligence_ramifications": intelligence_ramifications_report,
        "downstream_impact_queue": downstream_impact_report,
        "intelligence_cycle_audit": intelligence_cycle_audit_report,
        "competitive_vulnerability": competitive_vulnerability_report,
        "competitor_battle_card_review": _load_competitor_battle_card_review(),
        "intelligence_action_queue": _load_intelligence_action_queue(),
        # Sprint F — pre-brief intelligence assessment (written by intelligence_assessment.py).
        # Loaded first so _run_web_scan() can prefer the pre-built assessment data,
        # and so _compute_intelligence_assessment_summary() has access to proposals.
        "intelligence_assessment": _load_intelligence_assessment(),
        # Sprint E-2 / Sprint F — web scanner: external RSS headline sections.
        # Sprint F: prefers intelligence_assessment Phase 1 data when fresh,
        # avoiding a second network fetch during brief generation.
        # On failure / network unavailability: empty ScanResult keeps brief intact.
        "web_scan": _run_web_scan(_load_intelligence_assessment()),
        "direct_comms_health": direct_comms_items,
        "scheduled_tasks": [
            {
                "id": settings["daily_briefing"]["scheduled_task_id"],
                "schedule": f'{settings["daily_briefing"]["time_of_day_local"]} {settings["daily_briefing"]["timezone"]} daily',
                "status": "live" if settings["daily_briefing"]["enabled"] else "disabled",
            }
        ],
    }
    # RB-DEFECT-040 — surface the morning pipeline's execution_report at the
    # top level of `report`, where _intelligence_collection_summary_items()
    # and the "what_todd_doesnt_know_yet" front-page logic expect to find it
    # (report["execution_report"]). It was previously only nested inside
    # report["morning_pipeline_state"]["execution_report"], so both readers
    # always saw `{}` and silently fell back to "Not Available" / a hardcoded
    # source-count estimate — even on days the morning pipeline ran cleanly.
    report["execution_report"] = (
        (report.get("morning_pipeline_state") or {}).get("execution_report") or {}
    )
    # The public-collection contract is a separate same-day receipt so a
    # brief_only build cannot lose 4 AM scan statistics when reusing caches.
    try:
        _public_receipt_path = core.SYSTEM_DIR / ".cache" / "public_intelligence_collection_receipt.json"
        _public_receipt = json.loads(_public_receipt_path.read_text(encoding="utf-8"))
        if (_public_receipt.get("date") == today.isoformat()
                and _public_receipt.get("status") == "pass"):
            _execution_report = dict(report["execution_report"])
            _cycle_stats = dict(_execution_report.get("intelligence_cycle_statistics") or {})
            _daily_stats = dict(_cycle_stats.get("daily_monitoring") or {})
            _daily_stats.update({
                "sources_scanned": int(_public_receipt.get("sources_scanned") or 0),
                "items_fetched": int(_public_receipt.get("items_fetched") or 0),
                "entities_checked_for_new_sources": int(
                    _public_receipt.get("entities_checked_for_new_sources") or 0),
                "source_candidates_observed": int(
                    _public_receipt.get("source_candidates_observed") or 0),
            })
            _cycle_stats["daily_monitoring"] = _daily_stats
            _execution_report["intelligence_cycle_statistics"] = _cycle_stats
            report["execution_report"] = _execution_report
            report["public_intelligence_collection_receipt"] = _public_receipt
    except Exception:  # noqa: BLE001
        pass
    if _HAS_INTELLIGENCE_CYCLE_HEALTH:
        try:
            report["intelligence_cycle_health"] = _ich.assess(
                execution_report=report["execution_report"],
                source_health=report.get("source_health") or {},
                trace_audit=report.get("intelligence_cycle_audit") or {},
                downstream=report.get("downstream_impact_queue") or {},
                today=today,
            )
        except Exception as _exc:  # noqa: BLE001
            report["intelligence_cycle_health"] = {
                "status": "failed", "critical_alerts": 1, "error": str(_exc)}
    # RB 9.20 — DEFECT-008 fix: inject CoS judgment blocks.
    # Runs after the full report dict is assembled so cos_judgment has all signals.
    # Best-effort: a failure here must never suppress the brief.
    if _HAS_COS_JUDGMENT:
        try:
            _cos_blocks = _cj.build_all(report, today)
            report["source_freshness"] = _cos_blocks.get("source_freshness")
            report["cos_judgment"] = _cos_blocks.get("cos_judgment")
            report["what_is_not_happening"] = _cos_blocks.get("what_is_not_happening")
            report["execution_options"] = _cos_blocks.get("execution_options")
            report["macro_to_operator_synthesis"] = _cos_blocks.get("macro_to_operator_synthesis")
            # Preflight contract marker: "behavioral_intelligence": cos_blocks["behavioral_intelligence"]
            report["behavioral_intelligence"] = _cos_blocks.get("behavioral_intelligence")
            report["linkedin_relationship_delta"] = _cos_blocks.get("linkedin_relationship_delta")
            report["weekend_guidance"] = (_cos_blocks.get("cos_judgment") or {}).get("weekend_guidance")
        except Exception as _exc:  # noqa: BLE001
            report["cos_judgment_error"] = str(_exc)

    # RB-DEFECT-031 — merge the morning-newspaper / change-digest blocks
    # computed above (deferred merge: `report` doesn't exist at that point
    # in assembly).
    report["morning_headlines"] = _morning_headlines
    report["overnight_change_digest"] = _overnight_change_digest
    if _morning_headlines_error:
        report["morning_headlines_error"] = _morning_headlines_error

    # RB-DEFECT-021 — weekly planning layer. The brief is a *consumer* of
    # weekly_plan.json: it surfaces today's operating mode (gate, answers
    # "what kind of day is today / should Todd work today") and this week's
    # active outcomes + portfolio allocation (the reference frame that the
    # outcome-alignment scoring factor above scores items against).
    try:
        _plan = _current_weekly_plan(today)
        report["operating_mode"] = _cj.build_operating_mode(today, _plan)
        report["weekly_plan"] = {
            "week_of": _plan.get("week_of") if _plan else None,
            "is_current": _plan is not None,
            "outcomes": wp.active_outcomes(_plan) if _plan else [],
            "portfolio_allocation": (_plan or {}).get("portfolio_allocation", {}),
            "risks": (_plan or {}).get("risks", []),
            "forcing_functions": (_plan or {}).get("forcing_functions", []),
        }
    except Exception as _exc:  # noqa: BLE001
        report["weekly_plan_error"] = str(_exc)

    report["daily_prep_summary"] = build_daily_prep_summary(report)
    report["canonical_brief"] = build_canonical_brief(report)
    return report


def _canonical_item(*, title: str, summary: str, why_it_matters: str = "",
                    recommended_action: str = "", disposition: str = "monitor",
                    grounding: str = "inferred", freshness: str = "fresh",
                    source_refs: list[str] | None = None,
                    confidence: str = "medium",
                    action_options: list[str] | None = None,
                    extras: dict | None = None,
                    provenance: dict | None = None,
                    signal_state: str | None = None,
                    evidence: list[str] | None = None,
                    inference: list[str] | None = None) -> dict:
    """Small API-facing section item for GPTs to render without inventing shape."""
    if action_options is None:
        action_options = _default_action_options(disposition, recommended_action)
    item = {
        "title": title,
        "summary": summary,
        "why_it_matters": why_it_matters,
        "recommended_action": recommended_action,
        "disposition": disposition,
        "grounding": grounding,
        "freshness": freshness,
        "source_refs": source_refs or [],
        "confidence": confidence,
        "action_options": action_options,
    }
    if extras:
        item["extras"] = extras
    return _apply_intelligence_contract(
        item,
        provenance=provenance,
        signal_state=signal_state,
        evidence=evidence,
        inference=inference,
    )


def _default_action_options(disposition: str, recommended_action: str) -> list[str]:
    """User-facing affordances the operational layer can expose.

    RB should identify and recommend, then make the next move easy. These
    strings are stable command intents for a future UI/action layer.
    """
    if disposition == "ignore":
        return ["keep_ignored", "restore_to_watchlist"]
    if disposition == "monitor":
        return ["monitor", "create_watch_loop", "mark_irrelevant"]
    if disposition == "ask_todd":
        return ["answer_question", "create_loop", "defer", "mark_irrelevant"]
    opts = ["create_loop", "draft_next_action", "defer", "mark_done", "mark_irrelevant"]
    low = (recommended_action or "").lower()
    if "meeting prep" in low:
        opts.insert(0, "create_meeting_prep")
    if "follow up" in low or "reply" in low or "email" in low:
        opts.insert(0, "draft_message")
    return list(dict.fromkeys(opts))


def _confidence_numeric(label: str | None) -> float:
    return {
        "high": 0.82,
        "medium": 0.62,
        "low": 0.38,
    }.get(str(label or "medium").lower(), 0.62)


def _source_class_for_grounding(grounding: str | None) -> str:
    g = str(grounding or "").lower()
    if g in {"manual_user_provided", "manual_context", "user_uploaded_artifact"}:
        return "user_provided"
    if g in {"system_detected", "external_source", "source_backed"}:
        return "externally_discovered"
    if g == "inferred":
        return "system_inferred"
    return "unknown"


def _first_ref_class(source_refs: list[str]) -> str:
    refs = " ".join(source_refs).lower()
    if "market_signals.url:" in refs or "http" in refs:
        return "external_url"
    if "email" in refs or "calendar" in refs or "linkedin" in refs:
        return "connected_account"
    if "loop_ledger" in refs or "active_threads" in refs or "strategic_memory" in refs:
        return "operator_memory"
    if "source_health" in refs or "daily_prep" in refs or ".json" in refs:
        return "system_artifact"
    return "local_artifact" if refs else "unknown"


def _temporal_weight_from_timestamp(value: str | None, freshness: str) -> dict:
    dt = _parse_iso_dt(value)
    age_days = None
    bucket = "unknown"
    weight = 0.55
    if dt:
        age_days = max(0, int((datetime.now(timezone.utc) - dt).total_seconds() // 86400))
        if age_days <= 2:
            bucket = "recent_tactical"
            weight = 0.95
        elif age_days <= 14:
            bucket = "current"
            weight = 0.82
        elif age_days <= 90:
            bucket = "aging"
            weight = 0.58
        else:
            bucket = "durable_or_stale"
            weight = 0.38
    elif freshness in {"manual_context", "stale_source_limited"}:
        bucket = "durable_context" if freshness == "manual_context" else "stale_limited"
        weight = 0.45
    return {
        "timestamp": value,
        "age_days": age_days,
        "bucket": bucket,
        "weight": round(weight, 2),
        "note": "Freshness is balanced against durable context; recent does not automatically mean important.",
    }


def _signal_state_for_item(item: dict, corroboration_count: int) -> str:
    extras = item.get("extras") or {}
    explicit = extras.get("signal_state") or extras.get("lifecycle")
    if explicit:
        return str(explicit)
    disp = item.get("disposition")
    confidence = _confidence_numeric(item.get("confidence"))
    if disp == "act_today":
        return "Action-Relevant"
    if corroboration_count >= 2 and confidence >= 0.75:
        return "Strategically Significant"
    if corroboration_count >= 2:
        return "Corroborated"
    if item.get("freshness") == "stale_source_limited":
        return "Dormant"
    if disp == "ignore":
        return "Dormant"
    return "Tracked" if confidence >= 0.6 else "Observed"


def _estimated_reading_minutes(item: dict) -> int | None:
    """RB-DEFECT-021G — rough reading-time estimate (~220 wpm) from whatever
    body text is available, so the operator can self-prioritize deeper review."""
    text = " ".join(str(item.get(k) or "") for k in ("summary", "why_it_matters", "body", "excerpt"))
    words = len(text.split())
    if words < 20:
        return None
    return max(1, round(words / 220))


def _source_navigation_block(item: dict, provenance: dict | None, signal_timestamp) -> dict:
    """RB-DEFECT-021G — every elevated signal should carry a navigation
    contract: {source, date, est_reading_time, why_it_matters} so the
    operator can investigate independently rather than RB being the only
    path into the material."""
    refs = (provenance or {}).get("source_refs") or item.get("source_refs") or []
    source = refs[0] if refs else (item.get("extras") or {}).get("source_url") or item.get("source") or None
    return {
        "source": source,
        "date": signal_timestamp or item.get("freshness"),
        "est_reading_time_minutes": _estimated_reading_minutes(item),
        "why_it_matters": item.get("why_it_matters") or "",
    }


def _build_morning_headlines(market_signals_report: dict, *, limit: int = 7) -> list[dict]:
    """RB-DEFECT-031 — "morning newspaper" headlines layer.

    Groups the top market-signal items (already source-attributed and
    confidence-scored by market_signals.build_report) by category, rendering
    each as {headline, source, date, why_it_matters, url, confidence}. This
    is a pure rendering reframe over data already loaded — the brief should
    open with "what happened in the world" before "here's what to do about it."
    """
    items = (market_signals_report or {}).get("top") or []
    groups: dict[str, list[dict]] = {}
    for it in items[:limit]:
        section = (it.get("category") or "general").replace("_", " ").title()
        groups.setdefault(section, []).append({
            "headline": it.get("title"),
            "source": it.get("source_name"),
            "date": it.get("published_at"),
            "why_it_matters": it.get("pain_point_or_priority") or it.get("restaurant_operator_impact") or "",
            "url": it.get("url_canonical") or it.get("url"),
            "confidence": it.get("confidence"),
        })
    return [{"section": name, "items": rows} for name, rows in groups.items()]


def _build_overnight_change_digest(today: date) -> dict:
    """RB-DEFECT-031 — "what changed since yesterday" mutation digest.

    Reads the knowledge-mutation log populated by intelligence_mutation_engine
    (RB-DEFECT-029), filters to the last 24h (UTC, matching DEFECT-029's UTC
    correction), and groups by mutation type. This is the delta-first lead-in
    the brief was missing — humans orient on change, not restated snapshots.
    Degrades gracefully (empty digest, not an error) when the log is sparse.
    """
    since = (datetime.combine(today, datetime.min.time(), tzinfo=timezone.utc) - timedelta(days=1))
    log_path = core.CACHE_DIR / "knowledge_mutations.json"
    mutations: list[dict] = []
    if log_path.exists():
        try:
            mutations = (json.loads(log_path.read_text(encoding="utf-8")) or {}).get("mutations") or []
        except (OSError, json.JSONDecodeError):
            mutations = []
    recent = []
    for m in mutations:
        applied = m.get("applied_at")
        try:
            ts = datetime.fromisoformat(str(applied).replace("Z", "+00:00"))
        except (ValueError, TypeError):
            continue
        if ts >= since:
            recent.append(m)
    counts: dict[str, int] = {}
    for m in recent:
        mtype = m.get("type") or "unknown"
        counts[mtype] = counts.get(mtype, 0) + 1
    return {
        "since": since.isoformat(),
        "total": len(recent),
        "counts_by_type": counts,
        "mutations": recent,
    }


_WEEKLY_PLAN_CACHE: dict[str, Any] = {}


def _current_weekly_plan(today: date) -> dict | None:
    """RB-DEFECT-021 — load (and cache for this run) the active weekly_plan.

    Returns None when no plan exists or it's stale (different ISO week) —
    in which case alignment scoring degrades to a neutral no-op factor of
    1.0, so the brief behaves exactly as before until a plan is generated.
    """
    cache_key = today.isoformat()
    if cache_key not in _WEEKLY_PLAN_CACHE:
        plan = wp.load_plan()
        _WEEKLY_PLAN_CACHE[cache_key] = plan if wp.is_current(plan, today) else None
    return _WEEKLY_PLAN_CACHE[cache_key]


def _maybe_autodraft_weekly_plan(today: date) -> dict | None:
    """RB-DEFECT-021/036 — Monday-morning trigger for weekly plan creation.

    The gap this closes: RB had a propose-then-confirm weekly planning engine
    (weekly_plan_generator.py) but nothing actually *started* it — it sat idle
    until someone remembered to run it by hand. That's the same "computed but
    not wired" failure class as the other 021/031 defects, just one layer
    earlier (orchestration, not rendering).

    Behavior: on Monday, if there is no current live plan AND no draft already
    sitting on disk for this ISO week, generate one (best-effort, propose-only
    — never auto-confirms) and persist it to weekly_plan_draft.json so the
    brief can surface it as a ready-to-review proposal. Idempotent: re-running
    later the same week finds the existing draft and leaves it alone, so it
    won't clobber edits the user already made to it.

    Any other day, or if a draft/live plan already exists, this is a no-op —
    returns the existing draft (if any) so the brief can still mention it.
    """
    if wpg is None:
        return None
    try:
        existing_draft = None
        if wpg.DRAFT_PATH.exists():
            try:
                existing_draft = json.loads(wpg.DRAFT_PATH.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                existing_draft = None
        if existing_draft and wp.is_current(existing_draft, today):
            return existing_draft
        if today.weekday() != 0:  # Monday only — don't generate mid-week surprises
            return existing_draft
        plan = wpg.build_draft_plan(today)
        wpg.DRAFT_PATH.parent.mkdir(parents=True, exist_ok=True)
        wpg.DRAFT_PATH.write_text(json.dumps(plan, indent=2) + "\n", encoding="utf-8")
        plan["_autodraft_generated_today"] = True
        return plan
    except Exception as exc:
        return {"_autodraft_error": str(exc)}


def _strategic_significance_score(item: dict, corroboration_count: int) -> int:
    score = int(_confidence_numeric(item.get("confidence")) * 40)
    score += {"act_today": 35, "ask_todd": 25, "monitor": 12, "ignore": 0}.get(item.get("disposition"), 10)
    score += min(corroboration_count, 4) * 6
    if item.get("freshness") == "stale_source_limited":
        score -= 15
    if item.get("grounding") == "manual_user_provided" and item.get("disposition") == "monitor":
        score -= 10
    return max(0, min(100, score))


def _display_policy_for_item(item: dict, score: int, source_class: str, corroboration_count: int) -> dict:
    # RB-DEFECT-021C — maintenance-class loops only surface when due,
    # blocking an active strategic outcome, or carrying reputational risk.
    # Gated by display policy (suppression-by-default), not by score —
    # a high intrinsic score should not let routine maintenance crowd out
    # strategic work absent one of these triggers.
    if item.get("item_class") == "maintenance_loop":
        _plan = _current_weekly_plan(date.today())
        should_surface, reason = wp.maintenance_should_surface(item, _plan, date.today())
        if not should_surface:
            return {"policy": "suppress", "reason": reason}
        return {"policy": "surface", "reason": reason}
    if item.get("disposition") in {"act_today", "ask_todd"}:
        return {"policy": "surface", "reason": "action_or_decision_required"}
    if item.get("freshness") == "stale_source_limited":
        return {"policy": "surface_caveated", "reason": "source_gap_or_stale_data"}
    if source_class == "user_provided" and corroboration_count < 2 and score < 55:
        return {"policy": "state_mutation_only", "reason": "user_provided_low_novelty_no_new_corroboration"}
    if score >= 65 or corroboration_count >= 2:
        return {"policy": "surface", "reason": "strategic_significance_or_corroboration"}
    return {"policy": "surface_if_space", "reason": "contextual_signal_below_action_threshold"}


def _autonomous_discovery_value(
    source_class: str,
    grounding: str,
    disposition: str,
    score: int,
    signal_state: str,
    extras: dict,
) -> str:
    """Classify how much this item was RB-discovered vs. user-provided memory.

    Returns "high" | "medium" | "low".

    - high:   fresh connected-source discovery with changed state, contradiction,
              or high strategic significance.  RB found this; Todd likely did not
              already know it.
    - medium: system-inferred or connected-source item below the high bar —
              useful but not definitively novel.
    - low:    user-provided context, operator-memory, or manual active-thread
              state that RB is repeating.  Goes to known_state_reminders unless
              overdue or contradicted by fresh evidence.
    """
    is_user_provided = source_class == "user_provided"
    is_overdue = bool(extras.get("overdue"))
    is_contradicted = bool(extras.get("contradicted_by_fresh_evidence"))
    is_changed = (
        disposition in ("act_today", "ask_todd")
        or signal_state in ("Action-Relevant", "Strategically Significant")
    )

    # RB 2026-08-26: reviewed live — a bare "you had a text/call exchange with
    # X" (signal_type "direct_interaction") is never a discovery, because
    # Todd was personally a party to it; he already knows it happened. Only
    # non-participatory inferences from that interaction (a bounced-email
    # risk, a channel escalation) are genuine finds. Cap this class at "low"
    # regardless of everything else, so it never lands in "What RB Found
    # Without You Telling It" and instead reads as known/operational state.
    #
    # RB-2026-09-09: reviewed live — "pipeline_self_report" items (RB
    # reporting on whether its OWN discovery process found anything, or a
    # relationship-signal zero-state placeholder) got disposition=act_today
    # + grounding=system_detected same as a real discovery, so they scored
    # "high" and landed in "What RB Found Without You Telling It" as if
    # they were discoveries about the world. They are commentary about RB's
    # own pipeline health, not a discovery Todd didn't already have a way to
    # know about -- the same class of pollution already fixed for
    # overnight_delta_intelligence/email_intelligence_harvest on 2026-08-26.
    # Their real home is source-health/coverage framing (the brief's
    # coverage line, Proof Dashboard), not this section.
    #
    # RB-2026-09-10: "operational_bookkeeping" (e.g. SENT LOOP VERIFICATION
    # rows -- did a sent thread get a reply) is real state-tracking with a
    # correct destination (operational_changes_from_connected_sources), not
    # a discovery about the world. Added alongside the reopening of
    # email_intelligence_harvest as a discovery source below, so its
    # genuine headline items can flow through while bookkeeping rows still
    # can't.
    if extras.get("signal_type") in (
        "direct_interaction", "linkedin_inbound_message", "pipeline_self_report",
        "operational_bookkeeping",
    ):
        return "low"

    # RB 2026-08-26: a signal without real staleness information scored a
    # flat "medium" no matter how old it actually was (9+ days observed
    # live, presented as if it were today's finding). Reuse the same
    # age-bucketing already computed elsewhere (_temporal_weight_from_timestamp)
    # so age genuinely caps how "new" a discovery is allowed to claim to be.
    _age_days = _temporal_weight_from_timestamp(
        extras.get("signal_timestamp"), "fresh"
    ).get("age_days")
    _is_aging_or_older = _age_days is not None and _age_days > 3

    if is_user_provided:
        # Promote user-provided context only when something external changed it.
        if is_contradicted:
            return "medium"
        if is_overdue and disposition == "act_today":
            return "medium"
        return "low"

    if source_class == "externally_discovered":
        if _is_aging_or_older:
            return "medium" if (is_changed or score >= 70) else "low"
        if is_changed or score >= 70:
            return "high"
        return "medium"

    if source_class == "system_inferred":
        if _is_aging_or_older:
            return "medium" if (is_changed or score >= 65) else "low"
        if is_changed or score >= 65:
            return "high"
        return "medium"

    # unknown / unclassified — treat conservatively
    return "low"


def _apply_intelligence_contract(
    item: dict,
    *,
    provenance: dict | None = None,
    signal_state: str | None = None,
    evidence: list[str] | None = None,
    inference: list[str] | None = None,
) -> dict:
    """Attach the executive-intelligence contract to every brief item.

    This is deliberately deterministic: renderers and GPT clients should not
    have to infer provenance, novelty, lifecycle state, or fact/inference
    separation from prose.
    """
    source_refs = list(item.get("source_refs") or [])
    extras = item.get("extras") or {}
    source_class = (provenance or {}).get("source_class") or _source_class_for_grounding(item.get("grounding"))
    origin = (provenance or {}).get("origin") or item.get("grounding") or "unknown"
    if provenance and "corroboration_count" in provenance:
        corroboration_count = int(provenance.get("corroboration_count") or 0)
    else:
        corroboration_count = len(source_refs) or 0
    signal_timestamp = (
        (provenance or {}).get("first_seen_at")
        or extras.get("signal_timestamp")
        or extras.get("published_at")
        or extras.get("captured_at")
    )
    score = _strategic_significance_score(item, corroboration_count)
    temporal_weighting = _temporal_weight_from_timestamp(signal_timestamp, item.get("freshness") or "fresh")
    state = signal_state or _signal_state_for_item(item, corroboration_count)
    item["provenance"] = {
        "origin": origin,
        "source_class": source_class,
        "source_ref_class": (provenance or {}).get("source_ref_class") or _first_ref_class(source_refs),
        "first_seen_at": signal_timestamp,
        "source_refs": source_refs,
        "corroboration_count": corroboration_count,
        "corroboration_chain": (provenance or {}).get("corroboration_chain") or source_refs,
        "contradiction_history": (provenance or {}).get("contradiction_history") or extras.get("contradictions") or [],
    }
    item["confidence_evolution"] = {
        "current": item.get("confidence") or "medium",
        "score": _confidence_numeric(item.get("confidence")),
        "direction": extras.get("confidence_direction") or "unchanged_or_unknown",
        "basis": "explicit confidence label plus provenance/corroboration metadata",
    }
    item["temporal_weighting"] = temporal_weighting
    item["signal_state"] = state
    item["strategic_significance_score"] = score
    # RB-DEFECT-021G — source navigation contract on every elevated signal:
    # {source, date, est_reading_time, why_it_matters}, so the operator can
    # investigate independently rather than RB being a dead end.
    item["source_navigation"] = _source_navigation_block(item, item.get("provenance"), signal_timestamp)
    # RB-DEFECT-021B/021C — multiplicative outcome-alignment factor layered
    # on top of the intrinsic significance score. No-op (factor 1.0) until a
    # current weekly_plan.json exists, so behavior is unchanged by default.
    _plan = _current_weekly_plan(date.today())
    _alignment = wp.apply_alignment(score, item, _plan)
    item["outcome_alignment"] = _alignment
    score = _alignment["aligned_significance_score"]
    item["strategic_significance_score"] = score
    adv = _autonomous_discovery_value(
        source_class,
        item.get("grounding") or "",
        item.get("disposition") or "monitor",
        score,
        state,
        extras,
    )
    item["novelty"] = {
        "is_probably_new_to_user": source_class == "externally_discovered" and item.get("grounding") != "manual_user_provided",
        "novelty_density": (
            "high" if score >= 75 else
            "medium" if score >= 55 else
            "low"
        ),
        # RB 9.24B — autonomous discovery classification (DEFECT-013)
        "new_to_rb": source_class in ("externally_discovered", "system_inferred") and item.get("grounding") not in ("manual_user_provided", "manual_context"),
        "new_to_todd_likely": source_class == "externally_discovered" and item.get("grounding") not in ("manual_user_provided", "manual_context", "user_uploaded_artifact"),
        "source_discovered": source_class in ("externally_discovered", "system_inferred"),
        "user_provided_context": source_class == "user_provided",
        "changed_state": item.get("disposition") == "act_today" or state in ("Action-Relevant", "Strategically Significant"),
        "autonomous_discovery_value": adv,
    }
    item["display_policy"] = _display_policy_for_item(item, score, source_class, corroboration_count)
    item["evidence_inference"] = {
        "verified_or_detected_fact": evidence or ([item.get("summary")] if item.get("summary") else []),
        "inferred_implication": inference or ([item.get("why_it_matters")] if item.get("why_it_matters") else []),
        "alternative_explanations": extras.get("alternative_explanations") or [],
        "missing_evidence": extras.get("missing_evidence") or [],
    }
    return item


def _synthesize_operator_why(scores: dict, *, has_movement: bool) -> str:
    """RB-2026-09-09: replaces a raw 'Influence=high; relationship
    value=medium; ...' dump of score_operator()'s internal dimension names
    (confirmed live -- exactly this text shipped in "What RB Found Without
    You Telling It" and was called out as unreadable) with one synthesized
    sentence conveying what those dimensions actually mean: how big the
    operator is, whether this is a confirmed movement or just a market-
    signal mention, how close it is to Todd's network, and the net takeaway.
    """
    influence = scores.get("influence") or "low"
    relationship_value = scores.get("relationship_value") or "low"
    ecosystem_impact = scores.get("ecosystem_impact") or "low"
    opportunity = scores.get("future_opportunity") or "low"

    scale_phrase = {
        "critical": "one of the largest multi-brand operators RB tracks",
        "high": "a multi-brand operator with real scale",
        "medium": "a regional or single-concept operator",
        "low": "a smaller operator",
    }.get(influence, "an operator")

    proximity_phrase = {
        "critical": "directly in your network",
        "high": "one connection away from your network",
        "medium": "loosely connected to your network",
        "low": "not connected to your network",
    }.get(relationship_value, "unclear network proximity")

    if has_movement:
        basis_phrase = "a confirmed, dated movement"
    else:
        basis_phrase = "only a market-signal text match -- no confirmed movement yet"

    takeaway_phrase = {
        "critical": "worth acting on now",
        "high": "worth prioritizing",
        "medium": "worth watching, not yet worth acting on",
        "low": "low priority for now",
    }.get(opportunity, "unclear priority")

    ripple = " If it moves, the ripple across the ecosystem would be significant." if ecosystem_impact in ("high", "critical") else ""

    return (
        f"{scale_phrase.capitalize()}, {proximity_phrase} -- this is {basis_phrase}."
        f"{ripple} Net read: {takeaway_phrase}."
    )


def _strategic_operator_items(report: dict, *, limit: int = 5) -> list[dict]:
    """Return brief-worthy operator movements from the persistent entity lane.

    Proximity-only watchlist rows can be useful for reconciliation, but the
    morning brief should elevate operators here only when there is a persisted
    movement or a source-backed feeder match.
    """
    sor = report.get("strategic_operators") or {}
    # RB-2026-09-05: a feeder-only candidate (no persisted movement, just a
    # market_signals.json text match) has no expiry -- as long as the same
    # old article sits in market_signals.json, it keeps matching and
    # re-rendering byte-for-byte identical every day. Confirmed live: the
    # "Sizzling Platter" feeder signal was unchanged for 5 straight days in
    # "What RB Found Without You Telling It." A persisted movement doesn't
    # need this -- each one is already a distinct, dated event.
    _today_iso = report.get("today") or date.today().isoformat()
    _item_ledger = _load_brief_item_ledger()
    candidates = []
    for row in sor.get("top") or []:
        movements = row.get("recent_movements") or []
        feeder = row.get("market_signal_matches") or []
        if not movements and not feeder:
            continue
        scores = row.get("scores") or {}
        prox = row.get("relationship_proximity") or {}
        latest = movements[0] if movements else {}
        feeder_title = (feeder[0] or {}).get("title") if feeder else ""
        if not latest:
            feeder_marker = (feeder[0] or {}).get("url") or feeder_title
            feeder_key = f"feeder:{row.get('id') or row.get('name')}:{feeder_title}"
            if not _should_render_repeatable_item(
                _item_ledger, feeder_key, _today_iso, activity_marker=feeder_marker,
            ):
                continue
            _record_brief_item_seen(_item_ledger, feeder_key, _today_iso, activity_marker=feeder_marker)
        summary = (
            f"{latest.get('event_at')} {latest.get('movement_type')}: {latest.get('summary')}"
            if latest else
            f"Source-backed feeder signal: {feeder_title}"
        )
        why = _synthesize_operator_why(scores, has_movement=bool(latest))
        priority = scores.get("follow_up_priority") or "low"
        disposition = "act_today" if priority in {"critical", "high"} else "monitor"
        candidates.append(_canonical_item(
            title=row.get("name") or row.get("id") or "Strategic operator",
            summary=summary,
            why_it_matters=why,
            recommended_action=row.get("recommended_action") or "Monitor and persist material movement evidence.",
            disposition=disposition,
            grounding="system_detected",
            freshness="fresh",
            source_refs=row.get("source_refs") or ["strategic_operators.yaml"],
            confidence="high" if latest and latest.get("confidence") == "high" else "medium",
            extras={
                "operator_id": row.get("id"),
                "entity_type": row.get("entity_type"),
                "watchlist_bucket": row.get("watchlist_bucket"),
                "relationship_proximity": prox.get("resolved"),
                "relationship_proximity_evidence": prox.get("evidence") or [],
                "mutual_connections": row.get("mutual_connections") or [],
                "vendor_relationships": row.get("vendor_relationships") or [],
                "recent_movements": movements,
                "market_signal_matches": [
                    {
                        "title": item.get("title"),
                        "url": item.get("url"),
                        "source_name": item.get("source_name"),
                        "published_at": item.get("published_at"),
                    }
                    for item in feeder[:3]
                ],
                "scores": scores,
            },
        ))
    _save_brief_item_ledger(_item_ledger)
    return candidates[:limit]


def _event_day_label(event: dict, today_iso: str) -> str:
    start = event.get("start") or ""
    day = start[:10]
    if day == today_iso:
        return "today"
    try:
        today_d = date.fromisoformat(today_iso)
        ev_d = date.fromisoformat(day)
    except ValueError:
        return "upcoming"
    if ev_d == today_d + timedelta(days=1):
        return "tomorrow"
    return "this_week"


def _meeting_prep_items(report: dict, *, limit: int = 10) -> list[dict]:
    """Return calendar events that should become prep/deliverable prompts.

    Calendar is only useful in the brief if it changes what Todd should do.
    This ranks meetings that have known relationships, active-thread ties,
    unknown attendees, or deliverable-shaped titles.
    """
    cal = report.get("calendar") or {}
    today_iso = report.get("today") or ""
    if not cal.get("fetched_at"):
        return []

    now_utc = datetime.now(timezone.utc)

    candidates: list[tuple[int, dict]] = []
    for bucket in ("today", "tomorrow", "this_week"):
        for ev in cal.get(bucket) or []:
            # RB-2026-07-05: a declined event must never generate a prep item
            # (found via the SCN Guest Invitation defect — Todd's RSVP was
            # "declined" in the source data, but nothing downstream checked
            # it). A meeting whose start time has already passed is stale
            # for the same reason (found via the Blackthorn Monthly Team
            # Meeting complaint) — prep items must not survive their meeting.
            if (ev.get("self_response") or "").lower() == "declined":
                continue
            try:
                ev_start_dt = datetime.fromisoformat(ev.get("start") or "")
                if ev_start_dt.tzinfo is None:
                    ev_start_dt = ev_start_dt.replace(tzinfo=timezone.utc)
                if ev_start_dt < now_utc:
                    continue
            except ValueError:
                pass
            matched = [a for a in ev.get("attendees_matched") or [] if a.get("id")]
            unknown = [a for a in ev.get("attendees_matched") or [] if not a.get("id")]
            threads = ev.get("matched_threads") or []
            companies = ev.get("active_thread_company_hits") or []
            title = ev.get("title") or "Untitled meeting"
            title_low = title.lower()
            # Personal appointments belong on the calendar, not in an
            # executive meeting-prep queue. They have no business outcome,
            # relationship objective, or deliverable to prepare.
            if any(term in title_low for term in (
                "ophthalmology", "eye appointment", "doctor appointment",
                "dental appointment", "dentist", "medical appointment",
            )):
                continue
            if _is_non_business_personal_event(ev):
                continue
            deliverable_hit = any(k in title_low for k in MEETING_DELIVERABLE_KEYWORDS)

            score = 0
            if bucket == "today":
                score += 60
            elif bucket == "tomorrow":
                score += 40
            else:
                score += 10
            score += min(len(matched) * 8, 24)
            score += 25 if threads else 0
            score += 12 if companies else 0
            score += 10 if unknown else 0
            score += 18 if deliverable_hit else 0
            if score <= 10:
                continue

            candidates.append((score, {
                "event": ev,
                "bucket": bucket,
                "day_label": _event_day_label(ev, today_iso),
                "matched_attendees": matched,
                "unknown_attendees": unknown,
                "active_thread_ids": threads,
                "active_thread_company_hits": companies,
                "deliverable_signal": deliverable_hit,
                "score": score,
            }))

    candidates.sort(key=lambda x: x[0], reverse=True)
    return [c for _, c in candidates[:limit]]


# RB 9.77 — RB-DEFECT-044: prep-time keyword heuristics for
# _compute_upcoming_preparation_requirements. Order matters — first match wins.
_PREP_TIME_RULES: tuple[tuple[tuple[str, ...], int, tuple[str, ...]], ...] = (
    (("interview",), 30, ("candidate/role background", "prior interview notes")),
    (("earnings", "board", "qbr", "quarterly business review"), 120,
     ("financial/board materials", "prior meeting notes")),
    (("pipeline", "forecast", "sales funnel", "sales review", "funnel review"), 30,
     ("pipeline report", "forecast updates", "open opportunities")),
)


def _prep_time_estimate(title: str, mp: dict | None = None) -> tuple[int, list[str]]:
    """Heuristic prep-time estimate (minutes) and required inputs for an event title.

    Falls back to signals already computed by _meeting_prep_items (deliverable
    wording, known attendees, active-thread ties) when no keyword rule matches.
    """
    title_low = (title or "").lower()
    for keywords, minutes, inputs in _PREP_TIME_RULES:
        if any(k in title_low for k in keywords):
            return minutes, list(inputs)
    if mp and mp.get("deliverable_signal"):
        return 30, ["deliverable/agenda materials"]
    if mp and (mp.get("matched_attendees") or mp.get("active_thread_ids")):
        return 15, ["relationship notes", "open loop status"]
    return 15, ["agenda review"]


def _compute_upcoming_preparation_requirements(report: dict) -> list[dict]:
    """RB-DEFECT-044 Daily Brief — "Upcoming Preparation Requirements".

    Buckets upcoming commitments into Within 24 Hours / Within 7 Days / Within
    30 Days, each with a heuristic prep-time estimate and required inputs, so
    prep windows are flagged proactively rather than only on the day of.

    Within 24h / 7 days draw on calendar_overlay (today/tomorrow/this_week —
    the only horizon calendar_overlay covers). Within 30 days draws on
    loop_ledger's "future" bucket (loops targeted >7 days out), since RB has
    no calendar data beyond 7 days.
    """
    items: list[dict] = []
    cal = report.get("calendar") or {}
    today_iso = report.get("today") or ""

    if cal.get("fetched_at"):
        for bucket, horizon, disposition in (
            ("today", "Within 24 Hours", "act_today"),
            ("tomorrow", "Within 7 Days", "monitor"),
            ("this_week", "Within 7 Days", "monitor"),
        ):
            for ev in cal.get(bucket) or []:
                # RB-2026-09-09: this calendar scan duplicates
                # _meeting_prep_items()'s today/tomorrow/this_week loop but
                # never got the personal-event exclusion added there on
                # 2026-09-06 after "Badgers Football vs Notre Dame" got
                # full meeting-prep treatment. Confirmed live: without this
                # check, personal sports games still get prep-time
                # estimates and "schedule prep before this event" language
                # here even though _meeting_prep_items correctly excludes
                # them. Same filter, same reasoning, this call site too.
                if (ev.get("self_response") or "").lower() == "declined":
                    continue
                if _is_non_business_personal_event(ev):
                    continue
                title = ev.get("title") or "Untitled meeting"
                start = ev.get("start") or ""
                deliverable_hit = any(
                    k in title.lower() for k in MEETING_DELIVERABLE_KEYWORDS
                )
                minutes, inputs = _prep_time_estimate(title, {
                    "deliverable_signal": deliverable_hit,
                    "matched_attendees": [a for a in ev.get("attendees_matched") or [] if a.get("id")],
                    "active_thread_ids": ev.get("matched_threads") or [],
                })
                items.append(_canonical_item(
                    title=f"{horizon} — {title}",
                    summary=(
                        f"Estimated prep time: {minutes} min. "
                        f"Required inputs: {', '.join(inputs)}."
                    ),
                    why_it_matters=(
                        f"{_event_day_label(ev, today_iso)} at {start[11:16] or 'unknown time'} — "
                        "preparation should be scheduled ahead of this event, not started "
                        "when it begins."
                    ),
                    recommended_action=f"Schedule {minutes} min of prep before {start[:16] or 'this event'}.",
                    disposition=disposition,
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["calendar_overlay"],
                    confidence="high",
                    extras={
                        "horizon": horizon,
                        "prep_minutes": minutes,
                        "required_inputs": inputs,
                        "event_start": start,
                        "event_id": ev.get("id"),
                    },
                ))

    # Within 30 days: loops targeted beyond the 7-day calendar horizon.
    try:
        today_dt = date.fromisoformat(today_iso) if today_iso else date.today()
        for L in report.get("loops", {}).get("future") or []:
            target = L.get("target")
            if not target:
                continue
            days_out = (target - today_dt).days
            if not (7 < days_out <= 30):
                continue
            minutes, inputs = _prep_time_estimate(L.get("description") or "")
            items.append(_canonical_item(
                title=f"Within 30 Days — {L.get('party')}: {L.get('id')}",
                summary=(
                    f"Loop due {target.isoformat()} ({days_out} days out). "
                    f"Estimated prep time: {minutes} min. "
                    f"Required inputs: {', '.join(inputs)}."
                ),
                why_it_matters=f"{L.get('description') or 'Open loop'} — target {target.isoformat()}.",
                recommended_action=f"Schedule {minutes} min of prep ahead of {target.isoformat()}.",
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[f"loop_ledger.{L.get('id')}"],
                confidence="medium",
                extras={
                    "horizon": "Within 30 Days",
                    "prep_minutes": minutes,
                    "required_inputs": inputs,
                    "loop_id": L.get("id"),
                },
            ))
    except Exception:  # noqa: BLE001
        pass

    if not items:
        items.append(_canonical_item(
            title="No upcoming preparation requirements detected",
            summary=(
                "No calendar events in the next 7 days or loop targets in the next "
                "30 days require dedicated prep time."
            ),
            grounding="system_detected",
            freshness="fresh",
            source_refs=["calendar_overlay", "loop_ledger"],
            confidence="medium",
            disposition="monitor",
        ))
    return items


# RB 9.84 — RB-DEFECT-044 "Learned Patterns": category labels mirror the
# keyword groups in _PREP_TIME_RULES so recurring meeting types can be
# detected even though their literal titles vary day to day.
_PREP_CATEGORY_RULES: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("Interview prep", ("interview",)),
    ("Earnings/board review", ("earnings", "board", "qbr", "quarterly business review")),
    ("Sales/pipeline review", ("pipeline", "forecast", "sales funnel", "sales review", "funnel review")),
)

_PREP_HISTORY_FILENAME = "prep_requirements_history.json"
_PREP_HISTORY_MAX_DAYS = 90
_LEARNED_PATTERN_MIN_OCCURRENCES = 3


def _prep_item_category(title: str) -> str:
    """Map a prep-requirement title to a recurring-pattern category, or
    "Other" if it doesn't match a recognized recurring meeting type."""
    title_low = (title or "").lower()
    for label, keywords in _PREP_CATEGORY_RULES:
        if any(k in title_low for k in keywords):
            return label
    return "Other"


def _prep_history_path() -> Path:
    return core.CACHE_DIR / _PREP_HISTORY_FILENAME


def _record_prep_requirements_history(report: dict, prep_items: list[dict]) -> None:
    """RB 9.84 — RB-DEFECT-044 "Learned Patterns": append today's
    upcoming_preparation_requirements items to a rolling history log so
    _compute_learned_patterns can detect recurring prep-time patterns.

    One entry per recognized category per day (today's entries replace any
    prior entry for today, so repeated same-day brief regenerations don't
    inflate counts). History is trimmed to the most recent
    _PREP_HISTORY_MAX_DAYS days.
    """
    today_iso = report.get("today") or ""
    if not today_iso:
        return

    path = _prep_history_path()
    try:
        history = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(history, dict) or not isinstance(history.get("days"), dict):
            history = {"days": {}}
    except (OSError, json.JSONDecodeError, FileNotFoundError):
        history = {"days": {}}

    today_entries: list[dict] = []
    for item in prep_items or []:
        extras = item.get("extras") or {}
        prep_minutes = extras.get("prep_minutes")
        if prep_minutes is None:
            continue
        title = item.get("title") or ""
        # Strip the "Within N Days — " horizon prefix before categorizing.
        bare_title = title.split(" — ", 1)[-1] if " — " in title else title
        category = _prep_item_category(bare_title)
        if category == "Other":
            continue
        today_entries.append({"category": category, "prep_minutes": prep_minutes})

    history["days"][today_iso] = today_entries

    if len(history["days"]) > _PREP_HISTORY_MAX_DAYS:
        for old_day in sorted(history["days"])[:-_PREP_HISTORY_MAX_DAYS]:
            del history["days"][old_day]

    try:
        core.CACHE_DIR.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(history, indent=2), encoding="utf-8")
    except OSError:
        pass


def _compute_learned_patterns(report: dict, sections: dict) -> list[dict]:
    """RB 9.84 — RB-DEFECT-044 (Daily Brief, "Learned Patterns"): surface
    recurring preparation-time patterns from upcoming_preparation_requirements
    history -- e.g. "Sales/pipeline review has required 30 min of
    preparation on 5 of the last 12 days tracked" -- so RB can proactively
    recommend prep windows for recurring meeting types, not just estimate
    prep time for each individual occurrence.

    A pattern is surfaced once a category has appeared on
    _LEARNED_PATTERN_MIN_OCCURRENCES distinct tracked days, using the mode
    prep-time estimate across those days.
    """
    items: list[dict] = []

    try:
        history = json.loads(_prep_history_path().read_text(encoding="utf-8"))
        days = history.get("days") or {}
    except (OSError, json.JSONDecodeError, FileNotFoundError):
        days = {}

    days_tracked = len(days)

    by_category: dict[str, list[int]] = {}
    for day_entries in days.values():
        seen_today: set[str] = set()
        for entry in day_entries or []:
            category = entry.get("category")
            minutes = entry.get("prep_minutes")
            if not category or minutes is None or category in seen_today:
                continue
            seen_today.add(category)
            by_category.setdefault(category, []).append(minutes)

    for category, minutes_list in sorted(by_category.items()):
        occurrences = len(minutes_list)
        if occurrences < _LEARNED_PATTERN_MIN_OCCURRENCES:
            continue
        mode_minutes = max(set(minutes_list), key=minutes_list.count)
        items.append(_canonical_item(
            title=f"Learned pattern: {category}",
            summary=(
                f"{category} has required {mode_minutes} min of preparation "
                f"on {occurrences} of the last {days_tracked} day(s) tracked."
            ),
            why_it_matters=(
                f"Recurring prep-time pattern detected -- RB can proactively "
                f"recommend a {mode_minutes}-min prep window before the next "
                f"{category.lower()}."
            ),
            recommended_action=(
                f"Schedule {mode_minutes} min of prep ahead of the next "
                f"{category.lower()}."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["prep_requirements_history"],
            confidence="medium",
            extras={
                "category": category,
                "prep_minutes": mode_minutes,
                "occurrences": occurrences,
                "days_tracked": days_tracked,
            },
        ))

    if not items:
        if days_tracked < _LEARNED_PATTERN_MIN_OCCURRENCES:
            items.append(_canonical_item(
                title="Learned patterns: insufficient history",
                summary=(
                    f"Preparation-time tracking has run for {days_tracked} "
                    f"day(s); at least {_LEARNED_PATTERN_MIN_OCCURRENCES} are "
                    "needed before recurring patterns can be identified."
                ),
                why_it_matters="Confirms preparation-history tracking is running.",
                recommended_action="No action required -- check back after more days are tracked.",
                disposition="ignore",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["prep_requirements_history"],
                confidence="high",
                extras={"days_tracked": days_tracked},
            ))
        else:
            items.append(_canonical_item(
                title="No recurring preparation patterns detected",
                summary=(
                    f"No preparation-requirement category has recurred "
                    f"{_LEARNED_PATTERN_MIN_OCCURRENCES}+ times across the "
                    f"{days_tracked} day(s) tracked."
                ),
                why_it_matters="Confirms the pattern scan ran and found nothing material -- not a missed check.",
                recommended_action="No action required.",
                disposition="ignore",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["prep_requirements_history"],
                confidence="high",
                extras={"days_tracked": days_tracked},
            ))

    return items


def _compute_this_week_priorities(report: dict, sections: dict) -> list[dict]:
    """RB 9.79 — RB-DEFECT-044 (Daily Brief, "This Week"): near-term priorities
    landing in the next 2-7 days -- calendar events with a deliverable or
    relationship signal, loops closing this week, upcoming earnings calls for
    watched companies, and active interview/recruiter opportunities.

    Distinct from `upcoming_preparation_requirements` (prep-time estimates) and
    `decision_layer` (today's top decisions) -- this section answers "what's
    coming at me this week that I should be tracking now?"
    """
    items: list[dict] = []

    for mp in _meeting_prep_items(report):
        if mp["bucket"] != "this_week":
            continue
        if not (mp["deliverable_signal"] or mp["matched_attendees"] or mp["active_thread_ids"]):
            continue
        ev = mp["event"]
        title = ev.get("title") or "Untitled meeting"
        start = ev.get("start") or ""
        reasons = []
        if mp["deliverable_signal"]:
            reasons.append("deliverable-shaped title")
        if mp["matched_attendees"]:
            reasons.append(f"{len(mp['matched_attendees'])} known contact(s)")
        if mp["active_thread_ids"]:
            reasons.append(f"tied to active thread(s) {', '.join(mp['active_thread_ids'])}")
        items.append(_canonical_item(
            title=f"This week: {title}",
            summary=f"{mp['day_label'].title()} at {start[11:16] or 'unknown time'} — {'; '.join(reasons)}.",
            why_it_matters="Near-term meetings with known relationships or deliverable framing need lead time to prepare well.",
            recommended_action=f"Block prep time ahead of {start[:16] or 'this event'}.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["calendar_overlay"],
            confidence="high",
            extras={"event_start": start, "event_id": ev.get("id")},
        ))

    # RB-DEFECT-2026-07-27: this used to also list every "this_week" bucket
    # loop here (title "This week: {id} — {party}", why_it_matters "Loop
    # target: {date}.") -- but _compute_my_priorities' loops_and_obligations
    # already renders the exact same loops under "Closing this week:" with
    # richer detail (full description + a real recommended next step, not
    # just the target date). Assessed for overlap/noise: the same 5 loops
    # were appearing twice in one document, once with real context and once
    # as a bare date restatement. My Priorities is the canonical place for
    # loop detail; This Week now covers only what it doesn't already show
    # (deliverable-shaped meetings, earnings calls, active interviews).

    for ei in (sections.get("earnings_intelligence") or []):
        ext = ei.get("extras") or {}
        if ext.get("earnings_type") == "pre_earnings_alert" and (ext.get("days_until_report") or 99) <= 7:
            items.append(_canonical_item(
                title=f"This week: {ext.get('company', '')} earnings call",
                summary=ei.get("summary") or "",
                why_it_matters=ei.get("why_it_matters") or "",
                recommended_action=ei.get("recommended_action") or "",
                disposition=ei.get("disposition", "monitor"),
                grounding=ei.get("grounding", "inferred"),
                freshness=ei.get("freshness", "fresh"),
                source_refs=list(dict.fromkeys((ei.get("source_refs") or []) + ["earnings_intelligence"])),
                confidence=ei.get("confidence", "medium"),
                extras=ext,
            ))

    _INTERVIEW_KEYWORDS = ("interview", "screen", "recruiter", "panel")
    for opp in (sections.get("opportunity_board") or []):
        if opp.get("disposition") not in ("act", "act_today"):
            continue
        title_low = (opp.get("title") or "").lower()
        if any(k in title_low for k in _INTERVIEW_KEYWORDS):
            items.append(_canonical_item(
                title=f"This week: {(opp.get('title') or '').replace('[ACTIVE] ', '').replace('[WAITING] ', '')}",
                summary=opp.get("summary") or "",
                why_it_matters=opp.get("why_it_matters") or "",
                recommended_action=opp.get("recommended_action") or "",
                disposition=opp.get("disposition", "monitor"),
                grounding=opp.get("grounding", "inferred"),
                freshness=opp.get("freshness", "fresh"),
                source_refs=list(dict.fromkeys((opp.get("source_refs") or []) + ["opportunity_board"])),
                confidence=opp.get("confidence", "medium"),
            ))

    if not items:
        items.append(_canonical_item(
            title="No near-term (this week) priorities detected",
            summary="No deliverable-shaped meetings, upcoming earnings calls, or active interviews detected for the next 2-7 days.",
            why_it_matters="Confirms the this-week scan ran and found nothing material — not a missed check.",
            recommended_action="No action required.",
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["calendar_overlay", "earnings_intelligence", "opportunity_board"],
            confidence="high",
        ))

    return items


def _compute_this_month_priorities(report: dict, sections: dict) -> list[dict]:
    """RB 9.83 — RB-DEFECT-044 (Daily Brief, "This Month"): strategic
    priorities landing in the next 8-30 days -- loop targets beyond this
    week's horizon, upcoming earnings calls in the 30-day window, and
    longer-running active-opportunity-pipeline items.

    Distinct from `this_week_priorities` (2-7 days, near-term awareness) and
    `horizon_watch` (31-90 days, not yet actionable) -- this section answers
    "what strategic work should I be making progress on this month?"
    """
    items: list[dict] = []
    today_iso = report.get("today") or ""

    try:
        today_dt = date.fromisoformat(today_iso) if today_iso else date.today()
        for L in report.get("loops", {}).get("future") or []:
            target = L.get("target")
            if not target:
                continue
            days_out = (target - today_dt).days
            if not (7 < days_out <= 30):
                continue
            items.append(_canonical_item(
                title=f"This month: {L.get('id')} — {L.get('party')}",
                summary=L.get("description") or "",
                why_it_matters=f"Loop target: {target.isoformat()} ({days_out} days out).",
                recommended_action=f"Make progress on {L.get('id')} ahead of {target.isoformat()}.",
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[f"loop_ledger.{L.get('id')}"],
                confidence="high",
                extras={"loop_id": L.get("id"), "target_date": target.isoformat()},
            ))
    except Exception:  # noqa: BLE001
        pass

    for ei in (sections.get("earnings_intelligence") or []):
        ext = ei.get("extras") or {}
        days_out = ext.get("days_until_report")
        if ext.get("earnings_type") == "pre_earnings_alert" and days_out is not None and 7 < days_out <= 30:
            items.append(_canonical_item(
                title=f"This month: {ext.get('company', '')} earnings call",
                summary=ei.get("summary") or "",
                why_it_matters=ei.get("why_it_matters") or "",
                recommended_action=ei.get("recommended_action") or "",
                disposition=ei.get("disposition", "monitor"),
                grounding=ei.get("grounding", "inferred"),
                freshness=ei.get("freshness", "fresh"),
                source_refs=list(dict.fromkeys((ei.get("source_refs") or []) + ["earnings_intelligence"])),
                confidence=ei.get("confidence", "medium"),
                extras=ext,
            ))

    for opp in (sections.get("opportunity_board") or []):
        if opp.get("disposition") != "monitor":
            continue
        ext = opp.get("extras") or {}
        if (ext.get("evidence_age_days") or 0) < 14:
            continue
        items.append(_canonical_item(
            title=f"This month: {(opp.get('title') or '').replace('[ACTIVE] ', '').replace('[WAITING] ', '')}",
            summary=opp.get("summary") or "",
            why_it_matters=opp.get("why_it_matters") or "",
            recommended_action=opp.get("recommended_action") or "",
            disposition="monitor",
            grounding=opp.get("grounding", "inferred"),
            freshness=opp.get("freshness", "fresh"),
            source_refs=list(dict.fromkeys((opp.get("source_refs") or []) + ["opportunity_board"])),
            confidence=opp.get("confidence", "medium"),
            extras={"evidence_age_days": ext.get("evidence_age_days")},
        ))

    if not items:
        items.append(_canonical_item(
            title="No strategic (this month) priorities detected",
            summary="No loop targets in the 8-30 day window, upcoming earnings calls in the 30-day window, or longer-running active opportunities detected.",
            why_it_matters="Confirms the this-month scan ran and found nothing material — not a missed check.",
            recommended_action="No action required.",
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["loop_ledger", "earnings_intelligence", "opportunity_board"],
            confidence="high",
        ))

    return items


def _build_command_center(sections: dict, report: dict) -> list[dict]:
    """Morning operating board: the brief's highest-leverage answer.

    This converts the detailed sections into "what should I do with my day?"
    without becoming another dashboard.
    """
    loops = report.get("loops") or {}
    rsr = report.get("relationship_signals") or {}
    msr = report.get("market_signals") or {}
    out: list[dict] = []

    # Cross-channel opportunity stakeholder signals: critical-urgency items
    # (e.g. cross-channel-corroborated "final feedback" / decision-stage
    # milestones on an active opportunity) lead the command center, ahead of
    # everything else — these are time-sensitive relationship-state changes,
    # not routine task work.
    for item in sections.get("opportunity_signals", []):
        if item.get("disposition") == "act_today":
            out.append(item)

    act_items = [
        item for item in (
            sections.get("top_priorities_today", [])
            + sections.get("meeting_prep_and_deliverables", [])
            + sections.get("sent_followups_awaiting_response", [])
            + sections.get("last_24h_relationship_signals", [])
        )
        if item.get("disposition") == "act_today"
    ]
    if act_items:
        top = act_items[:3]
        out.append(_canonical_item(
            title="Today's operating board",
            summary="Top moves: " + " | ".join(i["title"] for i in top),
            why_it_matters=(
                "This is the minimum viable day: the few moves most likely to "
                "protect timing, relationships, revenue, or preparation."
            ),
            recommended_action="Start with these before generic task work.",
            disposition="act_today",
            grounding="inferred",
            freshness="fresh",
            source_refs=[r for i in top for r in i.get("source_refs", [])][:6],
            confidence="high",
            action_options=["create_todays_loops", "draft_next_actions", "defer_lower_priority_items"],
        ))

    meeting_count = sum(
        1 for i in (sections.get("meeting_prep_and_deliverables") or [])
        if not str(i.get("title") or "").lower().startswith("calendar source coverage")
    )
    if meeting_count:
        out.append(_canonical_item(
            title="Meeting prep queue",
            summary=f"{meeting_count} meeting(s) have prep, deliverable, relationship, or timing implications.",
            why_it_matters="Meetings create obligations; prep work should be visible before the calendar starts moving.",
            recommended_action="Create meeting prep briefs for review for the material meetings.",
            disposition="ask_todd",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[r for i in sections.get("meeting_prep_and_deliverables", []) for r in i.get("source_refs", [])][:6],
            confidence="high",
            action_options=["create_meeting_prep", "open_prep_loops", "ignore_meeting_prep"],
        ))

    sent = sections.get("sent_followups_awaiting_response") or []
    overdue = [i for i in sent if i.get("disposition") == "act_today"]
    waiting = [i for i in sent if i.get("disposition") == "monitor"]
    if overdue or waiting:
        out.append(_canonical_item(
            title="Waiting-on state",
            summary=f"{len(overdue)} overdue outbound(s); {len(waiting)} still inside expected-response windows.",
            why_it_matters=(
                "Separating overdue follow-up from legitimate waiting prevents task anxiety "
                "and avoids nudging too early."
            ),
            recommended_action=(
                "Follow up on overdue items; leave in-window waiting loops alone."
                if overdue else "Monitor waiting loops; no follow-up needed yet."
            ),
            disposition="act_today" if overdue else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[r for i in sent[:6] for r in i.get("source_refs", [])][:6],
            confidence="high",
            action_options=["draft_overdue_followups", "create_waiting_loops", "mark_resolved"],
        ))

    if loops.get("overdue") or loops.get("due_today"):
        out.append(_canonical_item(
            title="Loop risk",
            summary=f"{len(loops.get('overdue') or [])} overdue loop(s); {len(loops.get('due_today') or [])} due today.",
            why_it_matters="Open loops are the operating memory. Risk is timing slippage, not merely an unfinished task.",
            recommended_action="Close, re-date, or convert ambiguous loops into waiting loops.",
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["loop_ledger"],
            confidence="high",
            action_options=["review_loops", "close_verified_loops", "redate_loops", "convert_to_waiting"],
        ))

    # Publication status — surface where the brief will live and whether the
    # ChatGPT CTA URL is wired. Best-effort: failure never breaks the command center.
    try:
        import publish as _pub  # type: ignore
        _today_for_pub = None
        try:
            _today_for_pub = date.fromisoformat(report.get("today")) if report.get("today") else None
        except (TypeError, ValueError):
            _today_for_pub = None
        _chatgpt_url = _pub._resolve_chatgpt_brief_url()  # type: ignore[attr-defined]
        _cta_url = _chatgpt_url or _pub.public_url_for(_today_for_pub or date.today(), latest=True)
        if _cta_url:
            out.append(_canonical_item(
                title="ChatGPT briefing destination wired" if _chatgpt_url else "Publication destination wired",
                summary=(
                    f"Morning email CTA opens the RB ChatGPT cockpit at {_cta_url}"
                    if _chatgpt_url else
                    f"Morning email CTA points to {_cta_url}"
                ),
                why_it_matters=(
                    "Chat is the operational UX. The email is only the doorbell; "
                    "the full brief should be read and acted on inside ChatGPT."
                    if _chatgpt_url else
                    "Email CTA opens the RB operational layer, not Codex/Claude/local files."
                ),
                recommended_action=(
                    "Use the RB Custom GPT daily-brief action to read the current full brief."
                    if _chatgpt_url else
                    "Run `python3 system/scripts/publish.py --write --confirm` "
                    "from the 05:00 LaunchAgent to refresh the artifact at this URL."
                ),
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[
                    "settings.json:daily_briefing.delivery.chatgpt_brief_url"
                    if _chatgpt_url else
                    "settings.json:daily_briefing.operational_layer.public_url_base"
                ],
                confidence="high",
                action_options=["open_chatgpt_brief", "publish_now", "preview_email"],
            ))
        else:
            out.append(_canonical_item(
                title="ChatGPT briefing destination pending",
                summary=(
                    "The full brief is generated locally and retrievable through the RB API, "
                    "but no stable ChatGPT / Custom GPT URL is configured for the email CTA."
                ),
                why_it_matters=(
                    "Per settings.json delivery contract, ChatGPT is the operational UX. "
                    "The morning email must open ChatGPT, not a local file, Codex, Claude, or a placeholder."
                ),
                recommended_action=(
                    "Set daily_briefing.delivery.chatgpt_brief_url in settings.json "
                    "(or export RB_CHATGPT_BRIEF_URL) to the stable RB Custom GPT URL, then re-run publish.py."
                ),
                disposition="ask_todd",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["settings.json:daily_briefing.delivery.chatgpt_brief_url"],
                confidence="high",
                action_options=["set_chatgpt_brief_url", "open_rb_custom_gpt", "monitor"],
            ))
    except Exception:  # noqa: BLE001
        pass

    pv_items = sections.get("passive_verification_candidates") or []
    auto_count = sum(1 for i in pv_items if i.get("title", "").startswith("Auto-close ready"))
    possible_count = sum(1 for i in pv_items if i.get("title", "").startswith("Possible closure"))
    if auto_count or possible_count:
        out.append(_canonical_item(
            title="Loops RB can auto-close",
            summary=(
                f"{auto_count} loop(s) have canonical evidence supporting auto-closure"
                + (f"; {possible_count} more need operator review." if possible_count else ".")
            ),
            why_it_matters=(
                "Closing loops the system already verified keeps the ledger honest "
                "and removes manual cleanup from Todd's plate."
            ),
            recommended_action=(
                "Run the auto-close batch (POST /passive_verification with confirm=true), "
                "or review evidence first."
                if auto_count else
                "Review possible-resolution evidence and decide which loops to close."
            ),
            disposition="act_today" if auto_count else "ask_todd",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[r for i in pv_items for r in i.get("source_refs", [])][:6],
            confidence="high" if auto_count else "medium",
            action_options=["auto_close_batch", "review_evidence", "keep_all_open"],
        ))

    signal_counts = rsr.get("signal_counts_by_relevance") or {}
    market_count = msr.get("top_count") or 0
    if signal_counts or market_count:
        out.append(_canonical_item(
            title="New signal state",
            summary=(
                f"RI: {signal_counts.get('high', 0)} high, {signal_counts.get('medium', 0)} medium; "
                f"market/operator: {market_count} surfaced."
            ),
            why_it_matters="Signals only matter when they change a relationship, opportunity, prep need, or action.",
            recommended_action="Act on high RI; monitor medium/market items unless tied to a named thread.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh" if not rsr.get("stale_sources") else "stale_source_limited",
            source_refs=["relationship_signals", "market_signals"],
            confidence="medium" if rsr.get("stale_sources") else "high",
            action_options=["review_signals", "create_watch_loop", "mark_noise"],
        ))

    ignored = sections.get("what_to_ignore") or []
    if ignored:
        out.append(_canonical_item(
            title="Noise RB suppressed",
            summary=f"{len(ignored)} category/categories suppressed so the brief stays calm.",
            why_it_matters="Visible suppression builds trust that RB saw the noise and chose not to burden the day with it.",
            recommended_action="Keep ignored unless Todd wants one category restored.",
            disposition="ignore",
            grounding="inferred",
            freshness="fresh",
            source_refs=[r for i in ignored for r in i.get("source_refs", [])][:6],
            confidence="high",
            action_options=["keep_ignored", "restore_to_watchlist"],
        ))

    questions = sections.get("reconciliation_prompts") or []
    if questions:
        out.append(_canonical_item(
            title="One decision needed",
            summary=questions[0]["summary"],
            why_it_matters="RB should ask for the smallest clarification that improves future automation.",
            recommended_action=questions[0]["recommended_action"],
            disposition="ask_todd",
            grounding="inferred",
            freshness="fresh",
            source_refs=questions[0].get("source_refs", []),
            confidence="medium",
            action_options=["answer_question", "defer_question", "suppress_question"],
        ))

    if not out:
        out.append(_canonical_item(
            title="No critical operating moves detected",
            summary="No act-today items crossed the current threshold from the connected sources.",
            why_it_matters=(
                "A quiet board is only trustworthy when the prep summary shows the right "
                "sources were fresh enough to support that conclusion."
            ),
            recommended_action="Use the day for planned work; review stale sources before assuming the board is fully quiet.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh" if not rsr.get("stale_sources") else "stale_source_limited",
            source_refs=["daily_prep_summary"],
            confidence="medium",
            action_options=["continue_planned_work", "refresh_sources", "create_manual_loop"],
        ))

    return out[:7]


def _scan_row(*, source_name: str, scan_window: str, scan_status: str,
              evidence_count: int, ri_count: int, actions_taken: list[str] | None = None,
              confidence: str = "medium", freshness: str = "fresh",
              source_refs: list[str] | None = None,
              ri_assessment_summary: dict | None = None) -> dict:
    """Build a proof row for the Daily Prep Summary.

    `ri_assessment_summary` carries the P-036 7-status breakdown for this
    source.  When present, `actions_taken` should use P-036 status slugs
    (ri_assessed_proposed, ri_assessed_blocked, ri_assessed_duplicate,
    ri_assessed_irrelevant, ri_source_unavailable) rather than generic
    negative_scan_recorded.  Consumers that only read `actions_taken` get
    the same signal; consumers that read `ri_assessment_summary` get the
    full breakdown without unparsing action strings.
    """
    no_ri = ri_count == 0
    return {
        "source_name": source_name,
        "scan_window": scan_window,
        "scan_status": scan_status,
        "evidence_count": evidence_count,
        "ri_found": ri_count,
        "no_actionable_ri": no_ri,
        "actions_taken": actions_taken or ([] if no_ri else ["surfaced_in_relationship_signals"]),
        "confidence": confidence,
        "freshness": freshness,
        "source_refs": source_refs or [],
        # P-036: per-source assessment status breakdown.  Always present;
        # null fields mean the source does not produce a formal assessment.
        "ri_assessment_summary": ri_assessment_summary or {
            "recorded": 0, "proposed": 0, "duplicate": 0,
            "blocked": 0, "irrelevant": 0, "unavailable": 0,
        },
    }


def build_daily_prep_summary(report: dict) -> dict:
    """Prove the daily operating environment was prepared.

    This is intentionally derived from the same overlays and relationship
    signal report the brief already uses. It turns "no RI found" into an
    explicit, trust-building scan result instead of silent absence.
    """
    rsr = report.get("relationship_signals") or {}
    source_states = {s.get("name"): s for s in (rsr.get("source_states") or [])}
    signal_counts = rsr.get("signal_counts_by_source") or {}
    window = f"{(rsr.get('window_start') or '')[:16]} to {(rsr.get('window_end') or '')[:16]}"

    def _freshness(name: str) -> tuple[str, str]:
        state = source_states.get(name) or {}
        if state.get("stale"):
            return "stale_or_missing", "low" if state.get("age_hours") is None else "medium"
        return "fresh", "high"

    rows: list[dict] = []

    em = report.get("email") or {}
    freshness, conf = _freshness("email")
    rows.append(_scan_row(
        source_name="email",
        scan_window=window,
        scan_status="scanned" if em.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=(
            len(em.get("from_baseline") or [])
            + len(em.get("active_thread_company_hits") or [])
            + len(em.get("sent_followups") or [])
        ),
        ri_count=signal_counts.get("email", 0),
        actions_taken=[
            "relationship_signals_ranked" if signal_counts.get("email", 0) else "negative_scan_recorded",
            "sent_followups_checked",
        ],
        confidence=conf,
        freshness=freshness,
        source_refs=["email_overlay", "relationship_signals.source_states.email"],
    ))

    cal = report.get("calendar") or {}
    freshness, conf = _freshness("calendar")
    rows.append(_scan_row(
        source_name="calendar",
        scan_window=window,
        scan_status="scanned" if cal.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=sum(len(cal.get(k) or []) for k in ("today", "tomorrow", "this_week")),
        ri_count=signal_counts.get("calendar", 0),
        actions_taken=[
            "meeting_context_and_prep_needs_checked"
            if any(cal.get(k) for k in ("today", "tomorrow", "this_week"))
            else "negative_scan_recorded"
        ],
        confidence=conf,
        freshness=freshness,
        source_refs=["calendar_overlay", "relationship_signals.source_states.calendar"],
    ))

    interaction = report.get("interaction") or {}
    freshness, conf = _freshness("messages")
    rows.append(_scan_row(
        source_name="sms_messages",
        scan_window=window,
        scan_status="scanned" if interaction.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=len(interaction.get("matched_recent") or []),
        ri_count=signal_counts.get("messages_calls", 0),
        actions_taken=["direct_interactions_checked" if signal_counts.get("messages_calls", 0) else "negative_scan_recorded"],
        confidence=conf,
        freshness=freshness,
        source_refs=["interaction_overlay", "relationship_signals.source_states.messages"],
    ))

    freshness, conf = _freshness("calls")
    rows.append(_scan_row(
        source_name="phone_logs",
        scan_window=window,
        scan_status="scanned" if interaction.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=len(interaction.get("matched_recent") or []),
        ri_count=signal_counts.get("messages_calls", 0),
        actions_taken=["direct_interactions_checked" if signal_counts.get("messages_calls", 0) else "negative_scan_recorded"],
        confidence=conf,
        freshness=freshness,
        source_refs=["interaction_overlay", "relationship_signals.source_states.calls"],
    ))

    social = report.get("social") or {}
    freshness, conf = _freshness("social")
    rows.append(_scan_row(
        source_name="linkedin_public_posts",
        scan_window=window,
        scan_status="scanned" if social.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=len(social.get("from_baseline") or []) + len(social.get("active_thread_company_hits") or []),
        ri_count=signal_counts.get("social", 0),
        actions_taken=[
            "public_posts_checked_for_ri_and_market_signals"
            if signal_counts.get("social", 0) or social.get("from_baseline") or social.get("active_thread_company_hits") or social.get("topic_signal")
            else "negative_scan_recorded"
        ],
        confidence=conf,
        freshness=freshness,
        source_refs=["social_overlay", "relationship_signals.source_states.social"],
    ))

    # LinkedIn messaging — call the parser overlay so the scan row carries
    # real direction/matching/RI counts instead of just a file-exists check.
    linkedin_msg_path = core.PROJECT_DIR / "system" / "inbox" / "linkedin.messages.json"
    li_overlay: dict = {}
    try:
        import linkedin_messaging as _lim  # type: ignore
        li_overlay = _lim.linkedin_message_overlay()
    except Exception:  # noqa: BLE001
        li_overlay = {}
    li_totals = (li_overlay.get("totals") or {})
    li_in_window = int(li_totals.get("messages_in_window") or 0)
    li_ri_count = len(li_overlay.get("inbound_ri_candidates") or [])
    li_proposed_updates = len(li_overlay.get("proposed_last_touch_updates") or [])
    li_unmatched = len(li_overlay.get("unmatched_recurring_participants") or [])
    rows.append(_scan_row(
        source_name="linkedin_messaging",
        scan_window=window,
        scan_status="scanned" if linkedin_msg_path.exists() else "missing_or_not_fetched",
        evidence_count=int(li_totals.get("messages_total") or 0),
        ri_count=li_ri_count,
        actions_taken=(
            [
                f"linkedin_messages_parsed: {li_in_window} in window "
                f"(in={li_totals.get('inbound_in_window',0)}, "
                f"out={li_totals.get('outbound_in_window',0)})",
                f"matched_contacts={li_totals.get('matched_count',0)}; "
                f"proposed_last_touch_updates={li_proposed_updates}; "
                f"unmatched_recurring={li_unmatched}",
            ]
            if linkedin_msg_path.exists() else
            ["not_available_in_current_social_inputs"]
        ),
        confidence="high" if li_ri_count else ("medium" if linkedin_msg_path.exists() else "low"),
        freshness="fresh" if linkedin_msg_path.exists() else "stale_or_missing",
        source_refs=["linkedin_export.messages", "system/inbox/linkedin.messages.json"],
    ))

    soc_out = report.get("social_outbound") or {}
    freshness, conf = _freshness("social_outbound")
    rows.append(_scan_row(
        source_name="linkedin_own_post_engagement",
        scan_window=window,
        scan_status="scanned" if soc_out.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=len(soc_out.get("active_thread_engagement") or []),
        ri_count=signal_counts.get("social_outbound", 0),
        actions_taken=["own_post_engagement_checked" if signal_counts.get("social_outbound", 0) else "negative_scan_recorded"],
        confidence=conf,
        freshness=freshness,
        source_refs=["social_outbound_overlay", "relationship_signals.source_states.social_outbound"],
    ))

    ri_recent = report.get("ri_events_recent") or {}
    ri_count = len(ri_recent.get("newly_captured") or []) + len(ri_recent.get("proposed_unconfirmed") or [])
    rows.append(_scan_row(
        source_name="uploaded_ri_events",
        scan_window=window,
        scan_status="scanned" if ri_recent.get("available", True) else "unavailable",
        evidence_count=sum(len(ri_recent.get(k) or []) for k in ("newly_captured", "proposed_unconfirmed", "historical_uploaded", "rejected_today")),
        ri_count=ri_count,
        actions_taken=["ri_event_queue_checked" if ri_count else "negative_scan_recorded"],
        confidence="high" if ri_recent.get("available", True) else "low",
        freshness="fresh",
        source_refs=["ri_events_recent"],
    ))

    pri = report.get("passive_ri_ingest") or {}
    pri_written = len(pri.get("events_written") or [])
    pri_dup = len(pri.get("duplicates_skipped") or [])
    pri_blocked = sum(
        len(pri.get(b) or []) for b in (
            "blocked_low_confidence", "blocked_stale_source",
            "blocked_unmatched_entity", "blocked_no_date", "blocked_validation_error",
        )
    )
    pri_unavail = len(pri.get("source_unavailable") or [])
    pri_candidates = pri.get("candidates_seen") or 0
    # P-036: use the formal ri_assessment_summary if present (attached by
    # passive_ri_ingest._attach_ingest_ri_assessments); fall back to manual
    # count for older cache files.
    pri_assessment = pri.get("ri_assessment_summary") or {
        "recorded": 0,
        "proposed": pri_written,
        "duplicate": pri_dup,
        "blocked": pri_blocked,
        "irrelevant": 0,
        "unavailable": pri_unavail,
    }
    # P-036 action slugs — tell the story without repeating the numbers
    # redundantly in both actions_taken and ri_assessment_summary.
    pri_actions: list[str] = []
    if pri_written:
        pri_actions.append(f"ri_assessed_proposed:{pri_written}")
    if pri_dup:
        pri_actions.append(f"ri_assessed_duplicate:{pri_dup}")
    if pri_blocked:
        pri_actions.append(f"ri_assessed_blocked:{pri_blocked}")
    if pri_unavail:
        pri_actions.append(f"ri_source_unavailable:{pri_unavail}")
    if not pri_actions:
        pri_actions = ["ri_assessed_irrelevant"] if pri else ["not_run"]
    rows.append(_scan_row(
        source_name="passive_ri_ingest",
        scan_window=window,
        scan_status="scanned" if pri else "not_run",
        evidence_count=pri_candidates,
        ri_count=pri_written,
        actions_taken=pri_actions,
        confidence="high" if pri and not pri_unavail else "medium",
        freshness="fresh" if pri else "stale_source_limited",
        source_refs=["passive_ri_ingest.json"],
        ri_assessment_summary=pri_assessment,
    ))

    loops = report.get("loops") or {}
    open_loop_count = sum(len(loops.get(k) or []) for k in ("overdue", "due_today", "this_week", "future"))
    rows.append(_scan_row(
        source_name="open_loops",
        scan_window=f"as of {report.get('today')}",
        scan_status="scanned",
        evidence_count=open_loop_count,
        ri_count=len(loops.get("overdue") or []) + len(loops.get("due_today") or []),
        actions_taken=["loop_buckets_computed"],
        confidence="high",
        freshness="fresh",
        source_refs=["loop_ledger"],
    ))

    msr = report.get("market_signals") or {}
    rows.append(_scan_row(
        source_name="industry_watchlist",
        scan_window="last 36h freshness threshold",
        scan_status="scanned" if msr.get("fetched_at") else "missing_or_not_fetched",
        evidence_count=msr.get("input_count", 0) or 0,
        ri_count=msr.get("top_count", 0) or 0,
        actions_taken=["market_signals_ranked" if (msr.get("top_count", 0) or 0) else "negative_scan_recorded"],
        confidence="medium" if msr.get("stale") else "high",
        freshness="stale_or_missing" if msr.get("stale") else "fresh",
        source_refs=["market_signals"],
    ))

    pei_report = report.get("passive_email_intelligence") or {}
    pei_tel = pei_report.get("telemetry") or {}
    spam_cov = pei_tel.get("spam_trash_coverage") or {}
    rows.append(_scan_row(
        source_name="passive_email_intelligence",
        scan_window=f"last {pei_report.get('scan_window_days', 30)}d email metadata/snippets",
        scan_status="scanned" if not pei_report.get("error") else "failed",
        evidence_count=int(pei_tel.get("threads_scanned") or 0),
        ri_count=int(pei_tel.get("relevant_headlines_extracted") or 0),
        actions_taken=[
            f"newsletters_scanned:{pei_tel.get('newsletters_scanned', 0)}",
            f"deep_dives_triggered:{pei_tel.get('deep_dives_triggered', 0)}",
            f"noise_suppressed:{pei_tel.get('noise_suppressed', 0)}",
            f"spam_trash_coverage:{spam_cov.get('coverage_status', 'unknown')}",
        ],
        confidence="medium" if pei_tel.get("deep_dives_blocked_no_link") else "high",
        freshness="fresh" if not pei_report.get("error") else "stale_or_missing",
        source_refs=["passive_email_intelligence.json", "email_intelligence_sources.json"],
    ))

    source_health = report.get("source_health") or {}
    if source_health:
        health_sources = source_health.get("sources") or {}
        for name, row in health_sources.items():
            if not isinstance(row, dict):
                continue
            # Keep source_health as a first-class prep surface without
            # duplicating every internal derived cache in the visible rows.
            if int(row.get("tier") or 0) > 3:
                continue
            rows.append(_scan_row(
                source_name=f"source_health:{name}",
                scan_window=f"as of {source_health.get('generated_at') or 'unknown'}",
                scan_status=row.get("status") or "unknown",
                evidence_count=1 if row.get("last_refreshed_at") else 0,
                ri_count=0,
                actions_taken=[row.get("reason") or "health_status_recorded"],
                confidence="high" if row.get("status") == "refreshed" else "medium",
                freshness="fresh" if row.get("status") == "refreshed" else "stale_or_missing",
                source_refs=["source_health.json", f"source_health.sources.{name}"],
            ))

    smr = report.get("strategic_memory") or {}
    rows.append(_scan_row(
        source_name="persistent_strategic_memory",
        scan_window="durable memory store",
        scan_status="scanned",
        evidence_count=smr.get("count", 0) or 0,
        ri_count=len(smr.get("top") or []),
        actions_taken=[
            "strategic_memory_loaded_for_daily_brief_weighting"
            if (smr.get("count", 0) or 0) else
            "negative_scan_recorded"
        ],
        confidence="high",
        freshness="manual_context",
        source_refs=["strategic_memory"],
    ))

    total_ri = sum(r["ri_found"] for r in rows)
    negative_sources = sum(1 for r in rows if r["no_actionable_ri"])
    stale_sources = sum(1 for r in rows if r["freshness"] != "fresh")

    # P-036: aggregate ri_assessment_summary across all proof rows so
    # consumers can read the full 7-status picture from a single dict.
    agg_assessment: dict[str, int] = {
        "recorded": 0, "proposed": 0, "duplicate": 0,
        "blocked": 0, "irrelevant": 0, "unavailable": 0,
    }
    for r in rows:
        for status, count in (r.get("ri_assessment_summary") or {}).items():
            if status in agg_assessment:
                agg_assessment[status] += int(count or 0)

    # Also fold in the relationship_signals ri_assessment_summary if present,
    # since those signals feed into rows but don't have their own scan row.
    rsr_assessment = rsr.get("ri_assessment_summary") or {}
    for status in ("proposed", "blocked"):
        agg_assessment[status] += int(rsr_assessment.get(status) or 0)

    return {
        "prepared_at": (rsr.get("window_end") or ""),
        "scan_window": window,
        "totals": {
            "sources_scanned": len(rows),
            "relationship_signals_detected": total_ri,
            "sources_with_no_actionable_ri": negative_sources,
            "stale_or_missing_sources": stale_sources,
            "open_loops_checked": open_loop_count,
            "overdue_loops": len(loops.get("overdue") or []),
            "due_today_loops": len(loops.get("due_today") or []),
            "market_signals_elevated": msr.get("top_count", 0) or 0,
        },
        # P-036: full 7-status aggregate across all assessed sources.
        # "always assess" — these counts are always present even when zero.
        # "don't always display" — brief renderers should surface only
        # proposed and blocked when they're decision-relevant.
        "ri_assessment_totals": agg_assessment,
        "sources": rows,
        "source_health": source_health or None,
    }


def _brief_confidence(source_health: dict, prep: dict) -> str:
    trust = (source_health or {}).get("brief_trustworthiness") or (source_health or {}).get("overall_health")
    if trust == "green":
        return "HIGH"
    if trust == "partial":
        return "MEDIUM"
    if trust in {"under_instrumented", "not_configured"}:
        return "MEDIUM"
    totals = (prep or {}).get("totals") or {}
    return "MEDIUM" if totals.get("stale_or_missing_sources") else "HIGH"


def _verification_source_rows(report: dict) -> list[dict]:
    prep = report.get("daily_prep_summary") or {}
    source_health = prep.get("source_health") or report.get("source_health") or {}
    health_sources = source_health.get("sources") or {}
    rows: list[dict] = []
    for row in prep.get("sources") or []:
        name = row.get("source_name") or "unknown"
        health = health_sources.get(name) or {}
        rows.append({
            "source": name,
            "access_status": row.get("scan_status") or "unknown",
            "freshness": row.get("freshness") or "unknown",
            "last_successful_sync": health.get("last_refreshed_at") or row.get("scan_window") or "unknown",
            "new_items_processed": row.get("evidence_count", 0),
            "relationship_items_detected": row.get("ri_found", 0),
            "actions_taken": row.get("actions_taken") or [],
            "failed_scan_or_error": health.get("reason") if row.get("freshness") != "fresh" else "",
            "recovery_command": health.get("recovery_command"),
            "recovery_type": health.get("recovery_type"),
            "source_refs": row.get("source_refs") or [],
        })
    seen = {r["source"] for r in rows}
    for name, health in health_sources.items():
        if name in seen:
            continue
        rows.append({
            "source": name,
            "access_status": health.get("status") or "unknown",
            "freshness": "fresh" if health.get("status") == "refreshed" else "stale_or_missing",
            "last_successful_sync": health.get("last_refreshed_at") or "never",
            "new_items_processed": 0,
            "relationship_items_detected": 0,
            "actions_taken": [health.get("reason") or "source_health_recorded"],
            "failed_scan_or_error": health.get("reason") if health.get("status") != "refreshed" else "",
            "recovery_command": health.get("recovery_command"),
            "recovery_type": health.get("recovery_type"),
            "source_refs": ["source_health.json", f"source_health.sources.{name}"],
        })
    return rows


def _source_status_label(name: str, row: dict) -> str:
    status = row.get("status") or "unknown"
    if status == "stale":
        reason = row.get("reason") or ""
        return f"{name}: stale" + (f" ({reason})" if reason else "")
    if status == "skipped_no_raw_input":
        return f"{name}: not refreshed (source input unavailable)"
    if status == "not_configured":
        return f"{name}: not connected"
    if status == "failed":
        return f"{name}: refresh failed"
    return f"{name}: {status}"


def _direct_comms_section(report: dict) -> list[dict]:
    """RB-DEFECT-004 — render direct comms readiness as canonical brief items.

    Surfaces:
    - One item per source (messages, calls) with state and brief_language.
    - One urgency item per urgency signal (missed call from known contact, etc.).
    - A completeness caveat item when sources are stale/unavailable.

    All items go into resource_verification_and_freshness_status.
    """
    raw_items = report.get("direct_comms_health") or []
    if not raw_items:
        return []

    canonical: list[dict] = []

    # Completeness caveat — surface once as a top-level note when any source is not trustworthy.
    if _HAS_DIRECT_COMMS_HEALTH:
        try:
            caveat = _dch.get_completeness_caveat(raw_items)
            if caveat:
                canonical.append(_canonical_item(
                    title="Direct comms completeness caveat",
                    summary=caveat,
                    why_it_matters=(
                        "RB must not claim that 'no new signals' exist when direct communication "
                        "sources are stale, unavailable, or metadata-only. "
                        "Signal gaps from Messages or Calls are unconfirmed absences, not confirmed quiet."
                    ),
                    recommended_action=(
                        "Review source state and run the recovery command before treating "
                        "direct-channel silence as confirmed."
                    ),
                    disposition="act_today",
                    grounding="system_detected",
                    freshness="stale_source_limited",
                    source_refs=["inbox/messages.json", "inbox/calls.json"],
                    confidence="high",
                    action_options=["run_recovery_command", "continue_with_caveat"],
                ))
        except Exception:  # noqa: BLE001
            pass

    # Per-source readiness items.
    for item in raw_items:
        state = item.get("state")
        if not state:
            continue

        if state == "urgency_signal":
            # Urgency items get act_today and surface as operational risk.
            contact_id = item.get("contact_id", "unknown")
            canonical.append(_canonical_item(
                title=f"Urgency signal: {item.get('channel', 'direct_comms').replace('_', ' ')}",
                summary=item.get("brief_language", ""),
                why_it_matters=(
                    f"Missed or unanswered contact from {contact_id} detected in direct comms. "
                    "Active-opportunity contacts warrant same-day response assessment."
                ),
                recommended_action=(
                    f"Review contact {contact_id} — proposed: {item.get('proposed_mutation') or 'log touch and assess'}."
                ),
                disposition="act_today",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[f"inbox/{item.get('source', 'messages')}.json"],
                confidence="medium",
                action_options=["log_touch", "open_loop", "ignore"],
                extras={
                    "contact_id": contact_id,
                    "channel": item.get("channel"),
                    "direction": item.get("direction"),
                    "event_at": item.get("event_at"),
                    "proposed_mutation": item.get("proposed_mutation"),
                },
            ))
        elif state in ("messages", "calls") or item.get("source") in ("messages", "calls"):
            # Source-readiness item.
            source = item.get("source", "messages")
            source_label = "Apple Messages" if source == "messages" else "Apple Calls"
            trustworthy = state in ("available_fresh", "available_with_snippets")
            unmatched_count = item.get("unmatched_count", 0)
            unmatched_handles = item.get("unmatched_handles", [])
            canonical.append(_canonical_item(
                title=f"Direct comms: {source_label}",
                summary=item.get("brief_language", f"{source_label} state: {state}"),
                why_it_matters=(
                    f"{source_label} {'is a live direct-channel signal surface.' if trustworthy else 'is unavailable or stale — direct-channel signals cannot be confirmed.'}"
                ),
                recommended_action=(
                    "No action required — source is fresh." if trustworthy
                    else "Run the recovery command to restore direct comms coverage."
                ),
                disposition="monitor" if trustworthy else "act_today",
                grounding="system_detected",
                freshness="fresh" if trustworthy else "stale_source_limited",
                source_refs=[f"inbox/{source}.json"],
                confidence="high" if trustworthy else "medium",
                action_options=[] if trustworthy else ["run_recovery_command", "continue_with_caveat"],
                extras={
                    "direct_comms_state": state,
                    "event_count": item.get("event_count", 0),
                    "matched_count": item.get("matched_count", 0),
                    "unmatched_count": unmatched_count,
                    "urgency_count": item.get("urgency_count", 0),
                    "completeness_claim_safe": item.get("completeness_claim_safe", False),
                    "ri_candidate_count": len(item.get("ri_candidates", [])),
                },
            ))

            # Resolution queue: surface unmatched handles that have real conversation
            # volume so the user can register them or exempt them. A CoS never silently
            # discards intelligence — it flags what it couldn't process and asks for help.
            if source == "messages" and unmatched_count > 0 and unmatched_handles:
                two_way = [h for h in unmatched_handles if h.get("two_way")]
                one_way = [h for h in unmatched_handles if not h.get("two_way")]
                top_handles = (two_way + one_way)[:10]
                handle_lines = "; ".join(
                    f"{h['handle']} ({h['message_count']} msgs{', 2-way' if h.get('two_way') else ''})"
                    for h in top_handles
                )
                canonical.append(_canonical_item(
                    title=f"SMS Contact Resolution Queue — {len(unmatched_handles)} unregistered phone number(s)",
                    summary=(
                        f"RB detected activity from {unmatched_count:,} SMS events across "
                        f"{len(unmatched_handles)} phone number(s) not registered in your contact network. "
                        f"Top contacts by volume: {handle_lines}. "
                        f"These conversations are not being attributed to any known contact — "
                        f"intelligence from them is currently invisible to RB."
                    ),
                    why_it_matters=(
                        "Unregistered phone numbers mean active conversations are excluded from "
                        "relationship intelligence, loop tracking, and signal detection. "
                        "A CoS cannot work with intelligence it cannot attribute."
                    ),
                    recommended_action=(
                        "Match each phone number to an existing contact (add their phone to "
                        "baseline_index) or exempt it from future scans via sms_trusted_senders.json."
                    ),
                    disposition="act_today" if two_way else "monitor",
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["inbox/messages.json", "system/baseline_index.json"],
                    confidence="high",
                    action_options=["add_phone_to_contact", "exempt_handle", "review_later"],
                    extras={
                        "unmatched_handle_count": len(unmatched_handles),
                        "unmatched_event_count": unmatched_count,
                        "top_unmatched_handles": top_handles,
                        "two_way_count": len(two_way),
                    },
                ))

    return canonical


def _load_contacts_reconciliation_queue() -> list[dict]:
    """Return pending (unresolved) items from the contacts reconciliation queue."""
    try:
        raw = json.loads((core.CACHE_DIR / "contacts_reconciliation_queue.json").read_text())
        if isinstance(raw, list):
            return [item for item in raw if not item.get("resolved")]
    except (FileNotFoundError, json.JSONDecodeError):
        pass
    return []


def _resource_verification_section(report: dict) -> list[dict]:
    prep = report.get("daily_prep_summary") or {}
    source_health = prep.get("source_health") or report.get("source_health") or {}
    rows = _verification_source_rows(report)
    accessed = [r["source"] for r in rows if r["access_status"] in {"scanned", "refreshed"}]
    updated = [r["source"] for r in rows if r["freshness"] == "fresh"]
    unavailable = [r["source"] for r in rows if r["access_status"] in {"unavailable", "not_configured", "missing_or_not_fetched"}]
    stale = [r["source"] for r in rows if r["freshness"] != "fresh"]
    totals = prep.get("totals") or {}
    blind_spots = []
    for r in rows:
        if r["freshness"] != "fresh":
            reason = r.get("failed_scan_or_error") or "not fresh"
            blind_spots.append(f"{r['source']}: {reason}")
    summary = (
        f"Resources accessed: {len(accessed)}; updated/fresh: {len(updated)}; "
        f"unavailable: {len(unavailable)}; stale/missing: {len(stale)}; "
        f"new items processed: {sum(int(r.get('new_items_processed') or 0) for r in rows)}; "
        f"RI/action signals detected: {totals.get('relationship_signals_detected', 0)}; "
        f"open loops reviewed: {totals.get('open_loops_checked', 0)}; "
        f"overdue loops: {totals.get('overdue_loops', 0)}."
    )
    items = [_canonical_item(
        title="RESOURCE VERIFICATION",
        summary=summary,
        why_it_matters=(
            "This block proves what RB checked, what changed, what is stale or missing, "
            "and how much trust to place in the interpretation that follows."
        ),
        recommended_action=(
            "Resolve stale or missing sources before treating any quiet-source conclusion as complete."
            if stale else "Proceed with the brief; freshness gates are satisfied."
        ),
        disposition="act_today" if stale else "monitor",
        grounding="system_detected",
        freshness="stale_source_limited" if stale else "fresh",
        source_refs=["daily_prep_summary", "source_health.json"],
        confidence=_brief_confidence(source_health, prep).lower(),
        extras={
            "resources_accessed": accessed,
            "resources_updated": updated,
            "resources_unavailable": unavailable,
            "resources_stale": stale,
            "brief_confidence": _brief_confidence(source_health, prep),
            "known_blind_spots": blind_spots,
            "source_rows": rows,
            "overall_health": source_health.get("overall_health"),
            "brief_trustworthiness": source_health.get("brief_trustworthiness"),
            "generated_at": source_health.get("generated_at"),
        },
    )]

    # Contacts reconciliation queue — surface pending probable matches for user action
    pending_queue = _load_contacts_reconciliation_queue()
    if pending_queue:
        top = pending_queue[:10]
        names = ", ".join(
            item.get("contact_name") or item.get("display_name") or item.get("name") or "unknown"
            for item in top
        )
        items.append(_canonical_item(
            title=f"Contacts Reconciliation Queue — {len(pending_queue)} contact(s) awaiting review",
            summary=(
                f"RB identified {len(pending_queue)} contact(s) from an uploaded contacts export "
                f"that could not be automatically matched to baseline records. "
                f"Top entries: {names}. "
                f"Review these to enrich baseline phone/email data for matching against SMS, calls, and calendar."
            ),
            why_it_matters=(
                "Unresolved contacts mean SMS events, calls, and calendar activity from these people "
                "cannot be attributed — they appear as unregistered phone numbers and invisible signals."
            ),
            recommended_action=(
                "Say 'show contacts queue' to review probable matches and confirm or reject each entry."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["contacts_reconciliation_queue.json"],
            confidence="high",
            extras={
                "pending_queue_count": len(pending_queue),
                "top_pending": top,
            },
        ))

    return items


def _major_claim_items(items: list[dict], *, limit: int = 8) -> list[dict]:
    out = []
    for item in items:
        extras = dict(item.get("extras") or {})
        extras.setdefault("triggering_signal", item.get("summary") or item.get("title"))
        extras.setdefault("source", ", ".join(item.get("source_refs") or []) or "unknown")
        extras.setdefault("timing", extras.get("timing_priority") or item.get("freshness") or "current")
        out.append({**item, "extras": extras})
        if len(out) >= limit:
            break
    return out


def _market_lane_items(msr: dict, lane: str) -> list[dict]:
    items = []
    for item in (msr.get("top") or [])[:10]:
        text = " ".join(str(item.get(k) or "").lower() for k in (
            "title", "category", "signal_layer", "signal_type", "macro_force",
            "restaurant_operator_impact", "restaurant_tech_vendor_implication",
        ))
        if lane == "macro":
            keep = bool(item.get("macro_force")) or any(k in text for k in (
                "tariff", "trade", "fuel", "labor", "wage", "immigration",
                "interest", "consumer", "inflation", "food cost", "commodity",
            ))
        elif lane == "local":
            keep = any(k in text for k in (
                "local", "regional", "city", "state", "weather", "labor",
                "wage", "supply chain", "regulatory", "ordinance",
            ))
        else:
            keep = not bool(item.get("macro_force"))
        if keep:
            items.append(item)
    return items


def _market_item_to_canonical(item: dict, *, title_prefix: str = "") -> dict:
    action = item.get("recommended_action") or "monitor"
    refs = []
    if item.get("url"):
        refs.append(f"market_signals.url:{item['url']}")
    refs.append(f"market_signals.source:{item.get('source_name')} ({item.get('published_at')})")
    extras = {
        "signal_timestamp": item.get("published_at"),
        "confirmed_vs_rumored": item.get("confirmation_status") or item.get("grounding") or "source_backed",
        "restaurant_operator_impact": item.get("restaurant_operator_impact") or "",
        "restaurant_tech_vendor_implication": item.get("restaurant_tech_vendor_implication") or "",
        "macro_force": item.get("macro_force") or "",
        # 021E: structured implication category (pain/buying-behavior/operator-pressure/opportunity/relationship/theme)
        "implication": item.get("implication") or "",
        "timing": item.get("timing_priority") or "monitor",
        "source": item.get("source_name"),
        "published_at": item.get("published_at"),
        "source_quality": item.get("source_quality"),
        "missing_evidence": item.get("missing_evidence") or [],
        "alternative_explanations": item.get("alternative_explanations") or [],
    }
    return _canonical_item(
        title=(title_prefix + (item.get("title") or "Market signal"))[:140],
        summary=item.get("signal_layer") or item.get("signal_type") or item.get("category") or "",
        why_it_matters=item.get("why_this_matters_to_todd") or item.get("restaurant_operator_impact") or "",
        recommended_action=(
            f"[{action}] timing={item.get('timing_priority')}; "
            f"{item.get('relationship_opportunity') or ''}"
        ).strip(),
        disposition=action,
        grounding=item.get("grounding", "manual_user_provided"),
        freshness="fresh",
        source_refs=refs,
        confidence=item.get("confidence") or "medium",
        extras=extras,
        provenance={
            "origin": item.get("grounding", "manual_user_provided"),
            "source_class": _source_class_for_grounding(item.get("grounding", "manual_user_provided")),
            "first_seen_at": item.get("published_at"),
            "corroboration_count": len(refs),
            "corroboration_chain": refs,
        },
        signal_state=item.get("signal_state"),
        evidence=[
            item.get("title") or "Market signal",
            f"source={item.get('source_name')} published_at={item.get('published_at')}",
        ],
        inference=[
            item.get("why_this_matters_to_todd") or item.get("restaurant_operator_impact") or "",
        ],
    )


def _parse_iso_dt(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _load_personal_operating_system() -> dict:
    """Load personal_operating_system.yaml — best-effort, returns {} on miss."""
    try:
        import yaml as _yaml
        path = core.SYSTEM_DIR / "personal_operating_system.yaml"
        if path.exists():
            return _yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except Exception:  # noqa: BLE001
        pass
    try:
        # fallback: manual JSON equivalent if yaml not available
        path = core.SYSTEM_DIR / "personal_operating_system.json"
        if path.exists():
            return json.loads(path.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        pass
    return {}


def _personal_operating_system_items(today: date) -> list[dict]:
    """RB-DEFECT-036 — Personal Operating System section.

    Surfaces the week's energy allocation across life domains (career,
    relationships, faith, family, health) and the day's operating mode so
    the brief frames professional activity inside a whole-life context.
    A world-class CoS doesn't just track opportunities — it tracks whether
    the operator is running the right energy mix across their whole life.
    """
    pos = _load_personal_operating_system()
    if not pos:
        return []

    domains = pos.get("domains") or []
    rhythm = pos.get("weekly_rhythm") or {}
    principles = pos.get("operating_principles") or []

    day_name = today.strftime("%A").lower()
    today_rhythm = rhythm.get(day_name) or {}
    mode = today_rhythm.get("mode") or "Standard"
    intent = today_rhythm.get("intent") or ""
    day_priorities = today_rhythm.get("priorities") or []

    items = []

    # Today's operating mode
    items.append(_canonical_item(
        title=f"Today's Mode: {mode} — {today.strftime('%A %B %d')}",
        summary=intent,
        why_it_matters=(
            f"Today's priorities: {', '.join(day_priorities)}"
            if day_priorities else "See weekly rhythm for guidance."
        ),
        disposition="monitor",
        grounding="manual_user_provided",
        freshness="fresh",
        source_refs=["personal_operating_system.yaml"],
        confidence="high",
        extras={"mode": mode, "day": day_name, "intent": intent},
    ))

    # Weekly energy allocation
    alloc_lines = []
    for d in domains:
        pct = d.get("allocation", 0)
        label = d.get("label", "")
        focus = d.get("current_focus") or d.get("weekly_goal") or ""
        alloc_lines.append(f"{pct}% {label}: {focus[:80]}")

    items.append(_canonical_item(
        title="This Week's Energy Allocation",
        summary="\n".join(alloc_lines),
        why_it_matters=(
            "Allocation reflects current season priorities. "
            + (principles[0] if principles else "")
        ),
        disposition="monitor",
        grounding="manual_user_provided",
        freshness="fresh",
        source_refs=["personal_operating_system.yaml"],
        confidence="high",
        extras={"domains": [{"label": d.get("label"), "allocation": d.get("allocation"), "goal": d.get("weekly_goal")} for d in domains]},
    ))

    return items


def _load_todd_profile() -> dict:
    """Read 00_TODD_PROFILE.md and extract strategic theses + domain expertise.

    Returns a dict with keys:
      strategic_theses: list[str]
      market_thesis: str
      domain_expertise: str
      career_arc_summary: str
    """
    result: dict = {
        "strategic_theses": [],
        "market_thesis": "",
        "domain_expertise": "",
        "career_arc_summary": "",
    }
    try:
        profile_path = core.SYSTEM_DIR / "00_TODD_PROFILE.md"
        if not profile_path.exists():
            return result
        text = profile_path.read_text(encoding="utf-8")

        # Extract strategic theses (bullet list under "## Strategic theses")
        import re as _re
        theses_match = _re.search(
            r"## Strategic theses.*?\n\n((?:- .+\n?)+)",
            text,
            _re.IGNORECASE,
        )
        if theses_match:
            for line in theses_match.group(1).splitlines():
                line = line.strip().lstrip("- ").strip()
                if line:
                    result["strategic_theses"].append(line)

        # Extract restaurant-tech market thesis
        market_match = _re.search(
            r"### Restaurant-tech market thesis.*?\n\n(.+?)(?:\n\n|\Z)",
            text,
            _re.IGNORECASE | _re.DOTALL,
        )
        if market_match:
            result["market_thesis"] = market_match.group(1).strip()

        # Domain expertise: derive from career arc table (most recent roles)
        result["domain_expertise"] = (
            "Enterprise QSR operator technology — 26 years McDonald's franchise operations "
            "(Valley Management), 7.5 years PAR Technology ($100M+ ARR, McDonald's global account), "
            "Head of Restaurant Sales at NomadGo. Deep franchise economics, restaurant-tech "
            "vendor landscape, enterprise GTM, and operator-grade deployment reality."
        )
        result["career_arc_summary"] = (
            "26 yrs McDonald's franchise (ops + IT) → PAR Technology (TAM → CSO, $100M ARR) "
            "→ NomadGo (Head Restaurant Sales) → BridgePoint Ops (founder/advisor, Feb 2025–present)"
        )
    except Exception:  # noqa: BLE001
        pass
    return result


def _compute_user_active_context(report: dict, sections: dict) -> list[dict]:
    """Pre-computed dot-connecting context block for Part 2.

    Gives the GPT explicit material to answer "why does this signal matter to YOU
    specifically" without having to infer from scattered sections. Every Part 2
    signal should be routed through this context: current role, strategic thesis,
    domain expertise, and active life priorities.

    Placed first in _ACTION_BRIEF_SECTIONS_PART2 so the GPT loads it before
    processing any signal in Sections 3–5.
    """
    profile = _load_todd_profile()
    pos = _load_personal_operating_system()

    # ── Current role / entering context from opportunity_board ────────────────
    opp_items = sections.get("opportunity_board") or []
    active_opps = [
        o for o in opp_items
        if (o.get("extras") or {}).get("disposition") in ("act_today", "ask_todd")
        or o.get("disposition") in ("act_today", "ask_todd")
    ]

    role_lines: list[str] = []
    entering_company = ""
    entering_title = ""
    for opp in active_opps[:3]:
        extras = opp.get("extras") or {}
        company = extras.get("company") or opp.get("title", "").split("—")[0].strip()
        stage = extras.get("stage") or extras.get("status") or ""
        days_in = extras.get("days_in_pipeline") or ""
        line = company
        if stage:
            line += f" [{stage}]"
        if days_in:
            line += f" — {days_in}d in pipeline"
        role_lines.append(line)
        if not entering_company and stage and "offer" in stage.lower():
            entering_company = company

    role_summary = "; ".join(role_lines) if role_lines else "No active opportunities tracked."

    # ── Active life priorities from POS ──────────────────────────────────────
    domains = pos.get("domains") or []
    priority_lines: list[str] = []
    for d in domains:
        alloc = d.get("allocation", 0)
        label = d.get("label", "")
        focus = d.get("current_focus", "")
        if alloc >= 10 and focus:
            priority_lines.append(f"{label} ({alloc}%): {focus[:100]}")

    principles = pos.get("operating_principles") or []

    # ── Build the summary block ────────────────────────────────────────────────
    theses_text = "\n".join(f"• {t}" for t in profile["strategic_theses"][:6])
    if profile["market_thesis"]:
        theses_text += f"\n\nMarket thesis: {profile['market_thesis'][:300]}"

    summary_parts = []
    if role_summary:
        summary_parts.append(f"Active opportunities: {role_summary}")
    if entering_company:
        summary_parts.append(
            f"Entering context: {entering_company} — enterprise restaurant technology "
            f"payments and software. Target buyers: CFOs and VP-Technology at enterprise QSR operators."
        )
    summary_parts.append(f"Domain expertise: {profile['domain_expertise']}")
    summary_parts.append(f"Career arc: {profile['career_arc_summary']}")

    dot_connect_guide = (
        "When connecting any signal to this user: (1) name the specific opportunity or role, "
        "(2) name the target buyer or relationship this affects, "
        "(3) name the specific thesis it validates or challenges, "
        "(4) name the concrete next action. Generic connections = failure."
    )

    items = [
        _canonical_item(
            title="User Active Context — Dot-Connect Reference",
            summary="\n\n".join(summary_parts),
            why_it_matters=dot_connect_guide,
            disposition="monitor",
            grounding="manual_user_provided",
            freshness="fresh",
            confidence="high",
            source_refs=["00_TODD_PROFILE.md", "personal_operating_system.yaml", "opportunity_board"],
            extras={
                "entering_company": entering_company,
                "active_opportunities": role_lines,
                "strategic_theses": profile["strategic_theses"],
                "market_thesis": profile["market_thesis"][:400] if profile["market_thesis"] else "",
                "domain_expertise": profile["domain_expertise"],
                "career_arc": profile["career_arc_summary"],
                "active_priorities": priority_lines,
                "operating_principles": principles[:4],
            },
        )
    ]

    # ── Strategic thesis item (separate, for GPT depth) ───────────────────────
    if theses_text:
        items.append(_canonical_item(
            title="Strategic Thesis — Signal Lens",
            summary=theses_text,
            why_it_matters=(
                "Every signal in the brief should be evaluated against these theses. "
                "Does this signal validate, challenge, or create timing for one of these positions? "
                "Name the thesis in the dot-connect, not a generic 'this is relevant to your work.'"
            ),
            disposition="monitor",
            grounding="manual_user_provided",
            freshness="fresh",
            confidence="high",
            source_refs=["00_TODD_PROFILE.md"],
            extras={
                "theses": profile["strategic_theses"],
                "market_thesis": profile["market_thesis"][:400] if profile["market_thesis"] else "",
            },
        ))

    return items


def _active_opportunity_pipeline_items(report: dict) -> list[dict]:
    """RB-DEFECT-037 — Active Opportunity Pipeline (career intelligence).

    Surfaces tracked opportunities (job offers, candidate ranking, interview
    timelines, deal stage) the user has personally reported via
    processOpportunityUpdate. Distinct from _opportunity_signal_items (which
    correlates OTHER PEOPLE's messages against account dossiers) — this
    section is the user's own pipeline status, told to RB directly.

    "NEW SINCE LAST BRIEF" framing: opportunities with a history entry dated
    today (or within the last day) are surfaced here with disposition
    act_today/monitor based on stage urgency. Opportunities with no recent
    change are omitted entirely from this section (they remain queryable via
    getOpportunityPipeline) — addresses Report 2 Defect #4 (change-detection
    framing) and Defect #1 (missing career intelligence).
    """
    try:
        recent = opportunity_pipeline.recent_changes(within_days=1)
    except Exception:
        return []

    items = []
    urgent_stages = {"offer_verbal", "offer_written", "negotiating", "final_round"}
    for opp in recent:
        stage = opp.get("stage")
        company = opp.get("company")
        recent_history = opp.get("recent_history") or []

        change_lines = []
        for entry in recent_history:
            line = f"[{entry.get('date')}] stage: {entry.get('stage')}"
            if entry.get("candidate_position"):
                line += f" — {entry['candidate_position']}"
            for kd in entry.get("key_dates") or []:
                line += f" — {kd.get('label')}: {kd.get('date_text')}"
            change_lines.append(line)

        disposition = "act_today" if stage in urgent_stages else "monitor"

        items.append(_canonical_item(
            title=f"Career pipeline update — {company}",
            summary=(
                f"NEW SINCE LAST BRIEF: {company} — current stage: {stage}."
                + (f" Candidate position: {opp['candidate_position']}." if opp.get("candidate_position") else "")
                + ("\n" + "\n".join(change_lines) if change_lines else "")
            ),
            why_it_matters=(
                "Todd reported a change in status on an active opportunity he is "
                "personally pursuing — this directly affects career/financial "
                "decisions and may require a timely response."
            ),
            recommended_action=(
                "Review opportunity status and confirm whether any action "
                "(response, scheduling, decision) is needed before the next interview/deadline."
            ),
            disposition=disposition,
            grounding="user_reported",
            freshness="fresh",
            source_refs=["system/tracked_opportunities.json", f"opportunity:{opp.get('id')}"],
            confidence="high",
            action_options=["update_opportunity_pipeline", "create_followup_loop"],
            extras={
                "opportunity_id": opp.get("id"),
                "company": company,
                "role": opp.get("role"),
                "stage": stage,
                "candidate_position": opp.get("candidate_position"),
                "key_dates": opp.get("key_dates"),
            },
        ))
    return items


def _opportunity_signal_items(report: dict) -> list[dict]:
    """Cross-channel opportunity stakeholder signal correlation.

    For each active opportunity dossier (system/artifacts/registry.json,
    artifact_type=account_dossier), opportunity_signal_correlation.py scans
    email + SMS for messages from known stakeholders (entity-resolved via
    each contact's `aliases.emails` / `aliases.phones`) and classifies
    milestone language ("final feedback", offer/decision, scheduling
    request, etc.) — independent of job_search_active and independent of
    job_intelligence's title/company fit-scoring, since these are updates on
    opportunities already in motion, not new postings.

    Cross-channel-correlated, critical-urgency items (e.g. a recruiter email
    plus a same-evening SMS from a hiring-side contact, both on the same
    opportunity) are surfaced as `act_today` so they reach the command
    center.
    """
    osig = report.get("opportunity_signals") or {}
    opportunities = osig.get("opportunities") or []
    items = []
    for opp in opportunities:
        signals = opp.get("signals") or []
        milestone_summary = []
        for sig in signals:
            for m in sig.get("milestones") or []:
                label = m["milestone_type"].replace("_", " ")
                if label not in milestone_summary:
                    milestone_summary.append(label)

        cross_channel = opp.get("cross_channel_correlated")
        urgency = opp.get("top_urgency")
        disposition = "act_today" if urgency == "critical" else "monitor"

        signal_lines = []
        for sig in signals[:4]:
            who = sig.get("stakeholder_name") or "unknown"
            channel = sig.get("channel")
            snippet = (sig.get("snippet") or "").strip()
            signal_lines.append(f"[{channel}] {who}: \"{snippet}\"")

        summary = (
            f"{opp['entity']} — {opp['signal_count']} stakeholder signal(s) in the last "
            f"{osig.get('scan_window_days', 14)} days"
            + (", correlated across channels" if cross_channel else "")
            + (f". Milestone language: {', '.join(milestone_summary)}." if milestone_summary else ".")
        )

        source_refs = []
        for sig in signals:
            if sig.get("channel") == "email" and sig.get("thread_id"):
                source_refs.append(f"email_thread:{sig['thread_id']}")
            elif sig.get("channel") == "sms" and sig.get("message_id"):
                source_refs.append(f"sms:{sig['message_id']}")
        source_refs.append(opp["data_path"])

        items.append(_canonical_item(
            title=f"Opportunity signal — {opp['entity']}",
            summary=summary + "\n" + "\n".join(signal_lines),
            why_it_matters=(
                "Cross-channel corroboration (recruiter + hiring-side stakeholder "
                "contacting Todd within hours of each other) indicates this opportunity "
                "has reached a decision-relevant milestone."
                if cross_channel else
                "A known stakeholder on this active opportunity sent a message containing "
                "milestone language."
            ),
            recommended_action=opp.get("recommended_action") or "Review correlated stakeholder activity.",
            disposition=disposition,
            grounding="system_detected",
            freshness="fresh",
            source_refs=source_refs[:6],
            confidence="high",
            action_options=["respond_to_stakeholder", "update_opportunity_dossier", "create_followup_loop"],
            extras={
                "artifact_id": opp["artifact_id"],
                "opportunity_state": opp.get("opportunity_state"),
                "cross_channel_correlated": cross_channel,
                "top_urgency": urgency,
            },
        ))
    return items


def _job_intelligence_items(report: dict) -> list[dict]:
    """Job Intelligence — surface matching job opportunities from email and LinkedIn.

    Gated by opportunity_context.yaml → job_search_active.
    Returns [] when job_search_active is false — section is completely
    suppressed from the brief.  When active, returns one canonical item per
    detected role, ordered by fit score descending, with posting URLs as
    source_refs so the user can navigate directly.

    Each item includes:
      - Detected role title and company
      - Source (email thread subject / LinkedIn message sender)
      - Fit score and reasons
      - Posting URL(s) when available; flagged as speculative when not
      - Recommended action based on source type
    """
    ji = report.get("job_intelligence") or {}

    # Gate: if not active, return nothing — section does not appear in brief
    if ji.get("gate_status") != "active":
        return []

    signals = ji.get("signals") or []
    if not signals:
        # Active but no signals found — emit a single confirmation item
        return [_canonical_item(
            title="Job Intelligence — Active, No Roles Detected This Cycle",
            summary=(
                f"Scanned last {ji.get('scan_days', 14)} days of email and LinkedIn messages "
                f"for job opportunity signals. No roles matching your profile were detected."
            ),
            why_it_matters=(
                "Job search scanning is active. No inbound signals detected this cycle. "
                "This is a confirmed scan result, not a missing scan."
            ),
            recommended_action="No action required. Continue monitoring.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["job_intelligence.json"],
            confidence="high",
            extras={
                "gate_status": "active",
                "scan_days": ji.get("scan_days"),
                "signal_count": 0,
            },
        )]

    items = []
    for sig in signals[:10]:
        companies = sig.get("extracted_companies") or []
        titles = sig.get("extracted_titles") or []
        fit_score = int(sig.get("fit_score") or 0)
        reasons = sig.get("fit_reasons") or []
        posting_urls = sig.get("posting_urls") or []
        is_speculative = sig.get("is_speculative", True)
        source = sig.get("source") or "unknown"
        sender = sig.get("sender_name") or ""
        subject = sig.get("subject") or ""
        snippet = sig.get("snippet") or ""
        detected_at = sig.get("detected_at") or ""

        company_str = companies[0] if companies else "Unknown Company"
        title_str = titles[0] if titles else "Senior Role"
        source_label = "Email" if source == "email" else "LinkedIn" if source == "linkedin" else source.title()

        # Build a human-readable title
        item_title = f"{company_str} — {title_str}"
        if fit_score >= 80:
            item_title = f"🎯 {item_title} [{fit_score}% fit]"
        elif fit_score >= 60:
            item_title = f"📋 {item_title} [{fit_score}% fit]"

        summary_parts = [
            f"Source: {source_label}",
            f"From: {sender}" if sender else None,
            f"Signal: \"{subject[:80]}\"" if subject else None,
            f"Speculative — no posting URL found" if is_speculative else f"Posting URL available",
        ]
        summary = " | ".join(p for p in summary_parts if p)

        why = (
            f"Fit score: {fit_score}%. "
            + (f"Reasons: {'; '.join(reasons[:3])}. " if reasons else "")
            + ("Speculative signal — no formal posting URL detected. Monitor for confirmation." if is_speculative
               else "Job posting URL available — apply or confirm interest directly.")
        )

        if posting_urls:
            action = f"Review posting at: {posting_urls[0]}"
        elif source == "linkedin":
            action = f"Reply to LinkedIn message from {sender} to express interest or gather details."
        else:
            action = f"Reply to email from {sender} to confirm role details before proceeding."

        items.append(_canonical_item(
            title=item_title,
            summary=summary,
            why_it_matters=why,
            recommended_action=action,
            disposition="act_today" if fit_score >= 80 else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=posting_urls if posting_urls else [f"{source_label}: {subject[:60]}" if subject else source_label],
            confidence="high" if fit_score >= 75 else "medium",
            extras={
                "company": company_str,
                "role_title": title_str,
                "fit_score": fit_score,
                "fit_reasons": reasons,
                "posting_urls": posting_urls,
                "is_speculative": is_speculative,
                "source": source,
                "sender": sender,
                "signal_type": sig.get("signal_type") or "job_signal",
                "detected_at": detected_at,
                "snippet": snippet[:200],
            },
        ))
    return items


def _intelligence_collection_summary_items(report: dict) -> list[dict]:
    """RB-INTEL-021 — Intelligence Collection Summary front-matter section.

    Provides verifiable proof that intelligence collection executed prior to
    brief generation.  Answers: Did the scan run? When? What sources were
    scanned? How many signals were found? What is the collection health?

    Data is drawn from execution_report.intelligence_health_dashboard which is
    always present when the morning pipeline ran (scan_only or full).  Falls
    back gracefully when no execution report exists (e.g. manual brief builds).
    """
    er = report.get("execution_report") or {}
    if not er:
        return [_canonical_item(
            title="Intelligence Collection Summary — Not Available",
            summary="No pipeline execution report found for this brief cycle.",
            why_it_matters=(
                "Pre-brief intelligence collection status cannot be verified. "
                "Run morning_pipeline.py to generate a collection receipt."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="unknown",
            source_refs=["morning_pipeline"],
            confidence="low",
        )]

    dashboard = er.get("intelligence_health_dashboard") or {}
    sources_summary = dashboard.get("sources") or []
    summary_counts = dashboard.get("summary") or {}
    healthy = int(summary_counts.get("healthy") or 0)
    stale_count = int(summary_counts.get("stale") or 0)
    failed_partial = int(summary_counts.get("failed_or_partial") or 0)
    unavailable = int(summary_counts.get("unavailable") or 0)
    total_sources = int(summary_counts.get("total_sources") or len(sources_summary))

    refresh_status = er.get("refresh_status") or "Unknown"
    trust_score = er.get("trust_score") or dashboard.get("trust_score")
    trust_level = er.get("trust_level") or dashboard.get("overall_health") or "unknown"
    generated_at = er.get("generated_at") or dashboard.get("generated_at") or ""
    records_processed = int(er.get("records_processed") or 0)
    records_added = int(er.get("records_added") or 0)
    records_changed = int(er.get("records_changed") or 0)
    mutations_generated = int(er.get("mutations_generated") or 0)
    stale_sources_list = er.get("stale_sources") or []
    errors = er.get("processing_errors") or []
    cycle_statistics = dict(er.get("intelligence_cycle_statistics") or {})

    # "0 fetched" can mean the assessor reused a complete same-cycle cache,
    # not that RB gathered nothing. Preserve both sides of that distinction
    # so the reader-facing health appendix can report evaluated coverage
    # without leaking a misleading zero.
    assessment_stats = (report.get("intelligence_assessment") or {}).get("trust_stats") or {}
    if assessment_stats:
        daily_stats = dict(cycle_statistics.get("daily_monitoring") or {})
        daily_stats["items_from_cache"] = int(assessment_stats.get("items_from_cache") or 0)
        cycle_statistics["daily_monitoring"] = daily_stats

    # A gated weekday research run starts after the 4 AM scan receipt and may
    # finish before the 5 AM brief render. Read its append-only receipts here
    # so same-morning routine research is reported today, not tomorrow.
    cycle_date = str(er.get("date") or date.today().isoformat())
    receipt_path = core.SYSTEM_DIR / ".cache" / "routine_research_receipts.jsonl"
    same_day_receipts = []
    if receipt_path.exists():
        for raw in receipt_path.read_text(encoding="utf-8").splitlines():
            try:
                receipt = json.loads(raw)
            except (ValueError, TypeError):
                continue
            if str(receipt.get("completed_at") or "")[:10] == cycle_date:
                same_day_receipts.append(receipt)

    def _count_value(value) -> int:
        if isinstance(value, (list, tuple, set, dict)):
            return len(value)
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            return 0

    if same_day_receipts:
        routine = dict(cycle_statistics.get("routine_research") or {})
        routine.update({
            "accounts_or_entities_researched": len(same_day_receipts),
            "sources_checked": sum(_count_value(r.get("sources_checked")) for r in same_day_receipts),
            "evidence_items_added": sum(_count_value(r.get("evidence_items_added")) for r in same_day_receipts),
            "entities": [r.get("entity_name") for r in same_day_receipts if r.get("entity_name")],
        })
        cycle_statistics["routine_research"] = routine
    ramification_report = report.get("intelligence_ramifications") or {}
    if ramification_report:
        daily_stats = dict(cycle_statistics.get("daily_monitoring") or {})
        daily_stats["ramifications_generated"] = int(ramification_report.get("ramifications_generated") or 0)
        daily_stats["artifact_reviews_recommended"] = int(ramification_report.get("artifact_reviews_recommended") or 0)
        daily_stats["historical_events_routed_to_baseline"] = int(ramification_report.get("historical_events_excluded") or 0)
        cycle_statistics["daily_monitoring"] = daily_stats
    downstream_report = report.get("downstream_impact_queue") or {}
    if downstream_report:
        daily_stats = dict(cycle_statistics.get("daily_monitoring") or {})
        daily_stats["downstream_review_items_added"] = int(downstream_report.get("review_items_added") or 0)
        daily_stats["downstream_safe_updates_applied"] = int(downstream_report.get("safe_applied") or 0)
        daily_stats["downstream_failures"] = int(downstream_report.get("safe_failed") or 0)
        cycle_statistics["daily_monitoring"] = daily_stats
    audit_report = report.get("intelligence_cycle_audit") or {}
    if audit_report:
        daily_stats = dict(cycle_statistics.get("daily_monitoring") or {})
        daily_stats["trace_audit_status"] = audit_report.get("status") or "unknown"
        daily_stats["complete_intelligence_traces"] = int(audit_report.get("complete_traces") or 0)
        daily_stats["incomplete_intelligence_traces"] = int(audit_report.get("incomplete_traces") or 0)
        cycle_statistics["daily_monitoring"] = daily_stats
    watchdog = report.get("intelligence_cycle_health") or {}
    if watchdog:
        daily_stats = dict(cycle_statistics.get("daily_monitoring") or {})
        daily_stats["watchdog_status"] = watchdog.get("status") or "unknown"
        daily_stats["watchdog_critical_alerts"] = int(watchdog.get("critical_alerts") or 0)
        daily_stats["watchdog_warnings"] = int(watchdog.get("warnings") or 0)
        daily_stats["priority_source_blind_spots"] = [
            row.get("source") for row in (watchdog.get("priority_source_blind_spots") or [])
            if row.get("source")]
        cycle_statistics["daily_monitoring"] = daily_stats

    # Collection health label
    if refresh_status == "Success":
        collection_health = "Healthy"
        health_flag = "✓"
    elif refresh_status == "Partial":
        collection_health = "Degraded"
        health_flag = "⚠"
    else:
        collection_health = "Failed"
        health_flag = "✗"

    # Freshness % — healthy sources / total (excluding unavailable/not-applicable)
    eligible = healthy + stale_count + failed_partial
    freshness_pct = int(100 * healthy / eligible) if eligible > 0 else 0
    confidence_pct = int(trust_score) if isinstance(trust_score, (int, float)) else None

    # Scanned source names for display
    sources_scanned = er.get("sources_processed") or []
    sources_scanned_str = ", ".join(sources_scanned) if sources_scanned else "see source detail"

    # Format collection window
    collection_window = generated_at[:19].replace("T", " ") + " UTC" if generated_at else "unknown"

    summary_text = (
        f"Collection Status: {collection_health} {health_flag} | "
        f"Sources: {healthy}/{total_sources} healthy | "
        f"Freshness: {freshness_pct}%"
        + (f" | Trust: {confidence_pct}%" if confidence_pct is not None else "")
        + (f" | Mutations: {mutations_generated}" if mutations_generated else "")
    )

    # RB-DEFECT-2026-09-18: this was raw accounting fields with no framing --
    # "Records processed: N | New records: N | Changed: N | Mutations
    # generated: N" -- correct evidence, but it never said why the evidence
    # matters (handoff §Reporting contract: "Technical scoring and system
    # statuses appear in user-facing prose without explaining why a signal
    # matters"). The stats stay -- CHARTER.md's own "trust is earned by
    # stats" tenet -- but now read as support for a plain-language claim
    # instead of being the entire sentence.
    why_text = (
        "Confirms this cycle's collection actually ran and touched real "
        "data before this brief was built, not just that the job exited "
        "cleanly. "
        f"Records processed: {records_processed:,} | "
        f"New records: {records_added} | Changed: {records_changed} | "
        f"Mutations generated: {mutations_generated}"
    )
    if stale_sources_list:
        why_text += f" | Stale sources: {', '.join(stale_sources_list)}"
    if errors:
        error_names = [e.get("step") or str(e) for e in errors[:3]]
        why_text += f" | Errors: {', '.join(error_names)}"

    # ── personal_intel_proof — pre-computed per-source counts ────────────────
    # Aggregated here so the GPT has explicit numbers without synthesis across
    # multiple sections. Each row maps 1:1 to an IB-2 Personal Sources row.
    def _count_file_items(path: Path) -> int:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            return len(data.get("threads") or data.get("events") or [])
        except Exception:
            return 0

    _pei = report.get("passive_email_intelligence") or {}
    _msg_path = core.MESSAGES_PATH if hasattr(core, "MESSAGES_PATH") else None
    _calls_path = core.CALLS_PATH if hasattr(core, "CALLS_PATH") else None

    email_accounts: list[dict] = []
    for acct in ("personal", "bridgepoint"):
        ep = core.email_path_for(acct) if hasattr(core, "email_path_for") else None
        if ep and ep.exists():
            n = _count_file_items(ep)
            is_stale = f"email:{acct}" in stale_sources_list
            email_accounts.append({"account": acct, "threads": n, "stale": is_stale})

    cal_events_total = 0
    cal_stale = False
    for acct in ("personal", "bridgepoint"):
        cp = core.calendar_path_for(acct) if hasattr(core, "calendar_path_for") else None
        if cp and cp.exists():
            cal_events_total += _count_file_items(cp)
            if f"calendar:{acct}" in stale_sources_list:
                cal_stale = True

    sms_events = _count_file_items(_msg_path) if _msg_path and _msg_path.exists() else 0
    calls_events = _count_file_items(_calls_path) if _calls_path and _calls_path.exists() else 0

    personal_intel_proof = {
        "email_accounts": email_accounts,
        "email_threads_total": sum(a["threads"] for a in email_accounts),
        "email_stale": any(a["stale"] for a in email_accounts),
        "calendar_events_total": cal_events_total,
        "calendar_stale": cal_stale,
        "sms_events_total": sms_events,
        "calls_events_total": calls_events,
        "newsletters_scanned": int(_pei.get("newsletter_sources_scanned") or 0),
        "newsletter_deep_dives": int((_pei.get("email_intelligence_summary") or {}).get("deep_dives_triggered") or 0),
        "passive_email_threads_reviewed": int((_pei.get("email_intelligence_summary") or {}).get("threads_analyzed") or 0),
        "relationship_mutations_detected": int((_pei.get("email_intelligence_summary") or {}).get("relationship_mutations") or 0),
        "linkedin_messaging_stale": "linkedin_messaging" in stale_sources_list,
    }

    items = [_canonical_item(
        title=f"Intelligence Collection Summary — {collection_window}",
        summary=summary_text,
        why_it_matters=why_text,
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh" if refresh_status == "Success" else "degraded",
        source_refs=["morning_pipeline", "intelligence_health_dashboard"],
        confidence="high" if refresh_status == "Success" else ("medium" if refresh_status == "Partial" else "low"),
        extras={
            "collection_window": collection_window,
            "refresh_status": refresh_status,
            "collection_health": collection_health,
            "sources_attempted": total_sources,
            "sources_healthy": healthy,
            "sources_stale": stale_count,
            "sources_failed": failed_partial,
            "sources_unavailable": unavailable,
            "freshness_pct": freshness_pct,
            "trust_score": trust_score,
            "trust_level": trust_level,
            "records_processed": records_processed,
            "records_added": records_added,
            "records_changed": records_changed,
            "mutations_generated": mutations_generated,
            "stale_sources": stale_sources_list,
            "processing_errors": [e.get("step") for e in errors],
            "sources_scanned": sources_scanned,
            "personal_intel_proof": personal_intel_proof,
            "intelligence_cycle_statistics": cycle_statistics,
        },
    )]

    # Per-source health rows (top-level only — keeps brief readable)
    healthy_sources = [s for s in sources_summary if s.get("status") == "Healthy"]
    problem_sources = [s for s in sources_summary if s.get("status") not in {"Healthy", "Unavailable", "Not Applicable"}]

    if problem_sources:
        problem_lines = []
        for s in problem_sources[:6]:
            reason = s.get("failure_reason") or s.get("status") or "unknown"
            problem_lines.append(f"  • {s.get('source') or s.get('source_key')}: {reason}")
        items.append(_canonical_item(
            title=f"Collection Issues — {len(problem_sources)} source(s) not healthy",
            summary="\n".join(problem_lines),
            why_it_matters="These sources did not contribute fresh intelligence to this brief.",
            disposition="monitor",
            grounding="system_detected",
            freshness="degraded",
            source_refs=["intelligence_health_dashboard"],
            confidence="high",
            extras={"problem_sources": [
                {"source": s.get("source"), "status": s.get("status"), "reason": s.get("failure_reason")}
                for s in problem_sources
            ]},
        ))

    return items


def _operating_mode_framing_items(report: dict) -> list[dict]:
    """RB-DEFECT-021 — surface this week's operating mode + framing question
    as the lens for everything that follows. Was computed into
    report["operating_mode"]/["weekly_plan"] but never rendered."""
    om = report.get("operating_mode") or {}
    wp = report.get("weekly_plan") or {}
    if not om:
        return []
    mode = om.get("mode", "execution")
    framing_q = om.get("framing_question", "")
    day = om.get("day", "")
    is_current = bool(wp.get("is_current"))
    outcomes = wp.get("outcomes") or []
    if is_current and outcomes:
        summary = (
            f"{day}: operating in '{mode}' mode. {framing_q} "
            f"This week's outcomes: " + "; ".join(o.get("title", "") for o in outcomes[:3])
        )
        grounding = "system_detected"
        freshness = "fresh"
        confidence = "high"
    else:
        summary = (
            f"{day}: operating in '{mode}' mode. {framing_q} "
            f"No current weekly plan is on file — outcome-alignment scoring is "
            f"running in neutral passthrough until one is generated."
        )
        grounding = "inferred"
        freshness = "stale_source_limited"
        confidence = "low"
    return [_canonical_item(
        title=f"Operating mode: {mode.replace('_', ' ').title()}",
        summary=summary,
        why_it_matters=(
            "This is the lens RB applies to every item below — what should "
            "surface, get suppressed, or get boosted today is gated by this "
            "mode and (when current) by alignment to this week's outcomes."
        ),
        recommended_action=(
            "" if is_current else
            "Generate this week's plan (weekly outcomes + portfolio allocation) "
            "so RB can score today's items against actual goals, not just "
            "generic significance."
        ),
        disposition="monitor" if is_current else "act",
        grounding=grounding,
        freshness=freshness,
        source_refs=["operating_mode", "weekly_plan"],
        confidence=confidence,
        extras={"mode": mode, "framing_question": framing_q, "is_plan_current": is_current},
    )]


def _morning_headlines_from_web_scan(report: dict, limit: int = 7) -> list[tuple[str, dict]]:
    """Fallback: build morning-headline (category, item) pairs directly from
    the web_scan sections already in the report.  Called when the
    market_signals-based `report["morning_headlines"]` is empty — which happens
    whenever market_signals is stale but the web scanner ran successfully.

    Priority order: restaurant_technology first (most relevant to Todd's work),
    then restaurant_industry, then world_national.  Cap at `limit` total.
    """
    web_scan = report.get("web_scan") or {}
    buckets = [
        ("Restaurant Technology", web_scan.get("restaurant_technology") or []),
        ("Restaurant Industry", web_scan.get("restaurant_industry") or []),
        ("World & Business", web_scan.get("world_national") or []),
    ]
    flat: list[tuple[str, dict]] = []
    for category, items in buckets:
        for raw in items:
            if len(flat) >= limit:
                break
            flat.append((category, raw))
        if len(flat) >= limit:
            break
    return flat


def _morning_headlines_section_items(report: dict) -> list[dict]:
    """RB-DEFECT-031 — render the morning-newspaper headlines layer.

    Primary path: market_signals-based report["morning_headlines"] (grouped
    by category, pre-scored).  Fallback (fixes the ordering bug where
    morning_headlines was computed before web_scan loaded): pull directly from
    web_scan sections when the primary path is empty.  This means the section
    always has real headlines as long as *either* source has data — the
    original bug was that both paths existed but never connected, leaving the
    section empty even on mornings when 160 articles were available.
    """
    headlines = report.get("morning_headlines") or []

    # Build flat list from primary source
    flat: list[tuple[str, dict]] = []
    for group in headlines:
        category = group.get("section") or ""
        for h in (group.get("items") or []):
            flat.append((category, h))

    # Fallback: web_scan sections (the fix for the market_signals ordering bug).
    # Items stored in report["web_scan"] are already canonical-shaped
    # (_canonical_item dicts with title/why_it_matters/confidence/etc.).
    # Re-map to the {headline, source, date, why_it_matters, url, confidence}
    # shape used in the rendering loop below.
    if not flat:
        web_flat = _morning_headlines_from_web_scan(report)
        if web_flat:
            def _to_headline(canonical: dict) -> dict:
                extras = canonical.get("extras") or {}
                source_refs = canonical.get("source_refs") or []
                return {
                    "headline": canonical.get("title") or "Untitled",
                    "source": (
                        extras.get("source_name")
                        or (source_refs[0] if source_refs else "")
                    ),
                    "date": extras.get("published_at") or extras.get("date") or "",
                    "why_it_matters": (
                        canonical.get("summary")
                        or canonical.get("why_it_matters")
                        or ""
                    ),
                    "url": extras.get("url") or extras.get("url_canonical") or extras.get("source_url") or "",
                    "confidence": canonical.get("confidence") or "medium",
                    # 021E: pass implication through to headline items
                    "implication": extras.get("implication") or "",
                    # 021F: pass macro_category through for gating
                    "macro_category": extras.get("macro_category"),
                }
            flat = [(cat, _to_headline(raw)) for cat, raw in web_flat]

    if not flat:
        return [_canonical_item(
            title="No fresh headlines this cycle",
            summary="The morning headlines scan returned no qualifying items.",
            why_it_matters="Either nothing material moved overnight, or the source feed is stale — check signal_freshness.",
            disposition="monitor",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["market_signals", "web_scanner"],
            confidence="low",
        )]

    items = []
    for category, h in flat[:7]:
        title = h.get("headline") or "Untitled headline"
        items.append(_canonical_item(
            title=f"[{category}] {title}" if category else title,
            summary=f"{h.get('source', '')} — {h.get('date', '')}",
            why_it_matters=h.get("why_it_matters") or "",
            recommended_action="",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[h.get("url")] if h.get("url") else ["web_scanner"],
            confidence=h.get("confidence") or "medium",
            extras={
                "date": h.get("date"),
                "url": h.get("url"),
                "source_url": h.get("url"),
                "category": category,
                # 021E: pass implication through to rendered headline items
                "implication": h.get("implication") or "",
                # 021F: macro_category preserved for downstream gating
                "macro_category": h.get("macro_category"),
            },
        ))
    return items


def _signal_inventory_items(report: dict, *, limit: int = 12) -> list[dict]:
    """RB-DEFECT-036 — ranked signal inventory.

    Aggregates discrete intelligence events from all sources into a single
    ranked list.  The CoS layer can then say "N signals detected today —
    here are the top ones" with Importance/Confidence per signal, rather
    than burying everything in narrative prose where it gets lost.

    Sources pulled:
      - Relationship signals (actual contact interactions)
      - High-value web-scan items (acquisition, exec-change, funding, closure)
      - Overnight knowledge mutations
      - Loop triggers (overdue/due-today)

    Each signal gets:
      importance: high | medium | low
      confidence: 0–100 %
      signal_type: descriptive label
      source: named source
    """
    signals: list[dict] = []

    # --- Relationship signals ---
    rsr = report.get("relationship_signals") or {}
    for sig in (rsr.get("signals") or [])[:20]:
        imp = "high" if sig.get("disposition") in ("act_today", "ask_todd") else "medium"
        conf = int(_confidence_numeric(sig.get("confidence")) * 100)
        signals.append({
            "signal_type": sig.get("signal_type") or "relationship_event",
            "title": sig.get("title") or sig.get("summary") or "Relationship signal",
            "source": (sig.get("source_refs") or ["relationship_signals"])[0],
            "importance": imp,
            "confidence_pct": conf,
            "disposition": sig.get("disposition"),
            "url": None,
            "_rank_key": (3 if imp == "high" else 2, conf),
        })

    # --- Web-scan high-signal items (act_today disposition = acquisition/exec-change/closure) ---
    web_scan = report.get("web_scan") or {}
    for bucket in ("restaurant_technology", "restaurant_industry", "world_national"):
        for raw in (web_scan.get(bucket) or []):
            disp = raw.get("disposition")
            signal_type = (raw.get("extras") or {}).get("signal_type") or "news"
            if disp == "act_today" or signal_type in ("acquisition", "exec-change", "closure", "funding", "earnings"):
                imp = "high" if disp == "act_today" else "medium"
                conf = int(_confidence_numeric(raw.get("confidence")) * 100)
                extras = raw.get("extras") or {}
                signals.append({
                    "signal_type": signal_type,
                    "title": raw.get("title") or "News signal",
                    "source": extras.get("source_name") or (raw.get("source_refs") or ["web_scanner"])[0],
                    "importance": imp,
                    "confidence_pct": conf,
                    "disposition": disp or "monitor",
                    "url": extras.get("source_url") or "",
                    "why_it_matters": raw.get("why_it_matters") or raw.get("summary") or "",
                    # 021E: structured implication category
                    "implication": extras.get("implication") or "",
                    "_rank_key": (3 if imp == "high" else 2, conf),
                })

    # --- Loop triggers (overdue/due-today) ---
    loops = report.get("loops") or {}
    overdue = [lp for lp in (loops.get("open") or []) if lp.get("overdue") or lp.get("due_today")]
    for lp in overdue[:5]:
        signals.append({
            "signal_type": "loop_trigger",
            "title": f"Loop due: {lp.get('party') or lp.get('contact_name') or 'unknown'} — {lp.get('summary') or lp.get('loop_id','')}",
            "source": "loop_ledger",
            "importance": "high" if lp.get("overdue") else "medium",
            "confidence_pct": 100,
            "disposition": "act_today",
            "url": None,
            "_rank_key": (3, 100),
        })

    # --- Knowledge mutations (overnight) ---
    digest = report.get("overnight_change_digest") or {}
    total_mutations = digest.get("total", 0) if isinstance(digest, dict) else 0
    if total_mutations:
        signals.append({
            "signal_type": "knowledge_mutation",
            "title": f"{total_mutations} knowledge graph mutations since yesterday",
            "source": "intelligence_mutation_engine",
            "importance": "medium" if total_mutations >= 5 else "low",
            "confidence_pct": 90,
            "disposition": "monitor",
            "url": None,
            "_rank_key": (2 if total_mutations >= 5 else 1, 90),
        })

    # Sort: high-importance first, then by confidence desc
    signals.sort(key=lambda s: s.pop("_rank_key"), reverse=True)
    signals = signals[:limit]

    if not signals:
        return [_canonical_item(
            title="No discrete signals detected this cycle",
            summary="No relationship events, high-signal news items, or loop triggers found.",
            why_it_matters="Check source freshness — stale sources produce no signals.",
            disposition="monitor",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["relationship_signals", "web_scanner", "loop_ledger"],
            confidence="low",
        )]

    items = []
    for rank, sig in enumerate(signals, 1):
        url = sig.get("url") or ""
        why = sig.get("why_it_matters") or ""
        sig_type = sig["signal_type"]
        imp = sig["importance"]
        conf = sig["confidence_pct"]
        disp = sig["disposition"]

        # RB-INTEL-021: Explainability — why this signal was included.
        # Every signal gets a human-readable inclusion_reason so the user can
        # ask "why did this appear in my brief?" and get a direct answer.
        if sig_type == "loop_trigger":
            inclusion_reason = (
                f"Included because this relationship loop is {'overdue' if disp == 'act_today' else 'due today'}. "
                f"Loop triggers always surface at high importance — unaddressed loops erode relationship trust."
            )
        elif sig_type in ("acquisition", "funding", "exec-change", "closure"):
            inclusion_reason = (
                f"Included because this {sig_type} event has direct strategic relevance. "
                f"Market events of this type are classified as {imp}-importance signals "
                f"with {conf}% confidence from the web intelligence scan."
            )
        elif sig_type == "relationship_event":
            inclusion_reason = (
                f"Included because a new relationship activity was detected from a tracked contact. "
                f"Disposition: {disp}. Confidence: {conf}%."
            )
        elif sig_type == "knowledge_mutation":
            inclusion_reason = (
                f"Included because the intelligence knowledge graph recorded mutations since yesterday. "
                f"Mutations signal that previously tracked intelligence has changed — requiring review."
            )
        elif sig_type == "news":
            inclusion_reason = (
                f"Included because this news item scored {imp} importance in the web intelligence scan "
                f"based on signal type classification. Confidence: {conf}%."
            )
        else:
            inclusion_reason = (
                f"Included because this signal scored {imp} importance ({conf}% confidence) "
                f"from source: {sig['source']}. Disposition: {disp}."
            )

        items.append(_canonical_item(
            title=f"Signal {rank} [{imp.upper()}] — {sig['title']}",
            summary=f"Type: {sig_type} | Source: {sig['source']} | Confidence: {conf}%",
            why_it_matters=why or f"Requires disposition: {disp}",
            recommended_action="",
            disposition=disp,
            grounding="system_detected",
            freshness="fresh",
            source_refs=[url] if url else [sig["source"]],
            confidence="high" if conf >= 70 else "medium",
            extras={
                "signal_type": sig_type,
                "importance": imp,
                "confidence_pct": conf,
                "source": sig["source"],
                "url": url,
                "source_url": url,
                "rank": rank,
                # 021E: implication category for CoS rendering
                "implication": sig.get("implication") or "",
                # RB-INTEL-021: explainability — why this signal appeared in the brief
                "inclusion_reason": inclusion_reason,
            },
        ))
    return items


def _macro_signal_items(report: dict, plan_data: dict | None = None, *, limit: int = 6) -> list[dict]:
    """RB-DEFECT-021F — macro-economic/market-force signals gated by weekly_plan.outcomes.

    Reads web_scan items that have a `macro_category` set by web_scanner.py.
    Only surfaces a macro signal in the brief when it is relevant to the active
    weekly plan outcomes — i.e., the macro force can plausibly affect one of
    this week's pursuit targets.

    Macro categories: labor | consumer-spending | inflation | rates | traffic |
                      earnings | AI-investment

    Gating logic: each macro category maps to a set of industry/segment keywords.
    A signal is gated "relevant" if any active outcome's label/company contains
    keywords matching the category's relevant industry set, OR if the article
    mentions a company that appears in active outcomes (for earnings signals).
    """
    # Outcome relevance map: macro_category → industry keywords that make it relevant
    _MACRO_OUTCOME_RELEVANCE: dict[str, list[str]] = {
        "labor":            ["restaurant", "operator", "franchise", "hospitality", "food", "dining"],
        "consumer-spending": ["restaurant", "operator", "retail", "food", "dining", "consumer"],
        "traffic":          ["restaurant", "operator", "location", "dining", "store", "food"],
        "inflation":        ["restaurant", "operator", "vendor", "supply", "food", "cost", "dining"],
        "rates":            ["acquisition", "investment", "deal", "merger", "finance", "fund"],
        "earnings":         [],  # gated by company name matching (see below)
        "AI-investment":    ["tech", "software", "platform", "restaurant technology", "automation", "digital"],
    }

    # Build outcome context from active plan
    outcome_labels: list[str] = []
    outcome_companies: list[str] = []
    if plan_data:
        for o in (plan_data.get("outcomes") or []):
            lbl = (o.get("label") or o.get("name") or o.get("id") or "").lower()
            co = (o.get("company") or "").lower()
            if lbl:
                outcome_labels.append(lbl)
            if co:
                outcome_companies.append(co)
    # Default: if no plan, treat restaurant/operator/tech outcomes as active
    if not outcome_labels:
        outcome_labels = ["restaurant", "operator", "technology"]

    all_outcomes_text = " ".join(outcome_labels + outcome_companies)

    def _is_relevant(macro_cat: str, article_title: str, article_desc: str) -> bool:
        """Return True if this macro signal is relevant to the active outcomes."""
        keywords = _MACRO_OUTCOME_RELEVANCE.get(macro_cat, [])
        if macro_cat == "earnings":
            # Only surface earnings if a company from outcomes appears in the article
            article_text = (article_title + " " + article_desc).lower()
            return any(co in article_text for co in outcome_companies if co)
        return any(kw in all_outcomes_text for kw in keywords)

    macro_items: list[dict] = []
    web_scan = report.get("web_scan") or {}
    for bucket in ("restaurant_technology", "restaurant_industry", "world_national"):
        for raw in (web_scan.get(bucket) or []):
            extras = raw.get("extras") or {}
            macro_cat = extras.get("macro_category")
            if not macro_cat:
                continue
            title = raw.get("title") or ""
            desc = raw.get("summary") or raw.get("why_it_matters") or ""
            if not _is_relevant(macro_cat, title, desc):
                continue
            macro_items.append({
                "raw": raw,
                "macro_category": macro_cat,
                "implication": extras.get("implication") or "theme",
                "title": title,
                "desc": desc,
                "url": extras.get("source_url") or "",
                "source_name": extras.get("source_name") or (raw.get("source_refs") or ["web_scanner"])[0],
            })
            if len(macro_items) >= limit:
                break
        if len(macro_items) >= limit:
            break

    if not macro_items:
        return []

    items = []
    for entry in macro_items:
        cat = entry["macro_category"]
        url = entry["url"]
        items.append(_canonical_item(
            title=f"[MACRO:{cat.upper()}] {entry['title']}",
            summary=(
                f"Macro category: {cat} | Implication: {entry['implication']} | "
                f"Source: {entry['source_name']}"
            ),
            why_it_matters=(
                (entry["desc"][:250] if entry["desc"] else f"{cat} macro force detected.")
                + f" ↳ Relevant to active plan outcomes: "
                + (", ".join(outcome_companies[:3]) or "current week targets") + "."
            ),
            recommended_action=(
                f"Assess whether this {cat} signal changes timing, pricing, or "
                "relationship posture on any active pursuit."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[url] if url else [entry["source_name"]],
            confidence="medium",
            extras={
                "macro_category": cat,
                "implication": entry["implication"],
                "source_url": url,
                "source_name": entry["source_name"],
                "outcome_relevance": outcome_companies[:3] or outcome_labels[:3],
            },
        ))
    return items


def _overnight_change_digest_items(report: dict) -> list[dict]:
    """RB-DEFECT-031 — render the overnight mutation digest ("what changed
    since yesterday" via the knowledge-mutation log). Was computed into
    report["overnight_change_digest"] but never rendered."""
    digest = report.get("overnight_change_digest") or {}
    total = digest.get("total", 0)
    counts = digest.get("counts_by_type") or {}
    mutations = digest.get("mutations") or []
    if not total:
        return [_canonical_item(
            title="No knowledge-graph mutations in the last 24h",
            summary="The mutation log shows no new entries since the last cycle.",
            why_it_matters="Either nothing material was extracted from sources overnight, or upstream extraction is stalled — cross-check against new_intelligence_today.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["knowledge_mutations.json"],
            confidence="medium",
        )]
    breakdown = ", ".join(f"{v} {k.replace('_', ' ')}" for k, v in counts.items())
    items = [_canonical_item(
        title=f"{total} knowledge mutations in the last 24h",
        summary=f"Breakdown: {breakdown}.",
        why_it_matters="This is what RB actually changed in its understanding overnight — not what it read, what it concluded.",
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh",
        source_refs=["knowledge_mutations.json"],
        confidence="high",
        extras={"counts_by_type": counts, "total": total},
    )]
    for m in mutations[:5]:
        items.append(_canonical_item(
            title=m.get("description") or m.get("type") or "Mutation",
            summary=m.get("signal") or m.get("description") or "",
            why_it_matters=m.get("interpretation") or "",
            recommended_action="Review and confirm" if m.get("requires_confirmation") else "",
            disposition="act" if m.get("requires_confirmation") else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[(m.get("source") or {}).get("url", "")] if m.get("source") else [],
            confidence="high" if (m.get("confidence") or 0) >= 0.6 else "medium",
            extras={"type": m.get("type"), "requires_confirmation": m.get("requires_confirmation")},
        ))
    return items


def _weekly_plan_focus_items(report: dict) -> list[dict]:
    """RB-DEFECT-021 — render this week's outcomes/portfolio/risks as a
    discrete focus block so 'does this move an outcome forward' has a visible
    anchor in the brief, not just a silent scoring multiplier."""
    wp_data = report.get("weekly_plan") or {}
    if not wp_data.get("is_current"):
        today = date.today()
        draft = _maybe_autodraft_weekly_plan(today)
        if draft and not draft.get("_autodraft_error") and wp.is_current(draft, today):
            outcomes = draft.get("outcomes") or []
            lines = [
                f"[{o.get('portfolio_allocation_pct', o.get('allocation_pct', '?'))}%] {o.get('title', '')}"
                for o in outcomes[:5]
            ]
            generated_note = (
                "RB generated this proposal automatically this morning"
                if draft.get("_autodraft_generated_today")
                else "A draft is already waiting from earlier this week"
            )
            return [_canonical_item(
                title="This week's plan is drafted — awaiting your confirmation",
                summary=(
                    f"{generated_note}, anchored on active threads and the loop ledger:\n"
                    + "\n".join(lines)
                ),
                why_it_matters="Until confirmed, outcome-alignment scoring stays in neutral passthrough — items are ranked by generic significance, not by whether they advance this week's goals.",
                recommended_action="Review the proposed outcomes/allocations, edit if needed, then confirm to make this the live plan for the week.",
                disposition="ask_todd",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["weekly_plan_draft.json"],
                confidence="high",
                extras={"draft_outcomes": outcomes[:5], "week_of": draft.get("week_of")},
            )]
        return [_canonical_item(
            title="No current weekly plan on file",
            summary="Outcome-alignment scoring is running in neutral passthrough — items are ranked by generic strategic significance only, not by whether they advance this week's goals.",
            why_it_matters="Without a weekly plan, RB cannot distinguish 'busy' from 'productive toward what matters this week.'",
            recommended_action="Run the weekly planning step (Monday plan-generation) to set this week's outcomes and portfolio allocation.",
            disposition="act",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["weekly_plan.json"],
            confidence="high",
        )]
    plan_data = wp_data
    items = []
    outcomes = plan_data.get("outcomes") or []
    for o in outcomes[:5]:
        items.append(_canonical_item(
            title=f"This week's outcome: {o.get('title', '')}",
            summary=o.get("description") or "",
            why_it_matters=f"Allocation: {o.get('portfolio_allocation_pct', o.get('allocation_pct', '?'))}% — items aligned to this outcome are boosted; unaligned items are dampened.",
            disposition="monitor",
            grounding="manual_user_provided",
            freshness="fresh",
            source_refs=["weekly_plan.json"],
            confidence="high",
            extras={"allocation_pct": o.get("portfolio_allocation_pct", o.get("allocation_pct")), "status": o.get("status")},
        ))
    for r in (plan_data.get("risks") or [])[:3]:
        # Risk entries are structured dicts (id/title/description/severity/
        # source) written by weekly_plan_generator.py's _generate_risks --
        # str(r) on a dict renders its Python repr ("{'id': ..., 'title':
        # ...}") verbatim into the brief instead of the actual risk text.
        r_title = (r.get("title") if isinstance(r, dict) else None) or "Weekly risk flagged"
        r_desc = (r.get("description") if isinstance(r, dict) else None) or (r if isinstance(r, str) else "")
        items.append(_canonical_item(
            title=r_title,
            summary=r_desc,
            why_it_matters="Risks to this week's outcomes should shape what gets prioritized and what gets deferred.",
            disposition="monitor",
            grounding="manual_user_provided",
            freshness="fresh",
            source_refs=["weekly_plan.json"],
            confidence="medium",
            extras={"severity": r.get("severity")} if isinstance(r, dict) else {},
        ))
    return items


def _competitive_vulnerability_items(report: dict) -> list[dict]:
    """RB-DEFECT-1 (item 3) — convert competitive_vulnerability.py's brand
    scoring report into canonical items for the
    'Competitive Opportunity Watchlist' (rendered after Watchlist
    Intelligence per CANONICAL_RESPONSE_CONTRACT.md / TEMPLATE.md)."""
    cv = report.get("competitive_vulnerability") or {}
    brands = cv.get("brands") or []
    items: list[dict] = []
    tier_disposition = {"high_risk": "act", "emerging": "monitor", "watch": "monitor"}
    for b in brands:
        entity = b.get("entity", "")
        tier = b.get("tier", "watch")
        score = b.get("vulnerability_score")
        horizon = b.get("estimated_horizon_months")
        rfp = b.get("rfp_detected", False)
        categories = b.get("potential_categories") or []
        signals = b.get("signals") or []
        source_refs = [s["url"] for s in signals if s.get("url")][:3] or ["competitive_vulnerability.json"]
        title = f"{entity} — Opportunity Score: {score}/100"
        if rfp:
            title += " — RFP/RFI detected"
        recommended_action = (
            "RFP/RFI detected — this opportunity may already be in active competition. "
            "Review and prioritize outreach."
            if rfp else
            "Monitor for further signals; consider proactive outreach if categories align with active pipeline."
        )
        items.append(_canonical_item(
            title=title,
            summary=b.get("why_it_matters") or "Elevated vulnerability signals detected.",
            why_it_matters=(
                f"Potential categories: {', '.join(categories) if categories else 'unspecified'}. "
                f"Estimated opportunity horizon: {horizon} month(s)."
            ),
            recommended_action=recommended_action,
            disposition=tier_disposition.get(tier, "monitor"),
            grounding="system_detected",
            freshness="fresh",
            source_refs=source_refs,
            confidence=b.get("confidence", "medium"),
            extras={
                "entity_name": entity,
                "tier": tier,
                "vulnerability_score": score,
                "estimated_horizon_months": horizon,
                "rfp_detected": rfp,
                "potential_categories": categories,
                "signals": signals[:3],
            },
        ))
    return items


def _intelligence_action_queue_items(report: dict) -> list[dict]:
    """Render only the ranked top of the unified queue; preserve full data in cache.

    RB-2026-09-15: filters to status=="pending_review" before slicing the
    top 8 -- without this, a resolved item (see intelligence_action_queue.
    resolve()) would keep occupying a top-8 slot forever on every future
    cycle purely from its priority_score, crowding out genuinely new items
    Todd hasn't seen yet. Resolved items remain visible via
    getIntelligenceActionQueue for calibration/audit, just not re-nagged
    here daily."""
    queue = report.get("intelligence_action_queue") or {}
    labels = {
        "monitor": "MONITOR",
        "research_further": "RESEARCH",
        "contact_account": "CONTACT ACCOUNT",
        "build_pursuit": "BUILD PURSUIT",
        "competitive_displacement_opportunity": "DISPLACEMENT OPPORTUNITY",
    }
    pending = [row for row in (queue.get("items") or [])
               if row.get("status", "pending_review") == "pending_review"]
    items = []
    for row in pending[:8]:
        action_class = row.get("action_class") or "monitor"
        evidence = [str(value) for value in (row.get("supporting_evidence") or []) if value]
        questions = [str(value) for value in (row.get("disconfirming_questions") or []) if value]
        recommended = {
            "monitor": "Keep under observation; do not initiate outreach.",
            "research_further": "Close the named evidence gaps before deciding whether to engage.",
            "contact_account": "Review the evidence and relationship path, then seek authorization for account outreach.",
            "build_pursuit": "Validate the buying event and sponsor path before creating or advancing a pursuit.",
            "competitive_displacement_opportunity": "Validate incumbent scope, renewal timing, and dissatisfaction before displacement outreach.",
        }[action_class]
        items.append(_canonical_item(
            title=f"#{row.get('rank')} [{labels[action_class]}] {row.get('entity') or 'Unknown entity'}",
            summary=row.get("summary") or row.get("threshold_reason") or "Review candidate.",
            why_it_matters=row.get("threshold_reason") or "Ranked by the unified intelligence action threshold.",
            recommended_action=recommended,
            disposition="monitor" if action_class == "monitor" else "ask_todd",
            grounding="system_detected", freshness="fresh",
            source_refs=evidence or [row.get("source_cache") or "intelligence_action_queue.json"],
            confidence=row.get("confidence") or "medium",
            evidence=evidence,
            inference=[row.get("summary")] if row.get("summary") else [],
            extras={
                "queue_id": row.get("queue_id"), "priority_score": row.get("priority_score"),
                "action_class": action_class, "item_type": row.get("item_type"),
                "disconfirming_questions": questions, "missing_evidence": row.get("missing_evidence") or [],
                "review_first": True,
            },
        ))
    return items


def _competitor_battle_card_review_items(report: dict) -> list[dict]:
    """RB-2026-09-01 — convert competitor_intelligence_review.py's pending
    review queue into canonical items. New-today items render in full;
    items already pending from a prior day compact into one summary item
    so a stale battle card doesn't nag every cycle (same discipline as
    entity_convergence_scan.py's persisting-vs-new dedup)."""
    cbr = report.get("competitor_battle_card_review") or {}
    new_today = cbr.get("new_today") or []
    persisting = cbr.get("persisting") or []
    items: list[dict] = []

    kind_labels = {
        "material_signal_review": "New signal",
        "capture_signal_review": "Captured intelligence",
        "staleness_review": "Stale battle card",
    }
    for r in new_today:
        kind = r.get("kind", "")
        category = r.get("category")
        title = f"{kind_labels.get(kind, 'Review')}: {r.get('competitor_slug')}"
        if category:
            title += f" ({category})"
        items.append(_canonical_item(
            title=title,
            summary=r.get("reason", ""),
            why_it_matters="Flagged by the daily competitor-intelligence review scan for Todd's review before the battle card content changes.",
            recommended_action="Review and resolve via resolveCompetitorReviewItem; update the battle card via setCategoryBattleCard if warranted.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=[r.get("evidence_id")] if r.get("evidence_id") else ["competitor_intelligence review_queue.json"],
            confidence="medium",
            extras={
                "competitor_slug": r.get("competitor_slug"),
                "category": category,
                "kind": kind,
                "review_id": r.get("review_id"),
            },
        ))

    if persisting:
        items.append(_canonical_item(
            title=f"{len(persisting)} competitor battle-card review item(s) still pending",
            summary="Pending from a prior cycle; not re-detailed daily to avoid repeat noise.",
            why_it_matters="Unresolved review items accumulate silently unless surfaced periodically.",
            recommended_action="Review via getCompetitorProfile's pending_reviews when convenient.",
            disposition="monitor",
            grounding="system_detected",
            freshness="stale",
            source_refs=["competitor_intelligence review_queue.json"],
            confidence="medium",
            extras={"pending_review_ids": [r.get("review_id") for r in persisting]},
        ))
    return items


def _downstream_artifact_cascade_items(report: dict) -> list[dict]:
    """Intelligence-gathering cascade — RB-2026-08-28 (Todd's "foolproof data
    flow" spec): once intelligence is collected and assessed, the CoS must
    also assess and update downstream artifacts (Blue Sheets, Account
    Research) and report what it did. intelligence_cascade.py does the real
    work daily; this renders its cache as a single proof item, same pattern
    as _intelligence_collection_summary_items -- real named counts only, no
    live computation here.
    """
    ic = report.get("intelligence_cascade") or {}
    if not ic or ic.get("error"):
        return [_canonical_item(
            title="Downstream Artifact Cascade — Not Available",
            summary="No intelligence-cascade report found for this cycle.",
            why_it_matters=(
                "Cannot verify whether new intelligence was assessed against "
                "Blue Sheets and Account Research today."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="unknown",
            source_refs=["intelligence_cascade"],
            confidence="low",
        )]

    entities = int(ic.get("entities_with_new_intelligence") or 0)
    rels = int(ic.get("relationships_touched") or 0)
    synced = ic.get("blue_sheets_auto_synced") or []
    queued = ic.get("blue_sheets_queued_for_review") or []
    flagged = ic.get("account_research_flagged_stale") or []
    processed = ic.get("account_research_auto_processed") or []
    gaps_today = ic.get("coverage_gaps_today") or []
    gaps_pattern = ic.get("coverage_gaps_14d_pattern") or []
    map_synced = ic.get("master_account_plans_auto_synced") or []
    map_queued = ic.get("master_account_plans_queued_for_review") or []

    title = (
        f"Downstream Artifact Cascade — {entities} entit{'y' if entities == 1 else 'ies'} "
        f"with new intelligence, {rels} relationship(s) touched"
    )
    # RB-2026-09-10: the old summary always led with four zero-value clauses
    # ("Blue Sheets: 0 ... Account Research: 0 ...") before the one fact
    # that actually justifies act_today (a recurring 14-day coverage-gap
    # pattern) -- confirmed live: with that pattern real (10 accounts,
    # e.g. Subway) the rendered brief still showed "Coverage gaps: 0…",
    # truncated before the substantive part ever appeared. Same "lead with
    # what matters" fix already applied to Section E's earnings trend_note
    # (see render_intelligence_brief.py) -- lead with whichever findings are
    # actually driving act_today, and compact the rest after, instead of a
    # fixed four-clause zero-inventory every time.
    _lead: list[str] = []
    if gaps_pattern:
        _names = ", ".join(
            g.get("entity_name") or g.get("entity_id") or "?" for g in gaps_pattern[:3]
        )
        _more = f" (+{len(gaps_pattern) - 3} more)" if len(gaps_pattern) > 3 else ""
        _lead.append(
            f"{len(gaps_pattern)} account(s) have a recurring 14-day coverage-gap pattern "
            f"despite repeated signal touches: {_names}{_more}."
        )
    if queued:
        _lead.append(f"{len(queued)} Blue Sheet field(s) queued for review.")
    if map_queued:
        _lead.append(f"{len(map_queued)} Master Account Plan item(s) queued for review.")

    if _lead:
        summary = " ".join(_lead) + (
            f" Also today: {len(synced)} Blue Sheet field(s) auto-synced, {len(flagged)} Account "
            f"Research flagged stale, {len(processed)} auto-processed (24h SLA), {len(map_synced)} "
            f"Master Account Plan(s) auto-synced, {len(gaps_today)} new coverage gap(s)."
        )
    else:
        summary = (
            f"Blue Sheets: {len(synced)} field(s) auto-synced, {len(queued)} queued for review. "
            f"Account Research: {len(flagged)} flagged stale, {len(processed)} auto-processed "
            f"(24h SLA). Master Account Plans: {len(map_synced)} vendor plan(s) auto-synced, "
            f"{len(map_queued)} item(s) queued for review. Coverage gaps: {len(gaps_today)} today, "
            f"{len(gaps_pattern)} recurring 14-day pattern(s)."
        )
    # why_it_matters carries the real named counts (this is what
    # _render_simple_item_list actually shows in the rendered brief);
    # summary carries the boilerplate framing for the GPT-facing payload.
    why_it_matters = summary
    proof_framing = (
        "This is the proof that new intelligence was actually assessed against "
        "existing Blue Sheets and Account Research, not just collected and left "
        "unconnected to the artifacts that depend on it."
    )
    disposition = "act_today" if (queued or gaps_pattern or map_queued) else "monitor"

    return [_canonical_item(
        title=title,
        summary=proof_framing,
        why_it_matters=why_it_matters,
        recommended_action=(
            "Review queued Blue Sheet/Master Account Plan items and recurring coverage gaps."
            if (queued or gaps_pattern or map_queued) else ""
        ),
        disposition=disposition,
        grounding="system_detected",
        freshness="fresh",
        source_refs=["intelligence_cascade"],
        confidence="high",
        extras={
            "entities_with_new_intelligence": entities,
            "relationships_touched": rels,
            "blue_sheets_auto_synced": synced,
            "blue_sheets_queued_for_review": queued,
            "account_research_flagged_stale": flagged,
            "account_research_auto_processed": processed,
            "master_account_plans_auto_synced": map_synced,
            "master_account_plans_queued_for_review": map_queued,
            "coverage_gaps_today": gaps_today,
            "coverage_gaps_14d_pattern": gaps_pattern,
        },
    )]


def _overnight_delta_items(report: dict) -> list[dict]:
    """Summarize what changed since the previous daily cycle.

    This does not invent deltas. It converts existing scan counts into an
    explicit "what changed" section and labels stale/under-instrumented cases.
    """
    prep = report.get("daily_prep_summary") or {}
    totals = prep.get("totals") or {}
    loops = report.get("loops") or {}
    ri_recent = report.get("ri_events_recent") or {}
    passive = report.get("passive_ri_ingest") or {}
    market = report.get("market_signals") or {}
    strategic_events = report.get("strategic_events") or {}
    strategic_operators = report.get("strategic_operators") or {}
    signal_counts = (report.get("relationship_signals") or {}).get("signal_counts_by_relevance") or {}

    relationship_delta = (
        f"{totals.get('relationship_signals_detected', 0)} relationship/action signal(s) detected; "
        f"{len(ri_recent.get('newly_captured') or [])} persisted RI event(s); "
        f"{len(ri_recent.get('proposed_unconfirmed') or []) + len(passive.get('events_written') or [])} proposed RI event(s); "
        f"{signal_counts.get('high', 0)} high-relevance signal(s); "
        f"{len(loops.get('overdue') or [])} overdue loop(s); "
        f"{len(loops.get('due_today') or [])} due today."
    )
    market_delta = (
        f"{market.get('top_count', 0) or 0} market/operator signal(s) elevated from "
        f"{market.get('input_count', 0) or 0} reviewed row(s); "
        f"{strategic_events.get('top_count', len(strategic_events.get('top') or [])) if strategic_events else 0} strategic event(s) surfaced; "
        f"{strategic_operators.get('recent_movement_count', 0) if strategic_operators else 0} operator movement(s)."
    )

    stale_count = totals.get("stale_or_missing_sources", 0) or 0
    confidence = "medium" if stale_count else "high"
    freshness = "stale_source_limited" if stale_count else "fresh"
    action = (
        "Refresh stale sources, then regenerate before treating no-delta lanes as truly quiet."
        if stale_count else "Use these deltas as today's operating changes."
    )
    return [
        _canonical_item(
            title="Overnight relationship and operating deltas",
            summary=relationship_delta,
            why_it_matters="RB must answer what changed since yesterday before it offers narrative synthesis.",
            recommended_action=action,
            disposition="act_today" if len(loops.get("overdue") or []) or stale_count else "monitor",
            grounding="system_detected",
            freshness=freshness,
            source_refs=["daily_prep_summary", "ri_events_recent", "passive_ri_ingest.json", "loop_ledger"],
            confidence=confidence,
            extras={
                "relationship_signals_by_relevance": signal_counts,
                "ri_events_recent_counts": {
                    "persisted": len(ri_recent.get("newly_captured") or []),
                    "proposed": len(ri_recent.get("proposed_unconfirmed") or []),
                    "rejected": len(ri_recent.get("rejected_today") or []),
                    "historical_uploaded": len(ri_recent.get("historical_uploaded") or []),
                },
                "loop_delta_counts": {
                    "overdue": len(loops.get("overdue") or []),
                    "due_today": len(loops.get("due_today") or []),
                    "this_week": len(loops.get("this_week") or []),
                },
            },
        ),
        _canonical_item(
            title="Overnight market and operator deltas",
            summary=market_delta,
            why_it_matters=(
                "Market and operator movement matters only when RB can connect it to restaurant pressure, "
                "vendor timing, relationship opportunity, or action."
            ),
            recommended_action=(
                "Review elevated market/operator rows; create watch loops for act-today or ask-Todd items."
                if (market.get("top_count", 0) or 0) else
                "Do not infer market quietness unless market source coverage is fresh and complete."
            ),
            disposition="monitor" if not market.get("stale") else "act_today",
            grounding="system_detected",
            freshness="stale_source_limited" if market.get("stale") else freshness,
            source_refs=["market_signals", "strategic_events", "strategic_operators"],
            confidence="medium" if market.get("stale") else confidence,
            extras={
                "market_signals_elevated": market.get("top_count", 0) or 0,
                "market_rows_reviewed": market.get("input_count", 0) or 0,
                "strategic_events_elevated": strategic_events.get("top_count", len(strategic_events.get("top") or [])) if strategic_events else 0,
                "operator_movements": strategic_operators.get("recent_movement_count", 0) if strategic_operators else 0,
            },
        ),
    ]


def _autonomous_discovery_section(report: dict) -> list[dict]:
    """Show whether RB discovered anything without user-provided briefing input."""
    prep = report.get("daily_prep_summary") or {}
    source_health = prep.get("source_health") or report.get("source_health") or {}
    health_sources = source_health.get("sources") or {}
    market = report.get("market_signals") or {}

    rows = _verification_source_rows(report)
    autonomous_rows = [
        r for r in rows
        if r.get("access_status") in {"scanned", "refreshed"}
        and not any("manual_context" in str(x) for x in r.get("actions_taken") or [])
    ]
    manual_or_export = [
        name for name, row in health_sources.items()
        if isinstance(row, dict) and row.get("recovery_type") in {"manual_scan", "manual_export"}
    ]
    manual_market_count = sum(
        1 for item in market.get("top") or []
        if item.get("grounding") == "manual_user_provided"
    )
    system_discovery_count = max(0, (market.get("top_count", 0) or 0) - manual_market_count)
    freshness = "stale_source_limited" if (source_health.get("brief_trustworthiness") == "under_instrumented" or market.get("stale")) else "fresh"
    if system_discovery_count:
        title = "Autonomous discovery proof"
        summary = (
            f"RB refreshed/scanned {len(autonomous_rows)} source surface(s) and surfaced "
            f"{system_discovery_count} non-manual market/operator item(s)."
        )
        disposition = "monitor"
        confidence = "medium"
        action = "Review evidence chains and create watch loops for material non-manual discoveries."
    else:
        title = "Autonomous discovery gap"
        summary = (
            f"RB refreshed/scanned {len(autonomous_rows)} source surface(s), but current market/operator "
            f"brief items are manual/user-provided or absent. Manual/export-dependent lanes: "
            f"{', '.join(manual_or_export[:6]) or 'none recorded'}."
        )
        disposition = "act_today"
        confidence = "high"
        action = (
            "Enable overnight source fetchers or scheduled reviewed-row generation for market, macro, "
            "operator, LinkedIn, and relationship movement feeds before claiming autonomous discovery."
        )
    return [_canonical_item(
        title=title,
        summary=summary,
        why_it_matters=(
            "The daily brief must show net-new intelligence RB found on its own, or explicitly admit the lane "
            "is contextual recall / manual feed review."
        ),
        recommended_action=action,
        disposition=disposition,
        grounding="system_detected",
        freshness=freshness,
        source_refs=["daily_prep_summary", "source_health.json", "market_signals"],
        confidence=confidence,
        extras={
            "autonomous_source_surfaces_scanned": len(autonomous_rows),
            "manual_or_export_dependent_sources": manual_or_export,
            "manual_market_items": manual_market_count,
            "system_discovered_market_items": system_discovery_count,
            "coverage_status": source_health.get("brief_trustworthiness") or "unknown",
            # RB-2026-09-09: this item reports on RB's own discovery
            # process, not a discovery -- keep it out of "What RB Found
            # Without You Telling It" (see _autonomous_discovery_value).
            "signal_type": "pipeline_self_report",
        },
    )]


def _delivery_verification_section(report: dict) -> list[dict]:
    delivery = report.get("delivery_check") or {}
    pipeline = report.get("morning_pipeline_state") or {}
    settings = core.load_settings().get("daily_briefing") or {}
    delivery_settings = settings.get("delivery") or {}
    today_iso = report.get("today")
    steps = delivery.get("automated_steps") or {}
    fail_count = int(delivery.get("automated_fail_count") or 0)
    warn_count = int(delivery.get("automated_warn_count") or 0)
    pipeline_ok = pipeline.get("ok") is True and pipeline.get("date") == today_iso
    checked_at = delivery.get("checked_at")
    checked_dt = _parse_iso_dt(checked_at)
    stale_delivery_check = True
    if checked_dt:
        stale_delivery_check = (datetime.now(timezone.utc) - checked_dt).total_seconds() > 36 * 3600
    push_enabled = bool(delivery_settings.get("chatgpt_push_enabled"))
    sender_ready = (delivery_settings.get("sender_status") == "ready")
    native_task_mode = delivery_settings.get("chatgpt_task_delivery_mode")
    ok = pipeline_ok and bool(delivery) and fail_count == 0 and not stale_delivery_check
    summary = (
        f"Pipeline today: {'PASS' if pipeline_ok else 'FAIL/UNKNOWN'}; "
        f"delivery check: {'present' if delivery else 'missing'}"
        f"{' (stale)' if stale_delivery_check and delivery else ''}; "
        f"automated delivery failures: {fail_count}; warnings: {warn_count}; "
        f"ChatGPT push enabled: {push_enabled}; sender transport ready: {sender_ready}."
    )
    return [_canonical_item(
        title="Delivery verification",
        summary=summary,
        why_it_matters=(
            "The newspaper-at-the-door contract fails if the user has to ask whether the brief ran."
        ),
        recommended_action=(
            "Run task_delivery_check.py and fix failing delivery steps before relying on unattended delivery."
            if not ok else
            "Delivery proof is current; keep monitoring scheduled completion and notification."
        ),
        disposition="monitor" if ok else "act_today",
        grounding="system_detected",
        freshness="fresh" if ok else "stale_source_limited",
        source_refs=["morning_pipeline.json", "task_delivery_check.json", "settings.json:daily_briefing.delivery"],
        confidence="high",
        extras={
            "pipeline_ok_today": pipeline_ok,
            "pipeline_date": pipeline.get("date"),
            "pipeline_generated_at": pipeline.get("generated_at"),
            "delivery_checked_at": checked_at,
            "delivery_steps": steps,
            "fail_count": fail_count,
            "warn_count": warn_count,
            "chatgpt_push_enabled": push_enabled,
            "chatgpt_task_delivery_mode": native_task_mode,
            "sender_status": delivery_settings.get("sender_status"),
        },
    )]


def _ecosystem_intelligence_section(report: dict) -> list[dict]:
    """Build the ecosystem_intelligence canonical section from the pre-built ecosystem report.

    Rendering contract:
    1. watch_list_signals — render first; these are known-priority entities with new signals.
    2. mutation_log — render second; what changed in the graph this cycle.
    3. ambient_surface — render third; max 2 non-watch-list high-conviction findings.
    4. staleness_flags — render fourth; relationships needing verification attention.
    5. needs_todd — render as ask_todd items; CoS cannot resolve without user input.
    6. interrupt_queue — render last; pushed to interrupt queue this cycle.
    """
    eco = report.get("ecosystem_intelligence") or {}
    if not eco or eco.get("error"):
        error_msg = eco.get("error", "ecosystem graph unavailable")
        return [_canonical_item(
            title="Ecosystem intelligence unavailable",
            summary=f"RB could not build the ecosystem intelligence section: {error_msg}",
            disposition="ignore",
            grounding="stale_source_limited",
            freshness="stale",
            confidence="low",
        )]

    items: list[dict] = []

    # Watch list signals.
    for hit in eco.get("watch_list_signals") or []:
        status_text = _passive_intel_status_text(hit)
        items.append(_canonical_item(
            title=f"Watch list signal — {hit.get('entity_name', hit.get('entity_id'))}",
            summary=f"{hit.get('summary', '')} {status_text}".strip(),
            why_it_matters=f"Signal class: {hit.get('signal_class', '')}. This entity is on your watch list.",
            recommended_action=hit.get("recommended_action", "monitor"),
            disposition=hit.get("recommended_action", "monitor"),
            grounding="system_detected",
            freshness="fresh",
            confidence=hit.get("confidence", "medium"),
            source_refs=["ecosystem_intelligence_graph"],
            extras=_passive_intel_extras(hit),
            provenance=_passive_intel_provenance(hit),
            signal_state=hit.get("claim_status"),
        ))

    # Mutation log.
    mutations = eco.get("mutation_log") or []
    if mutations:
        mutation_summary = "; ".join(
            (
                f"{m.get('entity_name', m.get('entity_id'))} — "
                f"{m.get('signal_type', '').replace('_', ' ')} "
                f"({m.get('claim_status', 'unknown')}; "
                f"corroboration={m.get('corroboration_count', 0)}; "
                f"eligibility={m.get('graph_mutation_eligibility', 'unknown')})"
            )
            for m in mutations[:5]
        )
        items.append(_canonical_item(
            title=f"Ecosystem graph mutations this cycle ({len(mutations)})",
            summary=f"Graph updated: {mutation_summary}.",
            why_it_matters="These signals were written to the ecosystem graph from today's signal scan.",
            recommended_action="monitor",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            confidence="medium",
            source_refs=["ecosystem_intelligence_graph"],
            extras={
                "mutation_count": len(mutations),
                "passive_intelligence_contract": "rb_passive_intelligence_evaluation_v1",
                "mutations": mutations[:5],
            },
            provenance={
                "source_class": "externally_discovered",
                "source_ref_class": "system_artifact",
                "corroboration_count": max((m.get("corroboration_count", 0) for m in mutations), default=0),
                "corroboration_chain": ["ecosystem_intelligence_graph"],
            },
        ))

    # Ambient surface (max 2).
    for item in (eco.get("ambient_surface") or [])[:2]:
        status_text = _passive_intel_status_text(item)
        items.append(_canonical_item(
            title=f"Ambient signal — {item.get('entity_name', item.get('entity_id'))}",
            summary=f"{item.get('summary', '')} {status_text}".strip(),
            why_it_matters=f"CoS ambient scan. Signal class: {item.get('signal_class', '')}. Not currently on watch list.",
            recommended_action=item.get("recommended_action", "monitor"),
            disposition=item.get("recommended_action", "monitor"),
            grounding="system_detected",
            freshness="fresh",
            confidence=item.get("confidence", "medium"),
            source_refs=["ecosystem_intelligence_graph"],
            extras=_passive_intel_extras(item),
            provenance=_passive_intel_provenance(item),
            signal_state=item.get("claim_status"),
        ))

    # Staleness flags.
    stale = eco.get("staleness_flags") or []
    if stale:
        stale_summary = "; ".join(
            f"{s.get('from_entity_id', '')} → {s.get('to_entity_id', '')} ({s.get('days_overdue', '?')}d overdue)"
            for s in stale[:3]
        )
        items.append(_canonical_item(
            title=f"Stale vendor relationships ({len(stale)} flagged)",
            summary=f"These relationships need verification: {stale_summary}.",
            why_it_matters="Stale unverified relationships reduce brief trust. Use promote-confidence once a corroborating source is found.",
            recommended_action="monitor",
            disposition="monitor",
            grounding="system_detected",
            freshness="stale",
            confidence="low",
            source_refs=["ecosystem_intelligence_graph"],
        ))

    # Needs Todd.
    for need in eco.get("needs_todd") or []:
        items.append(_canonical_item(
            title=f"CoS recommendation — consider watching {need.get('entity_name', '')}",
            summary=need.get("suggestion", need.get("summary", "")),
            why_it_matters=f"Signal class: {need.get('signal_class', '')}. This entity is not on your watch list but had a high-conviction signal.",
            recommended_action="ask_todd",
            disposition="ask_todd",
            grounding="system_detected",
            freshness="fresh",
            confidence="medium",
            source_refs=["ecosystem_intelligence_graph"],
        ))

    # Interrupt queue items.
    for interrupt in eco.get("interrupt_queue") or []:
        items.append(_canonical_item(
            title=f"INTERRUPT — {interrupt.get('signal_type', '').replace('_', ' ').upper()}",
            summary=interrupt.get("summary", ""),
            why_it_matters="This signal meets the interrupt threshold: tier_1 watch list entity + qualifying signal class + high confidence + within 48 hours.",
            recommended_action="act_today",
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            confidence="high",
            source_refs=["ecosystem_interrupt_queue"],
        ))

    if not items:
        items.append(_canonical_item(
            title="Ecosystem intelligence — no new signals",
            summary="No new signals matched watch list or ambient threshold this cycle. Graph is current.",
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            confidence="high",
        ))

    return items


def _passive_intel_extras(item: dict) -> dict:
    """Return passive-intelligence metadata for canonical brief rendering."""
    return {
        "confidence_score": item.get("confidence_score"),
        "claim_status": item.get("claim_status"),
        "corroboration_count": item.get("corroboration_count", 0),
        "source_quality": item.get("source_quality"),
        "graph_mutation_eligibility": item.get("graph_mutation_eligibility"),
        "passive_intelligence_contract": "rb_passive_intelligence_evaluation_v1",
    }


def _passive_intel_provenance(item: dict) -> dict:
    """Map passive-intelligence metadata into the common provenance contract."""
    return {
        "source_class": "externally_discovered",
        "source_ref_class": "system_artifact",
        "corroboration_count": item.get("corroboration_count", 0),
        "corroboration_chain": item.get("corroboration_sources") or ["ecosystem_intelligence_graph"],
    }


def _passive_intel_status_text(item: dict) -> str:
    """Compact human-facing confidence/corroboration label for ecosystem signals."""
    claim_status = item.get("claim_status") or "insufficient_evidence"
    source_quality = item.get("source_quality") or "unknown"
    score = item.get("confidence_score")
    corroboration_count = item.get("corroboration_count", 0)
    eligibility = item.get("graph_mutation_eligibility") or "not_eligible"
    score_text = f"{score:.2f}" if isinstance(score, (int, float)) else "n/a"
    return (
        f"Intelligence status: {claim_status}; confidence score: {score_text}; "
        f"source quality: {source_quality}; corroboration: {corroboration_count}; "
        f"graph eligibility: {eligibility}."
    )


def _canonical_release_status(sections: dict, report: dict) -> list[dict]:
    """Score the daily brief against the RB 9.0 Chief-of-Staff contract."""
    prep = report.get("daily_prep_summary") or {}
    source_health = prep.get("source_health") or report.get("source_health") or {}
    delivery = report.get("delivery_check") or {}
    pipeline = report.get("morning_pipeline_state") or {}
    market = report.get("market_signals") or {}
    checks = {
        "resource_verification": "PASS" if sections.get("resource_verification_and_freshness_status") else "FAIL",
        "relationship_delta_analysis": "PASS" if sections.get("overnight_delta_intelligence") else "FAIL",
        "email_intelligence_harvest": "PASS" if sections.get("email_intelligence_harvest") else "FAIL",
        "autonomous_discovery": "PASS" if (sections.get("autonomous_discovery_evidence") or [{}])[0].get("title") == "Autonomous discovery proof" else "FAIL",
        "thesis_challenge": "PASS" if sections.get("thesis_confidence_and_challenges") else "FAIL",
        "macro_intelligence": "PASS" if sections.get("world_macro_macroeconomic_impact") else "FAIL",
        "pressure_stack": "PASS" if sections.get("macro_pressure_stack") else "FAIL",
        "pain_mapping": "PASS" if sections.get("restaurant_pain_mapping") else "FAIL",
        "franchise_alignment": "PASS" if sections.get("franchise_alignment_gap") else "FAIL",
        "action_lifecycle": "PASS" if sections.get("action_lifecycle_state") else "FAIL",
        "trust_telemetry": "PASS" if source_health else "PARTIAL",
        "action_generation": "PASS" if sections.get("recommended_actions_structured") and sections.get("action_orchestration_prompt") else "PARTIAL",
        "delivery_verification": (
            "PASS" if pipeline.get("ok") is True and delivery.get("automated_fail_count") == 0 else
            "PARTIAL" if delivery else "FAIL"
        ),
    }
    weights = {"PASS": 1.0, "PARTIAL": 0.5, "FAIL": 0.0}
    score = round(sum(weights[v] for v in checks.values()) / len(checks) * 100)
    disposition = "monitor" if score >= 85 else "act_today"
    failed = [k for k, v in checks.items() if v == "FAIL"]
    partial = [k for k, v in checks.items() if v == "PARTIAL"]
    return [_canonical_item(
        title="CANONICAL RELEASE STATUS",
        summary=(
            f"Canonicality score: {score}%. "
            f"PASS={sum(1 for v in checks.values() if v == 'PASS')}; "
            f"PARTIAL={len(partial)}; FAIL={len(failed)}."
        ),
        why_it_matters=(
            "The brief is accountable to the Chief-of-Staff contract: verified resources, deltas, "
            "passive email intelligence, autonomous discovery, thesis challenge, macro pressure, pain mapping, action state, delivery proof, and trust telemetry."
        ),
        recommended_action=(
            "Treat failed lanes as sprint defects before calling the brief canonical."
            if disposition == "act_today" else "Release criteria are satisfied for today's briefing."
        ),
        disposition=disposition,
        grounding="system_detected",
        freshness="fresh" if disposition == "monitor" else "stale_source_limited",
        source_refs=["canonical_brief.sections", "source_health.json", "task_delivery_check.json", "morning_pipeline.json"],
        confidence="high",
        extras={
            "canonicality_score": score,
            "checks": checks,
            "failed_lanes": failed,
            "partial_lanes": partial,
            "market_stale": bool(market.get("stale")),
        },
    )]


def _text_blob(item: dict) -> str:
    return " ".join(str(item.get(k) or "") for k in (
        "title", "summary", "signal_layer", "signal_type", "category",
        "pain_point_or_priority", "restaurant_operator_impact",
        "restaurant_tech_vendor_implication", "second_order_impact",
        "why_this_matters_to_todd", "relationship_opportunity",
    )).lower()


def _thesis_challenge_items(report: dict) -> list[dict]:
    """Render support and contradiction so RB does not become validation."""
    market_items = (report.get("market_signals") or {}).get("top") or []
    if not market_items:
        return [_canonical_item(
            title="Thesis challenge lane under-instrumented",
            summary="No source-backed market rows are available to test active restaurant-tech theses.",
            why_it_matters="RB must not reinforce a worldview from memory when current evidence is missing.",
            recommended_action="Refresh market, macro, and operator rows before using the brief as thesis validation.",
            disposition="act_today",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["market_signals"],
            confidence="high",
        )]

    support = []
    challenge = []
    for item in market_items[:12]:
        blob = _text_blob(item)
        if any(k in blob for k in (
            "rollback", "lawsuit", "failed", "failure", "errors", "skeptic",
            "trust", "friction", "integration", "resistance", "burned",
            "reliability", "accuracy", "rollout risk",
        )):
            support.append(item)
        if any(k in blob for k in (
            "launch", "rollout", "expansion", "adoption", "investment",
            "deploy", "automation", "productivity", "labor savings",
            "ai backbone", "introduces", "scale",
        )):
            challenge.append(item)

    title = "Dynamic thesis confidence"
    summary = (
        f"Evidence supporting operator skepticism / operational realism: {len(support)} item(s). "
        f"Evidence challenging or complicating that thesis: {len(challenge)} item(s)."
    )
    confidence = "medium" if support and challenge else "low" if not challenge else "medium"
    action = (
        "Carry both sides into outreach and content: skeptical operators exist, but adoption and investment are still moving."
        if support and challenge else
        "Actively seek contradictory evidence before treating the current thesis as strong."
    )
    return [_canonical_item(
        title=title,
        summary=summary,
        why_it_matters=(
            "Decision quality improves when RB shows evidence that weakens or complicates Todd's standing thesis, "
            "not only evidence that supports it."
        ),
        recommended_action=action,
        disposition="monitor" if challenge else "ask_todd",
        grounding="system_detected",
        freshness="fresh" if not (report.get("market_signals") or {}).get("stale") else "stale_source_limited",
        source_refs=[
            *[f"market_signals.url:{i.get('url')}" for i in support[:2] if i.get("url")],
            *[f"market_signals.url:{i.get('url')}" for i in challenge[:2] if i.get("url")],
        ] or ["market_signals"],
        confidence=confidence,
        extras={
            "active_thesis": "Operators are increasingly skeptical of fragmented AI/SaaS solutions.",
            "supporting_evidence_titles": [i.get("title") for i in support[:5]],
            "contradictory_or_complicating_titles": [i.get("title") for i in challenge[:5]],
            "confidence_direction": "mixed" if support and challenge else "under_tested",
        },
    )]


def _wrb_content_fingerprint(item: dict) -> str:
    """Normalized snippet identifying the underlying fact an item restates.

    Watchlist escalations copy their triggering evidence's text verbatim
    into extras.evidence_headline -- confirmed live: the same overdue loop
    matched two watchlist entities ("McDonald's" and "Genius") and rendered
    as two separate escalation items with identical evidence_headline text,
    and a Yum Brands earnings release and a Stripe-mentioning email headline
    each independently qualified for promotion via two different source
    paths (earnings_intelligence + watchlist escalation; email headline +
    watchlist escalation). Title-only dedup misses all of these since each
    path titles its copy differently. Prefer the fields that carry the
    actual restated fact (evidence_headline, headline_text) over title/
    summary, strip any leading "[TAG] " bracket prefix, and compare a
    60-char prefix -- long enough to distinguish real stories, short enough
    to survive minor rewording between the two paths.
    """
    ex = item.get("extras") or {}
    text = ex.get("evidence_headline") or ex.get("headline_text") or item.get("summary") or item.get("title") or ""
    text = re.sub(r"^\[[^\]]+\]\s*", "", text.strip())
    return text.lower()[:60]


_WRB_SOURCE_LABELS = {
    "earnings": "an earnings/press-release signal",
    "watchlist": "a watchlist escalation",
    "strategic": "a tracked strategic-signal update",
}


def _wrb_item_entities(item: dict, source: str) -> set[str]:
    """Normalized entity name(s) a What-RB-Found candidate is about, keyed
    by its source's own shape: earnings/watchlist items each carry a single
    named entity (extras.company / extras.entity_name); a strategic-signal
    event can name several companies (extras.entities.companies, built by
    strategic_events.py as a plain list of name strings)."""
    extras = item.get("extras") or {}
    if source == "earnings":
        names = [extras.get("company")]
    elif source == "watchlist":
        names = [extras.get("entity_name")]
    elif source == "strategic":
        names = list((extras.get("entities") or {}).get("companies") or [])
    else:
        names = []
    return {n.strip().lower() for n in names if n and n.strip()}


def _wrb_synthesize_connected_item(display_name: str, hits: list[tuple[str, dict]]) -> dict:
    """RB-2026-09-19: the actual point of a "connect the dots" discovery
    layer -- an entity independently surfaced by >=2 of What RB Found's
    three sources on the SAME day is a materially stronger signal than any
    one of them alone (independent sources rarely agree by coincidence),
    but until now each source's item was listed separately with nothing
    indicating the other two even existed. Folds them into one item instead
    of restating the same entity 2-3 times with no correlation drawn."""
    sources_hit = sorted({s for s, _ in hits})
    labels = [_WRB_SOURCE_LABELS.get(s, s) for s in sources_hit]
    titles = [it.get("title", "") for _, it in hits if it.get("title")]
    refs: list[str] = []
    for _, it in hits:
        refs.extend(it.get("source_refs") or [])
    return _canonical_item(
        title=f"[CONNECTED] {display_name} — {' + '.join(labels)}",
        summary=(
            f"{display_name} shows up today across {len(sources_hit)} independent sources RB "
            f"tracks separately: {', '.join(labels)}. " + " ".join(f'"{t}"' for t in titles)
        ),
        why_it_matters=(
            f"{display_name} appearing in {len(sources_hit)} unrelated feeds the same day is a "
            "stronger signal than any one of them alone -- independent sources rarely agree by "
            "coincidence. Reviewing them separately would miss that they're the same story."
        ),
        recommended_action=(
            f"Review {display_name}'s combined activity before treating any one of these as routine."
        ),
        disposition="act_today",
        grounding="system_detected",
        freshness="fresh",
        source_refs=refs or ["what_rb_found_synthesis"],
        confidence="high" if len(sources_hit) >= 3 else "medium",
        extras={
            "connected_sources": sources_hit,
            "entity_name": display_name,
            "component_titles": titles,
        },
    )


def _what_rb_found_v1_additional_sources(sections: dict) -> None:
    """RB-2026-09-10: "What RB Found Without You Telling It" v1 redesign.

    Todd, reviewing the section live: it should surface "items that were
    gathered through the intelligence sequence, that the user did not
    enter, that are meaningful in their world" -- overnight emails (handled
    separately by reopening email_intelligence_harvest as a discovery
    source, see _discovery_source_sections), high-value earnings/press-
    release hits, and new evidence for or against a tracked strategic
    signal -- ahead of the routine news sections, not buried below them.

    earnings_intelligence and watchlist_intelligence don't fit the generic
    novelty-based discovery_source_sections mechanism: earnings_monitor.py's
    _canonical_earnings_item() hardcodes autonomous_discovery_value="high"
    on every item regardless of type, so a routine "reports in N days"
    countdown reminder would score identically to an actual reported result
    -- exactly the low-value clutter this redesign is meant to remove, not
    reintroduce. watchlist_intelligence has the opposite problem: it carries
    one item per mandatory-coverage entity (100+), most legitimately "no
    change detected" placeholders that would also default to a "medium"
    autonomous_discovery_value under the generic externally_discovered
    rule. Both need an explicit, narrow filter instead of generic list
    membership.

    Mutates sections["what_rb_found_without_you_telling_it"] directly
    (rather than returning a list for the caller to dedup by title) so the
    content-fingerprint dedup below can check against what the earlier
    discovery-routing pass already added, and against its own three
    sources, in one place. Called after earnings_intelligence and
    watchlist_intelligence are populated (both compute later in
    build_report than this module's other section builders), so it cannot
    run inside the main discovery-routing pass above them -- see its call
    site.

    RB-2026-09-19: the three sources below used to be three independent
    appends with no cross-referencing -- an entity hit by both a watchlist
    escalation AND a fresh strategic-signal update on the same day was
    listed twice with nothing connecting them, which is exactly the "single-
    source pattern matching, not real dot-connecting" gap the 2026-08-28/
    2026-09-19 strategic assessments both flagged for this specific section
    (its own name promises synthesis; it wasn't doing any). Candidates are
    now collected first, grouped by entity, and an entity qualifying from
    >=2 distinct sources is folded into one _wrb_synthesize_connected_item()
    instead of being listed once per source. Deliberately scoped to only
    these three already-narrow, already-computed sources -- NOT a
    reimplementation of connect_the_dots's cross-time IntelligenceDB
    convergence engine, which already does this at a broader scale for a
    different section; duplicating that here would add a second synthesis
    engine on top of the very redundancy problem flagged in
    rb_daily_brief_quality_pass_2026_09_04.
    """
    target = sections["what_rb_found_without_you_telling_it"]
    _seen_fp = {_wrb_content_fingerprint(i) for i in target if isinstance(i, dict)}

    def _add(item: dict) -> None:
        fp = _wrb_content_fingerprint(item)
        if fp and fp in _seen_fp:
            return
        target.append(item)
        if fp:
            _seen_fp.add(fp)

    _candidates: list[tuple[str, dict]] = []

    # 1. Highest-materiality earnings/press-release hit: a real,
    # already-reported post-earnings signal only -- not the pre-earnings
    # countdown reminder (that's calendar awareness, not a discovery) and
    # not the [SCAN-HEALTH] self-check row. Ranked by strategic relevance,
    # then whether it's part of a recurring cross-quarter theme (the same
    # "sustained theme, not a one-off" materiality signal Section F already
    # uses for watchlist escalations); only the single highest-materiality
    # hit is promoted so this doesn't become a second earnings section.
    _post_earnings = [
        i for i in (sections.get("earnings_intelligence") or [])
        if isinstance(i, dict) and (i.get("extras") or {}).get("earnings_type") == "post_earnings_signal"
    ]
    if _post_earnings:
        def _earnings_rank(i: dict) -> tuple:
            rel = (i.get("extras") or {}).get("strategic_relevance") or "low"
            rel_rank = {"high": 0, "medium": 1, "low": 2}.get(rel, 2)
            has_trend = 0 if (i.get("extras") or {}).get("trend_note") else 1
            return (rel_rank, has_trend)
        _candidates.append(("earnings", sorted(_post_earnings, key=_earnings_rank)[0]))

    # 2. Watchlist escalations -- entity/press-release-driven status changes
    # ("Escalation" or "New Activity") already computed for Section F.
    # disposition=act_today is set only for those two status transitions,
    # so it's a clean, already-computed materiality signal -- not a second
    # ranking pass on top of Section F's own.
    #
    # RB-2026-09-10: confirmed live -- "McDonald's — Escalation: Overdue
    # loop L-2026-08-11-001 — Jeff Coffland" reached "What RB Found Without
    # You Telling It" here. That's a direct violation of the standing
    # editorial rule (feedback_rb_brief_editorial_standard): "Intelligence
    # Brief Section F is industry/watchlist movement (source-backed market
    # intelligence) — it is NOT where overdue internal loops/escalations
    # belong ... belongs in the Daily Brief instead." Section F's own
    # renderer (_render_watchlist_material_activity in
    # render_intelligence_brief.py) already excludes exactly this --
    # `extras.loop_id` set, or "overdue loop" in the why/summary text -- so
    # McDonald's correctly never appears in the rendered Section F; this
    # promotion loop read the same raw watchlist_intelligence data before
    # that filter runs and skipped it. Same exclusion, applied here too.
    for i in (sections.get("watchlist_intelligence") or []):
        if not isinstance(i, dict) or i.get("disposition") != "act_today":
            continue
        _ex = i.get("extras") or {}
        _why_or_summary = (i.get("why_it_matters") or i.get("summary") or "").lower()
        if _ex.get("loop_id") or "overdue loop" in _why_or_summary:
            continue
        _candidates.append(("watchlist", i))

    # 3. New evidence, arriving today, for or against a tracked strategic
    # signal (Section I). Excludes signals sitting with no new evidence
    # since a prior day -- those are "ongoing, unchanged" framing, not
    # something RB found today.
    for i in (sections.get("strategic_industry_signals") or []):
        if not isinstance(i, dict):
            continue
        days = (i.get("extras") or {}).get("days_since_evidence")
        if days is not None and days <= 1:
            _candidates.append(("strategic", i))

    # RB-2026-09-19: group qualifying candidates by entity; fold any entity
    # hit by >=2 distinct sources into one connected item instead of
    # listing it once per source with no correlation drawn (see docstring).
    _by_entity: dict[str, list[tuple[str, dict]]] = {}
    for source, item in _candidates:
        for name in _wrb_item_entities(item, source):
            _by_entity.setdefault(name, []).append((source, item))

    _folded_ids: set[int] = set()
    for name, hits in _by_entity.items():
        sources_hit = {s for s, _ in hits}
        if len(sources_hit) < 2:
            continue
        display_name = next(
            (
                (it.get("extras") or {}).get("entity_name") or (it.get("extras") or {}).get("company")
                for _, it in hits
                if (it.get("extras") or {}).get("entity_name") or (it.get("extras") or {}).get("company")
            ),
            name,
        )
        _add(_wrb_synthesize_connected_item(display_name, hits))
        _folded_ids.update(id(it) for _, it in hits)

    for _, item in _candidates:
        if id(item) not in _folded_ids:
            _add(item)


def _macro_pressure_stack_items(report: dict) -> list[dict]:
    market = report.get("market_signals") or {}
    items = market.get("top") or []
    macro_items = [i for i in items if i.get("macro_force")]
    forces = []
    for item in macro_items:
        mf = item.get("macro_force")
        if mf and mf not in forces:
            forces.append(mf)
    if not macro_items:
        return [_canonical_item(
            title="Pressure stack under-instrumented",
            summary=(
                "No source-backed tariff, oil/fuel, labor, commodity, interest-rate, consumer-spend, "
                "credit, or supply-chain row was elevated."
            ),
            why_it_matters="RB cannot responsibly infer restaurant margin pressure or sales-cycle friction without current macro evidence.",
            recommended_action="Add or refresh macro market_signals rows before making pressure-stack conclusions.",
            disposition="act_today" if market.get("stale") else "monitor",
            grounding="system_detected",
            freshness="stale_source_limited" if market.get("stale") else "fresh",
            source_refs=["market_signals"],
            confidence="medium",
        )]
    item = macro_items[0]
    chain = (
        f"{item.get('macro_force')} -> {item.get('restaurant_operator_impact') or 'operator cost or demand pressure'} -> "
        f"{item.get('restaurant_tech_vendor_implication') or 'vendor ROI scrutiny and sales-cycle pressure'}"
    )
    return [_canonical_item(
        title="Macroeconomic pressure stack",
        summary=f"Detected macro force(s): {', '.join(forces[:6])}. Chain: {chain}",
        why_it_matters=(
            "Macro pressure affects restaurant P&L, franchisee tolerance, technology budgets, "
            "implementation risk, and vendor sales timing."
        ),
        recommended_action="Translate macro items into buying-timing, ROI, and pipeline-risk assumptions before outreach.",
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh",
        source_refs=[f"market_signals.url:{i.get('url')}" for i in macro_items[:4] if i.get("url")] or ["market_signals"],
        confidence="medium",
        extras={
            "macro_forces": forces,
            "pressure_chain": chain,
            "operator_impact": item.get("restaurant_operator_impact"),
            "vendor_implication": item.get("restaurant_tech_vendor_implication"),
        },
    )]


PAIN_KEYWORDS = {
    "known_solvable_pain": ("labor scheduling", "forecast", "loyalty", "reporting", "training"),
    "operationally_unsolved_pain": ("accuracy", "friday night", "peak", "store-level", "throughput", "inventory"),
    "economically_constrained_pain": ("margin", "cost", "food cost", "labor cost", "cash flow", "roi", "ebitda"),
    "trust_damaged_pain": ("trust", "burned", "lawsuit", "rollback", "failed", "errors", "reliability"),
    "politically_constrained_pain": ("franchisee", "franchisor", "co-op", "governance", "standardization", "mandate"),
    "culturally_normalized_pain": ("always", "never", "manual", "workaround", "normalized", "accepted"),
    "theoretically_solved_practically_broken_pain": ("integration", "integrations", "fragmented", "implementation", "deployment"),
}


def _pain_mapping_items(report: dict) -> list[dict]:
    items = (report.get("market_signals") or {}).get("top") or []
    counts = {k: 0 for k in PAIN_KEYWORDS}
    examples: dict[str, list[str]] = {k: [] for k in PAIN_KEYWORDS}
    for item in items:
        blob = _text_blob(item)
        for pain_type, keywords in PAIN_KEYWORDS.items():
            if any(k in blob for k in keywords):
                counts[pain_type] += 1
                if len(examples[pain_type]) < 3:
                    examples[pain_type].append(item.get("title") or "Market signal")
    nonzero = {k: v for k, v in counts.items() if v}
    if not nonzero:
        return [_canonical_item(
            title="Pain mapping under-instrumented",
            summary="No current market item mapped cleanly to the restaurant pain taxonomy.",
            why_it_matters="RB should identify operational scars and adoption friction, not only market categories.",
            recommended_action="Enrich market rows with pain_point_or_priority, operator impact, deployment risk, and trust burden.",
            disposition="ask_todd",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["market_signals", "RB_9_RESTAURANT_REALITY_INTELLIGENCE_MODEL.md"],
            confidence="medium",
        )]
    top_type = max(nonzero, key=nonzero.get)
    return [_canonical_item(
        title="Restaurant pain map",
        summary="; ".join(f"{k}={v}" for k, v in sorted(nonzero.items())),
        why_it_matters=(
            "Pain category determines the GTM burden: solution proof, operational proof, economic proof, "
            "trust repair, political navigation, or belief transformation."
        ),
        recommended_action=f"Treat {top_type} as the primary adoption-risk lens for today's restaurant-tech signals.",
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh" if not (report.get("market_signals") or {}).get("stale") else "stale_source_limited",
        source_refs=["market_signals", "RB_9_RESTAURANT_REALITY_INTELLIGENCE_MODEL.md"],
        confidence="medium",
        extras={
            "pain_counts": counts,
            "examples_by_pain_type": examples,
            "primary_pain_type": top_type,
        },
    )]


def _franchise_alignment_items(report: dict) -> list[dict]:
    items = []
    for item in (report.get("market_signals") or {}).get("top") or []:
        blob = _text_blob(item)
        if any(k in blob for k in ("franchisee", "franchisor", "brand standard", "standardization", "rollout", "mandate", "governance")):
            items.append(item)
    if not items:
        return [_canonical_item(
            title="No franchise alignment-gap signal elevated",
            summary="No source-backed item currently names franchisee/franchisor rollout politics, governance, or standardization tension.",
            why_it_matters="Absence is a scan result only. Franchise economics may still determine rollout success even when current sources do not mention it.",
            recommended_action="Monitor brand-specific rollout, franchisee sentiment, and governance sources before assuming adoption is straightforward.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh" if not (report.get("market_signals") or {}).get("stale") else "stale_source_limited",
            source_refs=["market_signals"],
            confidence="medium",
        )]
    sample = items[0]
    return [_canonical_item(
        title="Franchisor / franchisee alignment gap",
        summary=(
            f"{len(items)} item(s) suggest rollout politics, franchisee trust, standardization, or governance tension. "
            f"Example: {sample.get('title')}"
        ),
        why_it_matters=(
            "Franchisors may value standardization, data, visibility, and brand consistency while franchisees value cash impact, "
            "simplicity, labor savings, support, and survivability."
        ),
        recommended_action="Evaluate the alignment gap before treating enterprise brand interest as franchisee adoption readiness.",
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh",
        source_refs=[f"market_signals.url:{i.get('url')}" for i in items[:4] if i.get("url")] or ["market_signals"],
        confidence="medium",
        extras={
            "alignment_gap_definition": "distance between franchisor value perception and franchisee value perception",
            "signals": [i.get("title") for i in items[:5]],
            "franchisor_value_lens": ["standardization", "reporting visibility", "customer data", "brand consistency"],
            "franchisee_value_lens": ["labor savings", "simplicity", "support responsiveness", "clear profitability impact"],
        },
    )]


def _suppressed_sent_followup_thread_ids() -> set[str]:
    settings = core.load_settings()
    return {
        str(thread_id)
        for thread_id in (
            (settings.get("email_overlay") or {})
            .get("suppressed_sent_followup_thread_ids")
            or []
        )
        if thread_id
    }


def _is_suppressed_sent_followup_thread(thread_id: object) -> bool:
    return bool(thread_id) and str(thread_id) in _suppressed_sent_followup_thread_ids()


# RB-2026-09-05: daily_brief.py has no cross-day dedup at all -- unlike
# render_intelligence_brief.py's core.StoryLedger (which suppresses a
# corporate news story once it's been shown a few days running), a
# generator here that keeps re-matching the same stale underlying record
# (a feeder signal, a sent-loop-verification thread) re-renders it verbatim
# forever. Confirmed live: the "Sizzling Platter" feeder-signal item in
# "What RB Found Without You Telling It" was byte-for-byte identical for 5
# straight days, and sent-loop-verification items for the same thread kept
# resurfacing across non-consecutive days. This is a small, purpose-built
# equivalent of StoryLedger for that class of bug -- not corporate-news
# identity resolution, just "have I already shown this exact content
# recently, and is there genuinely new evidence since." A single grace
# window that suits repeated nags (short) is used for both use sites below.
# RB-2026-09-06: hardcoded to the real system dir with no env-var override
# (unlike every other cross-run cache path in this codebase -- see
# conftest.py's RB_AUDIT_DIR/RB_REQUEST_LOG_PATH/etc. pattern), this file
# was silently contaminated by the test suite itself: any test that reaches
# _email_intelligence_harvest_items/_strategic_operator_items/the decision-
# layer annotation without isolating this path wrote real ledger entries
# using whatever fabricated `today` its fixtures used. Confirmed live: the
# real system/.cache/daily_brief_item_ledger.json ended up with entries
# dated first_seen=2026-05-28 and render_count in the hundreds, months
# before this feature existed. Same fix as every other such path: read an
# env var, default to the real location, and register the override in
# conftest.py so tests never touch production state again.
_BRIEF_ITEM_LEDGER_PATH = Path(os.environ.get(
    "RB_BRIEF_ITEM_LEDGER_PATH", str(core.SYSTEM_DIR / ".cache" / "daily_brief_item_ledger.json"),
))
_BRIEF_ITEM_ACTIVE_DISPLAY_DAYS = 3


def _load_brief_item_ledger() -> dict:
    try:
        return json.loads(_BRIEF_ITEM_LEDGER_PATH.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return {}


def _save_brief_item_ledger(ledger: dict) -> None:
    try:
        _BRIEF_ITEM_LEDGER_PATH.parent.mkdir(parents=True, exist_ok=True)
        _BRIEF_ITEM_LEDGER_PATH.write_text(json.dumps(ledger, indent=2, sort_keys=True), encoding="utf-8")
    except Exception:  # noqa: BLE001
        pass  # dedup ledger is a display nicety -- never block the brief on a write failure


def _should_render_repeatable_item(
    ledger: dict, key: str, today_iso: str, *,
    active_display_days: int = _BRIEF_ITEM_ACTIVE_DISPLAY_DAYS,
    activity_marker: str | None = None,
) -> bool:
    """True if `key` (a stable content identity, not a URL) hasn't already
    been shown for `active_display_days` running with no new evidence.

    `activity_marker` is whatever proves the underlying fact changed (e.g.
    last_activity_at on a sent-loop thread, or a feeder item's URL) -- when
    it differs from what was recorded last time, this is genuinely new
    evidence and always renders, resetting the display window."""
    entry = ledger.get(key)
    if not entry or not entry.get("first_seen"):
        return True
    if activity_marker and activity_marker != entry.get("last_activity_marker"):
        return True
    first_seen = date.fromisoformat(entry["first_seen"])
    days_shown = (date.fromisoformat(today_iso) - first_seen).days
    return days_shown < active_display_days


def _record_brief_item_seen(
    ledger: dict, key: str, today_iso: str, *, activity_marker: str | None = None,
) -> None:
    entry = ledger.get(key)
    if not entry or (activity_marker and activity_marker != entry.get("last_activity_marker")):
        entry = {"first_seen": today_iso}
        ledger[key] = entry
    entry["last_seen"] = today_iso
    entry["last_activity_marker"] = activity_marker
    entry["render_count"] = entry.get("render_count", 0) + 1


def _action_lifecycle_items(report: dict) -> list[dict]:
    email = report.get("email") or {}
    loops = report.get("loops") or {}
    sent = [
        s for s in (email.get("sent_followups") or [])
        if not _is_suppressed_sent_followup_thread(s.get("thread_id"))
    ]
    overdue_sent = [s for s in sent if s.get("response_status") == "response_overdue"]
    waiting_sent = [s for s in sent if s.get("response_status") != "response_overdue"]
    recently_closed = loops.get("closed") or []
    summary = (
        f"{len(sent)} sent follow-up(s) tracked; {len(overdue_sent)} overdue; "
        f"{len(waiting_sent)} still waiting/in-window; {len(loops.get('overdue') or [])} open loop(s) overdue; "
        f"{len(loops.get('due_today') or [])} due today; {len(recently_closed)} closed loop(s) retained."
    )
    action = (
        "Follow up only on overdue items; suppress redundant outreach for actions already sent or closed."
        if sent or recently_closed else
        "No sent-follow-up lifecycle evidence found; rely on loop state and source freshness before recommending outreach."
    )
    return [_canonical_item(
        title="Action lifecycle state",
        summary=summary,
        why_it_matters=(
            "RB should track state transitions: recommended, sent/completed, waiting, overdue, stale, suppressed, or ready for reassessment."
        ),
        recommended_action=action,
        disposition="act_today" if overdue_sent or loops.get("overdue") else "monitor",
        grounding="system_detected",
        freshness="fresh" if email.get("fetched_at") else "stale_source_limited",
        source_refs=["email_overlay.sent_followups", "loop_ledger"],
        confidence="high" if email.get("fetched_at") else "medium",
        extras={
            "sent_followups": len(sent),
            "overdue_sent_followups": len(overdue_sent),
            "waiting_sent_followups": len(waiting_sent),
            "overdue_loops": len(loops.get("overdue") or []),
            "due_today_loops": len(loops.get("due_today") or []),
            "closed_loops_retained": len(recently_closed),
            "suppression_rule": "do not recommend a duplicate outreach when sent/completed evidence exists",
        },
    )]


_LIFECYCLE_STOPWORDS = {
    "with", "from", "that", "this", "today", "tomorrow", "monitor", "review",
    "create", "follow", "action", "signal", "source", "thread", "email",
    "loop", "loops", "brief", "market", "restaurant", "industry", "candidate",
    "recommended", "recommendation", "status", "fresh", "stale", "system",
    "update", "updates", "strategic", "strategy", "next", "steps", "complete",
    "completed", "window", "waiting", "response", "responses",
}


def _lifecycle_tokens(text: str) -> set[str]:
    return {
        tok.lower()
        for tok in re.findall(r"[A-Za-z0-9][A-Za-z0-9'._-]{2,}", text or "")
        if len(tok) >= 4 and tok.lower() not in _LIFECYCLE_STOPWORDS
    }


def _lifecycle_item_text(item: dict) -> str:
    extras = item.get("extras") or {}
    return " ".join(str(v or "") for v in (
        item.get("title"),
        item.get("summary"),
        item.get("recommended_action"),
        item.get("why_it_matters"),
        extras.get("triggering_signal"),
        extras.get("source"),
    ))


def _is_lifecycle_sensitive_action(item: dict) -> bool:
    title = str(item.get("title") or "")
    if title.startswith("SENT LOOP VERIFICATION") or title == "EMAIL INTELLIGENCE HARVEST":
        return False
    text = " ".join(str(v or "") for v in (
        item.get("title"),
        item.get("recommended_action"),
        (item.get("extras") or {}).get("triggering_signal"),
    )).lower()
    return bool(re.search(
        r"\b("
        r"follow[- ]?up|followup|reach out|outreach|reply|respond|reconnect|"
        r"circle back|touch base|draft .*follow|send .*follow|send .*email|"
        r"create .*loop|waiting loop|close .*loop|update .*loop|defer loop"
        r")\b",
        text,
    ))


def _lifecycle_evidence_rows(report: dict) -> list[dict]:
    rows: list[dict] = []
    loops = report.get("loops") or {}
    for bucket in ("overdue", "due_today", "this_week", "future", "closed"):
        for loop in loops.get(bucket) or []:
            text = " ".join(str(loop.get(k) or "") for k in ("party", "description", "status_raw", "id"))
            rows.append({
                "kind": "loop",
                "state": "closed" if bucket == "closed" else f"open_{bucket}",
                "id": loop.get("id"),
                "label": loop.get("party") or loop.get("description") or loop.get("id"),
                "summary": loop.get("description") or "",
                "tokens": _lifecycle_tokens(text),
                "source_ref": f"loop_ledger:{loop.get('id')}",
            })

    for sent in (report.get("email") or {}).get("sent_followups") or []:
        if _is_suppressed_sent_followup_thread(sent.get("thread_id")):
            continue
        recipients = " ".join(
            " ".join(str(r.get(k) or "") for k in ("name", "email"))
            for r in sent.get("to") or []
            if isinstance(r, dict)
        )
        text = " ".join(str(v or "") for v in (
            sent.get("subject"), sent.get("snippet"), recipients,
            sent.get("response_status"), sent.get("category"),
        ))
        status = sent.get("response_status") or "unknown"
        state = "sent_waiting" if status == "awaiting_response" else "sent_overdue" if status == "response_overdue" else "sent_unknown"
        rows.append({
            "kind": "email_sent_followup",
            "state": state,
            "id": sent.get("thread_id"),
            "label": sent.get("subject") or recipients or sent.get("thread_id"),
            "summary": sent.get("snippet") or "",
            "tokens": _lifecycle_tokens(text),
            "source_ref": f"email_overlay.sent_followups:{sent.get('thread_id')}",
        })

    for sent in (report.get("passive_email_intelligence") or {}).get("sent_loop_verification") or []:
        if _is_suppressed_sent_followup_thread(sent.get("thread_id")):
            continue
        recipients = " ".join(
            " ".join(str(r.get(k) or "") for k in ("name", "email"))
            for r in sent.get("recipients") or []
            if isinstance(r, dict)
        )
        text = " ".join(str(v or "") for v in (
            sent.get("subject"), sent.get("snippet"), recipients,
            sent.get("category"), sent.get("lifecycle_state"),
        ))
        state = (
            "sent_waiting"
            if sent.get("lifecycle_state") == "outbound_sent_awaiting_response"
            else "response_received"
            if sent.get("lifecycle_state") == "response_received_after_outbound"
            else "sent_unknown"
        )
        rows.append({
            "kind": "passive_sent_verification",
            "state": state,
            "id": sent.get("thread_id"),
            "label": sent.get("subject") or recipients or sent.get("thread_id"),
            "summary": sent.get("lifecycle_effect") or sent.get("snippet") or "",
            "tokens": _lifecycle_tokens(text),
            "source_ref": f"passive_email_intelligence.sent_loop:{sent.get('thread_id')}",
        })
    return rows


def _public_lifecycle_match(row: dict) -> dict:
    return {
        "kind": row.get("kind"),
        "state": row.get("state"),
        "id": row.get("id"),
        "label": row.get("label"),
        "summary": row.get("summary"),
        "source_ref": row.get("source_ref"),
        "overlap": row.get("overlap") or [],
    }


def _lifecycle_gate(item: dict, report: dict, evidence_rows: list[dict] | None = None) -> dict:
    if evidence_rows is None:
        evidence_rows = _lifecycle_evidence_rows(report)
    item_tokens = _lifecycle_tokens(_lifecycle_item_text(item))
    sensitive = _is_lifecycle_sensitive_action(item)
    matches = []
    for row in evidence_rows:
        overlap = sorted(item_tokens & (row.get("tokens") or set()))
        if len(overlap) >= 2:
            matches.append({**row, "overlap": overlap[:6]})

    if not matches:
        return {"decision": "allow", "state": "not_matched", "matches": []}

    def _by_state(states: set[str]) -> dict | None:
        for row in matches:
            if row.get("state") in states:
                return row
        return None

    closed = _by_state({"closed"})
    waiting = _by_state({"sent_waiting", "response_received"})
    future = _by_state({"open_this_week", "open_future"})
    active = _by_state({"open_overdue", "open_due_today", "sent_overdue"})

    if sensitive and closed:
        return {
            "decision": "suppress",
            "state": "closed",
            "reason": f"Suppressed because matching loop/action is already closed: {closed.get('label')}.",
            "matches": [_public_lifecycle_match(closed)],
        }
    if sensitive and waiting:
        state = waiting.get("state")
        return {
            "decision": "suppress",
            "state": state,
            "reason": f"Suppressed because sent/email evidence already covers this action: {waiting.get('label')}.",
            "matches": [_public_lifecycle_match(waiting)],
        }
    if sensitive and future:
        return {
            "decision": "suppress",
            "state": future.get("state"),
            "reason": f"Suppressed because an existing open loop is not due for duplicate action: {future.get('label')}.",
            "matches": [_public_lifecycle_match(future)],
        }
    if sensitive and active:
        return {
            "decision": "allow_existing",
            "state": active.get("state"),
            "reason": f"Allowed through existing lifecycle item instead of creating a duplicate: {active.get('label')}.",
            "matches": [_public_lifecycle_match(active)],
        }
    return {"decision": "allow", "state": "matched_non_blocking", "matches": [_public_lifecycle_match(m) for m in matches[:2]]}


def _email_intelligence_harvest_items(report: dict) -> list[dict]:
    pei_report = report.get("passive_email_intelligence") or {}
    telemetry = pei_report.get("telemetry") or {}
    spam_cov = telemetry.get("spam_trash_coverage") or {}
    top = pei_report.get("top_headlines") or []
    sent_loops = [
        r for r in (pei_report.get("sent_loop_verification") or [])
        if not _is_suppressed_sent_followup_thread(r.get("thread_id"))
    ]
    accel = pei_report.get("trend_acceleration") or []
    if pei_report.get("error"):
        return [_canonical_item(
            title="EMAIL INTELLIGENCE HARVEST unavailable",
            summary=f"Passive email intelligence failed: {pei_report.get('error')}",
            why_it_matters="The inbox is a high-value intelligence stream; failure here means net-new market signals may be missed.",
            recommended_action="Run python3 system/scripts/passive_email_intelligence.py --cache --json and inspect the error.",
            disposition="act_today",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["passive_email_intelligence.py"],
            confidence="high",
        )]
    summary = (
        f"Newsletters scanned: {telemetry.get('newsletters_scanned', 0)}; "
        f"relevant headlines extracted: {telemetry.get('relevant_headlines_extracted', 0)}; "
        f"deep dives triggered: {telemetry.get('deep_dives_triggered', 0)}; "
        f"net-new strategic signals: {telemetry.get('net_new_strategic_signals', 0)}; "
        f"sent-loop signals: {telemetry.get('sent_loop_signals', 0)}; "
        f"outbound awaiting response: {telemetry.get('sent_outbound_awaiting_response', 0)}; "
        f"responses after sent mail: {telemetry.get('sent_response_after_outbound', 0)}; "
        f"noise suppressed: {telemetry.get('noise_suppressed', 0)}; "
        f"junk/spam/trash relevant finds: {telemetry.get('junk_spam_trash_relevant_finds', 0)}."
    )
    coverage = spam_cov.get("coverage_status") or "unknown"
    why = (
        "The headline is not the intelligence. RB extracts weak signals, pain categories, thesis implications, "
        "and deep-dive candidates from passive industry email before Todd manually screenshots or forwards them."
    )
    item = _canonical_item(
        title="EMAIL INTELLIGENCE HARVEST",
        summary=summary,
        why_it_matters=why,
        recommended_action=(
            "Retrieve underlying articles for deep-dive candidates; current normalized email cache has metadata/snippets only."
            if telemetry.get("deep_dives_blocked_no_link") else
            "Review top harvested headlines, sent-loop verification, and trend acceleration candidates."
        ),
        disposition="act_today" if telemetry.get("deep_dives_triggered") or telemetry.get("sent_loop_signals") else "monitor",
        grounding="system_detected",
        freshness="fresh",
        source_refs=["passive_email_intelligence.json", "email_intelligence_sources.json"],
        confidence="medium" if coverage == "not_proven_by_current_fetch" else "high",
        action_options=["retrieve_deep_dive_articles", "add_to_market_watchlist", "suppress_noise"],
        extras={
            "telemetry": telemetry,
            "spam_trash_coverage_status": coverage,
            "top_headlines": [
                {
                    "headline": r.get("headline"),
                    "source": r.get("source"),
                    "received_at": r.get("received_at"),
                    "score": r.get("strategic_relevance_score"),
                    "category": r.get("category"),
                    "themes": r.get("themes") or [],
                    "pain_types": r.get("pain_types") or [],
                    "deep_dive": r.get("deep_dive"),
                    "why_it_matters": r.get("why_it_matters"),
                    "recommended_action": r.get("recommended_action"),
                }
                for r in top[:6]
            ],
            "trend_acceleration": accel,
            # RB-2026-09-10: this whole item reports scan telemetry (how
            # many newsletters scanned, how many headlines extracted), not
            # a discovery -- keep it out of "What RB Found Without You
            # Telling It" now that email_intelligence_harvest is a discovery
            # source again (see _autonomous_discovery_value).
            "signal_type": "pipeline_self_report",
            "sent_loop_verification": [
                {
                    "subject": r.get("subject"),
                    "last_activity_at": r.get("last_activity_at"),
                    "category": r.get("category"),
                    "lifecycle_state": r.get("lifecycle_state"),
                    "lifecycle_effect": r.get("lifecycle_effect"),
                    "recommended_action": r.get("recommended_action"),
                    "recipients": r.get("recipients") or [],
                }
                for r in sent_loops[:6]
            ],
        },
    )
    # DEFECT-BRIEF-QUALITY fix: lead with individual headlines, not telemetry summary.
    # The telemetry item (scan stats) moves to the END so fresh news headlines appear first.
    # Mark telemetry item with disposition="ignore" so lifecycle engine doesn't suppress it.
    item["disposition"] = "ignore"  # telemetry row — not primary intelligence
    rows: list[dict] = []
    # RB-2026-09-05: suppress a sent-loop-verification thread already shown
    # recently with no new activity, so an unresolved thread doesn't nag
    # identically for days -- confirmed live: "RE: Declined: Catch-Up" and
    # "Re: Exciting Confidential Board Search" each resurfaced across
    # multiple non-consecutive days this week with zero new evidence.
    _today_iso = report.get("today") or date.today().isoformat()
    _item_ledger = _load_brief_item_ledger()
    _fresh_sent_loops = [
        r for r in sent_loops
        if _should_render_repeatable_item(
            _item_ledger, f"sent_loop:{r.get('thread_id')}", _today_iso,
            activity_marker=r.get("last_activity_at"),
        )
    ][:4]
    for r in _fresh_sent_loops:
        _record_brief_item_seen(
            _item_ledger, f"sent_loop:{r.get('thread_id')}", _today_iso,
            activity_marker=r.get("last_activity_at"),
        )
    _save_brief_item_ledger(_item_ledger)
    for r in _fresh_sent_loops:
        rows.append(_canonical_item(
            title=f"SENT LOOP VERIFICATION — {r.get('subject') or 'Outbound email'}",
            summary=(
                f"State={r.get('lifecycle_state')}; category={r.get('category')}; "
                f"last_activity={r.get('last_activity_at')}; recipients={len(r.get('recipients') or [])}."
            ),
            why_it_matters=r.get("lifecycle_effect") or (
                "Sent mail provides passive proof that an action was completed or that a waiting loop should be updated."
            ),
            recommended_action=r.get("recommended_action") or "Reconcile against open loops.",
            disposition="act_today" if r.get("lifecycle_state") == "response_received_after_outbound" else "monitor",
            grounding="system_detected",
            freshness=r.get("freshness") or "fresh",
            source_refs=[f"email_sent_thread:{r.get('thread_id')}", "passive_email_intelligence.json"],
            confidence=r.get("confidence") or "medium",
            extras={
                "sender": r.get("sender"),
                "recipients": r.get("recipients") or [],
                "mailbox_flags": r.get("mailbox_flags") or {},
                "snippet": r.get("snippet"),
                # RB-2026-09-10: loop bookkeeping (did a sent thread get a
                # reply?), not a discovery about the world -- correct
                # destination is operational_changes_from_connected_sources,
                # not "What RB Found Without You Telling It".
                "signal_type": "operational_bookkeeping",
            },
        ))
    # DEFECT-018: Expand each headline with strategic interpretation, not generic placeholder.
    # Cross-reference entities against active threads and contacts.
    try:
        _active_threads_for_eih = core.load_active_threads()
        _open_threads = [t for t in _active_threads_for_eih if t.get("status") == "open"]
        _thread_cos: dict[str, str] = {}  # company_lower → thread title
        for t in _open_threads:
            for co in (t.get("companies") or []):
                _thread_cos[co.lower()] = t.get("title") or t.get("id") or ""
        _baseline_for_eih = core.load_baseline()
        _company_contacts: dict[str, list[str]] = {}  # company_lower → [contact names]
        for entry in _baseline_for_eih:
            co = (entry.get("current_company") or "").lower()
            if co:
                _company_contacts.setdefault(co, []).append(entry.get("name") or "")
    except Exception:  # noqa: BLE001
        _thread_cos = {}
        _company_contacts = {}

    for r in top[:8]:  # expand top 8 headlines (up from 5)
        deep = r.get("deep_dive") or {}
        headline = r.get("headline") or "Email headline signal"
        source = r.get("source") or "Unknown source"
        received = (r.get("received_at") or "")[:10]
        category = r.get("category") or "industry_signal"
        themes = r.get("themes") or []
        entities = r.get("entities") or {}
        headline_cos = [c.lower() for c in (entities.get("companies") or [])]

        # Compute strategic interpretation linking headline to active threads
        opp_links: list[str] = []
        contact_links: list[str] = []
        for co_lower in headline_cos:
            if co_lower in _thread_cos:
                opp_links.append(_thread_cos[co_lower])
            contacts = _company_contacts.get(co_lower) or []
            contact_links.extend(contacts[:3])

        # Build strategic interpretation
        if opp_links:
            strategic_interp = (
                f"This signal mentions {', '.join(entities.get('companies', [])[:3])} — "
                f"which appears in your active opportunity: {opp_links[0]}. "
                f"The external signal and your active engagement are not independent. "
                f"Consider using this as a conversation catalyst."
            )
            disposition = "act_today"
        elif contact_links:
            strategic_interp = (
                f"Signal involves {', '.join(entities.get('companies', [])[:2])} — "
                f"network contacts at that company: {', '.join(contact_links[:3])}. "
                f"Market signal + known contact = outreach window."
            )
            disposition = "act_today"
        elif "operational_realism" in (r.get("strategic_tags") or []) or any(
            kw in headline.lower() for kw in
            ("ai", "automation", "operator", "restaurant", "pos", "payment", "retention")
        ):
            # RB-2026-09-10: dropped the leading "Category: X." here -- the
            # summary field below already prepends "Source: ... | Category:
            # X.", so this rendered as "Category: platform convergence.
            # Category: platform convergence." once these items started
            # reaching "What RB Found Without You Telling It".
            strategic_interp = (
                (f"Themes: {', '.join(themes)}. " if themes else "")
                + (r.get("why_it_matters") or "")
                + " Monitor for thesis reinforcement or contradiction."
            )
            disposition = "monitor"
        else:
            strategic_interp = r.get("why_it_matters") or "Monitor for relevance to active opportunities."
            disposition = "monitor"

        # RB-DEFECT-001: surface a real, clickable source URL. Prefer a direct
        # article link (`link_target`) when the email cache has one; otherwise
        # fall back to the Gmail permalink for the source thread so the user
        # can open the original email and follow its links. `email_thread:<id>`
        # remains in `source_refs` for internal provenance, but is not a URL
        # and must not be presented to the user as a link.
        article_url = r.get("link_target")
        email_url = r.get("email_permalink")
        source_url = article_url or email_url
        if article_url:
            link_note = f"Review article from {source} ({received})."
        elif email_url:
            link_note = f"Open the original {source} email ({received}) to read the full article."
        else:
            link_note = f"Review {source} item from {received} (no link available)."

        rows.append(_canonical_item(
            # RB-2026-09-10: bare `[:100]` cut mid-word ("...local paymen"),
            # confirmed live in "What RB Found Without You Telling It" once
            # these headlines started reaching that section. Same bug class
            # already fixed twice elsewhere (capacity_plan's nested
            # _truncate_at_word, then _truncate_at_word_cos for the CoS
            # 5-actions list) but never propagated here -- reuse the
            # existing helper instead of adding a third copy.
            title=f"[{source}] {_truncate_at_word_cos(headline, 100)}",
            summary=(
                f"Source: {source} | Date: {received} | Category: {category.replace('_',' ')}. "
                + strategic_interp
            ),
            why_it_matters=strategic_interp,
            recommended_action=(
                link_note + " "
                + ("Link to active opportunity: follow up." if opp_links else
                   "Use as outreach hook for network contacts." if contact_links else
                   r.get("recommended_action") or "Monitor.")
            ),
            disposition=disposition,
            grounding="system_detected",
            freshness="fresh",
            source_refs=[source, f"email_thread:{r.get('thread_id')}"],
            confidence="medium" if opp_links or contact_links else "low",
            extras={
                "source_publication": source,
                "received_at": received,
                "headline_text": headline,
                "category": category,
                "themes": themes,
                "entities": entities,
                "opportunity_links": opp_links,
                "contact_links": contact_links[:5],
                "strategic_relevance_score": r.get("strategic_relevance_score"),
                "pain_types": r.get("pain_types") or [],
                "deep_dive": deep,
                "source_url": source_url,
                "source_url_type": "article" if article_url else ("email" if email_url else None),
                "changed_state": True,  # news is always new; bypass lifecycle suppression
            },
        ))
    # Telemetry summary goes last — it's context, not intelligence
    rows.append(item)
    return rows


# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# Pending graph mutations (DEFECT-003 / contact-update surface)
# ---------------------------------------------------------------------------

def _build_pending_graph_mutations(today: date) -> list[dict]:
    """Scan the baseline for unconfirmed pending mutations and surface them.

    Detects two categories:

    1. LinkedIn-detected company/role changes held in notes but not applied
       to current_company/current_role (detected via 'now at X as of DATE'
       or 'CONFLICT: LinkedIn reads' note patterns).

    2. LinkedIn ingest delta cache — proposed changes from the last ingest
       that need review (who_matters_now moves not yet confirmed).

    Each item carries a `confirm_command` field with the mutations.py
    invocation needed to apply it — so the operator can paste-run directly.

    RC inner/broader contacts are surfaced as act_today;
    LKI and other signal classes are monitor.
    """
    import re as _re

    try:
        baseline = core.load_baseline()
    except Exception:  # noqa: BLE001
        return []

    items: list[dict] = []

    _CONFLICT_RE = _re.compile(
        r'\[(\d{4}-\d{2}-\d{2})\] (?:CONFLICT: LinkedIn reads (company|role) ([^;]+); canonical retained as ([^.]+)\.'
        r'|LinkedIn: (?:company|role) .+ -> .+)',
        re.IGNORECASE,
    )
    _NOW_AT_RE = _re.compile(
        r'now at ([^.]+?) as of (\d{4}-\d{2}-\d{2})',
        re.IGNORECASE,
    )
    _RESOLVED_MARKERS = ('conflict resolved', 'confirmed by todd', 'confirmed by operator',
                         'company-change-confirmed', 'role-change-confirmed')

    # Only surface RC and LKI contacts — VC/LMI company moves are not daily CoS material.
    _BRIEF_SIGNAL_CLASSES = {"RC", "LKI"}

    for entry in baseline:
        eid = entry.get("id") or ""
        name = entry.get("name") or ""
        signal_class = entry.get("signal_class") or ""
        rc_tier = entry.get("rc_tier") or ""

        # Skip non-strategic contacts — VC/LMI company moves handled in batch, not daily brief
        if signal_class not in _BRIEF_SIGNAL_CLASSES:
            continue

        notes = entry.get("notes") or ""
        notes_lower = notes.lower()
        current_co = (entry.get("current_company") or "").strip()
        current_role = (entry.get("current_role") or "").strip()
        tags = [t.lower() for t in (entry.get("tags") or [])]

        # Skip if already confirmed/resolved
        if any(m in notes_lower for m in _RESOLVED_MARKERS):
            continue
        if any(t in tags for t in ('company-change-confirmed', 'role-change-confirmed')):
            continue

        # Detect 'now at X as of DATE' where X ≠ current_company
        m = _NOW_AT_RE.search(notes)
        if m:
            notes_co = m.group(1).strip()
            detected_date = m.group(2)
            age_days = (today - date.fromisoformat(detected_date)).days if detected_date else 0
            co_match = (
                notes_co.lower() in current_co.lower()
                or current_co.lower() in notes_co.lower()
                or not notes_co
            )
            if not co_match and age_days > 0:
                is_rc_inner = signal_class == "RC" and rc_tier in ("inner", "broader")
                disposition = "act_today" if is_rc_inner else "monitor"
                confirm_cmd = (
                    f"python3 system/scripts/mutations.py contact-update "
                    f"--id {eid} --company \"{notes_co}\" "
                    f"--notes \"Confirmed company change to {notes_co} ({detected_date})\""
                )
                items.append(_canonical_item(
                    title=(
                        f"[PENDING MUTATION] {name} — company may have changed "
                        f"({current_co} → {notes_co}, detected {detected_date}, {age_days}d ago)"
                    ),
                    summary=(
                        f"Baseline shows {name} at {current_co!r} but notes from {detected_date} "
                        f"record 'now at {notes_co}'. "
                        f"This change is {age_days} days old and has not been confirmed."
                    ),
                    why_it_matters=(
                        f"{'Inner-tier RC contact' if is_rc_inner else signal_class + ' contact'} "
                        f"{name} may have a stale company in the baseline. "
                        "Stale company affects relationship intelligence and opportunity scoring."
                    ),
                    # RB-DEFECT-2026-08-14: recommended_action is reader-
                    # facing text (same field family as the meeting-prep CLI
                    # leak fixed above) -- it was set to the literal
                    # mutations.py shell invocation, not something a chat
                    # reader (or the GPT mediating the chat) can execute. The
                    # actual command stays in extras.confirm_command below
                    # for whatever internal tooling replays it.
                    recommended_action=(
                        f"Confirm {name}'s company changed to {notes_co} (detected {detected_date}) "
                        f"or correct the baseline if this isn't accurate."
                    ),
                    disposition=disposition,
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["baseline_index.json"],
                    confidence="medium",
                    extras={
                        "contact_id": eid,
                        "contact_name": name,
                        "signal_class": signal_class,
                        "rc_tier": rc_tier,
                        "mutation_type": "company_change",
                        "current_value": current_co,
                        "proposed_value": notes_co,
                        "detected_date": detected_date,
                        "age_days": age_days,
                        "confirm_command": confirm_cmd,
                        "requires_confirmation": True,
                    },
                ))

    # Sort: RC inner first, then broader, then LKI; within tier by age desc
    _tier_order = {"inner": 0, "broader": 1, "dormant_valuable": 2}
    items.sort(key=lambda x: (
        0 if (x.get("extras") or {}).get("signal_class") == "RC" else 1,
        _tier_order.get((x.get("extras") or {}).get("rc_tier") or "", 3),
        -((x.get("extras") or {}).get("age_days") or 0),
    ))

    # Cap to 8 items. If overflow, add an aggregate item so the user knows
    # how many more exist and can apply them in bulk.
    MAX_ITEMS = 8
    if len(items) > MAX_ITEMS:
        overflow = items[MAX_ITEMS:]
        overflow_count = len(overflow)
        items = items[:MAX_ITEMS]
        items.append(_canonical_item(
            title=f"+ {overflow_count} additional pending baseline update(s) — LKI contacts",
            summary=(
                f"{overflow_count} LKI contact(s) have LinkedIn-detected company changes "
                f"not yet applied to the baseline."
            ),
            why_it_matters=(
                "LKI company changes are lower priority than RC but accumulate as baseline staleness. "
                "Apply in bulk when convenient."
            ),
            # RB-DEFECT-2026-08-14: same CLI-leak class as above -- reader-
            # facing text, was a raw shell invocation.
            recommended_action=(
                f"Apply all {overflow_count} pending LKI company-change updates in bulk, "
                f"or review them individually first."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["baseline_index.json"],
            confidence="medium",
            extras={
                "overflow_count": overflow_count,
                "overflow_ids": [(x.get("extras") or {}).get("contact_id") for x in overflow[:20]],
                "mutation_type": "overflow_summary",
            },
        ))

    return items


# RB 9.42 — Layer 2: Relationship momentum + watchlist change detection
# ---------------------------------------------------------------------------

_MOMENTUM_TIER: list[tuple[int, str]] = [
    (7,   "HOT"),       # 0–7 days
    (30,  "WARM"),      # 8–30 days
    (60,  "COOLING"),   # 31–60 days
    (180, "COLD"),      # 61–180 days
    (9999, "FROZEN"),   # 181+ days
]

def _momentum_tier(days_quiet: int | None) -> str:
    if days_quiet is None:
        return "UNKNOWN"
    for threshold, label in _MOMENTUM_TIER:
        if days_quiet <= threshold:
            return label
    return "FROZEN"


def _compute_relationship_momentum(report: dict) -> list[dict]:
    """Build per-RC-contact operational status for brief Layer 2.

    RB-DEFECT-016-A: Source coverage gate — relationship momentum is only classified
    when required communication sources (SMS, email, LinkedIn) are available and current.
    When sources are INCOMPLETE, classifications are withheld and an INCOMPLETE marker
    is emitted instead.

    RB-DEFECT-016-B: Relationship domain filter — family and personal contacts are
    excluded from professional momentum scoring.

    Covers all RC contacts (inner + broader + dormant_valuable).  Each item
    shows: name, days_quiet, momentum_tier, open_loop_count, and recommended
    action.  Sorted by operational urgency, tier first:
      1. FROZEN
      2. COLD
      3. COOLING (30–60d)
      4. WARM / HOT (active)
    RB-2026-09-06: within a tier, contacts are ranked by relationship value
    (drr_score — tier weight, circle membership, evidence depth, alongside
    recency) rather than raw days_quiet, so the highest-value stale
    relationship leads even if a lower-value one has been quieter longer.
    days_quiet remains the tiebreaker for equal-value contacts.

    Returns a list of _canonical_item dicts.
    """
    try:
        try:
            today_dt = date.fromisoformat(str(report.get("today") or date.today())[:10])
        except ValueError:
            today_dt = date.today()
        baseline = core.load_baseline()

        # DEFECT-016-B: filter out family/personal contacts before any scoring
        rc_contacts_raw = [
            c for c in baseline
            if c.get("signal_class") == "RC"
            and c.get("rc_state") in (None, "ACTIVE", "")
        ]
        excluded_domain: list[dict] = []
        rc_contacts: list[dict] = []
        for c in rc_contacts_raw:
            if _HAS_COMPLETENESS_CONTRACT and _cc.should_exclude_from_professional_momentum(c):
                excluded_domain.append(c)
            else:
                rc_contacts.append(c)

        if not rc_contacts:
            return []

        # DEFECT-016-A: assess source coverage before any classification
        source_freshness: dict = {}
        completeness = None
        if _HAS_COMPLETENESS_CONTRACT:
            try:
                import cos_judgment as _cj_local
                source_freshness = _cj_local.build_source_freshness(report)
            except Exception:  # noqa: BLE001
                source_freshness = {}
            completeness = _cc.assess_momentum_coverage(report, source_freshness)

        # Build open-loop index from loop ledger
        try:
            all_loops = core.parse_loop_ledger()
            open_loops = [lp for lp in all_loops if not lp.closed]
            # Map contact name → open loop count
            loop_counts: dict[str, int] = {}
            for lp in open_loops:
                party_lower = lp.party.lower()
                loop_counts[party_lower] = loop_counts.get(party_lower, 0) + 1
        except Exception:  # noqa: BLE001
            loop_counts = {}

        # DEFECT-003: Build recent-SMS-touch index from direct_comms_health RI candidates.
        # SMS events with confirmed timestamps override stale baseline last_touch dates.
        # This prevents false COLD/FROZEN classification when SMS contact is more recent.
        # contact_id → most recent event date (as date object)
        _sms_latest: dict[str, date] = {}
        if _HAS_DIRECT_COMMS_HEALTH:
            try:
                _dch_items = report.get("direct_comms_health") or []
                for _dch_item in _dch_items:
                    _ri = _dch_item.get("ri_candidates") or []
                    for _cand in _ri:
                        _cid = _cand.get("contact_id")
                        _evt = _cand.get("event_at")
                        if not _cid or not _evt:
                            continue
                        try:
                            _evt_date = date.fromisoformat(str(_evt)[:10])
                            if _cid not in _sms_latest or _evt_date > _sms_latest[_cid]:
                                _sms_latest[_cid] = _evt_date
                        except (ValueError, TypeError):
                            pass
            except Exception:  # noqa: BLE001
                pass

        # Unified communication overlay. Momentum must reflect the newest
        # observed interaction across every available channel, not just the
        # persisted baseline plus one SMS candidate feed.
        _channel_latest: dict[str, tuple[date, set[str]]] = {}

        def _record_touch(contact_id: str | None, raw_at: object, channel: str) -> None:
            if not contact_id or not raw_at:
                return
            parsed: date | None = None
            raw = str(raw_at)
            try:
                parsed = date.fromisoformat(raw[:10])
            except ValueError:
                try:
                    from email.utils import parsedate_to_datetime
                    parsed = parsedate_to_datetime(raw).date()
                except (TypeError, ValueError, OverflowError):
                    return
            prior = _channel_latest.get(contact_id)
            if prior is None or parsed > prior[0]:
                _channel_latest[contact_id] = (parsed, {channel})
            elif parsed == prior[0]:
                prior[1].add(channel)

        for row in (report.get("interaction") or {}).get("matched_contacts") or []:
            _record_touch(row.get("id"), row.get("last_interaction_at"), "text/call")
        for row in (report.get("linkedin_messaging") or {}).get("matched_contacts") or []:
            _record_touch(row.get("id"), row.get("last_interaction_at"), "LinkedIn")
        email_overlay = report.get("email") or {}
        for row in email_overlay.get("from_baseline") or []:
            _record_touch((row.get("match") or {}).get("id"), row.get("last_message_at"), "email")
        for row in email_overlay.get("sent_followups") or []:
            for matched in row.get("matched_contacts") or []:
                _record_touch(matched.get("id"), row.get("sent_at"), "email")

        whatsapp_path = core.CACHE_DIR / "whatsapp_chats.json"
        if whatsapp_path.exists():
            try:
                whatsapp = json.loads(whatsapp_path.read_text(encoding="utf-8"))
                for chat in whatsapp.get("chats") or []:
                    for matched in chat.get("matched_baseline") or []:
                        _record_touch(matched.get("id"), chat.get("last_message_at"), "WhatsApp")
            except (OSError, json.JSONDecodeError):
                pass

        items: list[dict] = []

        # If coverage is INCOMPLETE, emit a single blocking item instead of classifications
        if completeness is not None and completeness.status == "INCOMPLETE":
            completeness.classifications_withheld = [
                c.get("name") or "" for c in rc_contacts if c.get("name")
            ]
            items.append(_canonical_item(
                title=(
                    "INCOMPLETE — Relationship Momentum Classification Withheld"
                ),
                summary=(
                    f"RB cannot classify relationship momentum for {len(rc_contacts)} RC contact(s). "
                    f"Required sources missing: {', '.join(completeness.missing_sources)}. "
                    f"Contacts affected: {', '.join((c.get('name') or '') for c in rc_contacts[:8])}."
                    + (" (+ more)" if len(rc_contacts) > 8 else "")
                ),
                why_it_matters=(
                    "Momentum scoring from baseline last_touch alone produces false COLD/FROZEN states "
                    "when SMS or LinkedIn interactions exist but are unreconciled. "
                    "RB is withholding all tier classifications until source coverage is restored."
                ),
                recommended_action=completeness.recovery_action,
                disposition="act_today",
                grounding="system_detected",
                freshness="stale_source_limited",
                source_refs=["completeness_contract", "direct_comms_health"],
                confidence="high",
                extras={
                    "completeness_status": "INCOMPLETE",
                    "missing_sources": completeness.missing_sources,
                    "classifications_withheld": completeness.classifications_withheld,
                    "recovery_action": completeness.recovery_action,
                    "contact_count": len(rc_contacts),
                },
            ))
            # Also emit a partial view using baseline only, flagged as low-confidence
            freshness_label = "stale_source_limited"
            confidence_label = "low"
            source_caveat = " [UNCONFIRMED — SMS/LinkedIn unreconciled]"
        else:
            # Sources are COMPLETE or PARTIAL — proceed with classification
            freshness_label = "fresh" if (completeness is None or completeness.status == "COMPLETE") else "stale_source_limited"
            confidence_label = "high" if (completeness is None or completeness.status == "COMPLETE") else "medium"
            source_caveat = "" if (completeness is None or completeness.status == "COMPLETE") else " [partial — LinkedIn unreconciled]"

        for contact in rc_contacts:
            name = contact.get("name") or ""
            cid = contact.get("id") or ""
            lt_raw = contact.get("last_touch")
            lt_date: date | None = None
            if lt_raw:
                try:
                    lt_date = date.fromisoformat(str(lt_raw))
                except ValueError:
                    pass

            # Use the newest source-backed interaction across all channels.
            sms_touch = _sms_latest.get(cid)
            if sms_touch:
                _record_touch(cid, sms_touch.isoformat(), "text/call")
            observed = _channel_latest.get(cid)
            observed_touch = observed[0] if observed else None
            observed_sources = sorted(observed[1]) if observed else []
            sms_overrides_baseline = (
                observed_touch is not None
                and (lt_date is None or observed_touch > lt_date)
            )
            effective_lt = observed_touch if sms_overrides_baseline else lt_date
            days_quiet = (today_dt - effective_lt).days if effective_lt else None

            tier = _momentum_tier(days_quiet)
            name_lower = name.lower()
            open_loop_count = loop_counts.get(name_lower, 0)

            # RB-2026-09-06: relationship value, not just staleness, now
            # decides ranking within a momentum tier -- see the sort below.
            # core.drr_score() already exists and is used elsewhere in this
            # codebase for exactly this kind of prioritization (tier weight
            # + circle membership + evidence depth, alongside recency), but
            # this section never used it, so within FROZEN/COLD the most
            # stale contact always won the top slot regardless of whether
            # it was actually a high-value relationship. Confirmed live:
            # a 2050-day-silent contact permanently outranked contacts RB
            # had much stronger evidence/tier signal for.
            try:
                drr = core.drr_score(contact, today_dt, report.get("active_threads"))
                drr_value = drr["score"]
            except Exception:  # noqa: BLE001
                drr_value = 0.0

            # Disposition logic
            if tier in ("FROZEN", "COLD"):
                disposition = "act_today"
            elif tier == "COOLING" and open_loop_count == 0:
                disposition = "act_today"
            elif tier == "COOLING":
                disposition = "monitor"
            else:
                disposition = "monitor"

            # Recommended action
            if tier == "FROZEN" and days_quiet and days_quiet > 365:
                # RB-2026-09-10: the FROZEN bucket is unbounded above
                # 181 days -- a contact quiet 202 days and one quiet 2,054
                # days (5.6 years) got the identical "Re-engage X ...
                # Consider opening a loop or scheduling a touch" text,
                # reading as equally urgent/actionable when they plainly
                # aren't. Confirmed live: Bridgett Hendrickson (2,054d,
                # tagged rc_tier=dormant_valuable -- Todd's own 2026-05-08
                # note says keep tracking her, not chase her routinely).
                # Stay honest about the actual gap instead of implying a
                # routine near-term touch is warranted; see
                # _render_relationship_momentum_status in
                # render_daily_brief.py for the matching re-rank so this
                # doesn't crowd out fresher FROZEN/COLD signals either.
                _years = days_quiet // 365
                action = (
                    f"{name} has been dormant {days_quiet} days (~{_years}y) — a long-shot "
                    "re-engage, not a routine touch. Worth pursuing only with a specific "
                    "reason to reach out."
                    + (" An open loop exists; close it if it's no longer live." if open_loop_count else "")
                )
            elif tier == "FROZEN":
                action = (
                    f"Re-engage {name} — no contact for {days_quiet} days. "
                    + ("An open loop exists; close or convert to outreach." if open_loop_count else
                       "Consider opening a loop or scheduling a touch.")
                )
            elif tier == "COLD":
                action = (
                    f"Contact {name} — {days_quiet} days since last touch. "
                    + ("Open loop needs progress." if open_loop_count else "Open a loop or set a follow-up.")
                )
            elif tier == "COOLING" and open_loop_count == 0:
                action = f"Schedule a touch with {name} ({days_quiet} days quiet, no open loop)."
            elif tier == "COOLING":
                action = f"Monitor {name} — {days_quiet} days quiet, {open_loop_count} open loop(s) in progress."
            else:
                action = f"Monitor {name} — relationship active ({days_quiet if days_quiet is not None else '?'} days since last touch)."

            # Build proposed last_touch mutation when any observed channel is newer.
            proposed_lt_update = None
            if sms_overrides_baseline and observed_touch:
                proposed_lt_update = {
                    "contact_id": cid,
                    "contact_name": name,
                    "current_last_touch": lt_raw,
                    "proposed_last_touch": observed_touch.isoformat(),
                    "source": "+".join(observed_sources),
                    "requires_confirmation": True,
                }

            # Build title/caveat — omit caveat when a source-backed touch is newer.
            effective_source = "+".join(observed_sources) if sms_overrides_baseline else "baseline"
            sms_note = (
                f" [{effective_source}: {observed_touch.isoformat()}]" if sms_overrides_baseline else ""
            )
            display_caveat = source_caveat if not sms_overrides_baseline else ""

            summary_parts = [
                f"Last touch (baseline): {lt_raw or 'never recorded'}.",
                *(
                    [f"Observed touch detected: {observed_touch.isoformat()} via {effective_source} — more recent than baseline."]
                    if sms_overrides_baseline else []
                ),
                f"Days quiet (effective): {days_quiet if days_quiet is not None else 'unknown'}.",
                f"Momentum: {tier}{display_caveat}.",
                f"Open loops: {open_loop_count}.",
            ]
            if contact.get("rc_tier"):
                summary_parts.append(f"RC tier: {contact['rc_tier']}.")

            items.append(_canonical_item(
                title=f"{name} — {tier}{display_caveat}{sms_note} ({days_quiet if days_quiet is not None else '?'}d quiet)",
                summary=" ".join(summary_parts),
                why_it_matters=(
                    f"RC contact in {tier} momentum state{display_caveat}. "
                    + (f"Observed touch on {observed_touch.isoformat()} via {effective_source}; baseline update remains pending. " if sms_overrides_baseline else "")
                    + (f"{open_loop_count} open loop(s) require progress." if open_loop_count else "No open loop — relationship may drift.")
                ),
                recommended_action=action,
                disposition=disposition,
                grounding="system_detected",
                freshness="fresh" if sms_overrides_baseline else freshness_label,
                source_refs=(
                    ["baseline_index.json", "loop_ledger"] + [f"communication:{s}" for s in observed_sources]
                    if sms_overrides_baseline else
                    ["baseline_index.json", "loop_ledger"]
                ),
                confidence="high" if sms_overrides_baseline else confidence_label,
                extras={
                    "contact_id": cid,
                    "contact_name": name,
                    "rc_tier": contact.get("rc_tier"),
                    "days_quiet": days_quiet,
                    "momentum_tier": tier,
                    "open_loop_count": open_loop_count,
                    "last_touch": lt_raw,
                    "sms_touch": sms_touch.isoformat() if sms_touch else None,
                    "sms_overrides_baseline": sms_overrides_baseline,
                    "observed_touch": observed_touch.isoformat() if observed_touch else None,
                    "observed_sources": observed_sources,
                    "effective_source": effective_source,
                    "proposed_last_touch_update": proposed_lt_update,
                    "current_company": contact.get("current_company"),
                    "circles": contact.get("circles") or [],
                    "drr_score": drr_value,
                    "classification_withheld": completeness is not None and completeness.status == "INCOMPLETE",
                    "completeness_status": completeness.status if completeness else "COMPLETE",
                    "missing_sources": completeness.missing_sources if completeness else [],
                },
            ))

        # Sort: FROZEN first, then COLD, then COOLING, then others; within a
        # tier, by relationship value (drr_score: tier weight + circles +
        # evidence depth, alongside recency) rather than raw days_quiet --
        # see the RB-2026-09-06 note above. days_quiet remains a tiebreaker
        # for contacts of equal computed value.
        _tier_order = {"FROZEN": 0, "COLD": 1, "COOLING": 2, "WARM": 3, "HOT": 4, "UNKNOWN": 5}
        items.sort(key=lambda x: (
            # INCOMPLETE blocking item always first
            0 if "INCOMPLETE" in (x.get("title") or "") else 1,
            _tier_order.get((x.get("extras") or {}).get("momentum_tier", "UNKNOWN"), 5),
            -((x.get("extras") or {}).get("drr_score") or 0.0),
            -((x.get("extras") or {}).get("days_quiet") or 0),
        ))

        # Emit excluded-domain items as a diagnostic note (not scored for momentum)
        if excluded_domain:
            items.append(_canonical_item(
                title=f"[DOMAIN EXCLUDED] {len(excluded_domain)} family/personal contact(s) excluded from professional momentum",
                summary=(
                    "Contacts excluded: "
                    + ", ".join(c.get("name") or "" for c in excluded_domain[:10])
                    + ("..." if len(excluded_domain) > 10 else "")
                    + ". Family and personal contacts do not affect professional momentum scoring."
                ),
                why_it_matters="Family/personal contacts excluded per DEFECT-016-B relationship domain filter.",
                recommended_action="No action required. Review relationship_domain field if exclusion is incorrect.",
                disposition="ignore",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["completeness_contract", "baseline_index.json"],
                confidence="high",
                extras={
                    "domain_excluded_contacts": [c.get("name") for c in excluded_domain],
                    "excluded_count": len(excluded_domain),
                },
            ))

        return items

    except Exception:  # noqa: BLE001
        return []


def _enrich_loop_with_contact_momentum(loop_item: dict, baseline: list[dict] | None = None) -> dict:
    """Add days_quiet and momentum_tier to a loops_and_obligations item.

    Mutates the item's extras dict in-place and returns the item.
    """
    if baseline is None:
        try:
            baseline = core.load_baseline()
        except Exception:  # noqa: BLE001
            return loop_item

    # Extract party name from title: "Overdue: L001 — Jane Smith"
    title = loop_item.get("title", "")
    parts = title.split("—", 1)
    party_name = parts[-1].strip() if len(parts) > 1 else ""
    if not party_name:
        return loop_item

    party_lower = party_name.lower()
    contact = next(
        (c for c in baseline if (c.get("name") or "").lower() == party_lower),
        None,
    )
    if not contact:
        return loop_item

    lt_raw = contact.get("last_touch")
    if lt_raw:
        try:
            lt_date = date.fromisoformat(str(lt_raw))
            days_quiet = (date.today() - lt_date).days
        except ValueError:
            days_quiet = None
    else:
        days_quiet = None

    tier = _momentum_tier(days_quiet)
    extras = loop_item.get("extras") or {}
    extras.update({
        "contact_days_quiet": days_quiet,
        "contact_momentum": tier,
        "contact_last_touch": lt_raw,
        "contact_rc_tier": contact.get("rc_tier"),
    })
    loop_item["extras"] = extras

    # Flag momentum gap: loop exists but contact is COLD/FROZEN
    if tier in ("COLD", "FROZEN") and days_quiet and days_quiet > 60:
        gap_note = (
            f" [MOMENTUM GAP: {contact.get('name', party_name)} quiet {days_quiet}d "
            f"— open loop but no recent touch]"
        )
        loop_item["summary"] = loop_item.get("summary", "") + gap_note
        loop_item["disposition"] = "act_today"

    return loop_item


def _load_prior_watchlist_status(published_dir: Path) -> dict[str, str]:
    """Load prior watchlist status from latest published brief.

    Returns dict of entity_name → status_category from the most recently
    published brief's watchlist_intelligence section.
    """
    latest_path = published_dir / "daily" / "latest_brief.json"
    if not latest_path.exists():
        return {}
    try:
        prior = json.loads(latest_path.read_text(encoding="utf-8"))
        prior_sections = (prior.get("canonical_brief") or {}).get("sections") or {}
        prior_wl = prior_sections.get("watchlist_intelligence") or []
        result: dict[str, str] = {}
        for item in prior_wl:
            if not isinstance(item, dict):
                continue
            extras = item.get("extras") or {}
            name = extras.get("entity_name") or ""
            status = extras.get("watchlist_status") or ""
            if name and status:
                result[name] = status
        return result
    except Exception:  # noqa: BLE001
        return {}


# ---------------------------------------------------------------------------
# RB 9.37 / DEFECT-020 — CoS brief structure helpers
# These derive the six new operational sections: executive_summary,
# watchlist_intelligence, emerging_themes, contrarian_view, decision_queue,
# trust_metrics.  All are best-effort and never block brief generation.
# ---------------------------------------------------------------------------

def _watchlist_entity_status(entity_name: str, sections: dict) -> tuple[str, str]:
    """Return (status_category, evidence_headline) for a watchlist entity.

    Status categories (in priority order):
      Escalation      — act_today disposition + entity name in item text
      New Activity    — new_intelligence_today item mentions entity
      Relevant Activity — any analysis section mentions entity
      No Change       — entity not found in any active section
    """
    def _name_in(text: str, name: str) -> bool:
        # RB 9.71: word-boundary match, not substring, on every token
        # (including short ones like "GK"). A plain substring check matched
        # "Hi Auto" against "auto" inside "Autonomous"; dropping short tokens
        # (old `len(p) > 2` filter) then let "GK Software" match on the bare
        # word "software" alone. Requiring all tokens — "gk" and "software"
        # — as whole words eliminates both false positives.
        parts = [p.lower() for p in name.lower().split() if len(p) >= 2]
        t = text.lower()
        return bool(parts) and all(
            re.search(r"\b" + re.escape(p) + r"\b", t) for p in parts
        )

    SCAN_SECTIONS = [
        "new_intelligence_today", "reactivated_intelligence",
        "overnight_delta_intelligence", "autonomous_discovery_evidence",
        "email_intelligence_harvest", "relationship_operational_signal_review",
        "strategic_industry_signals",
    ]
    # Escalation: act_today disposition AND name match
    for skey in SCAN_SECTIONS:
        for item in (sections.get(skey) or []):
            if not isinstance(item, dict):
                continue
            text = f"{item.get('title', '')} {item.get('summary', '')}"
            if _name_in(text, entity_name) and item.get("disposition") == "act_today":
                return "Escalation", item.get("title", "")
    # New Activity: new_intelligence_today
    for item in (sections.get("new_intelligence_today") or []):
        if not isinstance(item, dict):
            continue
        text = f"{item.get('title', '')} {item.get('summary', '')}"
        if _name_in(text, entity_name):
            return "New Activity", item.get("title", "")
    # Relevant Activity: any analysis section
    for skey in SCAN_SECTIONS[2:]:
        for item in (sections.get(skey) or []):
            if not isinstance(item, dict):
                continue
            text = f"{item.get('title', '')} {item.get('summary', '')}"
            if _name_in(text, entity_name):
                return "Relevant Activity", item.get("title", "")
    return "No Change", ""


_EXEC_HIRE_NAME_RE = re.compile(
    r"^(?P<company>.+?)\s+(?:names|appoints|hires|promotes)\s+"
    r"(?P<person>[A-Z][\w'\-]+(?:\s+[A-Z][\w'\-]+){1,2})\s+"
    r"(?:as\s+)?(?P<role>chief\s+\w+(?:\s+\w+)?\s+officer|c[a-z]{1,2}o\b)",
    re.IGNORECASE,
)


def _compute_notable_contact_moves(sections: dict) -> list[dict]:
    """Cross-reference exec-hire headlines (Section C/D "[EXEC HIRE]" items)
    against the baseline — a named executive taking a new role, especially a
    CTO, is exactly the kind of relationship-intelligence event RB exists to
    catch, but exec-hire headlines were only ever shown as generic industry
    news with no check against what RB already knows about that person.

    Only surfaces a match — silent otherwise (this is a bonus enrichment,
    not a required section)."""
    try:
        baseline = core.load_baseline()
    except Exception:
        return []
    name_index: dict[str, dict] = {}
    for entry in baseline:
        key = re.sub(r"\s+", " ", re.sub(r"[.,]", "", (entry.get("name") or "").strip().lower()))
        if key and key not in name_index:
            name_index[key] = entry

    items: list[dict] = []
    seen_people: set[str] = set()
    for section_key in ("restaurant_industry_headlines", "restaurant_technology_headlines"):
        for hl in sections.get(section_key) or []:
            extras = hl.get("extras") or {}
            badge = (extras.get("signal_badge") or "")
            if "EXEC HIRE" not in badge.upper():
                continue
            title = re.sub(r"^\[[^\]]+\]\s*", "", hl.get("title") or "")
            m = _EXEC_HIRE_NAME_RE.match(title)
            if not m:
                continue
            person = m.group("person").strip()
            company = m.group("company").strip()
            role = m.group("role").strip()
            key = re.sub(r"\s+", " ", re.sub(r"[.,]", "", person.lower()))
            if key in seen_people or key not in name_index:
                continue
            seen_people.add(key)
            match = name_index[key]
            prior_company = (match.get("current_company") or "").strip()
            prior_role = (match.get("current_role") or "").strip()
            is_cto = "chief technology officer" in role.lower() or role.lower() in ("cto",)
            same_company = prior_company and prior_company.lower() in company.lower()
            why = (
                f"Baseline match: RB already tracks {person}"
                + (f" ({prior_role} at {prior_company})" if prior_company else "")
                + ". "
                + (
                    f"This headline reports a move to {company} as {role} — verify this is the same "
                    f"person before treating it as a role change."
                    if prior_company and not same_company else
                    f"Confirms current role at {company}."
                )
            )
            items.append(_canonical_item(
                title=f"Notable contact move: {person} → {company} ({role})",
                summary=title,
                why_it_matters=why,
                recommended_action=(
                    "CTOs are high-value contacts — review the relationship card and consider outreach."
                    if is_cto else
                    "Review the relationship card for outreach opportunity."
                ),
                disposition="ask_todd" if prior_company and not same_company else "monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[extras.get("source_url") or ""],
                confidence="medium",
                extras={
                    "person": person,
                    "new_company": company,
                    "new_role": role,
                    "baseline_id": match.get("id"),
                    "baseline_current_company": prior_company,
                    "baseline_current_role": prior_role,
                    "is_cto": is_cto,
                    "source_url": extras.get("source_url"),
                },
            ))
    return items


def _watchlist_delta_is_market_signal_escalation(it: dict) -> bool:
    """RB-DEFECT-2026-08-19: an entity is only a market-signal escalation
    (belongs in the Watchlist Delta Summary's "Escalated" name list) if it
    isn't escalated purely by way of a shared overdue internal loop -- see
    the call site in build_canonical_brief for the full incident this
    closed. Extracted to module level (RB-2026-08-25) so it's independently
    testable instead of a closure buried in build_canonical_brief."""
    extras = it.get("extras") or {}
    if extras.get("loop_id"):
        return False
    why_text = (it.get("why_it_matters") or it.get("summary") or "").lower()
    return "overdue loop" not in why_text


def _watchlist_delta_passes_noise_filter(it: dict) -> bool:
    """RB-2026-08-25: applies the identical noise filter Section F's
    renderer (render_intelligence_brief._clean_watchlist_why) uses before
    it decides which entities to list -- without this, the Watchlist Delta
    Summary line can name an entity (e.g. a megacap platform mentioned with
    no restaurant/payments context) that Section F itself already drops as
    noise, producing a visible mismatch between the summary and the section
    body below it. See the call site in build_canonical_brief for the live
    incident (Amazon Web Services named in the summary, Google Cloud shown
    in Section F's actual list) this closed."""
    if rib is None:
        return True
    extras = it.get("extras") or {}
    name = extras.get("entity_name") or ""
    why = (it.get("why_it_matters") or it.get("summary") or "").strip()
    return rib._clean_watchlist_why(why, entity_name=name) is not None


def _compute_watchlist_intelligence(report: dict, sections: dict) -> list[dict]:
    """Build per-entity watchlist status for monitored people and companies.

    People watchlist  : inner-tier contacts from relationship_signals.
    Company watchlist : earnings_watch_list_mutations + strategic_operator_movements
                        + defect-report mandatory company coverage list.

    RB-INTEL-021 / Brief Quality: every entity in the mandatory coverage list
    receives an explicit item — either a signal or a confirmed "no developments
    detected" item.  Silence no longer means "checked and nothing found."

    Returns one canonical item per monitored entity.
    """
    # ── Mandatory coverage list ───────────────────────────────────────────────
    # Companies and individuals that must appear in watchlist_intelligence every
    # cycle, even when no signal was found.  Structured by category so rollups
    # are per-category in the brief rather than one flat "no change" block.
    # RB-DEFECT-2026-08-19: Todd, on the brand side of the watchlist: "I
    # think our watchlist needs to be bigger - potential customers as well
    # as competitors... I thought we had scoped this around 120-150
    # companies." Actual count at the time of this note was 107 (30 brands +
    # 77 tech), and the brand side -- the potential-customer side -- was
    # thin relative to both the tech side and restaurant_tech_watchlist.md's
    # own stated scope ("top public, scaled private, franchise, QSR, fast-
    # casual, casual dining... brands"). Expanded brand-heavy per his
    # explicit direction rather than growing both sides evenly.
    #
    # RB-2026-09-05: this block used to be ~100 lines of literal Python
    # lists, hand-duplicated in entity_alerts.py with nothing enforcing the
    # two stayed identical. Reading from watchlist_registry.json now --
    # recomputed fresh on every call to this function (it's a local, not a
    # module-level cache), so a promotion confirmed via watchlist_promotion.py
    # is visible on the very next brief without a process restart.
    _watchlist_registry = watchlist_registry.load_registry()
    MANDATORY_RESTAURANT_BRANDS = watchlist_registry.mandatory_restaurant_brands(_watchlist_registry)
    _tech_categories = watchlist_registry.restaurant_tech_categories(_watchlist_registry)

    # Industry executives — monitored as public signal sources (LinkedIn, press,
    # conference appearances, exec moves), not as relationship contacts.
    MANDATORY_EXECUTIVES: dict[str, list[str]] = {
        "exec_restaurant_ceo": [
            "David Gibbs",        # Yum Brands CEO
            "Chris Kempczinski",  # McDonald's CEO
            "Scott Boatwright",   # Chipotle CEO
            "Brian Niccol",       # former Chipotle; now Starbucks CEO
            "Kevin Hochman",      # Brinker CEO
            "Andrew Cathy",       # Chick-fil-A CEO
            "Patrick Doyle",      # board / former Domino's CEO, investor
            "Joe Guith",          # Chili's / Brinker president
            "John Peyton",        # Dine Brands CEO
            "Michael Skipworth",  # Wingstop CEO
        ],
        "exec_tech_ceo": [
            "Aman Narang",        # Toast CEO
            "Savneet Singh",      # PAR Technology CEO
            "Noah Glass",         # Olo founder / CEO
            "David Wilkinson",    # NCR Voyix CEO
            "Raju Vegesna",       # Zoho / SpotOn backer
            "John Morrison",      # Foods Connected CEO
            "Matt Wampler",       # ClearCOGS CEO
            "Krystle Mobayeni",   # Lunchbox CEO
            "Jason Merritt",      # Checkmate CEO
            "Raj Suri",           # Presto CEO
        ],
        "exec_investor": [
            "Danny Meyer",        # USHG / Enlightened Hospitality Investments
            "Howard Schultz",     # former Starbucks CEO / investor
            "Greg Creed",         # former Yum Brands CEO / board advisor
            "Kat Cole",           # board member / advisor across brands
            "Ron Shaich",         # Panera founder / Act III Investments
            "Marc Lore",          # Wonder / serial restaurant investor
        ],
        "exec_analyst": [
            "John Gordon",        # Pacific Management Consulting
            "Jonathan Maze",      # Nation's Restaurant News editor
            "Joe Guszkowski",     # RTN / industry reporter
            "Peter Romeo",        # FSR / restaurant journalist
            "Nicholas Upton",     # QSR Magazine editor
            "John Hamburger",     # Franchise Times / analyst
            "Paul Barron",        # NRN / digital media
            "Hudson Riehle",      # NRA SVP Research
        ],
        "exec_tech_analyst": [
            "Sriram Harish",      # restaurant tech analyst
            "Todd Blackwell",     # restaurant technology consultant
            "Donald Burns",       # The Restaurant Coach
            "Shawna Gibb",        # restaurant tech influencer
            "Carl Orsbourn",      # Delivering the Digital Restaurant author
            "Meredith Sandland",  # Empower Delivery / author
            "James Walker",       # restaurant ops / tech commentator
        ],
        "exec_operator": [
            "Tabassum Zalotrawala", # Chipotle Chief Development Officer
            "Mason Smoot",          # Portillo's COO
            "Russ Bendel",          # The Habit / operator veteran
            "Michael Kark",         # franchise operator / board member
            "Troy Alstead",         # former Starbucks COO
            "Tarun Lal",            # Dine Brands / restaurant operator
        ],
    }

    # Build flat list (deduped — a company in multiple user-defined categories
    # only appears once, under its primary category above)
    _seen_tech: set[str] = set()
    MANDATORY_RESTAURANT_TECH: list[str] = []
    _TECH_CATEGORY_MAP: dict[str, str] = {}
    for _cat, _names in _tech_categories.items():
        for _n in _names:
            if _n not in _seen_tech:
                _seen_tech.add(_n)
                MANDATORY_RESTAURANT_TECH.append(_n)
                _TECH_CATEGORY_MAP[_n] = _cat

    MANDATORY_ALL = MANDATORY_RESTAURANT_BRANDS + MANDATORY_RESTAURANT_TECH

    entities: list[dict] = []

    # People: inner-tier contacts
    rsr = report.get("relationship_signals") or {}
    for sig in (rsr.get("signals") or []):
        if sig.get("tier") == "inner":
            name = sig.get("name") or sig.get("contact_name") or ""
            if name and not any(e["name"] == name for e in entities):
                entities.append({"name": name, "type": "person", "mandatory": False})

    # Companies: from earnings_watch_list_mutations extras
    for item in (sections.get("earnings_watch_list_mutations") or []):
        if not isinstance(item, dict):
            continue
        extras = item.get("extras") or {}
        for co in (extras.get("companies_added") or extras.get("companies") or []):
            name = co.get("name") if isinstance(co, dict) else str(co)
            if name and not any(e["name"] == name for e in entities):
                entities.append({"name": name, "type": "company", "mandatory": False})

    # Companies: from strategic_operator_movements entity_name extras
    for item in (sections.get("strategic_operator_movements") or []):
        if not isinstance(item, dict):
            continue
        name = (item.get("extras") or {}).get("entity_name") or ""
        if name and not any(e["name"] == name for e in entities):
            entities.append({"name": name, "type": "company", "mandatory": False})

    # RB-DEFECT-2026-08-19: Companies promoted by technomic_watchlist_scan.py
    # -- the tiered (top 100 daily / rest weekly) press-release scan of the
    # full Technomic 1500-brand universe. Only entities that scan already
    # judged "meaningful signal to the user" (tier 1 by default, or tier 2
    # with a material signal_class) land in this manifest; a non-material
    # finding was recorded to system/ecosystem_intelligence.json instead and
    # deliberately never reaches this list. Gated on today's date so a stale
    # manifest from a prior failed/skipped scan can't silently re-surface.
    try:
        _technomic_path = core.CACHE_DIR / "technomic_watchlist_promoted.json"
        if _technomic_path.exists():
            _technomic_manifest = json.loads(_technomic_path.read_text(encoding="utf-8"))
            if _technomic_manifest.get("_scan_date") == date.today().isoformat():
                for _t in (_technomic_manifest.get("entities") or []):
                    _t_name = _t.get("name") if isinstance(_t, dict) else None
                    if _t_name and not any(e["name"] == _t_name for e in entities):
                        # check_press_release: True -- see the mandatory-only
                        # gate a few lines below. These entities are dynamic
                        # (mandatory=False, no "No Change" placeholder if
                        # nothing more turns up today), but the scan that
                        # promoted them already found a real press release,
                        # so they still need the press-release evidence
                        # lookup to run, or the finding never attaches to
                        # the item and it silently rolls into No Change.
                        entities.append({"name": _t_name, "type": "company",
                                          "mandatory": False, "check_press_release": True})
    except Exception:  # noqa: BLE001
        pass

    # Mandatory coverage entities — always included, signal or no signal
    for name in MANDATORY_RESTAURANT_BRANDS:
        if not any(e["name"] == name for e in entities):
            entities.append({"name": name, "type": "company", "mandatory": True, "category": "restaurant_brand"})
    for name in MANDATORY_RESTAURANT_TECH:
        if not any(e["name"] == name for e in entities):
            cat = _TECH_CATEGORY_MAP.get(name, "restaurant_tech_other")
            entities.append({"name": name, "type": "company", "mandatory": True, "category": cat})
    # Mandatory executives — public signal sources, roll up by sub-category when no signal
    for exec_cat, names in MANDATORY_EXECUTIVES.items():
        for name in names:
            if not any(e["name"] == name for e in entities):
                entities.append({
                    "name": name, "type": "person", "mandatory": True,
                    "category": exec_cat, "watchlist_executive": True,
                })

    _STATUS_DISP = {
        "Escalation": "act_today", "New Activity": "monitor",
        "Relevant Activity": "monitor", "No Change": "ignore",
    }
    _STATUS_CONF = {
        "Escalation": "high", "New Activity": "high",
        "Relevant Activity": "medium", "No Change": "low",
    }

    # Scan web_scan for entity mentions to detect "No Change" vs signal
    web_scan = report.get("web_scan") or {}
    web_all_titles: list[str] = []
    for bucket in ("restaurant_technology", "restaurant_industry", "world_national"):
        for item in (web_scan.get(bucket) or []):
            title = (item.get("title") or "").lower()
            desc = (item.get("summary") or item.get("description") or "").lower()
            web_all_titles.append(title + " " + desc)

    def _entity_in_web_scan(name: str) -> bool:
        """Return True if any web_scan item mentions this entity."""
        search_term = name.lower().replace("'", "")
        for text in web_all_titles:
            if search_term in text.replace("'", ""):
                return True
        return False

    # RB-9.65-D: entity_alerts.py maintains a Google-News-search "alerts" cache
    # for the mandatory watchlist (rotates ~8 entities/day). When an entity has
    # no signal from the brief sections or web_scan, check this cache before
    # confirming "no developments" — it covers M&A/funding/exec-move/layoff
    # headlines outside the configured RSS feed set.
    _entity_alerts_cache: dict = {}
    try:
        _alerts_path = core.CACHE_DIR / "entity_alerts_cache.json"
        if _alerts_path.exists():
            _entity_alerts_cache = (json.loads(_alerts_path.read_text(encoding="utf-8")) or {}).get("entities") or {}
    except Exception:
        _entity_alerts_cache = {}

    # RB-DEFECT-2026-07-15: pr_hits[0] (below) is whatever's currently first
    # in entity_alerts_cache.json for that entity, with no memory of what
    # was already reported -- so the same press release kept getting
    # flagged "New Activity" for an entity day after day as long as it sat
    # in the cache. Confirmed live: Domino's/PAR Technology/Agilysys/Revel/
    # SoundHound all showed the byte-identical news.google.com URL as "New
    # Activity" on both 2026-07-14 and 2026-07-15. Track the last URL
    # surfaced per entity so a genuinely new press release still counts as
    # new, but a repeat doesn't.
    _watchlist_new_activity_seen_path = core.CACHE_DIR / "watchlist_new_activity_seen.json"
    try:
        _watchlist_new_activity_seen: dict = json.loads(
            _watchlist_new_activity_seen_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, FileNotFoundError):
        _watchlist_new_activity_seen = {}
    _watchlist_new_activity_seen_updates: dict = dict(_watchlist_new_activity_seen)

    def _entity_alert_hit(name: str) -> dict | None:
        """Return the most recent alert item for this entity — press releases first."""
        rec = _entity_alerts_cache.get(name)
        if not rec:
            return None
        # Press releases take priority — they are official announcements
        pr_items = rec.get("press_release_items") or []
        if pr_items:
            return pr_items[0]
        items = rec.get("items") or []
        return items[0] if items else None

    def _entity_press_releases(name: str) -> list[dict]:
        """Return all cached press releases for this entity."""
        rec = _entity_alerts_cache.get(name)
        if not rec:
            return []
        return rec.get("press_release_items") or []

    # RB-DEFECT-066: post-earnings signals (build_earnings_intelligence's
    # earnings_type=post_earnings_signal items) are completed, high-
    # confidence market events, but were never wired into watchlist status
    # computation -- _watchlist_entity_status only scans a fixed list of
    # sections that doesn't include earnings_intelligence, so a company with
    # a confirmed earnings release still showed "No Change" here. And Section
    # E's renderer only picks up watchlist items whose *title* already
    # carries an EARNINGS/FUNDING/... badge, so even a correct non-"No
    # Change" status wouldn't have surfaced without a matching title. Build
    # a name -> override map from this cycle's post-earnings signals so
    # those entities get an authoritative Escalation status with an
    # EARNINGS-badged title instead of falling through to "No Change."
    _earnings_overrides: dict[str, dict] = {}
    for _ei in (sections.get("earnings_intelligence") or []):
        _ext = _ei.get("extras") or {}
        if _ext.get("earnings_type") != "post_earnings_signal":
            continue
        _company = (_ext.get("company") or "").strip()
        if not _company:
            continue
        _bare_title = (_ei.get("title") or "").replace(f"[POST-EARNINGS] {_company}: ", "").strip()
        _earnings_overrides[_company] = {
            # Must carry both the status word (every watchlist item title
            # states its status category -- see CBS1c) and the EARNINGS
            # badge (Section E's _render_earnings only picks up titles
            # containing one of its badge keywords).
            "title": f"{_company} — Escalation [EARNINGS] {_bare_title or 'earnings release'}",
            "evidence": _ei.get("summary") or _ei.get("why_it_matters") or "Earnings release detected.",
            "evidence_url": _ext.get("source_url") or None,
            # 2026-08-10 feature request: carry the history pointer through
            # so Section E can render a "full history" callout, not just
            # the truncated executive-summary text.
            "recommended_action": _ei.get("recommended_action") or "",
            "trend_note": _ext.get("trend_note") or "",
            "history_count": _ext.get("history_count") or 0,
            "history_api": _ext.get("history_api") or "getCompanyEarningsHistory",
            "exhibit_url": _ext.get("exhibit_url"),
        }

    result: list[dict] = []
    # No-change entities roll up per category. This keeps the brief compact
    # even with 150+ mandatory entities — only signals surface individually.
    # Executive watchlist members roll up by their sub-category just like
    # companies. Inner-tier relationship contacts are NOT watchlist executives
    # and always appear individually.
    no_change_buckets: dict[str, list[str]] = {
        "restaurant_brand": [],
        "restaurant_tech_pos": [], "restaurant_tech_backoffice": [],
        "restaurant_tech_digital": [], "restaurant_tech_ai": [],
        "restaurant_tech_loyalty": [], "restaurant_tech_payments": [],
        "restaurant_tech_infrastructure": [], "restaurant_tech_other": [],
        "exec_restaurant_ceo": [], "exec_tech_ceo": [], "exec_investor": [],
        "exec_analyst": [], "exec_tech_analyst": [], "exec_operator": [],
        "other": [],
    }
    seen: set[str] = set()
    for ent in entities:
        name = ent["name"]
        if name in seen:
            continue
        seen.add(name)
        status, evidence = _watchlist_entity_status(name, sections)

        # For mandatory entities with no signal detected in sections,
        # check web_scan directly before confirming "no developments."
        #
        # Evidence text built here is a human-facing display string (it feeds
        # why_it_matters and evidence_headline, both read directly by the
        # brief renderer and the GPT) — it must never carry an embedded
        # tracking/redirect URL. A raw Google-News redirect URL baked into
        # the sentence ("... (Source: Press Wire, https://news.google.com/
        # rss/articles/CBMi...) ") made every press-release-sourced entity's
        # "why it matters" an unreadable wall of text.
        # RB-DEFECT-2026-07-10e: evidence_url captures the real article/press-
        # release link so the renderer can produce a proper [title](url) link
        # like every other headline section — previously only the stripped
        # evidence sentence was kept and the URL was discarded entirely, so
        # Section F press-release bullets had no way to be read, unlike A-E.
        evidence_url = None
        earnings_override = _earnings_overrides.get(name)
        if earnings_override:
            # RB-DEFECT-066: a confirmed earnings release outranks whatever
            # _watchlist_entity_status found (or didn't) -- always escalate.
            status = "Escalation"
            evidence = earnings_override["evidence"]
            evidence_url = earnings_override["evidence_url"]
        elif status == "No Change" and (ent.get("mandatory") or ent.get("check_press_release")):
            in_scan = _entity_in_web_scan(name)
            if in_scan:
                status = "Relevant Activity"
                evidence = "Mentioned in today's web intelligence scan. Review morning_headlines for detail."
            else:
                # Check press releases first — official announcements are higher signal
                pr_hits = _entity_press_releases(name)
                pr_is_new = False
                if pr_hits:
                    pr = pr_hits[0]
                    pr_url = (pr.get("url") or "").strip()
                    already_surfaced = bool(pr_url) and _watchlist_new_activity_seen.get(name) == pr_url
                    if not already_surfaced:
                        pr_is_new = True
                        status = "New Activity"
                        pr_title = (pr.get("title") or "").strip()
                        pr_source = (pr.get("source") or "Press Wire").strip()
                        evidence = f"Press release: {pr_title} ({pr_source})" if pr_title else f"Press release via {pr_source}."
                        evidence_url = pr_url or None
                        if pr_url:
                            _watchlist_new_activity_seen_updates[name] = pr_url
                if not pr_is_new:
                    # RB-9.65-D: fall back to the entity_alerts Google-News cache
                    alert = _entity_alert_hit(name)
                    if alert:
                        status = "Relevant Activity"
                        badge = (alert.get("signal_badge") or "").strip()
                        alert_title = (alert.get("title") or "").strip()
                        evidence = f"{(badge + ' ') if badge else ''}{alert_title}".strip() or "Entity alert detected — review required."
                        evidence_url = (alert.get("url") or "").strip() or None

        is_mandatory = ent.get("mandatory", False)
        category = ent.get("category", "")
        is_watchlist_executive = ent.get("watchlist_executive", False)

        # Roll up no-change entities into per-category summary rows.
        # Watchlist executives (public figures) roll up by exec category.
        # Inner-tier relationship contacts (type=person, not watchlist_executive)
        # always appear individually so they stay visible.
        should_rollup = status == "No Change" and (
            ent["type"] != "person" or is_watchlist_executive
        )
        if should_rollup:
            bucket = category if category in no_change_buckets else "other"
            no_change_buckets[bucket].append(name)
            continue

        result.append(_canonical_item(
            title=earnings_override["title"] if earnings_override else f"{name} — {status}",
            summary=evidence or "Signal detected in monitoring window.",
            # "Monitored {type}. Evidence: ..." was pure boilerplate on every
            # single item — being monitored is already implied by appearing
            # in the watchlist at all, so it added a redundant clause to
            # every why_it_matters without adding information. State the
            # actual evidence directly instead.
            why_it_matters=evidence or "Signal detected — review required.",
            recommended_action=(
                (earnings_override["recommended_action"]
                 or "Review earnings release for vendor decision language and technology "
                    "investment signals.") if earnings_override
                else "Follow up immediately." if status == "Escalation"
                else "Review new signal." if status == "New Activity"
                else "Monitor for developments." if status == "Relevant Activity"
                else "No action needed."
            ),
            disposition=_STATUS_DISP.get(status, "monitor"),
            grounding="system_detected",
            freshness="fresh",
            source_refs=["relationship_signals", "intelligence_store.json"],
            confidence=_STATUS_CONF.get(status, "medium"),
            extras={
                "entity_name": name,
                "entity_type": ent["type"],
                "watchlist_status": status,
                "evidence_headline": evidence or None,
                "source_url": evidence_url,
                "coverage_confirmed": True,
                "mandatory_coverage": is_mandatory,
                "category": category,
                # RB-DEFECT-2026-08-12: this used to default True for any
                # active status (Escalation/New/Relevant), which isn't what
                # "changed" means -- it made every entity look like a fresh
                # change every single day it stayed active, masking the real
                # day-over-day diff the Layer-2 pass below computes (and
                # feeding a false signal to the "watchlist status changes"
                # delta detector at ~line 7759, and now also to render_
                # intelligence_brief.py/render_daily_brief.py's fresh-vs-
                # persisting escalation rendering). False here, matching the
                # "No Change" rollup's own default a few lines down --
                # the later pass (~line 16518) is the sole authority that
                # sets this True, and only when today's status genuinely
                # differs from the prior published brief's.
                "status_changed": False,
                **({
                    "trend_note": earnings_override["trend_note"],
                    "history_count": earnings_override["history_count"],
                    "history_api": earnings_override["history_api"],
                    "exhibit_url": earnings_override["exhibit_url"],
                } if earnings_override else {}),
            },
        ))

    _bucket_label = {
        "restaurant_brand": "Restaurant Chains & Groups",
        "restaurant_tech_pos": "POS",
        "restaurant_tech_backoffice": "Back Office",
        "restaurant_tech_digital": "Digital Ordering & Guest Experience",
        "restaurant_tech_ai": "AI (Restaurant & Horizontal)",
        "restaurant_tech_loyalty": "Loyalty & CRM",
        "restaurant_tech_payments": "Payments",
        "restaurant_tech_infrastructure": "Infrastructure & Integration",
        "restaurant_tech_other": "Restaurant Technology (Other)",
        "exec_restaurant_ceo": "Restaurant CEOs & Founders",
        "exec_tech_ceo": "Restaurant Technology CEOs",
        "exec_investor": "Investors & Board-Level",
        "exec_analyst": "Industry Analysts & Operators",
        "exec_tech_analyst": "Technology Analysts & Influencers",
        "exec_operator": "Enterprise Operators",
        "other": "Other Watchlist",
    }
    rollup_items: list[dict] = []
    for bucket, names in no_change_buckets.items():
        if not names:
            continue
        label = _bucket_label.get(bucket, bucket)
        rollup_items.append(_canonical_item(
            title=f"{label} — No Change ({len(names)} scanned, no material developments)",
            summary=(
                f"Scanned {len(names)}: "
                + ", ".join(names)
                + ". No material news, signals, or activity detected this cycle."
            ),
            why_it_matters=(
                "Coverage confirmed — each entity was scanned and returned no actionable signal. "
                "Render as a compact grid: `[ok] Name` for each entry in extras.no_change_entities."
            ),
            recommended_action="No action required. Continue monitoring.",
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["web_scanner", "relationship_signals", "intelligence_store.json"],
            confidence="high",
            extras={
                "entity_name": label,
                "entity_type": "rollup",
                "watchlist_status": "No Change",
                "evidence_headline": None,
                "coverage_confirmed": True,
                "mandatory_coverage": bucket != "other",
                "category": bucket,
                "status_changed": False,
                "no_change_entities": names,
                "no_change_count": len(names),
            },
        ))

    # Rollup items lead the list so they always survive Part 2's
    # _compact_section truncation (limit=12) — they are the only thing that
    # carries proof of coverage for the ~85+ "No Change" mandatory entities.
    # Highest-urgency individual signals (Escalation/New Activity) follow,
    # then lower-urgency ones, so the remaining slots go to what matters most.
    _urgency = {"Escalation": 0, "New Activity": 1, "Relevant Activity": 2}
    result.sort(key=lambda it: _urgency.get((it.get("extras") or {}).get("watchlist_status"), 3))

    if _watchlist_new_activity_seen_updates != _watchlist_new_activity_seen:
        try:
            _watchlist_new_activity_seen_path.parent.mkdir(parents=True, exist_ok=True)
            _watchlist_new_activity_seen_path.write_text(
                json.dumps(_watchlist_new_activity_seen_updates, indent=2), encoding="utf-8")
        except OSError:
            pass

    return rollup_items + result


def _compute_intelligence_cycle_continuation(report: dict, sections: dict) -> list[dict]:
    """Build the CoS follow-through checklist for closing the current intelligence cycle.

    Answers: "What must the CoS do before the next brief to keep the pipeline healthy?"

    Sources drawn from the fully-populated sections dict (runs after all other sections
    including graph_mutation_log).  Each item is an actionable task with a specific
    endpoint or operation to call.  Items are ordered by urgency.

    Categories:
    1. Pending confirmations — passive RI events that need user review
    2. Stale sources — feeds that must be refreshed before the next cycle is trustworthy
    3. Overdue loop debt — loops past target that need close/re-date
    4. Contact momentum debt — COLD/FROZEN RC contacts with no open loop
    5. Open decisions — decision_queue items that have not been resolved
    """
    today_dt = date.today()
    tasks: list[dict] = []

    # ── 1. Pending RI confirmations ───────────────────────────────────────────
    ri = report.get("ri_events_recent") or {}
    proposed_ri = ri.get("proposed_unconfirmed") or []
    pri = report.get("passive_ri_ingest") or {}
    passive_proposed = pri.get("events_written") or []
    total_pending = len(proposed_ri) + len(passive_proposed)

    def _ri_name(e: dict) -> str:
        flat = e.get("name") or e.get("contact_name") or e.get("entity_name")
        if flat:
            return flat
        people = (e.get("entities") or {}).get("people") or []
        if people:
            p = people[0]
            return p.get("raw") or p.get("matched_id") or "?"
        src_title = (e.get("source") or {}).get("title") or ""
        if "—" in src_title:
            return src_title.split("—")[-1].strip()
        return e.get("contact_id") or "?"

    if total_pending:
        pending_names = list({
            _ri_name(e) for e in (proposed_ri + passive_proposed)[:5]
        })
        tasks.append(_canonical_item(
            title=f"[CYCLE TASK] Confirm {total_pending} pending RI event(s)",
            summary=(
                f"{total_pending} RI event(s) proposed this cycle have not been confirmed. "
                f"Contacts: {', '.join(pending_names[:4])}{'…' if len(pending_names) > 4 else ''}. "
                "Until confirmed, RB state does not reflect these interactions — last_touch dates are stale."
            ),
            why_it_matters=(
                "Unconfirmed RI events leave the relationship baseline stale. "
                "COLD/FROZEN momentum scores for these contacts won't improve until events are confirmed."
            ),
            recommended_action=(
                f"Call reviewRIEvent for each of the {total_pending} pending event(s). "
                "Or call getRecentRIEvents to see the full pending list."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["ri_events_recent", "passive_ri_ingest.json"],
            confidence="high",
            extras={
                "pending_count": total_pending,
                "pending_contacts": pending_names,
                "ri_proposed": len(proposed_ri),
                "passive_proposed": len(passive_proposed),
                "endpoint": "reviewRIEvent",
            },
        ))

    # ── 2. Stale sources ──────────────────────────────────────────────────────
    source_health = (
        (report.get("daily_prep_summary") or {}).get("source_health")
        or report.get("source_health")
        or {}
    )
    health_sources = source_health.get("sources") or {}
    stale_tier1 = [
        name for name, row in health_sources.items()
        if isinstance(row, dict)
        and int(row.get("tier") or 0) == 1
        and row.get("status") != "refreshed"
    ]
    msr = report.get("market_signals") or {}
    if msr.get("stale"):
        stale_tier1 = list(set(stale_tier1 + ["market_signals"]))

    if stale_tier1:
        tasks.append(_canonical_item(
            title=f"[CYCLE TASK] Refresh {len(stale_tier1)} stale source(s) before next cycle",
            summary=(
                f"The following Tier 1 sources are stale and will degrade next brief's intelligence quality: "
                f"{', '.join(stale_tier1[:5])}{'…' if len(stale_tier1) > 5 else ''}. "
                "Call refreshSources to update all connected feeds."
            ),
            why_it_matters=(
                "Stale Tier 1 sources (email, calendar, market signals) are the primary cause of "
                "'quiet board' false negatives. The next brief cannot claim relationship or industry "
                "quiet if these sources are not refreshed."
            ),
            recommended_action="Call refreshSources to update all stale feeds before end of day.",
            disposition="act_today",
            grounding="system_detected",
            freshness="stale_source_limited",
            source_refs=["source_health.json"],
            confidence="high",
            extras={
                "stale_sources": stale_tier1,
                "stale_count": len(stale_tier1),
                "endpoint": "refreshSources",
            },
        ))

    # ── 3. Overdue loop debt ───────────────────────────────────────────────────
    loops = report.get("loops") or {}
    overdue = loops.get("overdue") or []
    if overdue:
        overdue_names = [f"{L['id']}/{L['party']}" for L in overdue[:4]]
        tasks.append(_canonical_item(
            title=f"[CYCLE TASK] Close or re-date {len(overdue)} overdue loop(s)",
            summary=(
                f"{len(overdue)} loop(s) are past their target date: "
                f"{', '.join(overdue_names)}{'…' if len(overdue) > 4 else ''}. "
                "Overdue loops accumulate as action debt and distort momentum scores."
            ),
            why_it_matters=(
                "Overdue loops are the clearest form of follow-through failure. Each overdue loop "
                "represents a commitment that was not closed. Letting them accumulate erodes RB's "
                "ability to surface genuine priorities."
            ),
            recommended_action=(
                f"For each of the {len(overdue)} overdue loop(s): call closeLoop (if complete) or "
                "addLoop with updated target (if deferred). Do not leave open past target."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["loop_ledger"],
            confidence="high",
            extras={
                "overdue_count": len(overdue),
                "overdue_loops": overdue_names,
                "endpoints": ["closeLoop", "addLoop"],
            },
        ))

    # ── 4. Contact momentum debt ───────────────────────────────────────────────
    momentum_items = sections.get("relationship_momentum_status") or []
    cold_frozen_no_loop = [
        item for item in momentum_items
        if (item.get("extras") or {}).get("momentum_tier") in ("COLD", "FROZEN")
        and (item.get("extras") or {}).get("open_loop_count", 0) == 0
    ]
    if cold_frozen_no_loop:
        names = [
            item.get("extras", {}).get("contact_id") or item.get("title", "").split("—")[0].strip()
            for item in cold_frozen_no_loop[:4]
        ]
        tasks.append(_canonical_item(
            title=f"[CYCLE TASK] Re-engage {len(cold_frozen_no_loop)} COLD/FROZEN RC contact(s) with no open loop",
            summary=(
                f"{len(cold_frozen_no_loop)} RC contact(s) are in COLD or FROZEN momentum state "
                f"with no open loop: {', '.join(names)}{'…' if len(cold_frozen_no_loop) > 4 else ''}. "
                "Without an open loop, these relationships have no tracked next step."
            ),
            why_it_matters=(
                "COLD/FROZEN contacts without open loops are the highest-risk relationship gaps. "
                "They represent relationships that are drifting with no active follow-through mechanism. "
                "Each additional day without action widens the reactivation gap."
            ),
            recommended_action=(
                f"For each of the {len(cold_frozen_no_loop)} contact(s): "
                "call addLoop to create a re-engagement loop, or touchContact to log direct outreach."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["baseline_index.json", "loop_ledger"],
            confidence="high",
            extras={
                "cold_frozen_no_loop_count": len(cold_frozen_no_loop),
                "contact_names": names,
                "endpoints": ["addLoop", "touchContact"],
            },
        ))

    # ── 5. Open decisions ─────────────────────────────────────────────────────
    decision_items = sections.get("decision_queue") or []
    unresolved = [d for d in decision_items if d.get("disposition") == "ask_todd"]
    if unresolved:
        decision_titles = [d.get("title", "?") for d in unresolved[:3]]
        tasks.append(_canonical_item(
            title=f"[CYCLE TASK] Resolve {len(unresolved)} decision(s) in queue",
            summary=(
                f"{len(unresolved)} decision(s) require your judgment before the next cycle: "
                f"{'; '.join(decision_titles)}{'…' if len(unresolved) > 3 else ''}. "
                "Unresolved decisions accumulate as cognitive debt across brief cycles."
            ),
            why_it_matters=(
                "Each unresolved decision in the queue blocks downstream execution: "
                "loops cannot be opened, mutations cannot be applied, and intelligence cannot be confirmed "
                "until the underlying question is answered."
            ),
            recommended_action=(
                "Answer each queued decision now or explicitly defer with a target date. "
                "Deferral must be recorded — do not silently skip."
            ),
            disposition="act_today" if len(unresolved) >= 3 else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["decision_queue"],
            confidence="high",
            extras={
                "unresolved_count": len(unresolved),
                "decision_titles": decision_titles,
            },
        ))

    if not tasks:
        tasks.append(_canonical_item(
            title="Intelligence cycle — clean state",
            summary=(
                "No pending confirmations, stale sources, overdue loops, "
                "COLD/FROZEN contacts without loops, or open decisions. "
                "The intelligence cycle is in clean state — next brief can proceed without backlog."
            ),
            why_it_matters=(
                "A clean cycle state means RB's operating intelligence is current and "
                "follow-through is complete. This is the target state."
            ),
            recommended_action="Proceed to next brief cycle — no backlog items.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["graph_mutation_log", "decision_queue", "loop_ledger"],
            confidence="high",
        ))

    return tasks


def _compute_graph_mutation_log(report: dict, sections: dict) -> list[dict]:
    """Build a structured log of all RB state changes this brief cycle.

    Answers: "What did RB actually change today?"

    Mutation categories:
    1. RI events — persisted (confirmed state writes), proposed (awaiting confirmation),
       rejected (explicitly not acted on)
    2. Passive RI — proposed from system signals (not yet confirmed by user)
    3. Loops — opened today (loop.opened == today), overdue/due buckets
    4. Intelligence lifecycle — new items identified, reactivated, suppressed
    5. Market signals — processed from feeds

    Returns one canonical item per mutation category (only non-zero categories).
    """
    today_dt = date.today()
    items: list[dict] = []

    # ── 1. RI events ─────────────────────────────────────────────────────────
    ri = report.get("ri_events_recent") or {}
    persisted = ri.get("newly_captured") or []
    proposed = ri.get("proposed_unconfirmed") or []
    rejected = ri.get("rejected_today") or []

    def _ri_event_name(e: dict) -> str:
        """Resolve a display name from an RI event dict.

        RI events produced by the passive detector store person names at
        entities.people[0].raw (or .matched_id), not at the top-level name/
        contact_name keys.  Fall back through all known schemas so we never
        render "?" unless the event truly has no person data.
        """
        # Flat keys (manual intake path)
        flat = e.get("name") or e.get("contact_name") or e.get("entity_name")
        if flat:
            return flat
        # Structured entities key (passive detector path)
        people = (e.get("entities") or {}).get("people") or []
        if people:
            p = people[0]
            return p.get("raw") or p.get("matched_id") or "?"
        # Source title fallback
        src_title = (e.get("source") or {}).get("title") or ""
        if src_title:
            # e.g. "Passive direct_interaction signal — Jeff Wayman"
            parts = src_title.split("—")
            if len(parts) > 1:
                return parts[-1].strip()
        return e.get("contact_id") or "?"

    if persisted or proposed or rejected:
        persisted_names = [_ri_event_name(e) for e in persisted[:4]]
        proposed_names = [_ri_event_name(e) for e in proposed[:3]]
        summary_parts = []
        if persisted:
            ns = ", ".join(persisted_names) + ("…" if len(persisted) > 4 else "")
            summary_parts.append(f"[PERSISTED] {len(persisted)} RI event(s) recorded: {ns}.")
        if proposed:
            ns = ", ".join(proposed_names) + ("…" if len(proposed) > 3 else "")
            summary_parts.append(
                f"[PROPOSED] {len(proposed)} RI event(s) awaiting confirmation: {ns}. "
                "Confirm via reviewRIEvent."
            )
        if rejected:
            summary_parts.append(f"[REJECTED] {len(rejected)} RI event(s) explicitly not recorded.")

        disposition = "act_today" if proposed else ("monitor" if persisted else "ignore")
        items.append(_canonical_item(
            title=f"RI events — {len(persisted)} persisted, {len(proposed)} proposed, {len(rejected)} rejected",
            summary=" ".join(summary_parts),
            why_it_matters=(
                "Persisted RI events are confirmed state writes. "
                "Proposed events are pending your confirmation — they do not change RB state until confirmed."
            ),
            recommended_action=(
                f"Confirm or reject {len(proposed)} proposed RI event(s) via reviewRIEvent."
                if proposed else
                "RI events are current. No confirmation required."
            ),
            disposition=disposition,
            grounding="system_detected",
            freshness="fresh",
            source_refs=["ri_events_recent"],
            confidence="high",
            extras={
                "persisted_count": len(persisted),
                "proposed_count": len(proposed),
                "rejected_count": len(rejected),
                "persisted_contacts": persisted_names,
                "proposed_contacts": proposed_names,
            },
        ))

    # ── 2. Passive RI ─────────────────────────────────────────────────────────
    pri = report.get("passive_ri_ingest") or {}
    pri_written = pri.get("events_written") or []
    pri_dup = len(pri.get("duplicates_skipped") or [])
    pri_blocked = sum(
        len(pri.get(b) or []) for b in (
            "blocked_low_confidence", "blocked_stale_source",
            "blocked_unmatched_entity", "blocked_no_date", "blocked_validation_error",
        )
    )
    if pri_written or pri_dup or pri_blocked:
        pri_names = [
            e.get("name") or e.get("contact_id") or "?"
            for e in pri_written[:3]
        ]
        summary = (
            f"[PROPOSED] {len(pri_written)} passive RI event(s) proposed from system signals"
            + (f" ({', '.join(pri_names)}{'…' if len(pri_written) > 3 else ''})" if pri_names else "")
            + "."
        )
        if pri_dup:
            summary += f" {pri_dup} duplicate(s) skipped."
        if pri_blocked:
            summary += f" {pri_blocked} candidate(s) blocked (low confidence, stale source, or insufficient data)."
        items.append(_canonical_item(
            title=f"Passive RI — {len(pri_written)} proposed from system signals",
            summary=summary,
            why_it_matters=(
                "Passive RI events are proposed by RB from system-detected signals (email patterns, "
                "calendar overlap, LinkedIn activity). They are not confirmed state changes until you "
                "review and accept them."
            ),
            recommended_action=(
                f"Review and confirm {len(pri_written)} passive RI event(s) via reviewRIEvent."
                if pri_written else "No passive RI events proposed this cycle."
            ),
            disposition="act_today" if pri_written else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["passive_ri_ingest.json"],
            confidence="medium",
            extras={
                "proposed_count": len(pri_written),
                "duplicates_skipped": pri_dup,
                "blocked_count": pri_blocked,
                "proposed_contacts": pri_names,
            },
        ))

    # ── 3. Loops opened today ─────────────────────────────────────────────────
    try:
        all_loops = core.parse_loop_ledger()
        loops_opened_today = [
            lp for lp in all_loops
            if not lp.closed and lp.opened == today_dt
        ]
        loops_closed_recent = [
            lp for lp in all_loops
            if lp.closed and lp.target >= today_dt - timedelta(days=3)
        ]
        if loops_opened_today or loops_closed_recent:
            opened_names = [f"{lp.id}/{lp.party}" for lp in loops_opened_today[:4]]
            closed_names = [f"{lp.id}/{lp.party}" for lp in loops_closed_recent[:3]]
            summary_parts = []
            if loops_opened_today:
                summary_parts.append(
                    f"[OPENED] {len(loops_opened_today)} loop(s) opened today: "
                    + ", ".join(opened_names) + ("…" if len(loops_opened_today) > 4 else "") + "."
                )
            if loops_closed_recent:
                summary_parts.append(
                    f"[CLOSED] {len(loops_closed_recent)} loop(s) closed in the last 3 days: "
                    + ", ".join(closed_names) + ("…" if len(loops_closed_recent) > 3 else "") + "."
                )
            items.append(_canonical_item(
                title=(
                    f"Loops — {len(loops_opened_today)} opened today"
                    + (f", {len(loops_closed_recent)} closed recently" if loops_closed_recent else "")
                ),
                summary=" ".join(summary_parts),
                why_it_matters=(
                    "Loop mutations are the clearest signal that RB is operating as an execution "
                    "layer, not just a reading layer. Opening and closing loops proves follow-through."
                ),
                recommended_action="Verify newly opened loops reflect current state; close completed loops.",
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["loop_ledger"],
                confidence="high",
                extras={
                    "loops_opened_today": len(loops_opened_today),
                    "loops_closed_recently": len(loops_closed_recent),
                    "opened_names": opened_names,
                    "closed_names": closed_names,
                },
            ))
    except Exception:  # noqa: BLE001
        pass

    # ── 4. Intelligence lifecycle transitions ─────────────────────────────────
    new_intel_count = len(sections.get("new_intelligence_today") or [])
    react_count = len(sections.get("reactivated_intelligence") or [])
    suppressed_count = len(sections.get("suppressed_today") or [])

    if new_intel_count or react_count or suppressed_count:
        summary_parts = []
        if new_intel_count:
            summary_parts.append(
                f"[NEW] {new_intel_count} first-time intelligence item(s) identified this cycle."
            )
        if react_count:
            summary_parts.append(
                f"[REACTIVATED] {react_count} previously dormant item(s) resurfaced by new evidence."
            )
        if suppressed_count:
            summary_parts.append(
                f"[SUPPRESSED] {suppressed_count} previously reported item(s) held back (no material change)."
            )
        items.append(_canonical_item(
            title=f"Intelligence — {new_intel_count} new, {react_count} reactivated, {suppressed_count} suppressed",
            summary=" ".join(summary_parts),
            why_it_matters=(
                "Intelligence lifecycle transitions prove the brief is a live operating layer, not a "
                "static summary. New items are first observations. Reactivated items prove evidence re-emerged. "
                "Suppressed items prove intentional omission, not accidental miss."
            ),
            recommended_action=(
                "Review new_intelligence_today and reactivated_intelligence sections for required follow-up."
                if (new_intel_count or react_count) else "No new intelligence this cycle."
            ),
            disposition="monitor" if (new_intel_count or react_count) else "ignore",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["intelligence_store.json", "new_intelligence_today"],
            confidence="high",
            extras={
                "new_items": new_intel_count,
                "reactivated_items": react_count,
                "suppressed_items": suppressed_count,
            },
        ))

    # ── 5. Market signals processed ───────────────────────────────────────────
    msr = report.get("market_signals") or {}
    ms_processed = msr.get("input_count") or 0
    ms_elevated = msr.get("elevated_count") or (
        len([i for i in (msr.get("items") or []) if i.get("elevated")])
    )
    if ms_processed:
        items.append(_canonical_item(
            title=f"Market signals — {ms_processed} processed, {ms_elevated} elevated",
            summary=(
                f"[SCANNED] {ms_processed} market signal(s) processed from industry feeds. "
                f"{ms_elevated} elevated to brief sections. "
                + (f"Source: stale ({msr.get('stale_reason', 'unknown reason')})."
                   if msr.get("stale") else "Source: fresh.")
            ),
            why_it_matters=(
                "Market signal processing proves RB actively scanned industry context, "
                "not just recalled prior thesis from memory."
            ),
            recommended_action=(
                "Refresh market_signals to improve coverage."
                if msr.get("stale") else "Market signal scan complete — no refresh needed."
            ),
            disposition="act_today" if msr.get("stale") else "monitor",
            grounding="system_detected",
            freshness="stale_source_limited" if msr.get("stale") else "fresh",
            source_refs=["market_signals"],
            confidence="medium" if msr.get("stale") else "high",
            extras={
                "signals_processed": ms_processed,
                "signals_elevated": ms_elevated,
                "source_stale": bool(msr.get("stale")),
            },
        ))

    return items


def _compute_pending_mutations(report: dict, sections: dict) -> list[dict]:
    """Surface interaction_ledger.json proposals unconfirmed for >12h (RB 9.69).

    relationship_intake.process_relationship_thread() writes interaction events
    with claim_status='proposed' and persistence_status='pending confirmation'.
    These require an explicit confirmRelationshipInteraction (POST
    /ingest/relationship/confirm) call to either persist or reject — RB never
    auto-confirms. The Custom GPT reaches this via the unified confirmProposal
    action (kind="relationship"); confirmRelationshipInteraction itself is
    for direct API callers only, not in the GPT's curated action list. If
    confirmation is skipped, the proposal sits in interaction_ledger.json
    indefinitely with no other surface calling it out.
    This is a separate mechanism from ri_events_recent/graph_mutation_log
    (24h window over ri_events.jsonl); this reads interaction_ledger.json
    directly so older unconfirmed proposals don't age out of view.
    """
    from datetime import datetime, timezone, timedelta

    ledger_path = core.SYSTEM_DIR / "interaction_ledger.json"
    try:
        ledger = json.loads(ledger_path.read_text())
    except (OSError, json.JSONDecodeError):
        return []

    cutoff = datetime.now(timezone.utc) - timedelta(hours=12)
    stale_proposed = []
    for interaction in ledger.get("interactions") or []:
        if interaction.get("claim_status") != "proposed":
            continue
        created_at = interaction.get("created_at")
        try:
            created_dt = datetime.fromisoformat(created_at)
        except (TypeError, ValueError):
            continue
        if created_dt.tzinfo is None:
            created_dt = created_dt.replace(tzinfo=timezone.utc)
        if created_dt < cutoff:
            stale_proposed.append(interaction)

    if not stale_proposed:
        return [_canonical_item(
            title="Pending mutations — none overdue",
            summary=(
                "No relationship-intelligence proposals have been awaiting "
                "confirmation for more than 12 hours."
            ),
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            confidence="high",
            source_refs=["interaction_ledger.json"],
        )]

    stale_proposed.sort(key=lambda i: i.get("created_at") or "")
    # entity.name is the raw extracted name (e.g. a voice-memo mis-transcription
    # like "Jeff Waman") even when contact_id has already been correctly
    # resolved to the baseline contact (see entity_resolution_note on the
    # interaction) -- prefer the resolved baseline name so the brief doesn't
    # surface transcription typos for contacts RB already knows correctly.
    try:
        _baseline_name_by_id = {c.get("id"): c.get("name") for c in core.load_baseline() if c.get("id")}
    except Exception:  # noqa: BLE001
        _baseline_name_by_id = {}
    def _resolved_name(i: dict) -> str:
        cid = i.get("contact_id")
        return (
            (cid and _baseline_name_by_id.get(cid))
            or (i.get("entity") or {}).get("name")
            or cid
            or "?"
        )
    names = [_resolved_name(i) for i in stale_proposed[:5]]
    name_list = ", ".join(names) + ("…" if len(stale_proposed) > 5 else "")

    return [_canonical_item(
        title=f"Pending mutations — {len(stale_proposed)} unconfirmed >12h",
        summary=(
            f"{len(stale_proposed)} relationship-intelligence interaction(s) have "
            f"been awaiting confirmation for over 12 hours: {name_list}."
        ),
        why_it_matters=(
            "Unconfirmed proposals do not update baseline_index.json or the "
            "relationship graph. Leaving them pending indefinitely means RB's "
            "recorded state silently diverges from what was actually discussed."
        ),
        # confirmRelationshipInteraction was never in the Custom GPT's 30-op
        # action list at all (checked 2026-07-06). Fixed by adding a unified
        # confirmProposal action (kind="relationship") that replaced the two
        # single-purpose confirmIdentityMatch/rejectIdentityMatch ops,
        # freeing a slot instead of costing one — see RB-DEFECT-2026-07-06.
        recommended_action=(
            f"Confirm or reject {len(stale_proposed)} pending interaction(s) via "
            f"confirmProposal (kind=\"relationship\"): {name_list}."
        ),
        disposition="act_today",
        grounding="system_detected",
        freshness="stale",
        confidence="high",
        source_refs=["interaction_ledger.json"],
        extras={
            "pending_count": len(stale_proposed),
            "pending_interaction_ids": [i.get("id") for i in stale_proposed[:10]],
            "pending_contacts": names,
            "oldest_created_at": stale_proposed[0].get("created_at"),
        },
    )]


def _compute_leadership_ownership_same_day(report: dict, sections: dict) -> list[dict]:
    """Surface executive-move/ownership-change candidates detected by TODAY's
    scan (RB-2026-09-18, next-sprint Workstream 1).

    executive_move_promotion.py and ownership_promotion.py both run daily in
    morning_pipeline.py but, until this, wrote only to their own pending-
    candidate stores -- nothing in any brief pointed at them, so a genuinely
    material detection (a named CEO change, a confirmed acquisition) was
    invisible unless Todd remembered to run `... pending` himself. This adds
    same-day VISIBILITY only, mirroring the pattern technomic_watchlist_scan.py
    already proved (write today's finds to a dated cache, read via a plain
    `_scan_date == today` check). It does NOT change the confirm-before-mutate
    gate: record_proposal() is still the only path that ever writes to
    baseline_index.json/ecosystem_intelligence.json, and every item below is
    labeled as an unconfirmed, extracted candidate -- never asserted as fact.
    """
    if not _HAS_LEADERSHIP_OWNERSHIP_PROMOTION:
        return []

    items: list[dict] = []
    try:
        exec_candidates = _emp.same_day_candidates()
    except Exception:  # noqa: BLE001
        exec_candidates = []
    try:
        owner_candidates = _ownp.same_day_candidates()
    except Exception:  # noqa: BLE001
        owner_candidates = []

    if exec_candidates:
        lines = []
        for c in exec_candidates:
            who = c.get("proposed_name") or "name not yet extracted"
            title = f" ({c['proposed_title']})" if c.get("proposed_title") else ""
            lines.append(f"{c.get('entity_name', '?')}: {who}{title}")
        items.append(_canonical_item(
            title=f"Leadership change candidates detected today — {len(exec_candidates)} unconfirmed",
            summary=(
                f"{len(exec_candidates)} possible executive-move signal(s) detected today, "
                f"pending review: {'; '.join(lines)}."
            ),
            why_it_matters=(
                "These are regex-extracted candidates, not verified facts -- nothing has been "
                "written to baseline_index.json. Left unreviewed, RB's contact records silently "
                "stay stale even though a change was actually detected today."
            ),
            recommended_action=(
                "Review via `python3 executive_move_promotion.py pending`, then confirm or reject each."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            confidence="medium",
            source_refs=["executive_move_promotion"],
            extras={"candidate_ids": [c.get("candidate_id") for c in exec_candidates]},
        ))

    if owner_candidates:
        lines = []
        for c in owner_candidates:
            owner = c.get("proposed_owner_name") or "owner not yet extracted"
            lines.append(f"{c.get('entity_name', '?')}: {owner}")
        items.append(_canonical_item(
            title=f"Ownership change candidates detected today — {len(owner_candidates)} unconfirmed",
            summary=(
                f"{len(owner_candidates)} possible ownership-change signal(s) detected today, "
                f"pending review: {'; '.join(lines)}."
            ),
            why_it_matters=(
                "These are regex-extracted candidates, not verified facts -- nothing has been "
                "written to ecosystem_intelligence.json. Left unreviewed, an entity's owner field "
                "stays blank/stale even though a change was actually detected today."
            ),
            recommended_action=(
                "Review via `python3 ownership_promotion.py pending`, then confirm or reject each."
            ),
            disposition="act_today",
            grounding="system_detected",
            freshness="fresh",
            confidence="medium",
            source_refs=["ownership_promotion"],
            extras={"candidate_ids": [c.get("candidate_id") for c in owner_candidates]},
        ))

    return items


_REVIEW_QUEUE_STALE_DAYS = 3


def _parse_review_queue_timestamp(value: str | None) -> "datetime | None":
    """Both `datetime.now(timezone.utc).isoformat(timespec='seconds')`
    ("...+00:00") and `strftime('%Y-%m-%dT%H:%M:%SZ')` ("...Z") are in live
    use across the six promotion scripts' `_now_iso()` helpers -- Python
    3.9's `datetime.fromisoformat()` (this project's runtime) does not
    accept a trailing "Z" directly, only gaining that in 3.11. Normalize
    both to one format rather than assuming either is stale/wrong."""
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (ValueError, AttributeError):
        return None


def _compute_review_queue_backlog(report: dict, sections: dict) -> list[dict]:
    """Strategic-assessment Finding 2 (2026-09-19): six independent review-
    first promotion scanners (tech_stack_relationship_promotion.py,
    watchlist_promotion.py, priority_account_publisher_scan.py,
    ownership_promotion.py, executive_move_promotion.py,
    job_postings_promotion.py) all share one proven scan/pending_candidates/
    record_proposal shape -- that part was never the gap. The gap was
    visibility: as of yesterday's work only executive-move/ownership got
    ANY brief surface, and only for same-day-fresh detections (see
    _compute_leadership_ownership_same_day above) -- the other four queues,
    and any BACKLOG in all six, were reachable only by running each
    script's own `... pending` CLI by hand. This answers "how many things
    are waiting on my confirm right now, across every queue, and how old is
    the oldest one" -- the exact question a Chief of Staff exists to answer
    unprompted -- by aggregating data every one of these scripts already
    computes, not by detecting anything new."""
    queues: list[tuple[object, str]] = []
    if _HAS_TECH_STACK_RELATIONSHIP_PROMOTION:
        queues.append((_tsrp, "tech-stack relationship"))
    if _HAS_WATCHLIST_PROMOTION:
        queues.append((_wlp, "watchlist promotion"))
    if _HAS_PRIORITY_ACCOUNT_PUBLISHER_SCAN:
        queues.append((_paps, "priority-account publisher match"))
    if _HAS_LEADERSHIP_OWNERSHIP_PROMOTION:
        queues.append((_ownp, "ownership change"))
        queues.append((_emp, "executive move"))
    if _HAS_JOB_POSTINGS_PROMOTION:
        queues.append((_jpp, "job posting"))

    total = 0
    per_queue_summaries: list[str] = []
    oldest_dt = None
    oldest_label = None
    now = datetime.now(timezone.utc)
    for module, label in queues:
        try:
            candidates = module.pending_candidates()
        except Exception:  # noqa: BLE001
            continue
        if not candidates:
            continue
        total += len(candidates)
        per_queue_summaries.append(f"{len(candidates)} {label}")
        for cand in candidates:
            dt = _parse_review_queue_timestamp(cand.get("detected_at"))
            if dt is not None and (oldest_dt is None or dt < oldest_dt):
                oldest_dt = dt
                oldest_label = label

    if total == 0:
        return [_canonical_item(
            title="Review-queue backlog — nothing pending",
            summary="No candidates awaiting confirm across any of the 6 review-first promotion queues.",
            disposition="ignore",
            grounding="system_detected",
            freshness="fresh",
            confidence="high",
            source_refs=["review_queue_backlog"],
        )]

    oldest_days = (now - oldest_dt).days if oldest_dt is not None else 0
    stale = oldest_days >= _REVIEW_QUEUE_STALE_DAYS
    oldest_clause = f" Oldest is a {oldest_label} candidate, detected {oldest_days} day(s) ago." if oldest_dt is not None else ""
    return [_canonical_item(
        title=f"Review-queue backlog — {total} item(s) across {len(per_queue_summaries)} queue(s)",
        summary=f"{total} candidate(s) awaiting confirm/reject: {', '.join(per_queue_summaries)}.{oldest_clause}",
        why_it_matters=(
            "These are review-first candidates from independent promotion scanners -- none "
            "become real data until confirmed, and nothing else in the brief surfaces this "
            "backlog; each queue is otherwise visible only via its own `... pending` CLI."
        ),
        recommended_action="Review and confirm/reject via each script's own `... pending`/`confirm`/`reject` CLI.",
        disposition="act_today" if stale else "monitor",
        grounding="system_detected",
        freshness="stale" if stale else "fresh",
        confidence="high",
        source_refs=["review_queue_backlog"],
        extras={"total_pending": total, "per_queue": per_queue_summaries, "oldest_days": oldest_days},
    )]


def _compute_what_changed(report: dict, sections: dict) -> list[dict]:
    """Build the delta layer: what changed since the last published brief.

    Compares today's state against latest_brief.json across:
    - Thread/opportunity state transitions (opened, closed, rejected, won)
    - New loops opened or closed since last brief
    - New intelligence items (new_intelligence_today section)
    - Relationship signals not present yesterday
    - Watchlist status changes

    Returns one canonical item per change category, or a single 'no change'
    item if nothing material shifted.
    """
    published_dir = core.SYSTEM_DIR / "published"
    latest_path = published_dir / "daily" / "latest_brief.json"
    changes: list[dict] = []

    if not latest_path.exists():
        return [_canonical_item(
            title="No prior brief available for delta comparison",
            summary="This appears to be the first brief cycle. No yesterday-vs-today delta available.",
            why_it_matters="Delta comparison requires at least two brief cycles.",
            recommended_action="Run tomorrow for a full delta view.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["published/daily/latest_brief.json"],
            confidence="high",
        )]

    try:
        prior = json.loads(latest_path.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return []

    prior_sections = (prior.get("canonical_brief") or {}).get("sections") or {}

    # ── 1. Thread state changes ───────────────────────────────────────────────
    try:
        active_threads_path = core.SYSTEM_DIR / "active_threads.yaml"
        import yaml as _yaml  # type: ignore
        _raw_threads = _yaml.safe_load(active_threads_path.read_text()) or []
        if isinstance(_raw_threads, dict):
            today_threads = _raw_threads.get("threads") or []
        else:
            today_threads = _raw_threads if isinstance(_raw_threads, list) else []

        # D2 FIX (RB-DEFECT-002): Use close_date / opened timestamps to gate deltas
        # to the actual delta window. Never diff against prior brief's section
        # membership — that produces false positives for threads that predate the cycle.
        delta_cutoff = yesterday  # anything on or after this date counts as "today"

        closed_today: list[str] = []
        new_today: list[str] = []
        for t in today_threads:
            status = t.get("status", "open")
            title = t.get("title", t.get("id", "?"))

            # Thread closed within the delta window (has close_date field)
            close_date_str = t.get("close_date") or ""
            if status == "closed" and close_date_str:
                try:
                    cd = date.fromisoformat(str(close_date_str))
                    if cd >= delta_cutoff:
                        closed_today.append(title)
                except ValueError:
                    pass

            # Thread opened within the delta window (has opened field)
            opened_str = t.get("opened") or ""
            if status == "open" and opened_str:
                try:
                    od = date.fromisoformat(str(opened_str))
                    if od >= delta_cutoff:
                        new_today.append(title)
                except ValueError:
                    pass
    except Exception:  # noqa: BLE001
        closed_today, new_today = [], []

    # ── 2. Loops opened/closed since last brief ───────────────────────────────
    today_dt = date.today()
    yesterday = today_dt - timedelta(days=1)
    try:
        all_loops = core.parse_loop_ledger()
        loops_opened_today = [lp for lp in all_loops if not lp.closed and lp.opened >= yesterday]
        loops_closed_today = [lp for lp in all_loops if lp.closed and lp.target >= yesterday]
    except Exception:  # noqa: BLE001
        loops_opened_today, loops_closed_today = [], []

    # ── 3. New intelligence items ─────────────────────────────────────────────
    new_intel = sections.get("new_intelligence_today") or []
    reactivated = sections.get("reactivated_intelligence") or []

    # ── 4. Watchlist status changes ───────────────────────────────────────────
    wl_changed = [
        item for item in (sections.get("watchlist_intelligence") or [])
        if (item.get("extras") or {}).get("status_changed")
    ]

    # ── Build items ───────────────────────────────────────────────────────────
    all_empty = (
        not closed_today and not new_today and
        not loops_opened_today and not loops_closed_today and
        not new_intel and not reactivated and not wl_changed
    )

    if all_empty:
        return [_canonical_item(
            title="No material changes since last brief",
            summary=(
                "Opportunity threads, loops, relationship signals, and watchlist "
                "entities are unchanged from the prior brief cycle."
            ),
            why_it_matters="Clean delta confirms current state is stable.",
            recommended_action="Proceed from current state — no catch-up required.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["published/daily/latest_brief.json"],
            confidence="medium",
        )]

    if closed_today or new_today:
        parts = []
        if closed_today:
            parts.append(
                f"CLOSED: {', '.join(closed_today[:4])}{'…' if len(closed_today) > 4 else ''}."
            )
        if new_today:
            parts.append(
                f"OPENED: {', '.join(new_today[:3])}{'…' if len(new_today) > 3 else ''}."
            )
        changes.append(_canonical_item(
            title=f"Opportunity/thread state: {len(closed_today)} closed, {len(new_today)} new",
            summary=" ".join(parts),
            why_it_matters="Thread state changes are the most important delta — they shift active priorities.",
            recommended_action=(
                "Review closed threads to confirm state is accurately recorded. "
                "New threads require attention."
            ),
            disposition="act_today" if new_today else "monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["active_threads.yaml"],
            confidence="high",
            extras={"closed": closed_today, "opened": new_today},
        ))

    if loops_opened_today or loops_closed_today:
        parts = []
        if loops_opened_today:
            names = [f"{lp.id}/{lp.party}" for lp in loops_opened_today[:3]]
            parts.append(f"OPENED: {', '.join(names)}.")
        if loops_closed_today:
            names = [f"{lp.id}/{lp.party}" for lp in loops_closed_today[:3]]
            parts.append(f"CLOSED: {', '.join(names)}.")
        changes.append(_canonical_item(
            title=f"Loops: {len(loops_opened_today)} opened, {len(loops_closed_today)} closed",
            summary=" ".join(parts),
            why_it_matters="Loop activity is direct evidence of follow-through execution.",
            recommended_action="Verify closed loops are complete. Review new loops for next action.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["loop_ledger"],
            confidence="high",
        ))

    if new_intel or reactivated:
        parts = []
        if new_intel:
            titles = [i.get("title", "?")[:50] for i in new_intel[:3]]
            parts.append(f"NEW: {'; '.join(titles)}{'…' if len(new_intel) > 3 else ''}.")
        if reactivated:
            titles = [i.get("title", "?")[:50] for i in reactivated[:2]]
            parts.append(f"REACTIVATED: {'; '.join(titles)}.")
        changes.append(_canonical_item(
            title=f"Intelligence: {len(new_intel)} new items, {len(reactivated)} reactivated",
            summary=" ".join(parts),
            why_it_matters="New intelligence items represent genuine first observations this cycle.",
            recommended_action="Review new_intelligence_today for required follow-up.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["new_intelligence_today"],
            confidence="high",
        ))

    if wl_changed:
        names = [(item.get("extras") or {}).get("entity_name", "?") for item in wl_changed[:3]]
        changes.append(_canonical_item(
            title=f"Watchlist: {len(wl_changed)} entity status change(s)",
            summary=f"Status changed for: {', '.join(names)}{'…' if len(wl_changed) > 3 else ''}. See watchlist_intelligence for detail.",
            why_it_matters="Watchlist status changes signal meaningful activity on monitored entities.",
            recommended_action="Review watchlist_intelligence for entity-level detail.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["watchlist_intelligence"],
            confidence="medium",
        ))

    # ── D7: Outbound communication closure signals ────────────────────────────
    # Scan sent email files for signals that an opportunity was closed or a
    # relationship was touched. These are first-party signals that the mutation
    # engine may have missed if the user didn't explicitly call ingestContent.
    outbound_signals = _scan_outbound_for_closure_signals(delta_cutoff)
    changes.extend(outbound_signals)

    return changes


def _scan_outbound_for_closure_signals(since: "date") -> list[dict]:
    """D7 — Scan sent email/SMS for outbound closure or touch signals.

    Looks at email_sent.*.json files for messages dated within the delta window
    that contain keywords indicating: opportunity closure, offer acceptance/decline,
    relationship touch to a known contact.

    Returns canonical items for each signal found.
    """
    import re as _re_d7
    results: list[dict] = []

    _CLOSURE_PATTERNS = [
        (r"\b(declining|not moving forward|passing on|withdrawing)\b", "opportunity_decline_signal"),
        (r"\b(accepting|accepted|excited to join|looking forward to starting)\b", "opportunity_accept_signal"),
        (r"\b(thank you for the opportunity|appreciate the consideration)\b", "outbound_closure_courtesy"),
    ]
    _TOUCH_PATTERNS = [
        (r"\b(following up|circling back|checking in|reaching out|wanted to connect)\b", "outbound_touch"),
    ]

    sent_files = [
        core.SYSTEM_DIR / "inbox" / "email_sent.personal.json",
        core.SYSTEM_DIR / "inbox" / "email_sent.bridgepoint.json",
    ]

    for sent_path in sent_files:
        if not sent_path.exists():
            continue
        try:
            messages = json.loads(sent_path.read_text(encoding="utf-8"))
            if isinstance(messages, dict):
                messages = messages.get("messages", messages.get("emails", []))
            for msg in (messages or []):
                # Date gate: only messages within the delta window
                msg_date_str = msg.get("date") or msg.get("sent_at") or msg.get("timestamp") or ""
                if msg_date_str:
                    try:
                        msg_date = date.fromisoformat(str(msg_date_str)[:10])
                        if msg_date < since:
                            continue
                    except ValueError:
                        continue
                else:
                    continue  # No timestamp → can't gate → skip (D2 principle)

                body_text = (msg.get("body") or msg.get("content") or msg.get("text") or "").lower()
                subject = (msg.get("subject") or "").lower()
                combined = f"{subject} {body_text}"

                for pattern, signal_type in _CLOSURE_PATTERNS + _TOUCH_PATTERNS:
                    if _re_d7.search(pattern, combined):
                        recipient = (
                            msg.get("to") or msg.get("recipient") or
                            (msg.get("recipients") or ["unknown"])[0]
                            if isinstance(msg.get("recipients"), list) else "unknown"
                        )
                        results.append(_canonical_item(
                            title=f"Outbound signal: {signal_type} detected",
                            summary=(
                                f"Sent email to {recipient} on {msg_date_str[:10]} "
                                f"contains {signal_type} language. Subject: {msg.get('subject', '(no subject)')[:60]}. "
                                "State mutation may be required — verify with ingestExecutiveDeclaration."
                            ),
                            why_it_matters=(
                                "Outbound closure signals in sent email indicate opportunity or "
                                "relationship state changes that must be registered in canonical state."
                            ),
                            recommended_action=(
                                "Confirm state mutation via ingestExecutiveDeclaration if this "
                                "represents a definitive state change."
                            ),
                            disposition="ask_todd",
                            grounding="system_detected",
                            freshness="fresh",
                            source_refs=[str(sent_path.name)],
                            confidence="medium",
                            extras={
                                "signal_type": signal_type,
                                "sent_date": msg_date_str[:10],
                                "recipient": str(recipient)[:100],
                                "subject": msg.get("subject", "")[:100],
                                "source_file": sent_path.name,
                            },
                        ))
                        break  # one signal per message is enough
        except Exception:  # noqa: BLE001
            pass

    return results


def _compute_newsletter_intelligence(_report: dict, _sections: dict) -> list[dict]:
    """Build one canonical item per newsletter edition that has extractable articles.

    Reads email threads that have `body_text` (fetched by fetch_google.py second pass),
    extracts article titles + URLs from the HTML, and returns them as brief items.
    Each item represents one newsletter edition: source name, date, article list.
    This proves the CoS is reading the inbox and surfaces what you haven't had time
    to read.
    """
    from datetime import datetime as _dt, timezone as _tz, timedelta as _td
    try:
        from passive_email_intelligence import _extract_body_articles, _extract_newsletter_summary, _source_name
    except ImportError:
        return []

    # Junk anchor patterns that indicate navigation/promo links, not articles
    _JUNK_STARTS = (
        "please ", "email me", "add us", "switch to", "this on-demand",
        "this week", "connect with", "and privacy", "step down",
        "watch the video", "this comparison", "a cstore", "explore the",
        "join ", "register ", "sign up", "subscribe",
    )

    def _is_real_article(title: str) -> bool:
        t = title.strip().lower()
        if any(t.startswith(s) for s in _JUNK_STARTS):
            return False
        if len(t) < 20:
            return False
        return True

    # Job-alert bots (LinkedIn's "Confidential Careers", generic jobs
    # digests) aren't newsletters — but broadening NEWSLETTER_DOMAINS to
    # linkedin.com (for genuine editorial digests like a contact's
    # "Hospitality Headline") also grants these full-body fetch, so they
    # now qualify as newsletter candidates on source name alone. Same
    # muting concept as _MUTED_EMAIL_SENDERS in render_intelligence_brief.py
    # (job alerts are muted there now that the job search is closed), applied
    # here at the source so they never reach the newsletter pool at all.
    _JOB_ALERT_SENDERS = (
        "confidential careers", "linkedin job", "jobs alert", "job alert",
        "new jobs update", "new europe jobs", "jobs update",
    )

    def _is_job_alert_sender(source: str, thread: dict) -> bool:
        sender_name = ((thread.get("last_message_from") or {}).get("name") or "").lower()
        s = source.lower()
        return any(p in s or p in sender_name for p in _JOB_ALERT_SENDERS)

    def _resolve_source(thread: dict) -> str:
        src = _source_name(thread)
        if src and src != "Industry email source":
            return src
        # Fallback: use sender name, cleaned up
        sender = (thread.get("last_message_from") or {})
        name = sender.get("name") or ""
        if name and len(name) > 2:
            # Strip common newsletter suffixes
            for suffix in (" Newsletter", " Daily", " Weekly", " Alerts", " News"):
                name = name.replace(suffix, "")
            return name.strip()
        # Last resort: domain from sender email
        email_addr = sender.get("email") or ""
        domain = email_addr.split("@")[-1].split(".")[0].capitalize() if "@" in email_addr else ""
        return domain or "Newsletter"

    _today = date.today()
    _cutoff = _dt(_today.year, _today.month, _today.day, tzinfo=_tz.utc) - _td(days=3)
    items: list[dict] = []
    _seen_keys: set[str] = set()  # deduplicate by (source, date)

    for acct in ("personal", "bridgepoint"):
        ep = core.email_path_for(acct) if hasattr(core, "email_path_for") else None
        if not ep or not ep.exists():
            continue
        try:
            data = json.loads(ep.read_text(encoding="utf-8"))
        except Exception:
            continue

        for thread in data.get("threads") or []:
            body = thread.get("body_text")
            if not body:
                continue

            # Skip if older than lookback window
            lma = thread.get("last_message_at") or ""
            try:
                from email.utils import parsedate_to_datetime as _pdt
                ts = _pdt(lma).astimezone(_tz.utc) if "," in lma else _dt.fromisoformat(lma.replace("Z", "+00:00"))
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=_tz.utc)
                if ts < _cutoff:
                    continue
                pub_date = ts.strftime("%b %d, %Y")
            except Exception:
                pub_date = lma[:10] if lma else "unknown"

            source = _resolve_source(thread)
            if _is_job_alert_sender(source, thread):
                continue
            articles = _extract_body_articles(body)
            # Filter junk anchors (CTAs, unsubscribe links, nav items)
            articles = [a for a in articles if _is_real_article(a.get("title", ""))]
            body_summary = _extract_newsletter_summary(body)
            # An essay-format newsletter (e.g. a LinkedIn "Top of the Fold"
            # personal write-up) can have zero real article links once the
            # masthead/CTA/author-profile junk is filtered out, but still have
            # genuine substance via body_summary — dropping the whole edition
            # for lacking a link list would throw away the one thing (the
            # summary) that made it worth reading in the first place.
            if not articles and not body_summary:
                continue

            # Deduplicate same newsletter edition across personal/bridgepoint accounts
            dedup_key = f"{source}|{pub_date}"
            if dedup_key in _seen_keys:
                continue
            _seen_keys.add(dedup_key)

            thread_id = thread.get("thread_id")
            email_permalink = (
                f"https://mail.google.com/mail/u/0/#all/{thread_id}"
                if thread_id else None
            )

            items.append(_canonical_item(
                title=f"{source} — {pub_date}",
                summary=f"{len(articles)} articles extracted from newsletter",
                why_it_matters=f"Industry newsletter with {len(articles)} articles not yet read.",
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[email_permalink or source],
                confidence="high",
                extras={
                    "source_name": source,
                    "pub_date": pub_date,
                    "article_count": len(articles),
                    "articles": articles[:15],
                    "body_summary": body_summary,
                    "email_permalink": email_permalink,
                    "account": acct,
                },
            ))

    # Sort by article count desc (most content first)
    items.sort(key=lambda i: i.get("extras", {}).get("article_count", 0), reverse=True)
    return items


def _compute_identity_match_candidates(_report: dict, _sections: dict) -> list[dict]:
    """Surface baseline<->inbound-email identity matches awaiting confirmation.

    Most baseline contacts have no email on file (LinkedIn imports don't expose
    email addresses). identity_match_review.py proposes exact-name matches
    between inbound email senders and email-less baseline contacts, but never
    auto-merges — the operator must confirm each one. This surfaces the
    pending queue so it isn't silently sitting in a cache file no one reads.
    """
    try:
        from identity_match_review import pending_candidates
    except ImportError:
        return []

    items: list[dict] = []
    try:
        for cand in pending_candidates():
            items.append(_canonical_item(
                title=f"Identity match: \"{cand.get('sender_name')}\" — {cand.get('baseline_name')}?",
                summary=(
                    f"Inbound email from {cand.get('sender_email')} (subject: "
                    f"\"{cand.get('thread_subject') or ''}\") matches baseline contact "
                    f"{cand.get('baseline_name')} ({cand.get('baseline_company') or 'no company on file'}) "
                    f"by name, but that contact has no email on file yet."
                ),
                why_it_matters=(
                    "Confirming links this correspondence to the contact's relationship history. "
                    "Never auto-merged — confirm only if you're sure it's the same person."
                ),
                recommended_action=f"Confirm or reject: {cand.get('id')}",
                disposition="ask_todd",
                grounding="system_detected",
                freshness="fresh",
                source_refs=[f"email.{cand.get('account')}.json", cand.get("thread_id") or ""],
                confidence="medium",
                extras={
                    "candidate_id": cand.get("id"),
                    "baseline_id": cand.get("baseline_id"),
                    "baseline_name": cand.get("baseline_name"),
                    "sender_name": cand.get("sender_name"),
                    "sender_email": cand.get("sender_email"),
                    "first_seen": cand.get("first_seen"),
                },
            ))
    except Exception:  # noqa: BLE001
        return []
    return items


def _compute_personal_intelligence_delta(_report: dict, _sections: dict) -> list[dict]:
    """Surface what the personal intelligence system actually saw in the last 24 hours.

    Reads raw personal data files — email threads, SMS events, opportunity history,
    calendar events — and produces factual delta items. These are the items that
    prove the system is a persistent intelligence layer, not a news aggregator.

    Returns one canonical item per personal data source that had activity.
    """
    from datetime import datetime as _dt, timezone as _tz, timedelta as _td

    _today = date.today()
    _cutoff = _dt(_today.year, _today.month, _today.day, tzinfo=_tz.utc) - _td(hours=36)
    items: list[dict] = []

    # ── 0. Career lifecycle transition detection ──────────────────────────────
    # When an offer is accepted and the job search closes, surface a synthesis
    # item so Part 1 proves the system knows the user's operating mode changed.
    try:
        ctx_path = core.SYSTEM_DIR / "profiles" / "todd_vahlsing" / "opportunity_context.yaml"
        if ctx_path.exists():
            import yaml as _yaml
            ctx = _yaml.safe_load(ctx_path.read_text(encoding="utf-8")) or {}
            career_phase = ctx.get("career_phase") or ""
            job_search_active = ctx.get("job_search_active", True)
            if not job_search_active and career_phase:
                # Find the accepted opportunity for context
                accepted_co = None
                accepted_role = None
                accepted_date = None
                opp_path = core.SYSTEM_DIR / "tracked_opportunities.json"
                if opp_path.exists():
                    opp_data = json.loads(opp_path.read_text(encoding="utf-8"))
                    for opp in opp_data.get("opportunities", []):
                        if opp.get("stage") == "offer_accepted":
                            accepted_co = opp.get("company") or opp.get("id")
                            accepted_role = opp.get("role") or ""
                            for kd in (opp.get("key_dates") or []):
                                if kd.get("event") == "offer_accepted":
                                    accepted_date = kd.get("date")
                phase_label = career_phase.replace("_", " ").title()
                title_parts = [f"Career phase: {phase_label}"]
                if accepted_co:
                    title_parts = [f"Career phase: {phase_label} — {accepted_co}"]
                summary_lines = [
                    "Job search closed. Active candidate pipeline suppressed.",
                    f"Accepted: {accepted_co} / {accepted_role}" if accepted_co else "",
                    "Operating mode: enterprise execution, not job-search management.",
                    "Workstreams shifting to: account mapping, stakeholder onboarding, territory planning.",
                ]
                summary = " ".join(s for s in summary_lines if s)
                items.append(_canonical_item(
                    title=" | ".join(title_parts),
                    summary=summary,
                    why_it_matters=(
                        "Major state transition: job search ended, onboarding phase active. "
                        "CoS operating cadence, priorities, and information needs have changed."
                    ),
                    disposition="act_today",
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["opportunity_context.yaml", "tracked_opportunities.json"],
                    confidence="high",
                    extras={
                        "delta_source": "lifecycle_transition",
                        "career_phase": career_phase,
                        "accepted_company": accepted_co,
                        "accepted_role": accepted_role,
                        "accepted_date": accepted_date,
                        "job_search_active": False,
                        "transition_implications": [
                            "Resume optimization work: STOP",
                            "Interview preparation: STOP",
                            "Competing opportunity pursuit: STOP",
                            "Enterprise account map: BEGIN",
                            "Internal stakeholder map: BEGIN",
                            "First-90-day operating system: BEGIN",
                            "RB migration into new employer ecosystem: BEGIN",
                        ],
                    },
                ))
    except Exception:
        pass

    # ── 1. Opportunity mutations (executive declarations) ─────────────────────
    try:
        opp_path = core.SYSTEM_DIR / "tracked_opportunities.json"
        if opp_path.exists():
            opp_data = json.loads(opp_path.read_text(encoding="utf-8"))
            recent_mutations: list[str] = []
            for opp in opp_data.get("opportunities", []):
                opp_name = opp.get("company") or opp.get("id") or "unknown"
                for h in opp.get("history") or []:
                    h_date = h.get("date") or ""
                    if h_date and h_date >= (_today - timedelta(days=7)).isoformat():
                        src = h.get("source_type", "")
                        stage = h.get("stage", "")
                        if src == "executive_declaration" or stage:
                            label = stage.replace("_", " ").upper() if stage else src.upper()
                            recent_mutations.append(f"{label}: {opp_name}")
            if recent_mutations:
                items.append(_canonical_item(
                    title=f"Opportunity mutations declared: {len(recent_mutations)}",
                    summary=" | ".join(recent_mutations[:5]),
                    why_it_matters="CEO declarations auto-mutated opportunity state. Verify stage matches your intent.",
                    disposition="act_today",
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["tracked_opportunities.json"],
                    confidence="high",
                    extras={"mutation_count": len(recent_mutations),
                            "mutations": recent_mutations[:10],
                            "delta_source": "tracked_opportunities"},
                ))
    except Exception:
        pass

    # ── 2. Email delta — new or updated threads since yesterday ───────────────
    # RB-DEFECT: this used to sample the first 4 threads in raw file order, so
    # a LinkedIn marketing blast or retail promo could represent 42 real
    # threads while a genuine networking-opportunity email sat unseen further
    # down the list. Now ranks candidates by business/personal relevance
    # before sampling, and drops pure retail marketing (CATEGORY_PROMOTIONS,
    # or a known-retail sender) from the sample entirely — it still counts
    # toward the total but can never displace something worth reading.
    _RETAIL_NOISE_SENDERS = [
        "kohl's", "kohls", "old navy", "gap ", "banana republic", "macy's",
        "macys", "target ", "walmart", "amazon deals", "bed bath", "ihop",
        "turbotax", "groupon", "wayfair", "overstock", "chase offers",
    ]
    # RB-DEFECT-2026-07-10: generic administrative keywords below ("confirm",
    # "urgent", "action required", "deadline") fire on ANY appointment/admin
    # email, not just genuine business context — a health-care visit
    # confirmation ("Todd, confirm your visit...") or a church service
    # reminder can score as "business relevant" purely on word overlap, with
    # nothing to outrank it if real business threads don't happen to contain
    # any of these words. Church/religious and health-care content is
    # suppressed from the sample outright (same pattern as retail noise
    # below) regardless of keyword score, since it can never be genuine
    # RB-relevant business intelligence.
    _PERSONAL_LIFE_NOISE_RE = re.compile(
        r"\b(church|ministries?|ministry|worship|sermon|devotional|"
        r"bible study|prayer|praises?|pastor|reverend|parish|diocese|"
        r"congregation|"
        r"health ?care|clinic|hospital|medical center|physician|"
        r"dentist|pediatric|orthodon|urgent care|patient portal|"
        r"your visit|appointment reminder)\b",
        re.IGNORECASE,
    )
    _BUSINESS_RELEVANCE_KEYWORDS = [
        "opportunity", "introduc", "interview", "proposal", "contract",
        "networking", "referral", "advisor", "board seat", "invest",
        "partnership", "acquisition", "role", "position", "offer letter",
        "schedule a call", "connect you with", "reference call",
        "follow up", "following up", "meeting request", "invoice",
        "deadline", "urgent", "action required", "please respond", "confirm",
    ]
    try:
        import personal_relationship_guard as _personal_guard

        candidates: list[dict] = []
        for acct in ("personal", "bridgepoint"):
            ep = core.email_path_for(acct) if hasattr(core, "email_path_for") else None
            if not ep or not ep.exists():
                continue
            data = json.loads(ep.read_text(encoding="utf-8"))
            for t in data.get("threads") or []:
                lma = t.get("last_message_at") or ""
                if not lma:
                    continue
                # Parse RFC 2822 / ISO dates
                try:
                    from email.utils import parsedate_to_datetime as _pdt
                    ts = _pdt(lma).astimezone(_tz.utc) if "," in lma else _dt.fromisoformat(lma.replace("Z", "+00:00"))
                    if ts.tzinfo is None:
                        ts = ts.replace(tzinfo=_tz.utc)
                    if ts < _cutoff:
                        continue
                except Exception:
                    continue

                subj = html.unescape((t.get("subject") or "(no subject)")[:50])
                sender = (t.get("last_message_from") or {})
                sender_name = html.unescape(sender.get("name") or sender.get("email") or "unknown")
                labels = set(t.get("labels") or [])
                text_check_raw = f"{subj} {t.get('snippet') or ''} {sender_name}"
                text_check = text_check_raw.lower()
                if _personal_guard.classify(
                    sender_name=sender_name,
                    sender_email=sender.get("email") or "",
                    text=text_check_raw,
                ).is_personal:
                    continue

                is_promo = "CATEGORY_PROMOTIONS" in labels or any(
                    p in text_check for p in _RETAIL_NOISE_SENDERS
                )
                is_personal_life = bool(_PERSONAL_LIFE_NOISE_RE.search(text_check))
                score = 0
                # NOTE: Gmail's CATEGORY_PERSONAL label means "landed in the
                # Primary inbox tab," not "personally relevant to business" —
                # it does not contribute to business-relevance score (see
                # _correspondence_label's docstring below for the same point).
                if "UNREAD" in labels:
                    score += 1
                if any(k in text_check for k in _BUSINESS_RELEVANCE_KEYWORDS):
                    score += 3

                candidates.append({
                    "line": f"{subj} — {sender_name}",
                    "score": score,
                    "is_promo": is_promo,
                    "is_personal_life": is_personal_life,
                    "ts": ts,
                })

        if candidates:
            total = len(candidates)
            ranked = sorted(
                (c for c in candidates if not c["is_promo"] and not c["is_personal_life"]),
                key=lambda c: (-c["score"], -c["ts"].timestamp()),
            )
            sample = [c["line"] for c in ranked[:4]]
            summary = "; ".join(sample) if sample else "(no business-relevant threads — remainder were promotional/personal/marketing)"
            if total > len(sample) and sample:
                summary += "…"

            items.append(_canonical_item(
                title=f"Email activity: {total} threads updated",
                summary=summary,
                why_it_matters="Recent email threads may contain open loops or relationship signals.",
                disposition="monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["email.personal.json", "email.bridgepoint.json"],
                confidence="high",
                extras={"thread_count": total,
                        "threads": [c["line"] for c in ranked[:10]],
                        "delta_source": "email"},
            ))
    except Exception:
        pass

    # ── 2b. High-priority personal correspondence (e.g. introductions) ────────
    # The generic "Email activity" delta above just samples the first few
    # threads in file order, so a single important inbound email can get
    # buried under routine/newsletter traffic. Gmail's own CATEGORY_PERSONAL +
    # IMPORTANT labels (present on genuine 1:1 correspondence, not bulk mail
    # or newsletters) are a reliable low-noise signal to surface separately —
    # missed a real intro email (David Drinan -> Sam Zats) this way before.
    try:
        _intro_re = re.compile(r"\bintroduc", re.IGNORECASE)
        # Automated/transactional mail (password resets, account verification) can
        # still land in Gmail's CATEGORY_PERSONAL + IMPORTANT buckets — exclude it
        # so it doesn't crowd out genuine 1:1 correspondence.
        _automated_sender_re = re.compile(
            r"\b(no-?reply|do-?not-?reply|notifications?|automated)\b", re.IGNORECASE
        )
        _transactional_subject_re = re.compile(
            r"reset your password|create your password|verify your (?:email|account)|"
            r"confirm your (?:email|account)|password reset|account verification",
            re.IGNORECASE,
        )
        # RB-DEFECT-2026-07-08: a calendar/meeting-invite forward (Teams/Zoom/
        # Meet "You are invited to a meeting, click here to join") carries zero
        # informational content, but a personal contact sending one still
        # landed in CATEGORY_PERSONAL + IMPORTANT and got surfaced as "genuine
        # 1:1 correspondence" worth reviewing. It's calendar logistics, not
        # correspondence — exclude it outright regardless of sender.
        _meeting_invite_re = re.compile(
            r"you (?:are|have been) invited to a (?:zoom|teams|google meet|microsoft teams) meeting|"
            r"click here to join|this event has been (?:updated|cancelled|canceled)|"
            r"invitation: .* @ ",
            re.IGNORECASE,
        )

        # RB-DEFECT-2026-07-08: Gmail's CATEGORY_PERSONAL label means "landed
        # in the Primary inbox tab" — it does NOT mean "personal in the human
        # sense." Sending baseline contacts who are networking/business
        # relationships (a startup CEO pitching a funding round, a colleague
        # at the user's own employer) were rendered as "Personal
        # correspondence" / "genuine 1:1 correspondence," which misrepresents
        # both the content and the relationship. Look the sender up against
        # the baseline to relabel by actual relationship context.
        _baseline_for_correspondence = core.load_baseline()
        _email_idx_for_correspondence = core._build_email_index(_baseline_for_correspondence)
        _name_idx_for_correspondence: dict[str, dict] = {}
        for _bentry in _baseline_for_correspondence:
            _bkey = re.sub(r"\s+", " ", re.sub(r"[.,]", "", (_bentry.get("name") or "").strip().lower()))
            if _bkey and _bkey not in _name_idx_for_correspondence:
                _name_idx_for_correspondence[_bkey] = _bentry
        try:
            _employer_id = compliance_engine.active_primary_employer_id()
            _employer_profile = compliance_engine.load_employer_profile(_employer_id) if _employer_id else None
            _employer_tokens = [
                t.strip().lower() for t in (_employer_profile or {}).get("company", "").split("/") if t.strip()
            ]
        except Exception:
            _employer_tokens = []

        def _correspondence_label(sender_email: str, sender_name: str) -> tuple[str, str]:
            """Return (label, why_it_matters) based on the sender's baseline
            relationship context, not just the Gmail category label."""
            match = _email_idx_for_correspondence.get(core._normalize_email(sender_email))
            if not match:
                _nkey = re.sub(r"\s+", " ", re.sub(r"[.,]", "", (sender_name or "").strip().lower()))
                match = _name_idx_for_correspondence.get(_nkey)
            company = ((match or {}).get("current_company") or "").strip()
            if company and _employer_tokens and any(tok in company.lower() for tok in _employer_tokens):
                return (
                    f"Colleague correspondence ({company})",
                    f"{sender_name} is a colleague at {company} per baseline — not personal correspondence.",
                )
            if company:
                return (
                    f"Business correspondence ({company})",
                    f"{sender_name} ({(match or {}).get('current_role') or 'contact'} at {company}) — "
                    "a networking/business relationship, not personal correspondence.",
                )
            # RB-DEFECT-2026-07-23: a baseline match with no current_company
            # on file (e.g. a HubSpot CRM contact ingested before a company
            # field was populated -- confirmed live for Ed Garner, a 2-week
            # active CRM contact with company=null) used to fall through to
            # the generic "Personal correspondence" label below. That label
            # is what render_intelligence_brief.py's suppression check
            # matches on to drop an item from the Intelligence Brief
            # entirely -- so a real, ongoing business email thread ("New
            # Time Proposed: Maps <> Bridgepoint") silently never surfaced.
            # The baseline is a professional-relationship tracker, not a
            # personal address book -- any match at all means this is a
            # known contact, regardless of whether company happens to be
            # populated.
            if match:
                return (
                    "Business correspondence (company unknown)",
                    f"{sender_name} is a known contact in baseline (no company on file) — "
                    "not personal correspondence.",
                )
            return (
                "Personal correspondence",
                "Marked IMPORTANT + CATEGORY_PERSONAL by Gmail — genuine 1:1 correspondence, not bulk mail.",
            )

        for acct in ("personal", "bridgepoint"):
            ep = core.email_path_for(acct) if hasattr(core, "email_path_for") else None
            if not ep or not ep.exists():
                continue
            data = json.loads(ep.read_text(encoding="utf-8"))
            for t in data.get("threads") or []:
                labels = set(t.get("labels") or [])
                if not {"CATEGORY_PERSONAL", "IMPORTANT", "INBOX"} <= labels:
                    continue
                if labels & {"SENT", "TRASH", "SPAM"}:
                    continue
                lma = t.get("last_message_at") or ""
                if not lma:
                    continue
                try:
                    from email.utils import parsedate_to_datetime as _pdt
                    ts = _pdt(lma).astimezone(_tz.utc) if "," in lma else _dt.fromisoformat(lma.replace("Z", "+00:00"))
                    if ts.tzinfo is None:
                        ts = ts.replace(tzinfo=_tz.utc)
                    if ts < _cutoff:
                        continue
                except Exception:
                    continue

                # Gmail snippets/subjects are HTML-sourced and carry literal
                # entities (I&#39;m -> I'm) that were never unescaped before
                # reaching rendered brief text.
                subject = html.unescape(t.get("subject") or "(no subject)")
                sender = t.get("last_message_from") or {}
                sender_name = html.unescape(sender.get("name") or sender.get("email") or "unknown")
                sender_email = sender.get("email") or ""
                if _automated_sender_re.search(sender_email) or _automated_sender_re.search(sender_name):
                    continue
                if _transactional_subject_re.search(subject):
                    continue
                snippet = html.unescape(t.get("snippet") or "")
                if _meeting_invite_re.search(subject) or _meeting_invite_re.search(snippet):
                    continue  # calendar logistics, not correspondence — zero informational content
                is_intro = bool(_intro_re.search(subject)) or bool(_intro_re.search(snippet))

                label, relationship_context = _correspondence_label(sender_email, sender_name)
                if is_intro:
                    title_label = "Introduction"
                    why = relationship_context + " Introduction emails go stale fast; reply or route to a broker."
                else:
                    title_label = label
                    why = relationship_context

                items.append(_canonical_item(
                    title=f"{title_label}: \"{subject[:60]}\" — {sender_name}",
                    summary=snippet[:220],
                    why_it_matters=why,
                    recommended_action="Reply to the introduction" if is_intro else "Review and respond if needed",
                    disposition="act_today",
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=[f"email.{acct}.json", t.get("thread_id") or ""],
                    confidence="high",
                    extras={
                        "delta_source": "personal_correspondence",
                        "account": acct,
                        "thread_id": t.get("thread_id"),
                        "sender_email": sender.get("email"),
                        "is_introduction": is_intro,
                        "correspondence_label": title_label,
                        "labels": sorted(labels),
                    },
                ))
    except Exception:
        pass

    # ── 3. SMS delta — new conversations in last 36h ──────────────────────────
    try:
        msg_path = core.MESSAGES_PATH if hasattr(core, "MESSAGES_PATH") else None
        if msg_path and msg_path.exists():
            msgs_data = json.loads(msg_path.read_text(encoding="utf-8"))
            recent_handles: set[str] = set()
            for ev in msgs_data.get("events") or []:
                at_str = ev.get("at") or ""
                if not at_str:
                    continue
                try:
                    ts = _dt.fromisoformat(at_str.replace("Z", "+00:00"))
                    if ts.tzinfo is None:
                        ts = ts.replace(tzinfo=_tz.utc)
                    if ts >= _cutoff:
                        h = ev.get("handle") or ""
                        if h:
                            recent_handles.add(h)
                except Exception:
                    pass
            if recent_handles:
                items.append(_canonical_item(
                    title=f"SMS activity: {len(recent_handles)} conversations in last 36h",
                    summary=f"{len(recent_handles)} contacts active via SMS.",
                    why_it_matters="Recent SMS conversations may contain relationship signals or open loops.",
                    disposition="monitor",
                    grounding="system_detected",
                    freshness="fresh",
                    source_refs=["messages.json"],
                    confidence="medium",
                    extras={"conversation_count": len(recent_handles),
                            "delta_source": "sms"},
                ))
    except Exception:
        pass

    # ── 4. Calendar — today + tomorrow events ─────────────────────────────────
    try:
        # Use the normalized overlay, not raw per-account files. The overlay
        # removes declined invitations and consolidates calendar semantics;
        # reading raw files here was how SCN resurfaced after being declined.
        cal = _report.get("calendar") or {}
        today_events = list(dict.fromkeys(
            (ev.get("title") or ev.get("summary") or "(no title)")[:40]
            for ev in (cal.get("today") or [])
        ))
        tomorrow_events = list(dict.fromkeys(
            (ev.get("title") or ev.get("summary") or "(no title)")[:40]
            for ev in (cal.get("tomorrow") or [])
        ))
        if today_events or tomorrow_events:
            parts = []
            if today_events:
                parts.append(f"Today: {', '.join(today_events[:3])}")
            if tomorrow_events:
                parts.append(f"Tomorrow: {', '.join(tomorrow_events[:3])}")
            items.append(_canonical_item(
                title=f"Calendar: {len(today_events)} today, {len(tomorrow_events)} tomorrow",
                summary=" | ".join(parts),
                why_it_matters="Calendar events for today and tomorrow.",
                disposition="act_today" if today_events else "monitor",
                grounding="system_detected",
                freshness="fresh",
                source_refs=["calendar.personal.json", "calendar.bridgepoint.json"],
                confidence="high",
                extras={"today_count": len(today_events),
                        "tomorrow_count": len(tomorrow_events),
                        "today_events": today_events[:5],
                        "tomorrow_events": tomorrow_events[:5],
                        "delta_source": "calendar"},
            ))
    except Exception:
        pass

    # ── Quiet cycle ───────────────────────────────────────────────────────────
    if not items:
        items.append(_canonical_item(
            title="Personal intelligence: no new activity in last 36h",
            summary="Email, SMS, calendar, and opportunity state unchanged since prior cycle.",
            why_it_matters="Clean delta — no new personal signals require attention.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["email", "messages.json", "calendar"],
            confidence="medium",
        ))

    return items


def _compute_five_things(sections: dict, report: dict) -> list[dict]:
    """Pick the 5 highest-priority items across the full brief by CoS judgment.

    Scoring logic (deterministic, no model):
    - disposition == 'act_today'  → score 100
    - disposition == 'ask_todd'   → score 80
    - disposition == 'monitor'    → score 40
    - disposition == 'ignore'     → score 0

    Within same disposition tier, boost by:
    +30 if grounding == 'system_detected' (verified signal)
    +20 if freshness == 'fresh'
    +10 if confidence == 'high'
    -20 if freshness in ('stale_source_limited', 'manual_context')

    Sections excluded (system/diagnostic):
    decision_queue, trust_metrics, source_audit, suppressed_today,
    active_knowledge_assets, five_things_today, what_changed,
    graph_mutation_log, pending_mutations, intelligence_cycle_continuation.

    Returns exactly 5 items (fewer if brief has fewer qualifying items).
    Each item wrapped as a reference with source_section tag.
    """
    SKIP = {
        "decision_queue", "trust_metrics", "source_audit", "suppressed_today",
        "active_knowledge_assets", "five_things_today", "what_changed",
        "what_changed_since_yesterday", "graph_mutation_log", "pending_mutations",
        "intelligence_cycle_continuation", "linkedin_intelligence_opportunity",
        "resource_verification_and_freshness_status",
        # DEFECT-016: never recirculate completeness/decision meta-sections into top-5
        "information_debt_queue", "decision_layer",
        # Source health is already surfaced in brief_status_header — exclude from top-5
        # to prevent it crowding out actual action items
        "source_trust_table", "source_gap_declarations", "brief_status_header",
        # CoS and W-2 are rendered separately at the top — don't recirculate
        "cos_today", "w2_intelligence", "capacity_plan",
    }
    DISP_SCORE = {"act_today": 100, "ask_todd": 80, "monitor": 40, "ignore": 0}
    FRESHNESS_BOOST = {"fresh": 20, "manual_context": -20, "stale_source_limited": -20}

    candidates: list[tuple[int, dict, str]] = []
    seen_titles: set[str] = set()

    for section_key, items in sections.items():
        if section_key in SKIP or not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            title = item.get("title") or ""
            if not title or title in seen_titles:
                continue
            # RB-2026-09-03: see build_decision_layer's matching exclusion
            # in completeness_contract.py -- RB's own bookkeeping self-
            # check items are not a real top-5 priority for Todd.
            if (item.get("extras") or {}).get("is_meta_accountability_note"):
                continue
            disp = item.get("disposition") or "monitor"
            if disp == "ignore":
                continue
            score = DISP_SCORE.get(disp, 40)
            if item.get("grounding") == "system_detected":
                score += 30
            score += FRESHNESS_BOOST.get(item.get("freshness") or "", 0)
            if item.get("confidence") == "high":
                score += 10
            # Boost critical-event markers
            if any(kw in title.lower() for kw in ("interview", "foods connected", "critical", "overdue")):
                score += 25
            candidates.append((score, item, section_key))
            seen_titles.add(title)

    candidates.sort(key=lambda x: -x[0])

    # RB-DEFECT-016-C: Category balance enforcement.
    # Loop items capped at 2-of-5. Strategic/decision items guaranteed ≥1 slot if available.
    # Preserve the full pre-balance list as overflow_pool so Sprint L overflow tagging works.
    _all_candidates = list(candidates)  # full sorted list before any trimming
    if _HAS_COMPLETENESS_CONTRACT:
        try:
            candidates = _cc.enforce_top5_category_balance(candidates, n=5)
        except Exception:  # noqa: BLE001
            candidates = candidates[:5]

    top5 = candidates[:5]
    # Overflow: any act_today items from the full pool that didn't make the top-5
    _top5_titles = {c[1].get("title") or "" for c in top5}
    overflow = [
        c for c in _all_candidates
        if (c[1].get("title") or "") not in _top5_titles
    ]

    # Sprint L — tag source items so cross-section dedup can reference rank by number.
    for rank, (score, item, source_section) in enumerate(top5, 1):
        item.setdefault("extras", {})["five_things_rank"] = rank

    # Sprint L — tag overflow act_today items so GPT knows they were compressed.
    overflow_act_today = []
    for score, item, source_section in overflow:
        if (item.get("disposition") or "") == "act_today":
            item.setdefault("extras", {})["five_things_overflow"] = True
            overflow_act_today.append((score, item, source_section))

    result: list[dict] = []
    for rank, (score, item, source_section) in enumerate(top5, 1):
        result.append(_canonical_item(
            title=f"#{rank}: {item.get('title', '')}",
            summary=item.get("summary") or item.get("why_it_matters") or "",
            why_it_matters=item.get("why_it_matters") or "",
            recommended_action=item.get("recommended_action") or "",
            disposition=item.get("disposition") or "monitor",
            grounding=item.get("grounding") or "system_detected",
            freshness=item.get("freshness") or "fresh",
            source_refs=item.get("source_refs") or [source_section],
            confidence=item.get("confidence") or "medium",
            extras={
                "source_section": source_section,
                "priority_score": score,
                "rank": rank,
            },
        ))

    # Sprint L — overflow summary item: surface compressed act_today count.
    if overflow_act_today:
        n = len(overflow_act_today)
        overflow_titles = ", ".join(
            item.get("title") or "?" for _, item, _ in overflow_act_today[:3]
        )
        if n > 3:
            overflow_titles += f", +{n - 3} more"
        overflow_source_refs = list({sec for _, _, sec in overflow_act_today})
        overflow_item = _canonical_item(
            title=f"+ {n} act_today item{'s' if n != 1 else ''} compressed to monitor",
            summary=(
                f"{n} additional act_today item{'s' if n != 1 else ''} did not rank in the top 5 "
                f"and have been compressed. Review if top-5 items are resolved: {overflow_titles}."
            ),
            why_it_matters=(
                f"Priority compression is active. These {n} item{'s' if n != 1 else ''} "
                f"scored below the top-5 threshold. They remain act_today in their source sections "
                f"but are not surfaced here to avoid overload."
            ),
            recommended_action=(
                "Ask 'show compressed items' to see the full overflow list."
            ),
            disposition="monitor",
            grounding="system_detected",
            freshness="current",
            source_refs=overflow_source_refs,
            confidence="high",
            extras={
                "is_overflow_summary": True,
                "overflow_count": n,
                "overflow_titles": [item.get("title") or "" for _, item, _ in overflow_act_today],
            },
        )
        # Sprint L: overflow summary is a system meta-item, not source-discovered intelligence.
        if isinstance(overflow_item.get("novelty"), dict):
            overflow_item["novelty"]["source_discovered"] = False
        result.append(overflow_item)

    return result


def _compute_critical_event(report: dict) -> list[dict]:
    """Surface the single highest-leverage calendar event for today.

    Checks calendar events for today, scores by:
    - interview / evaluation > strategy meeting > client meeting > internal
    - company relevance (Foods Connected, PAR, etc. > generic)
    - has meeting prep artifact already written vs missing

    Returns one item — the critical event with prep status and what's needed.
    If no events today, returns empty list.
    """
    calendar = report.get("calendar") or {}
    events = calendar.get("events") or []
    today_dt = date.today()
    today_str = today_dt.isoformat()

    # Filter to today's events
    today_events = []
    for ev in events:
        start = ev.get("start") or ""
        if start[:10] == today_str:
            today_events.append(ev)

    if not today_events:
        # Also check meeting_prep in report
        mp = report.get("meeting_prep") or {}
        if not mp:
            return []

    # Score events
    _KW_SCORES = {
        "interview": 100, "evaluation": 90, "assessment": 90,
        "foods connected": 95, "par technology": 80, "toast": 70,
        "client": 60, "customer": 60, "prospect": 65,
        "strategy": 50, "leadership": 45, "board": 45,
        "1:1": 30, "sync": 20, "standup": 10,
    }
    def _event_score(ev: dict) -> int:
        title = (ev.get("title") or ev.get("summary") or "").lower()
        score = 0
        for kw, pts in _KW_SCORES.items():
            if kw in title:
                score = max(score, pts)
        return score

    today_events.sort(key=_event_score, reverse=True)
    top_event = today_events[0] if today_events else None

    if not top_event:
        return []

    title = top_event.get("title") or top_event.get("summary") or "Untitled event"
    start = top_event.get("start") or ""
    time_str = start[11:16] if len(start) > 10 else "time unknown"
    attendees = top_event.get("attendees") or []
    attendee_str = ", ".join(
        (a.get("name") or a.get("email") or "?") for a in attendees[:4]
    ) if attendees else "attendees unknown"

    ev_score = _event_score(top_event)
    is_interview = ev_score >= 90

    # Check if meeting prep artifact exists
    prep_path = core.SYSTEM_DIR / "artifacts" / "meeting_prep"
    prep_exists = False
    if prep_path.exists():
        for f in prep_path.glob("*.md"):
            if title.lower()[:10] in f.stem.lower() or today_str.replace("-","") in f.stem:
                prep_exists = True
                break

    disposition = "act_today"
    summary_parts = [
        f"Today at {time_str}.",
        f"Attendees: {attendee_str}.",
    ]
    if is_interview:
        summary_parts.append("This is an interview/evaluation — the highest-leverage event today.")
    if not prep_exists:
        summary_parts.append("⚠ No prep packet found. Preparation required before this event.")
    else:
        summary_parts.append("Meeting prep artifact exists.")

    action = (
        "Review prep packet and confirm talking points before the event."
        if prep_exists else
        "Generate prep packet immediately via writeMeetingPrepArtifacts. Review and internalize before event."
    )

    return [_canonical_item(
        title=f"CRITICAL EVENT TODAY: {title} — {time_str}",
        summary=" ".join(summary_parts),
        why_it_matters=(
            "This is the highest-leverage event on today's calendar. "
            + ("Interview performance is the primary determinant of opportunity advancement. "
               if is_interview else "")
            + ("Preparation has not been completed." if not prep_exists else "Preparation is available.")
        ),
        recommended_action=action,
        disposition=disposition,
        grounding="system_detected",
        freshness="fresh",
        source_refs=[f"calendar.events.{top_event.get('id','today')}"],
        confidence="high",
        extras={
            "event_id": top_event.get("id"),
            "event_title": title,
            "event_time": time_str,
            "attendees": attendee_str,
            "is_interview": is_interview,
            "prep_exists": prep_exists,
            "event_score": ev_score,
        },
    )]


def _opp_probability(state: str, current_state: str, opened_str: str,
                     target_close_str: str, today: date) -> str:
    """Sprint K: infer probability (HIGH/MEDIUM/LOW) from opportunity signals."""
    text = (current_state or "").lower()

    # Hard negative signals → LOW
    if any(kw in text for kw in (
        "no response", "silent", "overdue", "not responded", "ghosted",
        "missed", "rejected", "closed", "no further",
    )):
        return "LOW"

    # State = WAITING without a positive qualifier → MEDIUM at best
    if state == "WAITING":
        if any(kw in text for kw in ("positive", "strong", "confirmed", "interested")):
            return "MEDIUM"
        return "LOW"

    # Check target proximity
    if target_close_str and target_close_str != "open":
        try:
            tc = date.fromisoformat(str(target_close_str))
            days_remaining = (tc - today).days
            if days_remaining < 0:
                return "LOW"   # past target — unknown status
            if days_remaining < 14:
                return "MEDIUM"  # tight window
        except (ValueError, TypeError):
            pass

    # Positive signals → HIGH
    if any(kw in text for kw in (
        "active evaluation", "positive", "strong", "confirmed", "scheduled",
        "advancing", "moving forward", "next step",
    )):
        return "HIGH"

    # Default for ACTIVE state without strong signals
    return "MEDIUM"


def _opp_evidence_age(current_state: str, context: str, opened_str: str,
                      today: date) -> int:
    """Sprint K: days since last evidence update. Scans for most recent ISO date."""
    text = f"{current_state or ''} {context or ''}"
    # Find all ISO date patterns (YYYY-MM-DD)
    dates_found: list[date] = []
    for m in re.finditer(r"\b(20\d{2}-\d{2}-\d{2})\b", text):
        try:
            dates_found.append(date.fromisoformat(m.group(1)))
        except ValueError:
            pass
    if dates_found:
        most_recent = max(dates_found)
        return max(0, (today - most_recent).days)
    # Fall back to opened date
    if opened_str:
        try:
            opened = date.fromisoformat(str(opened_str))
            return max(0, (today - opened).days)
        except (ValueError, TypeError):
            pass
    return 0


def _opp_missing_evidence(current_state: str, context: str) -> str:
    """Sprint K: identify missing evidence from state/context keywords."""
    text = f"{current_state or ''} {context or ''}".lower()

    if "overdue" in text:
        # Extract the loop reference if present
        m = re.search(r"(l-\d{4}-\d{2}-\d{2}-\d+)", text, re.IGNORECASE)
        loop_ref = m.group(1).upper() if m else "the overdue loop"
        return f"{loop_ref} is overdue — update required."
    if "not captured" in text or "not recorded" in text:
        return "Post-event capture not recorded — details unknown."
    if "no response" in text or "awaiting" in text or "silent" in text:
        return "External response not received — counterparty status unknown."
    if "pending" in text:
        return "Pending action has not been completed."
    return "No specific evidence gaps identified."


def _opp_forcing_function(target_close_str: str, current_state: str,
                          today: date) -> str:
    """Sprint K: the next hard deadline or forcing function for this opportunity."""
    # Scan current_state for explicit target/due dates
    due_dates: list[date] = []
    for m in re.finditer(r"target[^\d]*(\d{4}-\d{2}-\d{2})", current_state or "", re.IGNORECASE):
        try:
            due_dates.append(date.fromisoformat(m.group(1)))
        except ValueError:
            pass

    if due_dates:
        nearest = min(due_dates)
        days = (nearest - today).days
        if days < 0:
            return f"Loop target {nearest} is {-days}d overdue — resolve or reschedule immediately."
        return f"Loop target {nearest} ({days} days) — must act before then."

    # Fall back to target_close
    if target_close_str and target_close_str != "open":
        try:
            tc = date.fromisoformat(str(target_close_str))
            days = (tc - today).days
            if days < 0:
                return f"Target close {tc} is {-days}d overdue — confirm status or close thread."
            return f"Confirm definitive status before {tc} ({days} days)."
        except (ValueError, TypeError):
            pass

    return "No hard deadline — set a follow-up date to prevent this from going cold."


def _opp_linked_activity(thread: dict, report: dict) -> dict:
    """DEFECT-018: Aggregate all linked entity activity for an opportunity thread.

    Cross-references:
    1. email_overlay — threads matching any company or person in the opportunity
    2. calendar_overlay — events with opportunity participants
    3. sms_matches from direct_comms_health — messages to/from opportunity contacts

    Returns:
    {
        "latest_activity_date": date | None,
        "latest_activity_type": "email" | "calendar" | "sms" | "loop" | None,
        "latest_activity_label": str,
        "waiting_on": str | None,
        "evidence_sources": list[str],
        "evidence_age_days": int,
    }
    """
    today_dt = date.today()
    companies = [c.lower() for c in (thread.get("companies") or [])]
    people = thread.get("people") or []  # contact IDs

    activities: list[tuple[date, str, str]] = []  # (date, type, label)

    def _parse_email_date(raw: str) -> date | None:
        """Parse email date strings in multiple formats: ISO, RFC 2822, short."""
        if not raw:
            return None
        raw = str(raw).strip()
        # Try ISO first (YYYY-MM-DD)
        try:
            return date.fromisoformat(raw[:10])
        except (ValueError, TypeError):
            pass
        # Try RFC 2822 / email.utils
        try:
            import email.utils as _eu
            import time as _tm
            parsed = _eu.parsedate(raw)
            if parsed:
                return date.fromtimestamp(_tm.mktime(parsed))
        except (ValueError, TypeError, OverflowError, OSError):
            pass
        return None

    # 1. Email overlay — find threads linked to this opportunity thread ID
    thread_id = thread.get("id") or ""
    try:
        em = report.get("email") or {}

        # active_thread_company_hits: email threads matched to active opportunity threads
        for et in (em.get("active_thread_company_hits") or []):
            if thread_id in (et.get("active_thread_ids") or []):
                at_date = _parse_email_date(et.get("last_message_at") or "")
                if at_date:
                    activities.append((
                        at_date, "email",
                        f"Email: {(et.get('subject') or 'communication')[:60]}",
                    ))

        # sent_followups: outbound emails matched to this thread
        for sf in (em.get("sent_followups") or []):
            if thread_id in (sf.get("matched_threads") or []):
                # Skip automated brief emails
                subj = (sf.get("subject") or "").lower()
                if any(kw in subj for kw in ("rb daily brief", "daily brief backup", "daily brief is ready")):
                    continue
                at_date = _parse_email_date(sf.get("sent_at") or "")
                if at_date:
                    activities.append((
                        at_date, "email",
                        f"Sent: {(sf.get('subject') or 'outbound email')[:60]}",
                    ))

        # from_baseline: emails from/to contacts in this thread
        thread_people_lower = [p.lower() for p in people]
        for et in (em.get("from_baseline") or []):
            match = et.get("match") or {}
            contact_id = (match.get("id") or match.get("contact_id") or "").lower()
            if contact_id in thread_people_lower:
                at_date = _parse_email_date(et.get("last_message_at") or "")
                if at_date:
                    activities.append((
                        at_date, "email",
                        f"Email with {match.get('name','contact')}: {(et.get('subject') or '')[:60]}",
                    ))
    except Exception:  # noqa: BLE001
        pass

    # 2. Calendar overlay — find events with opportunity participants
    try:
        cal = report.get("calendar") or {}
        cal_events = cal.get("events") or []
        for ev in cal_events:
            attendees = [a.lower() for a in (ev.get("attendees") or [])]
            ev_summary = (ev.get("summary") or "").lower()
            company_match = any(co in ev_summary for co in companies)
            person_match = any(pid in attendees for pid in people)
            if company_match or person_match:
                ev_date = _parse_email_date(ev.get("start") or ev.get("date") or "")
                if ev_date:
                    activities.append((
                        ev_date, "calendar",
                        f"Calendar: {(ev.get('summary') or 'meeting')[:60]}",
                    ))
    except Exception:  # noqa: BLE001
        pass

    # 3. SMS — check direct_comms_health RI candidates for opportunity contacts
    try:
        dch_items = report.get("direct_comms_health") or []
        for dch_item in dch_items:
            for cand in (dch_item.get("ri_candidates") or []):
                if cand.get("contact_id") in people:
                    evt_date = _parse_email_date(cand.get("event_at") or "")
                    if evt_date:
                        activities.append((
                            evt_date, "sms",
                            f"SMS with {cand.get('contact_id')}",
                        ))
    except Exception:  # noqa: BLE001
        pass

    if not activities:
        return {
            "latest_activity_date": None,
            "latest_activity_type": None,
            "latest_activity_label": "No linked activity found",
            "waiting_on": None,
            "evidence_sources": [],
            "evidence_age_days": None,
        }

    activities.sort(key=lambda x: x[0], reverse=True)
    latest_date, latest_type, latest_label = activities[0]
    age_days = max(0, (today_dt - latest_date).days)

    # Determine waiting_on based on most recent activity type and direction
    waiting_on = None
    if latest_type == "email" and latest_label.startswith("Sent:"):
        waiting_on = "Awaiting response to outbound email"
    elif latest_type == "email" and not latest_label.startswith("Sent:"):
        waiting_on = "Inbound received — follow-up may be needed"
    elif latest_type == "calendar" and latest_date >= today_dt:
        waiting_on = "Upcoming meeting scheduled"
    elif latest_type == "calendar" and latest_date < today_dt:
        waiting_on = "Post-meeting follow-up may be needed"
    elif latest_type == "sms":
        waiting_on = "SMS/iMessage exchange — check thread for response needed"

    return {
        "latest_activity_date": latest_date.isoformat(),
        "latest_activity_type": latest_type,
        "latest_activity_label": latest_label,
        "waiting_on": waiting_on,
        "evidence_sources": list({t for _, t, _ in activities[:5]}),
        "evidence_age_days": age_days,
    }


def _compute_opportunity_board(report: dict) -> list[dict]:
    """Build a structured 4-state opportunity board (Sprint K: decision-support upgrade).

    States: ACTIVE → WAITING → REJECTED → CLOSED

    Each item now includes four decision-support fields in extras:
      probability       — HIGH/MEDIUM/LOW (inferred from state + signals + recency)
      evidence_age_days — days since last meaningful update
      missing_evidence  — what evidence gap is reducing confidence
      forcing_function  — the next hard deadline or action trigger

    Sources:
    - active_threads.yaml (type: job_opportunity, opportunity, recruiter_engagement)
    - strategic_memory.json (state: REJECTED, CLOSED_SILENT)
    """
    _today = report.get("today")
    if isinstance(_today, str):
        try:
            _today = date.fromisoformat(_today)
        except ValueError:
            _today = date.today()
    elif not isinstance(_today, date):
        _today = date.today()

    # Load threads (YAML may be a dict with a 'threads' key or a bare list)
    try:
        import yaml as _yaml
        active_threads_path = core.SYSTEM_DIR / "active_threads.yaml"
        _raw = _yaml.safe_load(active_threads_path.read_text()) or []
        if isinstance(_raw, dict):
            threads = _raw.get("threads") or []
        else:
            threads = _raw if isinstance(_raw, list) else []
    except Exception:  # noqa: BLE001
        threads = []

    OPPORTUNITY_TYPES = {"job_opportunity", "opportunity", "recruiter_engagement", "partnership"}
    opp_threads = [t for t in threads if t.get("type") in OPPORTUNITY_TYPES]

    # Load strategic memory for rejected/closed
    try:
        sm_path = core.SYSTEM_DIR / "strategic_memory.json"
        sm = json.loads(sm_path.read_text(encoding="utf-8"))
        closed_signals = [
            s for s in (sm.get("signals") or [])
            if s.get("state") in ("REJECTED", "CLOSED_SILENT", "CLOSED")
        ]
    except Exception:  # noqa: BLE001
        closed_signals = []

    items: list[dict] = []

    # Active/waiting threads
    for t in opp_threads:
        status = t.get("status", "open")
        current_state_text = t.get("current_state") or t.get("context") or ""
        context_text = t.get("context") or ""

        if status == "closed":
            state = "CLOSED"
        else:
            current_lower = current_state_text.lower()
            if any(kw in current_lower for kw in (
                "waiting", "await", "pending", "silent", "no response",
            )):
                state = "WAITING"
            else:
                state = "ACTIVE"

        companies = ", ".join(t.get("companies") or []) or "unknown"
        target_close = t.get("target_close") or "open"
        opened = t.get("opened") or ""

        # DEFECT-018: Cross-reference email/calendar/SMS for accurate evidence age
        linked = _opp_linked_activity(t, report)
        linked_age = linked.get("evidence_age_days")
        linked_label = linked.get("latest_activity_label") or ""
        linked_type = linked.get("latest_activity_type")
        waiting_on = linked.get("waiting_on")

        # Sprint K — decision-support fields (linked activity overrides text-scan age)
        text_age = _opp_evidence_age(current_state_text, context_text, opened, _today)
        if linked_age is not None and linked_age < text_age:
            evidence_age = linked_age  # use the more recent evidence
            evidence_source = linked_type or "linked_activity"
        else:
            evidence_age = text_age
            evidence_source = "thread_text"

        probability = _opp_probability(state, current_state_text, opened, target_close, _today)
        # Re-score probability when we have recent linked activity
        if linked_age is not None and linked_age <= 3 and probability == "LOW":
            probability = "MEDIUM"  # recent email/call upgrades LOW → MEDIUM
        missing_ev = _opp_missing_evidence(current_state_text, context_text)
        if waiting_on:
            missing_ev = waiting_on  # more accurate than text-based gap detection
        forcing_fn = _opp_forcing_function(target_close, current_state_text, _today)

        # Disposition: escalate if ACTIVE or if WAITING with aged evidence
        if state == "ACTIVE":
            disp = "act_today"
        elif state == "WAITING" and evidence_age > 7:
            disp = "act_today"  # stale WAITING → needs a nudge
        elif state == "WAITING":
            disp = "monitor"
        else:
            disp = "ignore"

        # Confidence label derived from probability (boosted when linked activity recent)
        conf = {"HIGH": "high", "MEDIUM": "medium", "LOW": "low"}.get(probability, "medium")

        # Decision-support why_it_matters with linked activity context
        prob_context = {
            "HIGH": "Signals are positive. Now is the time to advance.",
            "MEDIUM": "Mixed signals. Forward momentum is unclear.",
            "LOW": "Negative signals detected. Risk of loss if not addressed immediately.",
        }[probability]
        age_note = ""
        if evidence_age == 0:
            age_note = " Activity today."
        elif linked_age is not None and linked_age < 7:
            age_note = f" Latest: {linked_label} ({evidence_age}d ago)."
        elif evidence_age > 0:
            age_note = f" Last evidence: {evidence_age} days ago."

        why = (
            f"Probability: {probability}.{age_note} {prob_context} "
            + (f"Waiting on: {waiting_on}. " if waiting_on else f"Missing: {missing_ev}")
        )

        # Decision-support recommended_action (Sprint K — replaces generic)
        if state == "ACTIVE":
            action = (
                f"Advance {companies} today. "
                f"Forcing function: {forcing_fn}"
            )
        elif state == "WAITING":
            if evidence_age > 7:
                action = (
                    f"Evidence is {evidence_age} days old. "
                    f"Follow up to confirm status, OR formally close if unresponsive. "
                    f"Forcing function: {forcing_fn}"
                )
            else:
                action = (
                    f"Hold. Waiting state is expected. "
                    f"Forcing function: {forcing_fn}"
                )
        else:
            action = "Closed — no action required."

        source_refs = [f"active_threads.{t.get('id', '')}"]
        if linked_type == "email":
            source_refs.append("email_overlay")
        elif linked_type == "calendar":
            source_refs.append("calendar_overlay")
        elif linked_type == "sms":
            source_refs.append("inbox/messages.json")

        items.append(_canonical_item(
            title=f"[{state}] {t.get('title', companies)}",
            summary=(
                f"Company: {companies}. "
                f"Probability: {probability}. "
                f"Latest activity: {linked_label or 'none found'} ({evidence_age}d ago). "
                + (f"Waiting on: {waiting_on}. " if waiting_on else "")
                + f"State: {current_state_text[:80]}"
            ),
            why_it_matters=why,
            recommended_action=action,
            disposition=disp,
            grounding="system_detected",
            freshness="fresh",
            source_refs=source_refs,
            confidence=conf,
            extras={
                "state": state,
                "companies": companies,
                "thread_id": t.get("id"),
                "opportunity_state": state,
                # Sprint K — decision-support fields
                "probability": probability,
                "evidence_age_days": evidence_age,
                "evidence_source": evidence_source,
                "latest_activity": linked_label,
                "latest_activity_type": linked_type,
                "waiting_on": waiting_on,
                "missing_evidence": missing_ev,
                "forcing_function": forcing_fn,
                "target_close": str(target_close),
                # DEFECT-018 — linked activity detail
                "linked_activity": {
                    "latest_date": linked.get("latest_activity_date"),
                    "type": linked_type,
                    "label": linked_label,
                    "waiting_on": waiting_on,
                    "evidence_sources": linked.get("evidence_sources", []),
                },
            },
        ))

    # Rejected/closed from strategic memory
    for s in closed_signals:
        state = s.get("state", "CLOSED")
        items.append(_canonical_item(
            title=f"[{state}] {s.get('signal', '')[:60]}",
            summary=s.get("strategic_implication") or s.get("signal") or "",
            why_it_matters="Recorded as closed — suppressed from active opportunity tracking.",
            recommended_action="No action required.",
            disposition="ignore",
            grounding="manual_user_provided",
            freshness="fresh",
            source_refs=["strategic_memory.json"],
            confidence="high",
            extras={"state": state, "signal_id": s.get("id")},
        ))

    # State order: ACTIVE first, then WAITING, then CLOSED, then REJECTED
    _ORDER = {"ACTIVE": 0, "WAITING": 1, "CLOSED": 2, "REJECTED": 3, "CLOSED_SILENT": 4}
    items.sort(key=lambda x: _ORDER.get((x.get("extras") or {}).get("state", "CLOSED"), 5))

    if not items:
        return [_canonical_item(
            title="Opportunity Board — no tracked opportunities",
            summary="No active, waiting, rejected, or closed opportunities tracked in the system.",
            why_it_matters="Add opportunities via openThread to begin tracking.",
            recommended_action="Record new opportunities via openThread when they arise.",
            disposition="monitor",
            grounding="system_detected",
            freshness="fresh",
            source_refs=["active_threads.yaml"],
            confidence="high",
        )]

    return items


