# Sprint E-2 — Web headline section helpers
# ---------------------------------------------------------------------------

# RB-DEFECT-2026-07-20: _HEADLINE_FRESHNESS_DAYS/_CORPORATE_EVENT_MAX_AGE_DAYS
# used to be defined independently here AND in render_intelligence_brief.py --
# two copies of the same rule, free to drift out of sync. Both now source
# from rb_core.is_fresh_pub_date's shared constants; only the corporate-event
# *detection* below stays local, since this item shape has no pre-computed
# badge to check (unlike render_intelligence_brief.py's badge-based items).
_CORPORATE_EVENT_KEYWORDS = frozenset({
    "earnings", "revenue", "quarterly", "q1", "q2", "q3", "q4", "guidance",
    "acqui", "merger", "ipo", "funding", "series", "valuation", "exec", "ceo",
    "cfo", "cto", "appoints", "names", "hire", "depart", "resign", "bankrupt",
})

# Most BBC/NPR/Yahoo world-national items carry the same default signal_weight
# (10) — only a handful of corporate-event items score higher. When the
# RB-DEFECT-044 top-10 cap below breaks weight ties on pub_date alone, a same-day
# flood of lifestyle/consumer filler (wedding gifts, Instagram ads, airport
# strikes) wins purely on recency and crowds out substantive macro/geopolitical
# items that happen to be a day older. This mirrors the render-time relevance
# gate in render_intelligence_brief.py's _WORLD_RELEVANCE_KEYWORDS so the cap
# doesn't discard on-topic items before the renderer ever sees them.
_WORLD_HEADLINE_RELEVANCE_TERMS = (
    "economy", "gdp", "inflation", "interest rate", "federal reserve", "recession",
    "trade war", "tariff", "sanctions", "currency", "treasury", "bond yield",
    "war", "conflict", "ceasefire", "iran", "china", "russia", "ukraine", "nato",
    "israel", "taiwan", "north korea", "middle east", "trade deal", "g7", "g20",
    "regulation", "antitrust", "legislation", "congress", "senate",
    "executive order", "department of justice", "supreme court",
    "artificial intelligence", " ai ", "chip", "semiconductor", "cybersecurity",
    "data breach", "big tech", "payment", "fintech", "banking",
    "financial services", "acquisition", "merger", "ipo", "funding", "billion",
    "restaurant", "hospitality", "food service", "qsr", "quick service",
)


def _is_world_headline_relevant(item: dict) -> bool:
    """True if a world/national item scores high enough or matches a topical
    keyword — used to keep the RB-DEFECT-044 top-10 cap from being dominated
    by same-weight lifestyle filler on a pure recency tiebreak."""
    extras = item.get("extras") or {}
    if (extras.get("signal_weight") or 0) >= 50:
        return True
    title = (item.get("title") or "").lower()
    return any(term in title for term in _WORLD_HEADLINE_RELEVANCE_TERMS)


def _newest_evidence_first(evidence: list[dict]) -> list[dict]:
    """RB-DEFECT-2026-07-08: strategic_events.json's evidence accumulates in
    the order it was first captured (oldest first), so a caller taking the
    first few entries unsorted always cites among the OLDEST evidence for a
    long-running convergence signal -- confirmed live: a signal reporting
    "+1 evidence since last reported" (44 total) rendered a "Source:" line
    pointing to a May 20th article, 7 weeks stale, even though the delta
    driving today's mention was brand new. Sort newest-published first so
    the cited source actually reflects what's new."""
    return sorted(evidence, key=lambda ev: ev.get("published_at") or "", reverse=True)


_HEADLINE_RANK_KEY = lambda _i: (
    (_i.get("extras") or {}).get("signal_weight") or 0,
    (_i.get("extras") or {}).get("pub_date") or "",
)


def _cap_by_relevance(items: list[dict], cap: int = 10) -> list[dict]:
    """Rank on-topic items ahead of generic filler before applying the
    weight/recency tiebreak, so relevant-but-older items aren't crowded out
    by same-weight, same-day lifestyle noise, then truncate to cap."""
    on_topic = sorted(
        (i for i in items if _is_world_headline_relevant(i)),
        key=_HEADLINE_RANK_KEY, reverse=True,
    )
    filler = sorted(
        (i for i in items if not _is_world_headline_relevant(i)),
        key=_HEADLINE_RANK_KEY, reverse=True,
    )
    return (on_topic + filler)[:cap]


def _cap_headline_sections(sections: dict) -> None:
    """RB 9.80 — RB-DEFECT-044 (Intelligence Brief): enforce "5-10 items, new
    only" for the three headline sections. Mutates sections in place. Runs
    after lifecycle filtering (so previously-reported items are already gone)
    and before the RB 9.77 "no material developments" fallback.

    world_national_headlines feeds TWO downstream sections (A: World, B:
    National) via a scope split at render time. Capping the combined pool to
    10 before that split can starve one scope entirely if ranking happens to
    favor the other (confirmed: 100 fresh items, all top-10-ranked survivors
    classified as "world", leaving National with 0). Split by scope first,
    then cap each scope's pool independently so both sections retain their
    own top-10 regardless of how the two scopes rank against each other.
    """
    for hl_section in (
        "world_national_headlines",
        "restaurant_industry_headlines",
        "restaurant_technology_headlines",
    ):
        hl_items = sections.get(hl_section) or []
        if hl_section == "world_national_headlines":
            world_pool = [i for i in hl_items if core.classify_world_national_scope(i) == "world"]
            us_pool = [i for i in hl_items if core.classify_world_national_scope(i) == "us"]
            sections[hl_section] = _cap_by_relevance(world_pool) + _cap_by_relevance(us_pool)
        elif len(hl_items) > 10:
            sections[hl_section] = sorted(hl_items, key=_HEADLINE_RANK_KEY, reverse=True)[:10]


def _is_fresh_headline(item: dict, today: "date") -> bool:
    """Return True if item passes the shared freshness gate (rb_core.is_fresh_pub_date).

    Corporate event items (earnings, M&A, exec moves, funding) get the longer
    ceiling — detected here via keyword match, since this item shape has no
    pre-computed badge the way render_intelligence_brief.py's items do.
    """
    extras = item.get("extras") or {}
    pub_date_str = extras.get("pub_date") or extras.get("published_date") or ""
    if not pub_date_str:
        return True  # no date = can't gate = include (conservative)

    try:
        pub_date = date.fromisoformat(str(pub_date_str)[:10])
    except (ValueError, TypeError):
        return True  # unparseable date = include

    combined = " ".join([
        (item.get("title") or ""),
        (item.get("summary") or ""),
        str(extras.get("intelligence_type") or ""),
    ]).lower()
    is_corporate = any(kw in combined for kw in _CORPORATE_EVENT_KEYWORDS)
    return core.is_fresh_pub_date(pub_date, today, is_corporate)


def _filter_fresh_headlines(items: list[dict], today: "date") -> list[dict]:
    """Apply freshness gate to a list of headline items."""
    return [i for i in items if _is_fresh_headline(i, today)]


def _compute_world_headlines(report: dict) -> list[dict]:
    """Sprint E-2 + RB 10.6: world_national_headlines with 7-day freshness gate."""
    web_scan = report.get("web_scan") or {}
    raw = list(web_scan.get("world_national") or [])
    today = _report_today(report)
    return _filter_fresh_headlines(raw, today)


def _compute_restaurant_industry_headlines(report: dict) -> list[dict]:
    """Sprint E-2 + RB 10.6: restaurant_industry_headlines with 7-day freshness gate."""
    web_scan = report.get("web_scan") or {}
    raw = list(web_scan.get("restaurant_industry") or [])
    today = _report_today(report)
    return _filter_fresh_headlines(raw, today)


def _build_restaurant_tech_fallback(report: dict, total_scanned: int = 0) -> list[dict]:
    """RB 10.6 / RB-INT-024: Fallback when <2 fresh restaurant tech headlines exist.

    Shows scan count as proof of work + upcoming factual events from watchlist.
    Does NOT use strategic_industry_signals — those are analytical/thematic and
    belong in Section I, not in the newspaper headline section.
    """
    today = _report_today(report)

    # Events to Watch: watchlist items with future earnings dates or upcoming events only
    wl_items = report.get("watchlist_intelligence") or []
    events: list[str] = []
    for item in wl_items:
        extras = item.get("extras") or {}
        if extras.get("earnings_date") or extras.get("upcoming_event"):
            company = extras.get("entity_name") or item.get("title", "")[:40]
            event = extras.get("earnings_date") or extras.get("upcoming_event") or ""
            if company:
                events.append(f"• {company}: {event}" if event else f"• {company}")
        if len(events) >= 4:
            break

    scanned_note = f"Scanned {total_scanned} restaurant technology sources." if total_scanned else "Sources scanned."
    summary_parts = [
        f"{scanned_note} No material, net-new restaurant technology developments this cycle."
    ]
    if events:
        summary_parts.append("Events to Watch (upcoming):\n" + "\n".join(events))

    return [_canonical_item(
        title="Restaurant Technology — No Material Headlines This Cycle",
        summary="\n\n".join(summary_parts),
        why_it_matters=f"{scanned_note} Zero net-new developments = confirmed quiet, not a scan failure.",
        recommended_action="Monitor sources for new developments.",
        disposition="monitor",
        grounding="system_detected",
        freshness="fresh",
        source_refs=["restaurant_technology_headlines", "watchlist_intelligence"],
        confidence="medium",
        extras={
            "fallback": True,
            "sources_scanned_total": total_scanned,
            "generated_date": today.isoformat(),
        },
    )]


def _compute_restaurant_tech_headlines(report: dict) -> list[dict]:
    """Sprint E-2 + RB 10.6: restaurant_technology_headlines with freshness gate and fallback."""
    web_scan = report.get("web_scan") or {}
    raw = list(web_scan.get("restaurant_technology") or [])
    today = _report_today(report)
    fresh = _filter_fresh_headlines(raw, today)

    # If fewer than 2 fresh items, return the structured fallback instead
    if len(fresh) < 2:
        # Pass total raw count as proof-of-work for the fallback message
        return _build_restaurant_tech_fallback(report, total_scanned=len(raw))
    return fresh


def _report_today(report: dict) -> "date":
    """Extract today's date from the report dict, defaulting to date.today()."""
    _today = report.get("today")
    if isinstance(_today, str):
        try:
            return date.fromisoformat(_today)
        except ValueError:
            pass
    if isinstance(_today, date):
        return _today
    return date.today()


