    # 021D — load mutation log for relationship delta enrichment.
    # When IME has produced thesis_alignment / engagement_opportunity mutations
    # for a person, surface those descriptions instead of raw activity counts.
    _mutation_log_path = core.CACHE_DIR / "knowledge_mutations.json"
    _muts_by_name: dict[str, dict] = {}
    try:
        if _mutation_log_path.exists():
            _mut_log = json.loads(_mutation_log_path.read_text(encoding="utf-8"))
            _today_str = date.today().isoformat()
            for _m in (_mut_log.get("mutations") or []):
                if (_m.get("applied_at") or "")[:10] == _today_str:
                    _pname = (_m.get("person_name") or "").lower().strip()
                    if _pname and _m.get("type") in (
                        "thesis_alignment_detected", "engagement_opportunity",
                        "watchlist_signal",
                    ):
                        # keep highest-confidence mutation per person
                        prev = _muts_by_name.get(_pname)
                        if not prev or float(_m.get("confidence") or 0) > float(prev.get("confidence") or 0):
                            _muts_by_name[_pname] = _m
    except Exception:  # noqa: BLE001
        pass  # mutation log is optional enrichment — never block brief

