# Markdown rendering
# -----------------------------------------------------------------------------

def _fmt_date(d) -> str:
    if d is None:
        return "—"
    if isinstance(d, str):
        return d
    return d.isoformat()


def _render_source_collection_status(out: list, source_health: dict, report: dict) -> None:
    """DEFECT-020: Mandatory Source Intelligence Collection Status header.

    Renders a concise processing status table for every intelligence source
    before any relationship or opportunity intelligence is shown. Status is
    derived from source_health.json (produced by refresh_sources.py).

    Status values:
      PROCESSED  — source was refreshed today and data is current
      PENDING    — source exists but has not been refreshed today
      FAILED     — source refresh was attempted and failed
      MISSING    — source file not found / not configured
    """
    SOURCE_DISPLAY_ORDER = [
        ("linkedin_delta",       "LinkedIn Export Delta"),
        ("messages",             "Apple Messages"),
        ("calls",                "Apple Calls"),
        ("contacts",             "Apple Contacts"),
        ("whatsapp",             "WhatsApp"),
        ("email:personal",       "Gmail (Personal)"),
        ("email:bridgepoint",    "Gmail (BridgePoint)"),
        ("calendar:personal",    "Calendar (Personal)"),
        ("calendar:bridgepoint", "Calendar (BridgePoint)"),
        ("linkedin_messaging",   "LinkedIn Messages"),
        ("market_signals",       "Industry / Market Signals"),
        ("social_feed",          "LinkedIn Social Feed"),
    ]

    from datetime import date as _date, datetime as _dt, timezone as _tz

    today_iso = report.get("today") or _date.today().isoformat()
    health_sources: dict = (source_health.get("sources") or {}) if isinstance(source_health, dict) else {}

    def _status_for(src_key: str) -> tuple[str, str]:
        """Return (status_label, last_refreshed) for a source key."""
        row = health_sources.get(src_key)
        if row is None:
            # Try prefix match (e.g. "email" matches "email:personal")
            for k, v in health_sources.items():
                if k.startswith(src_key):
                    row = v
                    break
        if row is None:
            return "MISSING", "—"
        status = (row.get("status") or "").lower()
        last_at = row.get("last_refreshed_at") or ""
        if status in ("refreshed", "ok", "fresh"):
            # Check if it was refreshed today
            try:
                ts = _dt.fromisoformat(last_at)
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=_tz.utc)
                if ts.date().isoformat() == today_iso:
                    return "PROCESSED", last_at[:16]
                else:
                    return "PENDING", last_at[:16]
            except (ValueError, TypeError):
                return "PROCESSED", last_at[:16] if last_at else "—"
        elif status in ("failed", "error"):
            return "FAILED", last_at[:16] if last_at else "—"
        elif status in ("stale", "skipped_no_raw_input", "unavailable"):
            return "PENDING", last_at[:16] if last_at else "—"
        else:
            return "MISSING", "—"

    rows = []
    for src_key, display_name in SOURCE_DISPLAY_ORDER:
        status, last_at = _status_for(src_key)
        rows.append((display_name, status, last_at))

    processed = sum(1 for _, s, _ in rows if s == "PROCESSED")
    pending = sum(1 for _, s, _ in rows if s == "PENDING")
    failed = sum(1 for _, s, _ in rows if s == "FAILED")
    missing = sum(1 for _, s, _ in rows if s == "MISSING")

    overall = source_health.get("overall_health") or source_health.get("brief_trustworthiness") or "unknown"

    out.append("## Source Intelligence Collection Status\n")
    out.append(
        f"**Overall:** {overall.upper()} — "
        f"{processed} processed · {pending} pending · {failed} failed · {missing} missing\n"
    )

    STATUS_ICON = {
        "PROCESSED": "✓",
        "PENDING":   "~",
        "FAILED":    "✗",
        "MISSING":   "—",
    }

    out.append("| Source | Status | Last Refresh |")
    out.append("|---|---|---|")
    for display_name, status, last_at in rows:
        icon = STATUS_ICON.get(status, "?")
        out.append(f"| {display_name} | {icon} {status} | {last_at} |")
    out.append("")

    if pending or failed or missing:
        gaps = [name for name, s, _ in rows if s in ("PENDING", "FAILED", "MISSING")]
        out.append(
            f"> **Intelligence gap:** The following sources were not processed before this brief was generated: "
            f"{', '.join(gaps[:6])}{'…' if len(gaps) > 6 else ''}. "
            f"Intelligence derived from these sources may be absent or stale."
        )
        out.append("")

    # DEFECT-024: Show any recent upload receipts from /ingest/upload
    receipt_path = Path(__file__).resolve().parent.parent / ".cache" / "ingest_upload_receipt.json"
    if receipt_path.exists():
        try:
            receipt = json.loads(receipt_path.read_text())
            received = receipt.get("received_at", "")[:19]
            pipeline = receipt.get("pipeline_run", "?")
            iid = receipt.get("ingestion_id", "?")
            dry = " [DRY RUN]" if receipt.get("dry_run") else ""
            out.append(f"**Upload receipt:** `{receipt.get('filename')}` — {pipeline} pipeline — received {received} — ID `{iid}`{dry}")
            # Show ingest delta if available
            ir = receipt.get("ingest_result") or {}
            hc = ir.get("headline_counts") or {}
            if hc:
                out.append(
                    f"  Delta: {hc.get('new_connections',0)} new · "
                    f"{hc.get('company_changes',0)} company changes · "
                    f"{hc.get('role_changes',0)} role changes · "
                    f"{hc.get('disconnections',0)} disconnections"
                )
            out.append("")
        except Exception:
            pass


def render_today_md(report: dict) -> str:
    today = report["today"]
    weekday = report["weekday"]
    summary = report["baseline"]
    settings = core.load_settings()
    out = []
    out.append(f"# Today — {today}\n")
    canonical = report.get("canonical_brief") or {}
    c_sections = canonical.get("sections") or {}
    # RB-2026-09-02: the newer CoS front matter already renders prep proof,
    # command center, priorities, meeting prep, sent-followup state, and source
    # health. Keep diagnostic/API-mirror detail sections opt-in; rendering all
    # computed sections made the daily brief repetitive and materially harder
    # to read.
    _render_detail_sections = bool(
        ((settings.get("daily_briefing") or {}).get("render_legacy_detail_sections"))
    )

    verification_items = c_sections.get("resource_verification_and_freshness_status") or []
    prep = report.get("daily_prep_summary") or {}
    prepared_at = prep.get("prepared_at") or prep.get("generated_at") or prep.get("computed_at")
    totals = prep.get("totals") or {}

    def _render_front_section(title: str, items: list[dict], *, action_label: str = "Recommended action") -> None:
        out.append(f"## {title}\n")
        if not items:
            out.append("_No source-backed items in this section._\n")
            return
        for item in items:
            extras = item.get("extras") or {}
            out.append(
                f"- **[{item.get('disposition')}] {item.get('title')}** "
                f"(`{item.get('grounding')}` / `{item.get('freshness')}`, confidence {item.get('confidence')})"
            )
            if item.get("summary"):
                out.append(f"  - Fact / detected state: {item.get('summary')}")
            if extras.get("signal_timestamp"):
                out.append(f"  - Signal timestamp: {extras.get('signal_timestamp')}")
            if extras.get("confirmed_vs_rumored"):
                out.append(f"  - Confirmed vs rumored: {extras.get('confirmed_vs_rumored')}")
            provenance = item.get("provenance") or {}
            temporal = item.get("temporal_weighting") or {}
            display_policy = item.get("display_policy") or {}
            if provenance:
                out.append(
                    "  - Provenance: "
                    f"{provenance.get('source_class')} / {provenance.get('source_ref_class')}; "
                    f"corroboration={provenance.get('corroboration_count')}; "
                    f"state={item.get('signal_state')}; "
                    f"temporal={temporal.get('bucket')} ({temporal.get('weight')}); "
                    f"display={display_policy.get('policy')}"
                )
            if item.get("why_it_matters"):
                out.append(f"  - Inference / why it matters: {item.get('why_it_matters')}")
            evidence_inference = item.get("evidence_inference") or {}
            missing_evidence = evidence_inference.get("missing_evidence") or []
            alternatives = evidence_inference.get("alternative_explanations") or []
            if alternatives:
                out.append(f"  - Alternative explanations: {'; '.join(alternatives[:3])}")
            if missing_evidence:
                out.append(f"  - Missing evidence: {'; '.join(missing_evidence[:3])}")
            if extras.get("restaurant_operator_impact"):
                out.append(f"  - Restaurant operational effect: {extras.get('restaurant_operator_impact')}")
            if extras.get("restaurant_tech_vendor_implication"):
                out.append(f"  - Restaurant tech implication: {extras.get('restaurant_tech_vendor_implication')}")
            if item.get("recommended_action"):
                out.append(f"  - {action_label}: {item.get('recommended_action')}")
            if item.get("source_refs"):
                out.append(f"  - Source: {', '.join(item.get('source_refs') or [])}")
        out.append("")

    # ---------------------------------------------------------------------
    # Daily Prep Summary (preparation proof) must lead the brief.
    # ---------------------------------------------------------------------
    out.append("## Daily Prep Summary\n")
    out.append("Preparation proof first. RB shows what it refreshed/checked before recommending action.\n")
    if prepared_at:
        out.append(f"- **Prepared at:** {prepared_at}")
    if totals:
        sources_scanned = totals.get("sources_scanned")
        fresh_or_updated = totals.get("fresh_or_updated_sources") or totals.get("fresh_sources")
        stale_or_missing = totals.get("stale_or_missing_sources")
        new_items = totals.get("new_items_processed")
        ri = totals.get("relationship_signals_detected")
        if sources_scanned is not None:
            out.append(f"- **Sources scanned:** {sources_scanned}")
        if fresh_or_updated is not None:
            out.append(f"- **Updated/fresh:** {fresh_or_updated}")
        if stale_or_missing is not None:
            out.append(f"- **Stale/missing:** {stale_or_missing}")
        if new_items is not None:
            out.append(f"- **New items processed:** {new_items}")
        if ri is not None:
            out.append(f"- **RI/action signals detected:** {ri}")
    out.append("")

    if verification_items:
        item = verification_items[0]
        extras = item.get("extras") or {}
        out.append("### Preparation Proof (Source Health)\n")
        out.append(f"- **Brief confidence:** {extras.get('brief_confidence') or item.get('confidence', '').upper()}")
        out.append(f"- **Overall health:** {extras.get('overall_health') or 'unknown'}")
        out.append(f"- **Brief trustworthiness:** {extras.get('brief_trustworthiness') or 'unknown'}")
        out.append(f"- **Generated at:** {extras.get('generated_at') or 'unknown'}")
        out.append(f"- **Summary:** {item.get('summary')}")
        blind = extras.get("known_blind_spots") or []
        out.append(f"- **Known blind spots:** {', '.join(blind[:8]) if blind else 'none detected'}")
        out.append("")
        if _render_detail_sections:
            out.append("| Resource | Access | Freshness | Last successful sync | New items | RI/actions | Recovery |")
            out.append("|---|---|---|---|---:|---:|---|")
            for row in extras.get("source_rows") or []:
                recovery = row.get("recovery_command") or row.get("failed_scan_or_error") or "—"
                out.append(
                    f"| {row.get('source')} | {row.get('access_status')} | {row.get('freshness')} | "
                    f"{row.get('last_successful_sync')} | {row.get('new_items_processed', 0)} | "
                    f"{row.get('relationship_items_detected', 0)} | {recovery} |"
                )
            out.append("")

    # Morning Command Center must follow the prep proof at the top of the brief.
    _render_front_section(
        "Morning Command Center",
        c_sections.get("morning_command_center") or [],
        action_label="Next action",
    )

    # DEFECT-020: Source Intelligence Collection Status remains visible near
    # the top, but not ahead of the prep proof + command center contract.
    source_health = (
        prep.get("source_health")
        or report.get("source_health")
        or {}
    )
    _render_source_collection_status(out, source_health, report)

    weekend = report.get("weekend_guidance")
    if weekend and weekend.get("is_weekend"):
        out.append(f"## {weekend.get('day')} — {weekend.get('mode', 'weekend').replace('_', ' ').title()} Mode\n")
        out.append(f"_{weekend.get('guidance')}_\n")
        focus = weekend.get("recommended_focus") or []
        if focus:
            for f in focus:
                out.append(f"- {f}")
            out.append("")

    # ---------------------------------------------------------------------
    # RB 9.24B / DEFECT-013: discovery proof must follow prep proof.
    # Manual/operator-memory state belongs later unless it changed.
    # ---------------------------------------------------------------------
    _render_front_section(
        "What RB Found Without You Telling It",
        c_sections.get("what_rb_found_without_you_telling_it") or [],
    )
    _render_front_section(
        "Operational Changes From Connected Sources",
        c_sections.get("operational_changes_from_connected_sources") or [],
    )
    if _render_detail_sections:
        _render_front_section(
            "Autonomous Discovery Evidence",
            c_sections.get("autonomous_discovery_evidence") or [],
        )
        _render_front_section(
            "Overnight Delta Intelligence",
            c_sections.get("overnight_delta_intelligence") or [],
        )
        _render_front_section(
            "Email Intelligence Harvest",
            c_sections.get("email_intelligence_harvest") or [],
        )
        _render_front_section(
            "Thesis Confidence & Challenges",
            c_sections.get("thesis_confidence_and_challenges") or [],
        )

    cal = report.get("calendar") or {}
    em = report.get("email") or {}
    cal_today_n = len(cal.get("today") or []) if cal.get("fetched_at") else None
    cal_week_n = sum(len(cal.get(k) or []) for k in ("today", "tomorrow", "this_week")) if cal.get("fetched_at") else None
    em_hits_n = (len(em.get("active_thread_company_hits") or []) + len(em.get("from_baseline") or [])) if em.get("fetched_at") else None

    headline = (
        f"{weekday}. {len(report['crossings'])} active RCs past their dormancy "
        f"threshold. {len(report['loops']['overdue'])} loop(s) past target, "
        f"{len(report['loops']['due_today'])} due today, "
        f"{len(report['loops']['this_week'])} more this week. "
        f"{len(report['active_threads'])} active threads on the board."
    )
    if cal_today_n is not None:
        headline += f" {cal_today_n} meeting(s) today, {cal_week_n} in the next 7 days."
    if em_hits_n is not None:
        headline += f" {em_hits_n} relevant inbox thread(s) from graph or active-thread companies."
    soc = report.get("social") or {}
    if soc.get("fetched_at"):
        soc_n = len(soc.get("from_baseline") or []) + len(soc.get("active_thread_company_hits") or [])
        headline += f" {soc_n} feed post(s) from your network."

    if _render_detail_sections:
        _render_front_section(
            "Relationship / Operational Signal Review",
            c_sections.get("relationship_operational_signal_review") or [],
        )
        _render_front_section("Industry Brief", c_sections.get("industry_brief") or [])
        _render_front_section(
            "Local / Regional Restaurant Environment",
            c_sections.get("local_regional_restaurant_environment") or [],
        )
        _render_front_section(
            "World / Macro / Macroeconomic Impact",
            c_sections.get("world_macro_macroeconomic_impact") or [],
        )
        _render_front_section(
            "Macro Pressure Stack",
            c_sections.get("macro_pressure_stack") or [],
        )
    out.extend(_render_behavioral_intelligence_md(report))
    out.extend(_render_whatsapp_intelligence_md(report))
    out.extend(_render_knowledge_mutations_md())
    if _render_detail_sections:
        _render_front_section(
            "Restaurant Pain Mapping",
            c_sections.get("restaurant_pain_mapping") or [],
        )
        _render_front_section(
            "Franchise Alignment Gap",
            c_sections.get("franchise_alignment_gap") or [],
        )
        _render_front_section(
            "Action Lifecycle State",
            c_sections.get("action_lifecycle_state") or [],
        )
        _render_front_section(
            "Known-State Reminders",
            c_sections.get("known_state_reminders") or [],
        )
    _render_front_section(
        "Delivery Verification",
        c_sections.get("delivery_verification") or [],
    )
    _render_front_section(
        "Canonical Release Status",
        c_sections.get("canonical_release_status") or [],
    )
    _already_rendered_titles = {
        item.get("title")
        for section_key in (
            "morning_command_center",
            "what_rb_found_without_you_telling_it",
            "operational_changes_from_connected_sources",
            "delivery_verification",
            "canonical_release_status",
        )
        for item in (c_sections.get(section_key) or [])
        if item.get("title")
    }
    _render_front_section(
        "Recommended Actions",
        [
            item for item in (c_sections.get("recommended_actions_structured") or [])
            if item.get("title") not in _already_rendered_titles
        ],
        action_label="Suggested next step",
    )
    orchestration_items = c_sections.get("action_orchestration_prompt") or []
    if orchestration_items:
        out.append("## Action Orchestration Prompt\n")
        out.append(orchestration_items[0].get("summary") or "Do you want me to create a to-do list or action loops from these recommendations?")
        out.append("")

    if not _render_detail_sections:
        return "\n".join(out).rstrip() + "\n"

    out.append("---\n")
    out.append("## Operating Snapshot\n")
    out.append(headline + "\n")
    out.append("---\n")

    # Canonical CoS opening — these sections mirror the API contract so a
    # model consuming either markdown or JSON sees the same operating order.
    prep = report.get("daily_prep_summary") or {}
    prep_sources = prep.get("sources") or []
    if _render_detail_sections and prep_sources:
        totals = prep.get("totals") or {}
        out.append("## Daily prep summary\n")
        out.append(
            f"Prepared: `{prep.get('prepared_at') or 'unknown'}`. "
            f"Scanned {totals.get('sources_scanned', 0)} source(s); "
            f"detected {totals.get('relationship_signals_detected', 0)} RI signal(s); "
            f"{totals.get('sources_with_no_actionable_ri', 0)} source(s) had no actionable RI; "
            f"{totals.get('stale_or_missing_sources', 0)} source(s) were stale or missing.\n"
        )
        out.append("| Source | Window | Status | Evidence | RI | Result | Confidence |")
        out.append("|---|---|---|---:|---:|---|---|")
        for row in prep_sources:
            result = "RI found" if row.get("ri_found") else "No actionable RI found"
            if row.get("freshness") != "fresh":
                result += "; refresh recommended"
            out.append(
                f"| {row['source_name']} | {row['scan_window']} | "
                f"{row['scan_status']} / {row['freshness']} | "
                f"{row['evidence_count']} | {row['ri_found']} | "
                f"{result} | {row['confidence']} |"
            )
        out.append("")

    command_items = c_sections.get("morning_command_center") or []
    if _render_detail_sections and command_items:
        out.append("## Morning command center\n")
        out.append(
            "RB identifies what matters and recommends the next operating move. "
            "This is the board for the day, not another dashboard.\n"
        )
        for item in command_items:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            out.append(f"  - {item['summary']}")
            if item.get("recommended_action"):
                out.append(f"  - Do: {item['recommended_action']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    freshness_items = c_sections.get("signal_freshness") or []
    if _render_detail_sections and freshness_items:
        out.append("## Signal freshness\n")
        out.append("Instrumentation state comes first; it controls how much trust to place in every quiet/no-signal conclusion.\n")
        out.append("| Source | State | Grounding | Action |")
        out.append("|---|---|---|---|")
        for item in freshness_items:
            out.append(
                f"| {item['title']} | {item['summary']} | "
                f"{item['grounding']} / {item['freshness']} | {item['recommended_action']} |"
            )
        out.append("")

    top_items = c_sections.get("top_priorities_today") or []
    if _render_detail_sections and top_items:
        out.append("## Top priorities today\n")
        out.append("Pre-ranked CoS operating items. Each one has disposition, grounding, and freshness labels.\n")
        for item in top_items[:8]:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            out.append(f"  - {item['summary']}")
            if item.get("recommended_action"):
                out.append(f"  - Do: {item['recommended_action']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    meeting_items = c_sections.get("meeting_prep_and_deliverables") or []
    if _render_detail_sections and meeting_items:
        out.append("## Meeting prep & deliverables\n")
        out.append(
            "Calendar events that need preparation, deliverable checks, or a tracked prep loop. "
            "RB should offer to create meeting prep for review when context is available.\n"
        )
        for item in meeting_items[:8]:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            out.append(f"  - {item['summary']}")
            out.append(f"  - Do: {item['recommended_action']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    # Sent followups — awaiting response. Sourced from the email overlay's
    # sent_followups section (sprint step 2a) and surfaced here so Todd
    # sees what's pending and what's overdue without scanning his sent
    # mailbox by hand. Overdue items rank above awaiting.
    sf_items = c_sections.get("sent_followups_awaiting_response") or []
    if _render_detail_sections and sf_items:
        out.append("## Sent followups — awaiting response\n")
        out.append(
            "What you sent and haven't heard back on yet. Overdue items "
            "(beyond the expected-response window) are listed first. "
            "Silence is not rejection.\n"
        )
        for item in sf_items[:8]:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            out.append(f"  - {item['summary']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    # RI Events — Last 24 Hours.
    # Surfaces durable RI captures (per P-021) so the brief proves what
    # was persisted vs. proposed vs. uploaded-but-historical. Empty if
    # no events landed in the window — silent rather than chatty.
    rie = report.get("ri_events_recent") or {}
    rie_total = sum(len(rie.get(k) or []) for k in (
        "newly_captured", "proposed_unconfirmed", "historical_uploaded", "rejected_today",
    ))
    if rie.get("available") and rie_total > 0:
        out.append("## RI Events — Last 24 Hours\n")
        out.append(
            "Captures from the RI event stream (`system/ri_events/`). "
            "Each line names the event date, signal, persistence state, and "
            "matched entities. Use this to track what RB has actually "
            "remembered vs. what's still waiting for your confirm.\n"
        )

        def _ri_line(ev: dict) -> str:
            ev_at = (ev.get("event_at") or "")[:10]
            sig = (ev.get("signal") or {}).get("type") or "manual_relationship_signal"
            people = [
                p.get("matched_id") or p.get("raw") or "?"
                for p in (ev.get("entities") or {}).get("people") or []
            ]
            companies = [
                c.get("matched_id") or c.get("raw") or "?"
                for c in (ev.get("entities") or {}).get("companies") or []
            ]
            who = ", ".join(people[:3]) or "—"
            if companies:
                who += " · " + " / ".join(companies[:2])
            trace = ev.get("trace_id")
            trace_part = f" (trace {trace})" if trace else ""
            return f"- **{ev_at}** — {sig} :: {who}{trace_part}"

        if rie.get("newly_captured"):
            out.append("### Newly captured (persisted)\n")
            for ev in rie["newly_captured"][:10]:
                out.append(_ri_line(ev))
            out.append("")

        if rie.get("proposed_unconfirmed"):
            out.append("### Proposed (awaiting your confirm)\n")
            for ev in rie["proposed_unconfirmed"][:10]:
                out.append(_ri_line(ev))
                bundle_id = (ev.get("persistence") or {}).get("proposed_mutation_bundle_id")
                if bundle_id:
                    out.append(
                        f"  - Confirm: `POST /ri_events/{ev.get('event_id')}/confirm` "
                        f"with the accept/reject lists from the original review response."
                    )
            out.append("")

        if rie.get("historical_uploaded"):
            out.append("### Historical artifacts uploaded today (not fresh momentum)\n")
            out.append(
                "These were captured today but the underlying event happened >14 "
                "days ago. They route to evidence-only; daily-brief momentum is "
                "unchanged.\n"
            )
            for ev in rie["historical_uploaded"][:5]:
                ev_at = (ev.get("event_at") or "")[:10]
                cap_at = (ev.get("captured_at") or "")[:10]
                out.append(f"- captured {cap_at} / occurred {ev_at} :: " + _ri_line(ev).removeprefix("- "))
            out.append("")

        if rie.get("rejected_today"):
            out.append("### Rejected today\n")
            for ev in rie["rejected_today"][:5]:
                out.append(_ri_line(ev))
            out.append("")

    # Active threads — the context lens behind the canonical priority list.
    out.append("## Active threads\n")
    if report["active_threads"]:
        out.append(
            "Strategic contexts currently in motion. Every section below should be read through "
            "these — they are the lens, not background.\n"
        )
        # High-boost threads in a small bold call-out, others in a compact table
        high = [t for t in report["active_threads"] if t.get("boost_for_brief") == "high"]
        med = [t for t in report["active_threads"] if t.get("boost_for_brief") == "medium"]
        low = [t for t in report["active_threads"] if t.get("boost_for_brief") not in ("high", "medium")]
        for t in high:
            out.append(f"\n**{t['title']}** (`{t['id']}`)")
            if t.get("current_state"):
                out.append(f"\n{t['current_state']}")
        if med or low:
            out.append("")
            out.append("| Title | Type | Target close | Boost |")
            out.append("|---|---|---|---:|")
            for t in med + low:
                out.append(
                    f"| {t['title']} | {t.get('type','—')} | "
                    f"{t.get('target_close','—')} | x{t.get('boost_score','1.0')} |"
                )
    else:
        out.append("(none) — no active threads declared in `system/active_threads.yaml`.")

    out.append("")

    # ----------------------------------------------------------------------
    # Relationship signals — last 24 hours (CoS section).
    # Leads the brief: priorities → signals → reconciliation → ignore → stale.
    # ----------------------------------------------------------------------
    rsr = report.get("relationship_signals") or {}
    sigs = rsr.get("signals") or []
    recons = rsr.get("reconciliation_needed") or []
    stale = rsr.get("stale_sources") or []
    ignored = rsr.get("what_to_ignore") or []
    out.append("## Relationship signals — last 24 hours\n")
    out.append(
        "This is the CoS layer of the brief. Industry intelligence is "
        "subordinate to relationship and action intelligence; only items with "
        "named people, named companies, or active-thread implications appear "
        "here. Each signal carries reasoning, evidence, and a recommended "
        "next move."
    )
    out.append("")
    counts = rsr.get("signal_counts_by_relevance") or {}
    src_counts = rsr.get("signal_counts_by_source") or {}
    out.append(
        f"**Window:** {rsr.get('window_start','')[:16]} → "
        f"{rsr.get('window_end','')[:16]} ({rsr.get('window_hours', 24)}h). "
        f"**Volume:** {counts.get('high',0)} high · {counts.get('medium',0)} medium · "
        f"{counts.get('low',0)} low. **By source:** "
        f"email {src_counts.get('email',0)}, calendar {src_counts.get('calendar',0)}, "
        f"messages/calls {src_counts.get('messages_calls',0)}, "
        f"social {src_counts.get('social',0)}, outbound {src_counts.get('social_outbound',0)}."
    )
    out.append("")
    # Top priorities — high-relevance signals, deduped per (contact, source)
    high = [s for s in sigs if s.get("strategic_relevance") == "high"]
    medium = [s for s in sigs if s.get("strategic_relevance") == "medium"]
    if high or medium:
        # Per Tenet 13 / the 2026-05-18 grounding test, every surfaced
        # priority carries an explicit grounding label so the operator
        # can tell a directly-observed signal from a synthesis and a
        # stale-feed conclusion from a fresh one.
        out.append(
            "_Grounding tags below: `system_detected` (observed in a "
            "connected source this window), `inferred` (RB synthesis from "
            "rules), `manual_user_provided` (typed by you in "
            "active_threads.yaml or a card), `stale_source_limited` "
            "(source feed is past its freshness threshold — read with "
            "caution)._\n"
        )
    if high:
        out.append("### Top priorities\n")
        seen: set[tuple] = set()
        for s in high:
            key = (s.get("contact_id") or s.get("name"), s.get("source"), s.get("signal_type"))
            if key in seen:
                continue
            seen.add(key)
            thread_tag = (" — thread: " + ", ".join(s["active_thread_ids"])) if s.get("active_thread_ids") else ""
            grounding = s.get("grounding", "system_detected")
            freshness = s.get("freshness", "fresh")
            label_bits = [f"grounding=`{grounding}`"]
            if freshness != "fresh":
                label_bits.append(f"freshness=`{freshness}`")
            out.append(
                f"- **{s.get('name') or '—'}** "
                f"({s['source']}, {s['signal_type']}, strength {s['signal_strength']:.2f}, "
                f"{' · '.join(label_bits)})"
                f"{thread_tag}"
            )
            out.append(f"  - Why: {s['reasoning']}")
            out.append(f"  - Do: {s['recommended_action']}")
            if s.get("reconciliation_prompt"):
                out.append(f"  - Reconcile: {s['reconciliation_prompt']}")
        out.append("")
    if medium:
        out.append("### Worth attention\n")
        seen2: set[tuple] = set()
        for s in medium[:10]:
            key = (s.get("contact_id") or s.get("name"), s.get("source"), s.get("signal_type"))
            if key in seen2:
                continue
            seen2.add(key)
            thread_tag = (" — thread: " + ", ".join(s["active_thread_ids"])) if s.get("active_thread_ids") else ""
            grounding = s.get("grounding", "system_detected")
            freshness = s.get("freshness", "fresh")
            label = f"grounding=`{grounding}`"
            if freshness != "fresh":
                label += f" · freshness=`{freshness}`"
            out.append(
                f"- {s.get('name') or '—'} "
                f"({s['source']}, {s['signal_type']}, strength {s['signal_strength']:.2f}, {label})"
                f"{thread_tag} — {s['recommended_action']}"
            )
        out.append("")
    if not (high or medium):
        out.append("No relationship signals crossed the medium/high threshold in the window. "
                   "Low-relevance items remain in the raw report dict.\n")
    if recons:
        out.append("### Reconciliation needed\n")
        out.append(
            "Narrow questions where RB has signal but not enough certainty to mutate state. "
            "Resolving these improves the graph without guessing.\n"
        )
        for r in recons[:12]:
            safe = "safe to write" if r.get("safe_to_write") else "needs confirmation"
            out.append(f"- **[{r['urgency']}]** {r['prompt']}")
            out.append(f"  - Suggested: `{r['recommended_mutation']}` ({safe}).")
        out.append("")
    if stale:
        out.append("### Stale-source warnings\n")
        out.append(
            "These feeds have not refreshed inside their freshness threshold. "
            "Any 'no new signals from this source' conclusion is unreliable "
            "until refresh runs.\n"
        )
        for s in stale:
            age = s.get("age_hours")
            age_label = f"{age}h stale" if age is not None else "never fetched"
            rec_block = s.get("recommended_refresh") or {}
            caveat = rec_block.get("caveat") or s.get("recommendation") or ""
            cmd = rec_block.get("command")
            out.append(
                f"- **{s['name']}**: {age_label} (threshold {s['threshold_hours']}h). "
                f"{caveat}"
            )
            if cmd:
                out.append(f"  - Refresh: `{cmd}`")
        out.append("")
    if ignored:
        out.append("### What RB ignored\n")
        out.append(
            "RB explicitly chose not to surface these. Listed so suppression is visible and "
            "auditable, per Tenet 13.\n"
        )
        for w in ignored:
            out.append(f"- {w['category']} ({w['count']}): {w['reason']}")
        out.append("")

    # Calendar overlay — meetings today / tomorrow / this week
    cal = report.get("calendar") or {}
    if cal.get("fetched_at"):
        out.append("## Calendar — what's on the books\n")
        stale_note = " *(stale — refresh)*" if cal.get("stale") else ""
        accts = cal.get("accounts_seen") or []
        accts_label = ", ".join(accts) if accts else "—"
        out.append(f"Source freshness: {cal['fetched_at']}{stale_note}. Accounts: {accts_label}\n")
        any_shown = False
        for label, key in (("Today", "today"), ("Tomorrow", "tomorrow"), ("This week", "this_week")):
            events = cal.get(key) or []
            if not events:
                continue
            any_shown = True
            out.append(f"\n**{label}** ({len(events)})\n")
            for ev in events:
                time = (ev.get("start") or "")[11:16]
                day = (ev.get("start") or "")[:10]
                acct_tag = f" [{ev['account_id']}]" if ev.get("account_id") else ""
                thread_tag = (" — thread: " + ", ".join(ev["matched_threads"])) if ev.get("matched_threads") else ""
                co_tag = (" / company: " + ", ".join(ev["active_thread_company_hits"])) if ev.get("active_thread_company_hits") else ""
                out.append(f"- {day} {time}{acct_tag} — **{ev['title']}**{thread_tag}{co_tag}")
                for a in ev["attendees_matched"]:
                    if a["id"]:
                        out.append(f"  - ✓ {a['name']} ({a['signal_class']}/{a.get('rc_tier') or '—'}) — `{a['email']}`")
                    else:
                        out.append(f"  - · `{a['email']}` — **not in baseline**")
        if not any_shown:
            out.append("\nNo events on the calendar in the next 7 days.")
        # Attendees-not-in-baseline summary
        if cal.get("attendees_not_in_baseline"):
            out.append("\n**Attendees in the week's calendar who aren't in baseline:**")
            for a in cal["attendees_not_in_baseline"][:10]:
                ev = a.get("last_seen_event") or {}
                out.append(f"- `{a['email']}` (in {a['count']} event{'s' if a['count']>1 else ''}, next: {ev.get('start','—')[:10]} {ev.get('title','')[:60]})")

    # Email overlay — what's hitting the inbox from your graph or active-thread companies
    em = report.get("email") or {}
    if em.get("fetched_at"):
        out.append("\n## Inbox — signal from your graph\n")
        stale_note = " *(stale — refresh)*" if em.get("stale") else ""
        accts = em.get("accounts_seen") or []
        accts_label = ", ".join(accts) if accts else "—"
        out.append(f"Source freshness: {em['fetched_at']}{stale_note}. Accounts: {accts_label}\n")

        if em.get("active_thread_company_hits"):
            out.append("\n**Active-thread company hits** (sender not yet in baseline; recommend promoting):\n")
            for h in em["active_thread_company_hits"]:
                mark = "•" if h["unread"] else " "
                acct_tag = f" [{h['account_id']}]" if h.get("account_id") else ""
                out.append(f"- {mark} {h['last_message_at'][:10]}{acct_tag} — `{h['sender_email']}` — *{h['subject'][:80]}*")
                out.append(f"  threads: {','.join(h['active_thread_ids'])}")
                if h.get("snippet"):
                    out.append(f"  > {h['snippet'][:160]}")
        if em.get("from_baseline"):
            out.append(f"\n**From contacts in baseline** ({len(em['from_baseline'])}):\n")
            for r in em["from_baseline"][:10]:
                mark = "•" if r["unread"] else " "
                tier = r["match"].get("rc_tier") or "—"
                tag = (" — thread: " + ", ".join(r["matched_threads"])) if r.get("matched_threads") else ""
                acct_tag = f" [{r['account_id']}]" if r.get("account_id") else ""
                out.append(f"- {mark} {r['last_message_at'][:10]}{acct_tag} — {r['match']['name']} ({r['match']['signal_class']}/{tier}){tag} — *{r['subject'][:80]}*")
        if not em.get("from_baseline") and not em.get("active_thread_company_hits"):
            out.append("\nNothing in the inbox matches a baseline contact or active-thread company.")
        if em.get("noise_skipped") or em.get("self_sent_skipped"):
            out.append(
                f"\n_Filtered: {em.get('noise_skipped',0)} newsletter/no-reply, "
                f"{em.get('self_sent_skipped',0)} self-sent._"
            )

    # Social overlay — what your graph is posting about
    social = report.get("social") or {}
    if social.get("fetched_at"):
        out.append("\n## Network signal — what your graph is posting about\n")
        stale_note = " *(stale — refresh)*" if social.get("stale") else ""
        src = social.get("source") or "unknown"
        out.append(f"Source: {src}, fetched {social['fetched_at']}{stale_note}\n")

        if social.get("from_baseline"):
            out.append(f"\n**Posts from contacts in your baseline** ({len(social['from_baseline'])}):\n")
            for r in social["from_baseline"][:10]:
                tier = r["match"].get("rc_tier") or "—"
                tag = (" — thread: " + ", ".join(r["matched_threads"])) if r.get("matched_threads") else ""
                out.append(f"- {(r.get('posted_at') or '')[:10]} — **{r['match']['name']}** ({r['match']['signal_class']}/{tier}){tag}")
                out.append(f"  > {r['text'][:240]}")
                eng = r.get("engagement") or {}
                if any(v is not None for v in eng.values()):
                    out.append(f"  _likes: {eng.get('likes','—')}, comments: {eng.get('comments','—')}, shares: {eng.get('shares','—')}_")

        if social.get("active_thread_company_hits"):
            out.append(f"\n**Posts touching an active-thread company** ({len(social['active_thread_company_hits'])}):\n")
            for r in social["active_thread_company_hits"][:5]:
                out.append(f"- {(r.get('posted_at') or '')[:10]} — {r.get('author_name')} — companies: {', '.join(r.get('active_thread_company_hits') or [])}")
                out.append(f"  > {r['text'][:240]}")

        if social.get("topic_signal"):
            out.append("\n**Topic signal** — active-thread companies appearing in multiple posts in the window:\n")
            for t in social["topic_signal"]:
                out.append(f"- {t['post_count']}× **{t['company']}**")

        if social.get("authors_not_in_baseline"):
            out.append("\n**Recurring authors not in baseline** (2+ posts or active-thread hits):")
            for a in social["authors_not_in_baseline"][:10]:
                co = (f" — companies: {', '.join(a['company_hits'])}") if a["company_hits"] else ""
                out.append(f"- {a['count']}× {a['name']}{co}")

        if not (social.get("from_baseline") or social.get("active_thread_company_hits")):
            out.append("\nFeed captured but nothing matched the baseline or an active thread.")

    # Social outbound — engagement on YOUR posts + recommendations
    # DEFECT-023: Only surface own-post section when actual engagement signals exist.
    # Showing the user their own post content provides zero intelligence.
    # The intelligence is the reaction, not the post.
    soc_out = report.get("social_outbound") or {}
    _suppress_own_posts = report.get("_cos_suppress_own_posts", True)
    _has_engagement = (
        bool(soc_out.get("engagement_by_contact"))
        or bool(soc_out.get("engagement_silence"))
        or bool(soc_out.get("topic_engagement_map"))
        or int((soc_out.get("signal_counts") or {}).get("social_outbound", 0)) > 0
    )
    if soc_out.get("fetched_at") and (_has_engagement or not _suppress_own_posts):
        out.append("\n## Your posts — engagement signal\n")
        stale_note = " *(stale — refresh)*" if soc_out.get("stale") else ""
        out.append(f"Source freshness: {soc_out['fetched_at']}{stale_note}\n")

        if soc_out.get("recent_posts"):
            out.append(f"\n**Posts in the last 30 days** ({len(soc_out['recent_posts'])}):\n")
            for p in soc_out["recent_posts"][:5]:
                eng = p.get("engagement_totals") or {}
                tag = (" — threads: " + ",".join(p["active_thread_ids"])) if p.get("active_thread_ids") else ""
                out.append(f"- {(p.get('posted_at') or '')[:10]}{tag} — likes {eng.get('likes','—')}, comments {eng.get('comments','—')}, shares {eng.get('shares','—')}")
                out.append(f"  > {(p.get('text') or '')[:200]}")

        if soc_out.get("engagement_by_contact"):
            out.append(f"\n**Engagement-by-contact** (DRR-weighted) — your top engagers:")
            out.append("\n| Contact | Tier | Comp. | likes / comments / shares | Last engagement |")
            out.append("|---|---|---:|---|---|")
            for c in soc_out["engagement_by_contact"][:10]:
                tier = c.get("rc_tier") or "—"
                out.append(f"| **{c['name']}** | {c['signal_class']}/{tier} | {c['composite']} | {c['total_likes']}/{c['total_comments']}/{c['total_shares']} | {(c.get('last_engagement_at') or '—')[:10]} |")

        if soc_out.get("engagement_silence"):
            names = ", ".join(s["name"] for s in soc_out["engagement_silence"][:8])
            out.append(f"\n**Engagement silence** — used to engage, went quiet: {names}.")

        if soc_out.get("topic_engagement_map"):
            top_topics = ", ".join(f"`{t['topic']}` ({t['total_engagement_score']})"
                                   for t in soc_out["topic_engagement_map"][:5])
            out.append(f"\n**Top topics by engagement:** {top_topics}.")

    # Direct interaction overlay — phone calls + text messages
    interaction = report.get("interaction") or {}
    if interaction.get("fetched_at"):
        out.append("\n## Direct interaction signal — calls + messages\n")
        stale_note = " *(stale — refresh)*" if interaction.get("stale") else ""
        totals = interaction.get("totals") or {}
        out.append(f"Source: macOS Messages + Call History, fetched {interaction['fetched_at']}{stale_note}\n")
        out.append(
            f"{totals.get('messages_in_window',0)} messages, "
            f"{totals.get('calls_in_window',0)} calls in window. "
            f"{totals.get('matched_count',0)} contacts matched, "
            f"{totals.get('unmatched_count',0)} unmatched events.\n"
        )

        if interaction.get("matched_contacts"):
            out.append("\n**Matched contacts** — direct interaction in last 30 days:\n")
            out.append("| Contact | Tier | Msgs (in/out) | Calls (in/out/missed) | Last |")
            out.append("|---|---|---|---|---|")
            for c in interaction["matched_contacts"][:12]:
                tier = c.get("rc_tier") or "—"
                out.append(
                    f"| **{c['name']}** | {c['signal_class']}/{tier} | "
                    f"{c['messages_in']}/{c['messages_out']} | "
                    f"{c['calls_in']}/{c['calls_out']}/{c['calls_missed']} | "
                    f"{(c.get('last_interaction_at') or '')[:10]} |"
                )

        if interaction.get("proposed_last_touch_updates"):
            out.append(
                f"\n**Proposed `last_touch` updates** "
                f"({len(interaction['proposed_last_touch_updates'])}) — apply with "
                f"`python3 system/scripts/interaction_overlay.py --apply-last-touch`:\n"
            )
            for u in interaction["proposed_last_touch_updates"][:8]:
                gap = u.get("gap_days_since_current")
                gap_label = f"{gap}d stale" if gap else "no prior touch"
                out.append(
                    f"- **{u['name']}**: `{u.get('current_last_touch') or '(none)'}` → "
                    f"`{u['proposed_last_touch']}` ({gap_label}). Evidence: {u['evidence']}."
                )

        if interaction.get("unmatched_recurring_handles"):
            out.append(
                f"\n**Unmatched recurring handles** (3+ events from a number not in "
                f"baseline) — promotion candidates:\n"
            )
            for u in interaction["unmatched_recurring_handles"][:8]:
                out.append(
                    f"- `{u['handle']}` — {u['events']} events, last "
                    f"{(u.get('last_at') or '')[:10]}, "
                    f"services: {','.join(u['services'])}"
                )

    # Post recommendations
    recs = report.get("post_recommendations") or []
    if recs:
        out.append("\n## Posting opportunities\n")
        out.append("Recommendations grounded in active threads + engagement history.\n")
        for r in recs[:6]:
            out.append(f"\n- **[{r['impact'].upper()}]** {r['title']}")
            out.append(f"  _{r['rationale']}_")

    out.append("")
    # Crossings
    out.append("## Crossings\n")
    if report["crossings"]:
        out.append("Sorted by overage, most overdue first.\n")
        out.append("| Days overdue | Name | Tier | Last touch | Company | Circles |")
        out.append("|---:|---|---|---|---|---|")
        for c in report["crossings"]:
            circles = ", ".join(f"`{x}`" for x in c["circles"]) or "—"
            out.append(
                f"| **{c['overage']}** | {c['name']} | {c['tier']} | "
                f"{_fmt_date(c['last_touch'])} ({c['days_ago']}d ago) | "
                f"{c['company'] or '—'} | {circles} |"
            )
    else:
        out.append("(none) — every ACTIVE RC is inside its tier threshold.\n")
    if report["no_last_touch_rcs"]:
        names = ", ".join(c["name"] for c in report["no_last_touch_rcs"])
        out.append(
            f"\n**No `last_touch` on record:** {names}. Invisible to the dormancy "
            "engine until a date is added — surfaced under the gap section below.\n"
        )

    # Loops
    out.append("\n## Loops\n")
    if report["loops"]["overdue"]:
        out.append("**Past target:**\n")
        out.append("| ID | Target | Party | Loop |")
        out.append("|---|---|---|---|")
        for L in report["loops"]["overdue"]:
            out.append(f"| {L['id']} | {L['target']} | {L['party']} | {L['description']} |")
    else:
        out.append("**Past target:** (none) — clean board.\n")
    if report["loops"]["due_today"]:
        out.append("\n**Due today:**\n")
        out.append("| ID | Party | Loop |")
        out.append("|---|---|---|")
        for L in report["loops"]["due_today"]:
            out.append(f"| {L['id']} | {L['party']} | {L['description']} |")
    if report["loops"]["this_week"]:
        out.append("\n**Closing this week (through Friday close of business):**\n")
        out.append("| Target | ID | Party |")
        out.append("|---|---|---|")
        for L in report["loops"]["this_week"]:
            out.append(f"| {L['target']} | {L['id']} | {L['party']} |")
    if (report.get("loops") or {}).get("future"):
        out.append("\n**Upcoming (beyond this week):**\n")
        out.append("| Target | ID | Party |")
        out.append("|---|---|---|")
        for L in (report.get("loops") or {}).get("future") or []:
            out.append(f"| {L['target']} | {L['id']} | {L['party']} |")

    # Strategic operator movements. This is the persistent entity lane,
    # not the market/news lane. It is rendered only when the overlay has
    # source-backed feeder matches or persisted recent movements.
    op_items = c_sections.get("strategic_operator_movements") or []
    sor_block = report.get("strategic_operators") or {}
    if op_items:
        out.append("\n## Strategic operator movements\n")
        out.append(
            "Persistent operator intelligence. These are entity-grounded movements "
            "or feeder matches interpreted through influence, relationship value, "
            "operational pressure, ecosystem impact, and future opportunity.\n"
        )
        for item in op_items[:5]:
            extras = item.get("extras") or {}
            scores = extras.get("scores") or {}
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            if item.get("summary"):
                out.append(f"  - Movement: {item['summary']}")
            out.append(
                "  - Strategic read: "
                + "; ".join(
                    x for x in [
                        f"entity={extras.get('entity_type')}" if extras.get("entity_type") else "",
                        f"watchlist={extras.get('watchlist_bucket')}" if extras.get("watchlist_bucket") else "",
                        f"proximity={extras.get('relationship_proximity')}" if extras.get("relationship_proximity") else "",
                        f"priority={scores.get('follow_up_priority')}" if scores.get("follow_up_priority") else "",
                    ]
                    if x
                )
            )
            score_text = ", ".join(
                x for x in [
                    f"influence {scores.get('influence')}" if scores.get("influence") else "",
                    f"relationship value {scores.get('relationship_value')}" if scores.get("relationship_value") else "",
                    f"operational pressure {scores.get('operational_pressure')}" if scores.get("operational_pressure") else "",
                    f"ecosystem impact {scores.get('ecosystem_impact')}" if scores.get("ecosystem_impact") else "",
                    f"future opportunity {scores.get('future_opportunity')}" if scores.get("future_opportunity") else "",
                ]
                if x
            )
            if score_text:
                out.append(f"  - Categorical scores: {score_text}")
            if extras.get("mutual_connections"):
                out.append(
                    "  - Network overlap: "
                    + ", ".join(f"`{m}`" for m in extras["mutual_connections"][:6])
                )
            if item.get("why_it_matters"):
                out.append(f"  - Why this matters: {item['why_it_matters']}")
            if item.get("recommended_action"):
                out.append(f"  - Recommended action: {item['recommended_action']}")
        out.append("")
    elif sor_block and not sor_block.get("error"):
        out.append("\n## Strategic operator movements\n")
        out.append(
            f"_No source-backed operator movements surfaced._ "
            f"{sor_block.get('operator_count', 0)} persistent operator(s) remain on watch; "
            f"{sor_block.get('recent_movement_count', 0)} recent movement(s), "
            f"{sor_block.get('market_signal_match_count', 0)} feeder match(es).\n"
        )

    # Market and restaurant-tech context. Subordinate to relationship
    # intelligence — placed AFTER operational sections so the brief leads
    # with action, not industry commentary. Only populated when
    # system/inbox/market_signals.json carries source-backed items;
    # otherwise the freshness section above already reported the lane as
    # missing/stale.
    ind_items = c_sections.get("condensed_industry_context") or []
    msr_block = report.get("market_signals") or {}
    if ind_items:
        out.append("\n## Market and restaurant-tech context\n")
        out.append(
            "Source-backed market, vendor, macro, and industry context. "
            "This remains subordinate to the relationship operating board and "
            "does not replace persistent strategic operator records.\n"
        )
        for item in ind_items[:7]:
            extras = item.get("extras") or {}
            out.append(
                f"- **[{item['disposition']}] {item['title']}** "
                f"(`{item['grounding']}` / `{item['freshness']}`, confidence {item['confidence']})"
            )
            if item.get("summary"):
                out.append(f"  - Signal: {item['summary']}")
            if item.get("why_it_matters"):
                out.append(f"  - Why this matters: {item['why_it_matters']}")
            if extras.get("second_order_impact"):
                out.append(f"  - Second-order impact: {extras['second_order_impact']}")
            if extras.get("restaurant_operator_impact"):
                out.append(f"  - Restaurant/operator impact: {extras['restaurant_operator_impact']}")
            if extras.get("restaurant_tech_vendor_implication"):
                out.append(f"  - Restaurant-tech implication: {extras['restaurant_tech_vendor_implication']}")
            if extras.get("relationship_opportunity"):
                out.append(f"  - Relationship opportunity: {extras['relationship_opportunity']}")
            if item.get("recommended_action"):
                out.append(f"  - Recommended action: {item['recommended_action']}")
            if extras.get("timing_priority"):
                out.append(f"  - Timing priority: `{extras['timing_priority']}`")
        out.append("")
    elif msr_block and not msr_block.get("has_data"):
        # Explicitly say the lane is empty rather than silently omitting it.
        out.append("\n## Market and restaurant-tech context\n")
        out.append(
            f"_Under-instrumented._ {msr_block.get('stale_reason') or ''} "
            f"No synthesized market thesis is rendered here — the brief is "
            f"source-backed only.\n"
        )

    loop_prompt = c_sections.get("suggested_loop_creation") or []
    if loop_prompt:
        out.append("\n## Suggested loop creation\n")
        for item in loop_prompt:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(f"- **{item['title']}**")
            out.append(f"  - {item['summary']}")
            out.append(f"  - Ask: {item['recommended_action']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    closeout_items = c_sections.get("end_of_day_closeout") or []
    if closeout_items:
        out.append("\n## End-of-day closeout\n")
        for item in closeout_items:
            actions = ", ".join(f"`{a}`" for a in item.get("action_options", [])[:4])
            out.append(f"- **{item['title']}**")
            out.append(f"  - {item['summary']}")
            out.append(f"  - Do: {item['recommended_action']}")
            if actions:
                out.append(f"  - Actions: {actions}")
        out.append("")

    # Quiet zones
    out.append("\n## Quiet zones\n")
    if report["quiet_zones"]:
        out.append("Inner-tier RCs inside the 30-day window — good standing.\n")
        out.append("| Name | Last touch | Days ago | Company |")
        out.append("|---|---|---:|---|")
        for q in report["quiet_zones"]:
            out.append(f"| {q['name']} | {_fmt_date(q['last_touch'])} | {q['days_ago']} | {q['company'] or '—'} |")
    else:
        out.append("(none) — no inner-tier RCs are currently inside their window.\n")

    # DRR top — boosted by active threads
    out.append("\n## Highest-relevance right now\n")
    if report["drr_top"]:
        out.append(
            "DRR ranking with active-thread boost applied. `x1.00` means no open "
            "thread names this contact; higher means a thread is in motion that touches them.\n"
        )
        out.append("| Score | Boost | Thread(s) | Class | Tier | Name |")
        out.append("|---:|---:|---|---|---|---|")
        for r in report["drr_top"][:12]:
            t = ", ".join(r.get("matched_threads") or []) or "—"
            out.append(
                f"| **{r['score']:.1f}** | x{r['thread_boost']:.2f} | {t} | "
                f"{r.get('signal_class') or '—'} | {r.get('rc_tier') or '—'} | {r['name']} |"
            )

    # Gap surface
    out.append("\n## \"I don't know\" gap surface\n")
    out.append("Per Tenet 13. Surfaced explicitly so silence is acknowledged.\n")
    if report["no_last_touch_rcs"]:
        names = ", ".join(c["name"] for c in report["no_last_touch_rcs"])
        out.append(f"- **RCs without `last_touch`:** {names}.")
    if report["missing_cards"]:
        names = ", ".join(f"{c['name']} ({c['tier']})" for c in report["missing_cards"])
        out.append(f"- **RCs without a card file:** {names}.")
    if report["contact_gaps"]:
        out.append("- **Inner/broader RCs missing email or phone:**")
        out.append("")
        out.append("  | Name | Tier | Missing |")
        out.append("  |---|---|---|")
        for g in report["contact_gaps"]:
            out.append(f"  | {g['name']} | {g['tier']} | {', '.join(g['missing'])} |")

    # Circles snapshot
    out.append("\n## Circles\n")
    out.append(f"{len(report['circles'])} total.\n")
    out.append("| Circle | Type | Status |")
    out.append("|---|---|---|")
    for c in report["circles"]:
        out.append(f"| `{c['id']}` | {c['circle_type']} | {c['status'] or '—'} |")

    # RB 9.20 — CoS judgment rendering (DEFECT-008 fix).
    # Hard truths, negative space, and execution options must appear in every brief.
    # These are not optional analysis — they are posture enforcement.
    # RB 9.20 — CoS judgment rendering (DEFECT-008 fix).
    # Key schema from cos_judgment.py:
    #   hard_truths items: claim, why_it_matters, evidence, confidence, grounding, recommended_disposition
    #   what_is_not_happening: list of {type, observed_absence, why_it_matters, source_ref}
    #   execution_options: list of {action, target, reason, requires_confirmation, endpoint}
    _cos_j = report.get("cos_judgment") or {}
    _hard_truths = _cos_j.get("hard_truths") or []
    _what_not = report.get("what_is_not_happening") or []
    _exec_opts = report.get("execution_options") or []
    _cos_err = report.get("cos_judgment_error")

    if _cos_err:
        out.append("\n## CoS Judgment Layer\n")
        out.append(f"_CoS judgment unavailable: {_cos_err}_\n")
    elif _hard_truths or _what_not or _exec_opts:
        out.append("\n## CoS Judgment — Hard Truths\n")
        out.append(
            "Evidence-bound findings. No invented criticism. "
            "When evidence is absent: RB is under-instrumented here.\n"
        )
        if _hard_truths:
            for ht in _hard_truths:
                if isinstance(ht, dict):
                    out.append(f"- **{ht.get('claim') or 'Hard truth'}:** {ht.get('evidence') or ''}")
                    if ht.get("why_it_matters"):
                        out.append(f"  - Why it matters: {ht['why_it_matters']}")
                    if ht.get("recommended_disposition"):
                        out.append(f"  - Disposition: `{ht['recommended_disposition']}`")
        else:
            out.append("_No hard truths detected from current evidence._\n")
        out.append("")

        if _what_not:
            out.append("\n## What Is Not Happening\n")
            out.append("Detected strategic silences and absences. These are as important as what is present.\n")
            for ab in _what_not:
                if isinstance(ab, dict):
                    out.append(f"- **{ab.get('observed_absence') or ab.get('type') or 'Absence'}**")
                    if ab.get("why_it_matters"):
                        out.append(f"  - Why it matters: {ab['why_it_matters']}")
                    if ab.get("recommended_disposition"):
                        out.append(f"  - Disposition: `{ab['recommended_disposition']}`")
            out.append("")

        if _exec_opts:
            out.append("\n## Execution Options\n")
            out.append(
                "Concrete closure options. Write-like actions require confirmation.\n"
            )
            for opt in _exec_opts:
                if isinstance(opt, dict):
                    req_conf = opt.get("requires_confirmation", True)
                    conf_label = " _(requires confirmation)_" if req_conf else ""
                    label = f"{opt.get('action') or 'option'}: {opt.get('target') or ''}".strip(": ")
                    out.append(f"- **{label}**{conf_label}: {opt.get('reason') or ''}")
                    if opt.get("endpoint"):
                        out.append(f"  - Endpoint: {opt['endpoint']}")
            out.append("")

    # Network state
    bb = report["baseline"]
    sig = bb["by_signal_class"]
    out.append("\n## State of the network\n")
    normalized_sig = sorted(
        ((str(k), v) for k, v in sig.items() if k is not None and str(k).strip()),
        key=lambda item: item[0],
    )
    parts = " · ".join(f"{k} {v}" for k, v in normalized_sig)
    rc_tiers = bb["rc_by_tier"]
    out.append(
        f"**{bb['total']:,} total entries.** Signal class: {parts}. "
        f"RC tiers (all ACTIVE): inner {rc_tiers.get('inner',0)}, "
        f"broader {rc_tiers.get('broader',0)}, "
        f"dormant_valuable {rc_tiers.get('dormant_valuable',0)}. "
        f"**{len(report['circles'])} Circles standing.** "
        f"**{report['brief_count']:,} briefs.**\n"
    )

    out.append("---\n")
    out.append(
        f"*Generated by `system/scripts/daily_brief.py` on {today}. "
        "Editorial framing (if any) is layered on top by the operator session; "
        "all numbers above are deterministic.*"
    )
    out.append("\nDo you want me to create a to-do list or action loops from these recommendations?")
    return "\n".join(out) + "\n"


def render_manifest_md(report: dict) -> str:
    today = report["today"]
    bb = report["baseline"]
    sig = bb["by_signal_class"]
    rc_tiers = bb["rc_by_tier"]
    out = []
    out.append("# RB System Manifest\n")
    out.append(
        "Single-page status. Regenerated by `system/scripts/daily_brief.py`. "
        "Holds *current state only* — no version-numbering, no governance ceremony. "
        "If you want history, ask git.\n"
    )
    out.append(f"---\n\n**Last updated:** {today}\n")

    # Baseline
    out.append("## Baseline\n")
    normalized_sig = sorted(
        ((str(k), v) for k, v in sig.items() if k is not None and str(k).strip()),
        key=lambda item: item[0],
    )
    sig_parts = " · ".join(f"{k} {v}" for k, v in normalized_sig)
    out.append(f"- **Total entries:** {bb['total']:,}")
    out.append(f"- **Signal class breakdown:** {sig_parts}")
    out.append(
        f"- **RC tier breakdown:** inner {rc_tiers.get('inner',0)} · "
        f"broader {rc_tiers.get('broader',0)} · "
        f"dormant_valuable {rc_tiers.get('dormant_valuable',0)}"
    )

    # Loops
    out.append("\n## Loops\n")
    open_count = sum(
        len(report["loops"][k]) for k in ("overdue", "due_today", "this_week", "future")
    )
    out.append(f"- **Open loops:** {open_count}")
    out.append(f"- **Closed in ledger:** {len(report['loops']['closed'])}")
    out.append(f"- **Loops past target today:** {len(report['loops']['overdue'])}")
    out.append(f"- **Loops due today:** {len(report['loops']['due_today'])}")
    out.append(f"- **Loops closing within 7 days:** {len(report['loops']['this_week'])}")

    # Circles
    out.append("\n## Circles\n")
    out.append(f"{len(report['circles'])} total.\n")
    out.append("| Circle | Type | Status |")
    out.append("|---|---|---|")
    for c in report["circles"]:
        out.append(f"| `{c['id']}` | {c['circle_type']} | {c['status'] or '—'} |")

    # Cards
    out.append("\n## Cards\n")
    total_rcs = sum(bb["rc_by_state"].values()) if bb["rc_by_state"] else sig.get("RC", 0)
    have_cards = total_rcs - len(report["missing_cards"])
    out.append(f"- **Total RC cards:** {have_cards}")
    if report["missing_cards"]:
        names = ", ".join(c["name"] for c in report["missing_cards"])
        out.append(f"- **RCs without a card yet:** {len(report['missing_cards'])} ({names})")
    else:
        out.append("- **RCs without a card yet:** 0")

    # Briefs
    out.append("\n## Briefs\n")
    out.append(f"- **Total IB files in `system/briefs/`:** {report['brief_count']:,}")

    # Scheduled tasks
    out.append("\n## Scheduled tasks\n")
    out.append("| Task ID | Schedule | Status |")
    out.append("|---|---|---|")
    for t in report["scheduled_tasks"]:
        out.append(f"| `{t['id']}` | {t['schedule']} | {t['status']} |")

    # Gap surface (short form)
    out.append("\n## Notable in-flight items\n")
    if report["no_last_touch_rcs"]:
        names = ", ".join(c["name"] for c in report["no_last_touch_rcs"])
        out.append(f"- **RC(s) with no `last_touch`:** {names}.")
    if report["loops"]["overdue"]:
        for L in report["loops"]["overdue"]:
            out.append(f"- **Overdue loop {L['id']}** — {L['party']} (target {L['target']}).")
    if report["missing_cards"]:
        names = ", ".join(c["name"] for c in report["missing_cards"])
        out.append(f"- **Missing RC cards:** {names}.")

    # Doc rules
    out.append(
        "\n## Documentation rules\n\n"
        "The canonical operating documents — read at session start:\n\n"
        "1. `settings.json` (operating preferences, verbosity)\n"
        "2. selected user profile (`profiles/{profile_id}/profile.md`; `00_TODD_PROFILE.md` in legacy single-user mode)\n"
        "3. `CHARTER.md` (mission, principles, design structure, methodology, roadmap pointer)\n"
        "4. `README.md` (system overview)\n"
        "5. `01_RB_TENETS.md` (principles, full text)\n"
        "6. `ARCHITECTURE.md` (system behavior)\n"
        "7. `SCHEMAS.md` (data model)\n"
        "8. `heuristics.md` (cluster-level rules)\n"
        "9. `WHAT_PERSISTS.md` (persistence contract)\n"
        "10. `network_map.md` (current network shape)\n"
        "11. `STATUS.md` (live/partial/designed/not-built breakdown)\n"
    )

    out.append(
        "\n## Maintenance discipline\n\n"
        "- This manifest is overwritten on each daily-brief run; it should always read as current.\n"
        "- The numbers here are produced by `system/scripts/daily_brief.py` reading `baseline_index.json`, "
        "`loop_ledger.md`, `cards/`, `briefs/`, and `circles/` directly. If a number here disagrees with the "
        "canonical files, the canonical files win — re-run the script.\n"
        "- The today.md and MANIFEST.md numbers are generated from the SAME report dict, so they are "
        "guaranteed to agree.\n"
    )

    next_day = (date.fromisoformat(today) + timedelta(days=1)).isoformat()
    out.append(f"\n---\n\n*Auto-generated {today}. Next regeneration: {next_day} 05:00 CT.*\n")
    return "\n".join(out) + "\n"


