def _render_linkedin_delta_md(report: dict) -> list:
    """Render LinkedIn Relationship Delta section as a list of markdown lines.

    Ported from RB 9.20 sprint (wrong-dir daily_brief.py).
    Used by test_daily_brief_linkedin_delta_intelligence.py and render_today_md().
    Enforces: no static import language (file_processed, contacts_imported, etc.).
    """
    li = report.get("linkedin_relationship_delta") or {}
    out = []
    out.append("## LinkedIn Relationship Delta\n")

    if not li.get("available"):
        label = li.get("label") or "unavailable"
        note = li.get("note") or ""
        out.append(f"LinkedIn delta: `{label}`")
        if note:
            out.append(f"\n_{note}_")
        out.append("")
        return out

    data = li.get("data") or {}
    ingested_at = li.get("ingested_at") or "?"
    ingested_str = ingested_at[:19] if len(str(ingested_at)) > 10 else ingested_at
    out.append(f"Delta cache fresh — ingested: {ingested_str}\n")

    bc = data.get("baseline_comparison") or {}
    if bc:
        out.append(
            f"**Baseline comparison:** {bc.get('contacts_matched_in_baseline', '?')} matched / "
            f"{bc.get('export_contact_count', '?')} in export / "
            f"{bc.get('contacts_not_in_baseline', '?')} new connections\n"
        )

    promotions = data.get("promotions") or []
    if promotions:
        out.append(f"\n**Promotions detected ({len(promotions)}):**\n")
        for p in promotions[:5]:
            out.append(f"- **{p['name']}** ({p.get('rc_tier', '—')}) — {p['old_title']} → {p['new_title']}")

    company_changes = data.get("company_changes") or []
    title_changes = data.get("title_changes") or []
    if company_changes or title_changes:
        total = len(company_changes) + len(title_changes)
        out.append(f"\n**Company/title moves ({total} total):**\n")
        for c in (company_changes + title_changes)[:8]:
            name = c.get("name", "?")
            if "old_company" in c:
                out.append(f"- {name}: {c['old_company']} → {c['new_company']}")
            else:
                out.append(f"- {name}: {c.get('old_title', '?')} → {c.get('new_title', '?')}")

    oq = data.get("outreach_queue") or []
    if oq:
        out.append(f"\n**Outreach queue ({len(oq)}):**\n")
        for item in oq[:5]:
            out.append(f"- **{item['name']}** — {item.get('reason', '?')} [priority: {item.get('priority', '?')}]")
            out.append(f"  Requires confirmation: {item.get('requires_confirmation', True)}")

    return out


def _render_behavioral_intelligence_md(report: dict) -> list:
    """Render persistent macro behavioral intelligence into the daily brief."""
    bi = report.get("behavioral_intelligence") or {}
    out = []
    out.append("## Behavioral Intelligence\n")

    if not bi.get("available"):
        label = bi.get("label") or "source_unavailable"
        note = bi.get("note") or "No source-backed behavioral intelligence is available."
        out.append(f"Behavioral intelligence: `{label}`")
        out.append(f"\n_{note}_")
        out.append("")
        return out

    out.append(
        f"Persistent behavioral layer: {bi.get('signal_count', 0)} signal(s), "
        f"{bi.get('artifact_count', 0)} artifact(s), "
        f"{bi.get('recent_signal_count', 0)} recent signal(s)."
    )
    if bi.get("source"):
        out.append(f"Source: `{bi.get('source')}`\n")

    signals = bi.get("signals") or []
    if signals:
        out.append("**Recent behavioral signals:**")
        for signal in signals[:6]:
            evidence = signal.get("evidence_sentences") or []
            evidence_line = evidence[0] if evidence else signal.get("source_text_snippet", "")
            status = signal.get("claim_status") or "unknown"
            persistence = signal.get("persistence_status") or "unknown"
            out.append(
                f"- **{signal.get('signal_type', 'behavioral_signal')}** "
                f"({signal.get('confidence', 'unknown')} confidence; "
                f"{status}; {persistence})"
            )
            if evidence_line:
                out.append(f"  - Evidence: {evidence_line}")
            if signal.get("source_type") or signal.get("signal_date"):
                out.append(
                    f"  - Source: {signal.get('source_type', 'unknown')} / "
                    f"{signal.get('signal_date', 'unknown date')}"
                )

    artifacts = bi.get("artifacts") or []
    if artifacts:
        out.append("\n**Behavioral artifacts:**")
        seen_artifacts: set[tuple[str, str, str]] = set()
        unique_artifacts: list[dict] = []
        for artifact in artifacts:
            key = (
                str(artifact.get("artifact_name") or ""),
                str(artifact.get("definition") or ""),
                str(artifact.get("strategic_significance") or ""),
            )
            if key in seen_artifacts:
                continue
            seen_artifacts.add(key)
            unique_artifacts.append(artifact)
        for artifact in unique_artifacts[:4]:
            out.append(f"- **{artifact.get('artifact_name', 'Behavioral artifact')}**")
            if artifact.get("definition"):
                out.append(f"  - Definition: {artifact.get('definition')}")
            if artifact.get("strategic_significance"):
                out.append(f"  - Strategic significance: {artifact.get('strategic_significance')}")

    out.append("")
    return out


def _render_knowledge_mutations_md() -> list:
    """DEFECT-026: Render overnight knowledge graph mutations in the daily brief.

    Shows what CHANGED in the knowledge graph — not what articles were found.
    The mutation is the deliverable. The article is the evidence.
    """
    from pathlib import Path as _Path
    import json as _json
    from datetime import datetime as _datetime, timezone as _timezone

    out = []
    log_path = _Path(__file__).resolve().parent.parent / ".cache" / "knowledge_mutations.json"
    if not log_path.exists():
        return out

    try:
        log = _json.loads(log_path.read_text())
    except Exception:
        return out

    today = _datetime.now(_timezone.utc).date().isoformat()
    mutations = [m for m in (log.get("mutations") or [])
                 if (m.get("applied_at") or "")[:10] == today]
    if not mutations:
        return out

    # Group by source
    by_source: dict[str, list[dict]] = {}
    for m in mutations:
        src = m.get("source_title") or "Unknown source"
        by_source.setdefault(src, []).append(m)

    out.append("## Overnight Knowledge Mutations\n")
    out.append(f"{len(mutations)} knowledge graph update(s) applied from today's intelligence.\n")

    for source, muts in by_source.items():
        out.append(f"**{source}** — {len(muts)} mutation(s)")

        vendor_muts = [m for m in muts if m.get("type") == "vendor_customer_relationship"]
        exec_muts = [m for m in muts if m.get("type") == "executive_pov"]
        thesis_muts = [m for m in muts if m.get("type") == "thesis_validation"]
        watchlist_muts = [m for m in muts if m.get("type") == "watchlist_signal"]
        alignment_muts = [m for m in muts if m.get("type") == "thesis_alignment_detected"]
        engagement_muts = [m for m in muts if m.get("type") == "engagement_opportunity"]

        if vendor_muts:
            out.append(f"  - Confirmed relationships: "
                       + "; ".join(m["description"][:60] for m in vendor_muts[:5]))
        if exec_muts:
            out.append(f"  - Executive intelligence: "
                       + "; ".join(m["description"][:60] for m in exec_muts[:3]))
        if thesis_muts:
            themes = [m.get("theme", "?") for m in thesis_muts]
            out.append(f"  - Thesis strengthened: {', '.join(themes)}")
        if watchlist_muts:
            out.append(f"  - Watchlist signals: {len(watchlist_muts)}")
        if alignment_muts:
            out.append(
                "  - Relationship alignment: "
                + "; ".join(m["description"][:100] for m in alignment_muts[:3])
            )
        if engagement_muts:
            out.append(
                "  - Engagement opportunities: "
                + "; ".join(
                    (m.get("suggested_action") or m["description"])[:120]
                    for m in engagement_muts[:3]
                )
            )

    out.append("")
    return out


def _render_whatsapp_intelligence_md(report: dict) -> list:
    """Render WhatsApp intelligence block into the daily brief (DEFECT-021)."""
    from pathlib import Path as _Path
    import json as _json

    out = []
    chats_path = _Path(__file__).resolve().parent.parent / ".cache" / "whatsapp_chats.json"
    if not chats_path.exists():
        return out  # No WhatsApp data yet — section omitted silently

    try:
        raw = _json.loads(chats_path.read_text())
    except Exception:
        return out

    chats = raw.get("chats") or []
    if not chats:
        return out

    strategic_rel = [c for c in chats if c.get("classification") == "strategic_relationship"]
    strategic_grp = [c for c in chats if c.get("classification") == "strategic_group"]
    velocity_up = [c for c in chats if (c.get("velocity") or {}).get("trend") == "increasing"]

    out.append("## WhatsApp Intelligence\n")
    out.append(
        f"Processed: {len(chats)} chats · "
        f"Strategic relationships: {len(strategic_rel)} · "
        f"Strategic groups: {len(strategic_grp)}"
    )
    out.append("")

    if strategic_grp:
        out.append("**Strategic Groups:**")
        for c in strategic_grp:
            vel = c.get("velocity") or {}
            out.append(
                f"- **{c['chat_name']}** — {c.get('message_count', 0)} messages, "
                f"trend: {vel.get('trend', '?')} "
                f"({vel.get('this_month_count', 0)} this month)"
            )
            matched = [m.get("name") for m in (c.get("matched_baseline") or [])]
            if matched:
                out.append(f"  - Known participants: {', '.join(matched)}")
        out.append("")

    if strategic_rel:
        out.append("**Strategic Relationships (1:1):**")
        for c in strategic_rel:
            vel = c.get("velocity") or {}
            matched = [m.get("name") for m in (c.get("matched_baseline") or [])]
            name = matched[0] if matched else c["chat_name"]
            out.append(
                f"- **{name}** — {c.get('message_count', 0)} messages, "
                f"trend: {vel.get('trend', '?')} "
                f"({vel.get('this_month_count', 0)} this month)"
            )
        out.append("")

    if velocity_up:
        out.append(
            f"**Communication velocity increases:** "
            + ", ".join(c["chat_name"] for c in velocity_up)
        )
        out.append("")

    return out


def _write_completion_artifact(
    today: date,
    report: dict,
    status: str,
    started_at: str,
    published_paths: list,
    failed_integrations: list | None = None,
) -> None:
    """Write system/.cache/daily_brief_status.json after brief generation.

    Ported from RB 9.20 sprint (wrong-dir daily_brief.py). Used by
    test_daily_brief_completion_status.py and the notification layer.
    """
    from pathlib import Path as _Path
    sf = report.get("source_freshness") or {}
    sources = sf.get("sources") or {}

    stale_sources = [k for k, v in sources.items() if v.get("stale")]
    source_refreshes = [
        {"source": k, "label": v.get("label"), "fetched_at": v.get("fetched_at") or v.get("ingested_at")}
        for k, v in sources.items()
    ]

    now_str = datetime.now().isoformat(timespec="seconds")
    artifact = {
        "date": today.isoformat(),
        "started_at": started_at,
        "completed_at": now_str,
        "status": status,
        "source_refreshes": source_refreshes,
        "failed_integrations": failed_integrations or [],
        "stale_sources": stale_sources,
        "critical_failures": [s for s in (failed_integrations or []) if "email" in s or "baseline" in s],
        "published_paths": published_paths,
        "cos_judgment_confidence": (report.get("cos_judgment") or {}).get("confidence") or "unknown",
        "hard_truths_count": len((report.get("cos_judgment") or {}).get("hard_truths") or []),
        "execution_options_count": len(report.get("execution_options") or []),
        "what_is_not_happening_count": len(report.get("what_is_not_happening") or []),
        "notification_line": (
            f"RB Daily Brief {status} at {datetime.now().strftime('%H:%M')} — "
            f"{len(stale_sources)} stale source(s), "
            f"{len((report.get('cos_judgment') or {}).get('hard_truths') or [])} hard truth(s), "
            f"{len(report.get('execution_options') or [])} execution option(s)."
        ),
    }

    # Use core.CACHE_DIR so tests can override it with a tempdir.
    import rb_core as _core
    _core.CACHE_DIR.mkdir(parents=True, exist_ok=True)
    (_core.CACHE_DIR / "daily_brief_status.json").write_text(
        json.dumps(artifact, default=str, indent=2)
    )


def main() -> int:
    p = argparse.ArgumentParser()
    p.add_argument("--date", help="ISO date to treat as 'today' (default: system date)")
    p.add_argument("--dry-run", action="store_true", help="Print, do not write.")
    p.add_argument("--json", action="store_true", help="Emit JSON report and exit.")
    p.add_argument("--cache", action="store_true",
                   help="Also write the report to system/.cache/daily_brief.json")
    p.add_argument("--refresh-sources", action="store_true",
                   help="Run refresh_sources.py --all --refresh-signals before computing.")
    p.add_argument("--smoke", action="store_true",
                   help="Run the Step 6 canonical-brief smoke (no inbox I/O).")
    args = p.parse_args()
    if args.smoke:
        return _smoke_canonical_brief()

    today = date.fromisoformat(args.date) if args.date else date.today()

    if args.refresh_sources:
        cmd = [
            sys.executable or "python3",
            str(Path(__file__).resolve().parent / "refresh_sources.py"),
            "--all",
            "--save-health",
            "--refresh-signals",
        ]
        rc = subprocess.run(
            cmd,
            stdout=sys.stderr if args.json else None,
            stderr=sys.stderr if args.json else None,
        )
        if rc.returncode != 0:
            print(
                "WARNING: source refresh returned non-zero; continuing with "
                "existing caches and surfacing stale-source caveats.",
                file=sys.stderr,
            )

    report = build_report(today)

    if args.cache:
        core.write_cache("daily_brief", report, source="daily_brief.py")

    if args.json:
        print(json.dumps(report, default=str, indent=2))
        return 0

    today_md = render_today_md(report)
    manifest_md = render_manifest_md(report)

    if args.dry_run:
        print("===== today.md =====")
        print(today_md)
        print("===== MANIFEST.md =====")
        print(manifest_md)
        return 0

    today_path = core.SYSTEM_DIR / "today.md"
    manifest_path = core.SYSTEM_DIR / "MANIFEST.md"
    started_at = datetime.now().isoformat(timespec="seconds")
    today_path.write_text(today_md)
    manifest_path.write_text(manifest_md)
    print(f"Wrote {today_path.relative_to(core.PROJECT_DIR)} and "
          f"{manifest_path.relative_to(core.PROJECT_DIR)} for {today}.")
    _write_completion_artifact(
        today,
        report,
        status="complete",
        started_at=started_at,
        published_paths=[str(today_path.relative_to(core.PROJECT_DIR)),
                         str(manifest_path.relative_to(core.PROJECT_DIR))],
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
